window.__D("text/zohar/c019",{"p":[[9520011713,"<p>בָּרְכוּ אֶת יְיָ'. אֶת דַּיְיקָא. כִּדְקָאמְרָן, דָּא (בראשית ה' ע\"ב) שַׁבָּת דְּמַעֲלֵי שַׁבַּתָּא. בָּרוּךְ יְיָ' הַמְבוֹרָךְ, דָּא אַפִּיקוּ דְּבִרְכָאן מִמְּקוֹרָא דְּחַיֵּי, וַאֲתָר דְּנָפִיק מִנֵּיהּ כָּל שַׁקְיוּ, לְאַשְׁקָאָה לְכֹלָּא. וּבְגִין דְּאִיהוּ מְקוֹרָא בְּרָזָא דְּאָת קַיְּימָא, קָרֵינָן לֵיהּ הַמְבוֹרָךְ, אִיהוּ מַבּוּעָא דְּבֵירָא. כֵּיוָן דְּמָטוּ תַּמָּן, הָא וַדַּאי בֵּירָא אִתְמַלְּיָא, דְּלָא פַּסְקִין מֵימוֹי לְעָלְמִין.</p>\n<p>וְעַל דָּא לָא אַמְרֵינָן, בָּרוּךְ אֶת יְיָ' הַמְבוֹרָךְ, אֶלָּא בָּרוּךְ יְיָ', דְּאִלְמָלֵא לָא מָטֵי הָתָם נְבִיעוּ מִמְּקוֹרָא עִלָּאָה, לָא אִתְמַלְּיָא בֵּירָא כְּלָל, וְעַל דָּא הַמְבוֹרָךְ, אֲמַאי אִיהוּ הַמְבוֹרָךְ. בְּגִין דְּאִיהוּ אַשְׁלִים וְאַשְׁקֵי לְעוֹלָם וָעֶד. עוֹלָם וָעֶד דָּא אִיהוּ שַׁבָּת דְּמַעֲלֵי שַׁבַּתָּא, וַאֲנָן תַּקְעִין בִּרְכָּאן בְּאֲתָר דְּאִקְרֵי מְבוֹרָךְ. וְכֵיוָן דְּמָטָאן הָתָם, כֻּלְּהוּ לְעוֹלָם וָעֶד, וְדָא אִיהוּ בָּרוּךְ יְיָ' הַמְבוֹרָךְ. עַד הָכָא, מָטוּן בִּרְכָּאן מֵעָלְמָא עִלָּאָה, וְכֻלְּהוּ לְעוֹלָם וָעֶד, לְאִתְבָרְכָא וּלְאִתְשָׁקָאָה, וּלְמֶהוֵי שְׁלִים כְּדְקָא יֵאוֹת, מַלְיָא מִכָל סִטְרִין.</p>\n<p>בָּרוּךָ: דָּא (קס\"ב ע\"א, עקב רע\"א ע\"א) מְקוֹרָא עִלָּאָה, דְּכָל בִּרְכָּן נָפְקִין מִנֵּיהּ. וְכַד סִיהֲרָא אִשְׁתְּלִים, קָרֵינָן לָהּ הָכִי לְגַבֵי תַּתָּאֵי, אֲבָל בָּרוּךְ מְקוֹרָא עִלָּאָה כִּדְקַאמְרָן. יְיָ': דָּא אֶמְצָעִי דְּכָל סִטְרִין עִלָּאִין. הַמְבוֹרָךְ: דָּא שְׁלָמָא דְּבֵיתָא, מַבּוּעָא דְּבֵירָא, לְאַשְׁלָמָא וּלְאַשְׁקָאָה כֹּלָּא. לְעוֹלָם וָעֶד: דָּא עָלְמָא תַּתָּאָה, דְּאִצְטְרִיךְ לְאִתְבָּרְכָא. וּמִשְׁחָא וּרְבוּ דְּבָרוּךְ יְיָ' וְהַמְבוֹרָךְ, כֹּלָּא אִיהוּ לְעוֹלָם וָעֶד. (מבורך כמה דאת אמר (בראשית מט) בן פורת)</p>\n<p>וְעַל דָּא, בְּרָכָה דָּא, אִצְטְרִיכוּ כָּל עַמָּא לְבָרְכָא, וּבְמַעֲלֵי שַׁבַּתָּא, בִּרְעוּ דְּלִבָא, וּבְחֶדְוָה בָּעוּ לְמִשְׁרֵי בְּשֵׁרוּתָא בִּבְרָכָה דָּא, לְאִתְבָּרְכָא הַאי שַׁבָּת דְּמַעֲלֵי שַׁבַּתָּא, (ליליא) מֵעַמָּא קַדִישָׁא כְּדְקָא יֵאוֹת. בְּהַאי בְּרָכָה.</p>\n<p>(ס\"א ברכו) כַּד שָׁרָאן יִשְׂרָאֵל לְבָרְכָא, קָלָא אָזְלָא בְּכֻלְּהוּ רְקִיעִין, דְּמִתְקַדְּשֵׁי בִּקְדוּשָּׁא דְּמַעֲלֵי שַׁבַּתָּא. זַכָּאִין אַתּוּן עַמָּא קַדִישָׁא, דְּאַתּוּן מְבָרְכֵי וּמְקַדְּשֵׁי לְתַתָּא, בְּגִין דְּיִתְבָּרְכוּן וְיִתְקַדְּשׁוּן לְעֵילָּא, כַּמָּה מַשְׁרְיָין <Nonei></i>עִלָּאִין קַדִּישִׁין, זַכָּאִין אִינּוּן בְּהַאי עָלְמָא, וְזַכָּאִין אִינּוּן בְּעָלְמָא דְּאָתֵי, וְלָא מְבָרְכֵי יִשְׂרָאֵל בְּרָכָה דָּא, עַד דְּמִתְעַטְּרָן בְּעִטְרִין דְּנִשְׁמָתִין קַדִּישִׁין כִּדְקַאמְרָן. זַכָּאָה עַמָּא דְּזַכֵּי לוֹן בְּעָלְמָא דֵּין, לְמִזְכֵּי לוֹן לְעָלְמָא דְּאָתֵי.</p>\n<p>בְּהַאי לֵילְיָא שִׁמּוּשָׁא דְּחַכִּימִין, בְּאִלֵּין נִשְׁמָתִין קַדִּישִׁין דְּמִתְעַטְּרָן בְּהוּ, וְאַף עַל גַּב דְּהָא אוֹקִימְנָא וְכֹלָּא חַד. וּבְכָל אֲתָר דְּתִשְׁכַּח לְחַכִּימִין בְּהַאי מִלָּה, בְּסִטְרָא דָּא, וּלְזִמְנִין בְּסִטְרָא דָּא, כֹּלָּא אִיהוּ חַד. וְהָנֵי מִילֵּי הָא אוֹקִימְנָא, אֲבָל בְּזִמְנָא דָּא, דְּמִתְעַטְּרָן כֻּלְּהוּ בְּנִשְׁמָתִין וְרוּחִין חַדְתִּין יְתֵירִין קַדִּישִׁין, כְּדֵין אִיהִי זִמְנָא דְּשִׁמּוּשָׁא דִּלְהוֹן, בְּגִין דְּלִיהֱוֵי נְגִידוּ לְהַהוּא שִׁמּוּשָׁא, בִּנְגִידוּ דִּקְדוּשָׁה, בְּנַיְיחָא עִלָּאָה, וְיִפְקוּן בְּנַיְיהוּ קַדִישִׁין כַּדְקָא חֲזִי.</p>\n<p>רָזָא דָּא לְחַכִּימִין אִתְיְיהִיבַת. בְּשַׁעֲתָּא דְּאִתְפְּלִיג לֵילְיָא, בְּלֵילְיָא דָּא, קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְאַעֲלָא בְּגִנְתָּא דִּלְעֵילָּא. וְרָזָא דָּא, בְּיוֹמֵי (ויקרא מ\"ט ע\"ב) דְּחוֹל קוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִנְתָּא דְּעֵדֶן דִּלְתַתָּא, לְאִשְׁתַּעְשְׁעָא עִם צַדִיקַיָּא דְּשָׁרָאן תַּמָּן, וּבְשַׁבָּת, בְּהַהוּא לֵילְיָא דְּשַׁבְּתָא, קוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִנְתָּא דִּלְעֵילָּא, בְּרָזָא דִּמְקוֹרָא עִלָּאָה.</p>\n<p>בְּגִין דִּבְיוֹמֵי דְּחוֹל, כָּל נִשְׁמָתִין דְּצַדִיקַיָּא כֻּלְּהוּ, בְּגִנְתָּא דִּי בְּאַרְעָא שַׁרְיָין. וְכַד אִתְקַדָּשׁ יוֹמָא בְּמַעֲלֵי שַׁבַּתָּא, כָּל אִינּוּן מַשְׁרְיָין דְּמַלְאָכִין קַדִּישִׁין דִּי מְמָנָן גּוֹ גִּנְתָּא דִּלְתַתָּא, כֻּלְּהוּ סַלְּקִין לְהָנֵי נִשְׁמָתִין, דְּשַׁרְיָין גּוֹ גִּנְתָּא דִּלְתַתָּא, לְעַאֲלָא לְגַבֵּי הַהוּא רְקִיעָא דְּקַיְּימָא עַל גִּנְתָּא, וּמִתַּמָּן אִזְדַּמְנוּ רְתִיכִין קַדִישִׁין, דְּסַחֲרָאן כּוּרְסֵי יְקָרָא דְּמַלְכָּא, וְסַלְּקִין לוֹן לְכָל אִינּוּן נִשְׁמָתִין, בְּגִנְתָּא דִּלְעֵילָּא.</p>\n<p>כֵּיוָן דְּאִלֵּין רוּחִין סַלְּקִין, כְּדֵין רוּחִין (צ\"ח ע\"ב, שלח קע\"ג ע\"א) אָחֲרָנִין קַדִּישִׁין, נַחְתִּין, לְאִתְעַטְּרָא בְּהוּ עַמָּא קַדִּישָׁא. אִלֵּין סַלְּקִין, וְאִלֵּין נַחְתִּין.</p>\n<p>וְאִי תֵּימָא, הָא גִּנְתָּא דִּבְאַרְעָא, בְּיוֹמָא דְּשַׁבְּתָא יָתְבָא בְּרֵיקָנַיָּיא בְּלָא נִשְׁמָתִין דְּצַדִּיקַיָּא. לָאו הָכִי. אֶלָּא נִשְׁמָתִין אַזְלִין, וְנִשְׁמָתִין אַתְיָין. נִשְׁמָתִין סַלְּקִין, וְנִשְׁמָתִין נַחְתִּין. נִשְׁמָתִין אַזְלִין מִגּוֹ גִּנְתָּא, וְנִשְׁמָתִין אַתְיָין לְגוֹ גִּנְתָּא. כָּל אִינּוּן נִשְׁמָתִין דְּצַדִּיקַיָּיא, דְּמִתְלַבְּנָן בְּיוֹמֵי דְּחוֹל, וְעַד לָא עָאלוּ לְגוֹ גִּנְתָּא, בְּשַׁעֲתָא דְּאִלֵּין נָפְקִין, אִלֵּין עָאלִין וְגִנְתָּא לָא (רנ\"ג ע\"א) אִשְׁתְּאַר בְּרֵיקַנְיָּא. בְּרָזָא דְּלֶחֶם הַפָּנִים בְּיוֹם הִלָּקְחוֹ.</p>\n<p>וְאִי תֵּימָא, כַּד אָהַדְרוּ בְּיוֹמֵי דְּחוֹל. בְּמָה (נ\"א כמה) אִתְמַשְּׁכָן דּוּכְתֵּי לְאָרְכָּא וּפוּתְיָא וְרוּמָא, בְּגִנְתָּא, וְלָא אִתְיְדַע. כְּגַוְונָא דְּרָזָא דְּאֶרֶץ הַצְּבִי, דְּהֲוָה אִתְמְשַּׁךְ לְכָל סִטְרִין וְלָא אִתְיְדַע. כְּגַוְונָא דִּצְבִי, דְּכָל מַה דְּאִתְרַבֵּי, מַשְׁכֵּיהּ אִתְרַבֵּי לְכָל סְטָר, וְלָא אִתְיְידָע. וְאִית כְּמָה נִשְׁמָתִין, דְּכֵיוָן דְּסַלְּקִין, תּוּ לָא נַחְתִּין.</p>\n<p>נִשְׁמָתִין סַלְּקִין, וְנִשְׁמָתִין נַחְתִּין, לְאִתְעַטְּרָא בְּהוּ עַמָּא קַדִּישָׁא. וּבְמַעֲלֵי שַׁבַּתָּא, גִּלְגּוּלָא דְּנִשְׁמָתִין אִיהוּ, אִלֵּין אַזְלִין, וְאִלֵּין אַתְיָין, אִלֵּין סַלְּקִין וְאִלֵּין נַחְתִּין. מַאן חָמֵי כַּמָּה רְתִיכִין קַדִּישִׁין, דִּי מְשַׁטְּטֵי לְכָאן וּלְכָאן. כֻּלְּהוּ בְּחֶדְוָה, כֻּלְּהוּ בִּרְעוּ, בְּאִלֵּין נִשְׁמָתִין לְאַעְטְּרָא לְעַמָּא קַדִּישָׁא, לְאַעְטְּרָא לְכַמָּה צַדִּיקַיָּיא, גִּנְתָּא דְּעֵדֶן לְתַתָּא, עַד שַׁעֲתָא דְּכָרוֹזָא קָאִים, וְקָארֵי מְקוּדָשׁ מְקוּדָשׁ. כְּדֵין נַיְיחָא שְׁכִיחַ, וּשְׁכִיכוּ לְכֹלָּא. וְחַיָּיבֵי גֵּיהִנָּם כֻּלְּהוּ מִשְׁתַּכְכֵי בְּדוּכְתַּיְיהוּ, וְאִית לוֹן נַיְיחָא. וְנִשְׁמָתִין כֻּלְּהוּ מִתְעַטְּרָן, אִלֵּין לְעֵילָּא וְאִלֵּין לְתַתָּא. זַכָּאָה עַמָּא, דְּחוּלָקָא דָּא לְהוֹן.</p>\n<p>בְּפַלְגוּת לֵילְיָא דְּמַעֲלֵי שַׁבַּתָּא, דְּחַכִּימִין מִתְעֲרִין לְשִׁמּוּשָׁא דִּלְהוֹן, הַהוּא רוּחָא עִלָּאָה, דְּמִתְעַטְּרָן בֵּיהּ, כַּד יוֹמָא אִתְקַדָּשׁ, בְּשַׁעֲתָא דְּאִינּוּן נַיְימֵי בְּעַרְסַיְיהוּ, וְנִשְׁמָתִין אַחֲרָנִין דִּלְהוֹן, בָּעָאן לְסַלְּקָא לְמֵחמֵי בִּיקָרָא דְּמַלְכָּא, כְּדֵין הַהוּא רוּחַ עִלָּאָה דְּנָחִית בְּמַעֲלֵי שַׁבַּתָּא, נָטִיל הַהִיא נִשְׁמְתָא, וְסַלְּקִין לְעֵילָּא, וְאִתְסַחְיָא נִשְׁמְתָא אַחֲרָא בְּבוּסְמִין דְּגִנְתָּא דְּעֵדֶן, וְתַמָּן חָמֵי מַה דְּחָמֵי.</p>\n<p>וְכַד נַחְתָּא לְאַשְׁרָאָה בְּדוּכְתָּהָא בְּפַלְגּוּת לֵילְיָא, הַהִיא נִשְׁמְתָא תָּבַאת לְדוּכְתָּהָא. וּבָעֵי לְאִינוּן <Nonei></i>חַכִּימִין לוֹמַר, חַד פְּסוּקָא דְּאִתְעָרוּתָא, דְּהַהוּא רוּחָא עִלָּאָה קַדִּישָׁא דְּעָטְרָא דְּשַׁבַּתָּא, כְּגוֹן, (ישעיהו ס״א:א׳) רוּחַ יְיָ' אֱלהִים עָלָי יַעַן מָשַׁח יְיָ', אוֹתִי לְבַשֵּׂר עֲנָוִים וְגוֹ'. (יחזקאל א׳:כ״א) בְּלֶכְתָּם יֵלֵכוּ וּבְעָמְדָם יַעֲמֹדוּ וּבְהִנָּשְׂאָם מֵעַל הָאָרֶץ וְגוֹ', אֶל אֲשֶׁר יִהְיֶה שָׁם הָרוּחַ לָלֶכֶת יֵלֵכוּ וְגוֹ'. בְּגִין דְּמִתְעַטְּרָן בְּהַהוּא רוּחָא, בְּאִתְעָרוּתָא דִּלְהוֹן בְּחֶדְוָה דְּשִׁמּוּשָׁא, וִיְהֵא נְגִידוּ דְּהַהוּא רוּחַ עִלָּאָה דְּשַׁבַּתָּא, בְּהַהוּא שִׁמּוּשָׁא דְּמִצְוָה.</p>\n<p>רַב הַמְנוּנָא סָבָא, כַּד הֲוָה (כ\"ד ע\"א) סָלִיק מִנָּהֲרָא בְּמַעֲלֵי שַׁבַּתָּא, הֲוָה יָתִיב רִגְעָא חֲדָא, וְזָקִיף עֵינוֹי, וַהֲוָה חַדֵּי, וַהֲוָה אָמַר, דְּהֲוָה יָתִיב, לְמֵחֱמֵי חֶדְוָה דְּמַלְאֲכֵי עִלָּאֵי. אִלֵּין סַלְּקִין, וְאִלֵּין נַחְתִּין. וּבְכָל מַעֲלֵי שַׁבַּתָּא, יָתִיב בַּר נָשׁ בָּעוֹלָם הַנְּשָׁמוֹת. זַכָּאָה אִיהוּ מַאן דְּיָדַע בְּרָזִין דְּמָארֵיהּ.</p>"],[9520011714,"<p>כַּד נָהִיר יְמָמָא בְּיוֹמָא דְּשַׁבַּתָּא, סְלִיקוּ דְּחֶדְוָה סָלִיק (בראשית ח' ע\"א) בְּכֻלְּהוּ עָלְמִין, בְּנַיְיחָא בְּחֶדְוָה. כְּדֵין (תהילים י״ט:ב׳) הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל וּמַעֲשֵׂי יָדָיו מַגִּיד הָרָקִיעַ. מַאן שָׁמַיִם. אִלֵּין שָׁמַיִם, דִּשְׁמָא עִלָּאָה אִתְחָזֵי בְּהוּ, דִּשְׁמָא קַדִּישָׁא אִתְרְשִׁים בְּהוּ.</p>\n<p>מְסַפְּרִים, מַאי מְסַפְּרִים, אִי תֵּימָא כְּמַאן דְּמִשְׁתָּעֵי סִפּוּר דְּבָרִים. לָאו הָכִי. אֶלָּא דְּנָהֲרִין וּנְצִיצִין בִּנְצִיצוּ דִּנְהוֹרָא עִלָּאָה, וְסַלְּקִין בִּשְׁמָא, דְּכָלִיל בִּנְהִירוּ דִּשְׁלִימוּ עִלָּאָה.</p>\n<p>וּמַאן אִיהוּ סִפּוּר. דְּנַצְּצֵי בִּנְהִירוּ דִּשְׁלִימוּ דְּסֵפֶר עִלָּאָה. וּבְגִין כַּךְ, סַלְּקִין בִּשְׁמָא שְׁלִים, וְנַהֲרִין בִּנְהִירוּ שְׁלִים, וְנַצְצֵי בִּנְצִיצוּ שְׁלִים. אִינְהוּ מְנַצְצֵי וְנַהֲרֵי בְּגַרְמַיְיהוּ, מִגּוֹ נְהִירוּ דִּנְצִיצוּ דְּסֵפֶר עִלָּאָה, וְנַצְצֵי וְנַהֲרֵי לְכָל סְטָר וּסְטָר (נ\"א לכל כבוד וכבוד) דְּמִתְדַּבְּקָן בֵּיהּ, דְּהָא מִנַּיְיהוּ, מֵהַהוּא סְפִירוּ וּנְהִירוּ, נָהִיר כָּל עִזְקָא וְעִזְקָא, וְנָצִיץ בִּנְצִיצוּ, בְּגִין דִּבְּהַאי יוֹמָא מִתְעַטְּרָן שָׁמַיִם, וְסַלְּקִין בִּשְׁמָא קַדִּישָׁא, יַתִּיר מִשְּׁאָר יוֹמִין.</p>\n<p>וּמַעֲשֵׂה יָדָיו, הַהוּא טַלָּא עִלָּאָה, דְּנָהִיר מִכָּל סִטְרִין גְּנִיזִין, דְּאִיהוּ מַעֲשֵׂה יָדָיו, וְתִקּוּנָא דִּילֵיהּ, דְּמִתַּתְקְנָא בְּיוֹמָא דָּא מִכָּל שְׁאָר יוֹמִין.</p>\n<p>מַגִּיד הָרָקִיעַ. מַאי מַגִּיד. מָשִׁיךְ וְנָגִיד לְתַתָּא, מֵרֵישָׁא דְּמַלְכָּא, מַלְיָא מִכָּל סִטְרוֹי. הָרָקִיעַ, הַהוּא רָקִיעַ, דְּאִיהוּ מַבּוּעָא דְּבֵירָא. וְדָא אִיהוּ הַהוּא נָהָר דְּנָפִיק מֵעֵדֶן, וְדָא אִיהוּ דְּנָגִיד וּמָשִׁיךְ לְתַתָּא, נְגִידוּ דְּטַלָּא עִלָּאָה, דְּנָהִיר וְנָצִיץ בִּנְצִיצוּ מִכָּל סִטְרִין. וְדָא רָקִיעַ אַנְגִּיד לֵיהּ בִּמְשִׁיכוּ דִּרְחִימוּ וְתִיאוּבְתָּא, לְאַשְׁקָאָה שַׁקְיוּ דְּחֶדְוָה, לְמַעֲלֵי שַׁבַּתָּא.</p>\n<p>וְכַד נָגִיד וּמָשִׁיךְ הַהוּא טַלָּא דִּבְדוֹלְחָא, כֹּלָּא (נגיד) מַלְיָא וּשְׁלִים בְּאָתְווֹי קַדִּישִׁין, בְּכָל אִינּוּן שְׁבִילִין קַדִּישִׁין. כֵּיוָן דְּכֹלָּא אִתְחַבָּר בֵּיהּ, אִתְעָבִיד בֵּיהּ אָרְחָא לְאַשְׁקָאָה וּלְבָרְכָא לְתַתָּא.</p>\n<p>יוֹם לְיוֹם: יוֹמָא לְיוֹמָא, וְעִזְקָא לְעִזְקָא. הַשְׁתָּא מִשְׁתָּעֵי קְרָא בְּאֹרַח פְּרָט, הֵיךְ שָׁמַיִם מְסַפְּרִים וּמְתַקְּנִין בִּסְפִירוּ וּבִנְצִיצוּ עִלָּאָה לְהַאי כָּבוֹד, וְהֵיךְ נָגִיד וּמָשִׁיךְ הַהוּא רְקִיעָא, נְגִידוּ דְּטַלָּא עִלָּאָה. וְאָמַר, יוֹם לְיוֹם יַבִּיעַ אֹמֶר. יוֹמָא לְיוֹמָא, וְדַרְגָּא לְדַרְגָּא, יְחַוֶּה (ס\"א אוחז) לְאִתְכַּלְּלָא דָּא בְּדָא, וּלְאִתְנָהֲרָא דָּא מִן דָּא, מֵהַהוּא סְפִירוּ דִּמְנַצְּצֵי וּמְנַהֲרֵי שָׁמַיִם, לְהַאי כָּבוֹד. יַבִּיעַ: כְּמָה דְאַתְּ אָמֵר מַבָּע אִתְעָבִיד וְגוֹ'. אוֹחוּ לְאַנְהֲרָא דָּא מִן דָּא, וּלְאִתְנַצְּצָא דָּא מִן דָּא, מֵהַהוּא סְפִירוּ וּנְצִיצוּ.</p>\n<p>אֹמֶ\"ר: כְּלָלָא דְּאַתְוָון וּשְׁבִילִין דְּנָפְקִין מֵאַבָּא וְאִימָּא, וְהַהוּא רֵישָׁא דְּנָפִיק מִנַּיְיהוּ, דְּאִיהוּ בְּרָא בּוּכְרָא, אָלֶף: אַבָּא. וְכַד אִיהוּ סָלִיק וְנָחִית, אִתְחַבְּרַת מ' בַּהֲדֵי א', וְאִיהוּ אֵם. ר': רֵישָׁא (קע\"ח ע\"ב) בּוּכְרָא. כַּד מִתְחַבְּרָן אַתְוָון כֻּלְּהוּ, אֹמֶר. דָּא נְהִירוּ דְּאַבָּא וְאִימָּא וּבְרָא בּוּכְרָא, וְנָהֲרִין דָּא בְּדָא בְּחִבּוּרָא חֲדָא. שַׁלְטָא בְּיוֹמָא דְּשַׁבַּתָּא. וְעַל דָּא כֹּלָּא אִתְכְּלִיל דָּא בְּדָא, בְּגִין לְמֶהוֵי חַד. וּבְגִין כַּךְ אוֹחוּ דָּא בְּדָא, הַהוּא אֹמֶר שְׁלִיטוּ עִלָּאָה, לְמֶהֱוֵי כֹּלָּא חַד.</p>\n<p>וְכַד כָּל הַאי אִתְנְגִיד וְאִתְמְשַׁךְ לְהַאי רָקִיעַ, כְּדֵין אִיהוּ אַשְׁקֵי וְאַנְהִיר לְתַתָּא, לְהַאי כְּבוֹד אֵל, לְמֶעְבַּד תּוֹלָדִין בְּדִיּוּקְנָא דְּאִינּוּן <Nonei></i>שָׁמַיִם, דְּנָהֲרִין לְהַהוּא כְּבוֹד אֵל. (ודא הוא דכתיב)</p>\n<p>וְלַיְלָה לְלַיְלָה יְחַוֶּה דָּעַת, רְתִיכִין דִּילָהּ (דא לדא) דְּאִינּוּן גּוּפָא דְּכֻרְסְיָיא, וְכֻלְּהוּ אִקְרוּן לֵילוֹת, כְּמָה דְאַתְּ אָמֵר (תהילים ט״ז:ז׳) אַף לֵילוֹת יִסְּרוּנִי כִלְיוֹתָי. רְתִיכָא עִלָּאָה, אִתְקְרֵי יָמִים, יוֹם לְיוֹם. רְתִיכָא תַּתַּאָה, אִקְרֵי לֵילוֹת, לַיְלָה לְלַיְלָה.</p>\n<p>יְחַוֶּה. דָּעַת, יְחַוֶּה: יְחַיֶּה. יְחַיֶּה תּוֹלָדִין, דְּאִינּוּן (נ\"א באינון) שָׁמַיִם. וְאִי תֵּימָא, יְחַוֶּה לָאו יְחַיֶּה. תָּא חֲזֵי, כְּתִיב (בראשית ג׳:כ׳) וַיִּקְרָא הָאָדָם שֵׁם אִשְׁתּוֹ חַוָּה, כִּי הִיא הָיְתָה אֵם כָּל חַי. חַוָּה וְחַיָּה בְּמִלָּה חֲדָא סַלְּקִין. וְעַל דְּאִסְתָּלַּק (נ\"א דא אסתלק) י', וְעָיִיל ו', דְּאִיהוּ כְּדְקָא יֵאוֹת, דְּהָא ו' אִיהוּ חַיִּין וַדַּאי, וְעַל דָּא חַוָּה וְחַיָּה, י' (ס\"א זעירא נטילא) נָטְלָא חַיִּין מִן ו'. אוּף הָכָא, יְחַוֶּה, יְחַיֶּה.</p>\n<p>דָּעַת: דָּא אִיהוּ רָזָא דְּשָׁמַיִם. מַה שָׁמַיִם שִׁית סִטְרִין, אוּף הָכָא שִׁית סִטְרִין, בְּאִינּוּן תּוֹלָדִין דְּקָא יְחַיֶּה כְּגַוְונָא דִּילֵיהּ, וְעַל דָּא יוֹם לְיוֹם אִתְכְּלִיל בְּדַרְגָּא עִלָּאָה אֹמֶ\"ר. וְלַיְלָה לְלַיְלָה בְּרָזָא דִּדְכוּרָא, דְּקָא נָהִיר לָהּ דְּאִיהוּ שְׁמֵיהּ (נ\"א שמים') דָּעַת.</p>\n<p>וּבְגִין דְּהַאי אֹמֶר רָזָא עִלָּאָה אִיהוּ, וְלָא כִּשְׁאָר אֲמִירָן, אַהְדָּר קְרָא עָלֵיהּ וְאָמַר, אֵין אֹמֶר וְאֵין דְּבָרִים, כִּשְׁאָר אֲמִירָן דְּעָלְמָא. אֶלָּא הַאי אֹמֶר, רָזָא עִלָּאָה אִיהוּ, בְּדַרְגִּין עִלָּאִין, דְּלֵית תַּמָּן אֲמִירָן וּדְבָרִים, וְלָא אִשְׁתְּמָעוּ, כִּשְׁאַר דַּרְגִּין דְּאִינּוּן רָזָא דִּמְהֵימְנוּתָא, דְּאִינּוּן קָלָא דְּמִשְׁתְּמַע, אֲבָל הָנֵי לָא (בראשית נ') אִשְׁתְּמָעוּ לְעָלְמִין, וְהַיְינוּ דִּכְתִּיב בְּלִי נִשְׁמַע קוֹלָם.</p>\n<p>אֲבָל בְּכָל הָאָרֶץ יָצָא קַוָּם, אַף עַל גַּב דְּאִינּוּן טְמִירִין עִלָּאִין, דְּלָא אִתְיְידָעוּ לְעָלְמִין, נְגִידוּ וּמְשִׁיכוּ דִּלְהוֹן, אִתְמְשַׁךְ וְאִתְנְגִיד לְתַתָּא. וּבְגִין הַהוּא מְשִׁיכוּ, אִית לָן מְהֵימְנוּתָא שְׁלֵימָתָא, בְּהַאי עָלְמָא, וְכָל בְּנִי עָלְמָא מִשְׁתָּעוּ רָזָא דִּמְהֵימְנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּאִינּוּן דַּרְגִּין, כְּאִילּוּ אִתְגַּלְּיָין, וְלָא הֲווֹ טְמִירִין וּגְנִיזִין, וְהַיְינוּ וּבִקְצֵה תֵבֵל מִלֵּיהֶם, מֵרֵישָׁא דְּעָלְמָא, עַד סַיְיפֵי עָלְמָא מִשְׁתָּעָאן אִינּוּן חַכִּימֵי לִבָּא, בְּאִינּוּן דַּרְגִּין גְּנִיזִין, אַף עַל גַּב דְּלָא אִתְיְידָעוּ.</p>\n<p>אֲבָל בְּמָה אִשְׁתְּמוֹדְעָן, בְּגִין דְּלַשֶּׁמֶשׁ שָׂם אֹהֶל בָּהֶם, בְּגִין שִׁמְשָׁא קַדִּישָׁא, דְּאִיהוּ מַשְׁכְּנָא מֵאִינּוּן דַּרְגִּין עִלָּאִין קַדִּישִׁין, וְאִיהוּ נְהוֹרָא, דְּנָטִיל כָּל נְהוֹרִין גְּנִיזִין, וְהַהוּא מְשִׁיכוּ דִּלְהוֹן, וּבְגִינֵיהּ אִתְחָזֵי מְהֵימְנוּתָא בְּכָל עָלְמָא.</p>\n<p>מַאן דְּנָטִיל לְשִׁמְשָׁא, כְּמַאן דְּנָטִיל לְכֻלְּהוּ דַּרְגִּין. בְּגִין דְּשִׁמְשָׁא אִיהוּ אֹהֶל דְּאִתְכְּלִיל בְּהוֹן, וְנָטִיל כֹּלָּא, וְאִיהוּ נָהִיר לְכָל אִינּוּן גְּוָונֵי נְהוֹרִין לְתַתָּא. וְעַל דָּא וְהוּא כְּחָתָן יוֹצֵא מֵחֻפָּתוֹ, בִּנְהִירוּ וּנְצִיצוּ דְּכָל נְהוֹרִין גְּנִיזִין, דְּכֻלְּהוּ בְּתִיאוּבְתָּא בִּרְעוּתָא שְׁלִים, יָהֲבֵי לֵיהּ רְעוּתַיְיהוּ וּנְהִירוּ דִּלְהוֹן, כְּמָה דִּלְחָתָן אִית רְעוּ וְתִיאוּבְתָּא דְּכַלָּה (נ\"א דכלהו) לְמֵיהַב לָהּ נְבִזְבְּזָן וּמַתְּנָן. וְעַל דָּא וְהוּא כְּחָתָן יוֹצֵא מֵחֻפָּתוֹ.</p>\n<p>מַאן חֻפָּתוֹ. דָּא עֵדֶן. וְרָזָא דָּא, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן. עֵדֶן, דָּא אִיהוּ חוּפָּא דְּחַפְיָא עַל כֹּלָּא. יָשִׂישׂ כַּגִבּוֹר. יָשִׂישׂ, מִסִּטְרָא דְּאוֹר קַדְמָאָה דְּלָא אִשְׁתְּכַח בֵּיהּ דִּינָא כְּלָל. כְּגִבּוֹר, מִסִּטְרָא דִּגְבוּרָה, וְאַף עַל גַּב דִּגְבוּרָה אִיהִי דִּינָא שְׁלִים, כְּגִבּוֹר כְּתִיב, וְלָא גִּבּוֹר, בְּגִין דְּאַמְתִּיק דִּינָא בְּחֶסֶד, וְנָטִיל כֹּלָּא כַּחֲדָא, בְּתִיאוּבְתָּא וּרְעוּתָא שְׁלִים. וְכָל דָּא, לָרוּץ אֹרַח. כְּמָה דְאַתְּ אָמֵר (ישעיהו מ״ג:ט״ז) הַנּוֹתֵן בַּיָּם דָּרֶךְ לְאַשְׁקָאָה וּלְאַשְׁלְמָא נְהִירוּ דְּסִיהֲרָא בְּכָל סִטְרִין, (רט\"ו ע\"א) וּלְמִפְתַּח בָּהּ אֹרַח לְאַנְהָרָא לְתַתָּא.</p>\n<p>מִקְצֵה הַשָּׁמַיִם מוֹצָאוֹ, מִסַּיְיפֵי אִלֵּין שָׁמַיִם עִלָּאִין דְּקָאָמַרָן, אִיהוּ אַפִּיק, בְּגִין דִּבְסִיּוּמָא דְּגוּפָא, אִיהוּ אַפִּיק, וּבְהַהוּא אֲתָר אִשְׁתְּמוֹדַע בֵּין דְּכַר לְנוּקְבָּא. וְדָא הוּא דִּכְתִּיב, (דברים ד׳:ל״ב) וּלְמִקְצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמָיִם. קְצֵה הַשָּׁמַיִם דָּא (ר' ע\"א) עָלְמָא עִלָּאָה. וּלְמִקְצֵה הַשָּׁמַיִם, דָּא (מלכא ד) שְׁלָמָא דִּילֵיהּ. כְּמָה דְּהַאי נָטִיל כָּל נְהוֹרִין, וְכֻלְּהוּ בֵּיהּ, אוּף הָכִי הַאי, נָטִיל כָּל נְהוֹרִין, וְכֻלְּהוּ בֵּיהּ, וְאִיהוּ נָפִיק מִקְּצֵה הַשָּׁמַיִם.</p>\n<p>וּתְקוּפָתוֹ: דְּסָחֲרָא (ס\"א דסיהרא) בְּכָל אִינּוּן סִטְרִין (נ\"א ספירן) קַדִּישִׁין, דְּאִתְחָזוּן <Nonei></i>לְאִתְנָהֲרָא וּלְאִתְשָׁקָאָה וּלְנַצְּצָא מִנֵּיהּ. וְאֵין נִסְתָּר, לֵית מַאן דְּאִתְחַפְיָא מֵהַהוּא נְהִירוּ, דְּהָא לְכֻלְּהוּ אַנְהִיר בִּכְלָלָא חֲדָא, לְכָל חַד וְחַד כְּמָה דְּאִתְחָזֵי לֵיהּ.</p>\n<p>וְכַד כֻּלְּהוּ אִשְׁתְּלִימוּ וְאִתְנְהִירוּ מִגּוֹ שִׁמְשָׁא, כְּדֵין סִיהֲרָא מִתְעַטְּרָא בְּגַוְונָא דְּאִימָּא עִלָּאָה, שְׁלֵימָא בְּנ' תַּרְעִין, וְדָא אִיהוּ דִּכְתִּיב תּוֹרַת יְיָ' תְּמִימָה, דְּהָא כְּדֵין אִיהִי (שלימא) תְּמִימָה, מִכָּל סִטְרִין, בְּרָזָא דַּחֲמֵשׁ דַּרְגִּין, כְּגַוְונָא דְּאִימָא עִלָּאָה, דְּאִינּוּן חֲמֵשׁ רָזָא דְּחַמְשִׁין.</p>\n<p>וּבְגִינֵי כַּךְ, אִיהִי אַתְיָא בַּחֲמֵשׁ חֲמֵשׁ תֵּיבִין, בְּגִין לְאַשְׁלְמָא לְרָזָא דְּחַמְשִׁין. תּוֹרַת יְיָ' תְּמִימָה מְשִׁיבַת נָפֶשׁ, הָא חֲמֵשׁ. עֵדוּת יְיָ' נְאֱמָנָה מַחְכִּימַת פֶּתִי, הָא חֲמֵשׁ. פִּקּוּדֵי יְיָ' יְשָׁרִים מְשַׂמְּחֵי לֵב, הָא חֲמֵשׁ. מִצְוַת יְיָ' בָּרָה מְאִירַת עֵינַיִם, הָא חֲמֵשׁ. יִרְאַת יְיָ' טְהוֹרָה עוֹמֶדֶת לָעַד, הָא חֲמֵשׁ. מִשְׁפְּטֵי יְיָ' אֱמֶת צָדְקוּ יַחְדָּיו, הָא חֲמֵשׁ. וְכֻלְּהוּ אַתְיָין בַּחֲמֵשׁ חֲמֵשׁ, לְאִתְכַּלְּלָא כְּגַוְונָא דְּאִימָּא עִלָּאָה.</p>\n<p>וְעַל דָּא, יְהוָֹ\"ה יְהוָֹ\"ה שִׁית זִמְנִין, לָקֳבֵל שִׁית סִטְרִין עִלָּאִין, דְּאִינּוּן רָזָא דִּשְׁמָא עִלָּאָה, (נ\"א דשמיא עלאין) וְעַל דָּא, סִיהֲרָא אִתְמַלְּיָא וְאִשְׁתְּלִים בְּסִדּוּרָא עִלָּאָה כְּדְקָא יֵאוֹת, וְדָא אִיהוּ בְּיוֹמָא דְּשַׁבַּתָּא, דְּכֹלָּא אִשְׁתְּלִים כְּדְקָא יֵאוֹת, בְּרָזָא דְּשַׁבַּתָּא עֵילָּא וְתַתָּא.</p>\n<p>וְעַל דָּא בְּיוֹמָא דָּא, אִתּוֹסָף נְהִירוּ בְּכֹלָּא, כִּדְקַאמְרָן. שָׁמַיִם נַטְלֵי מִמְּקוֹרָא דְּחַיֵּי בְּקַדְמִיתָא, וְאִינּוּן מְנַהֲרֵי וּמְתַקְּנֵי לִכְבוֹד עִלָּאָה, מֵרָזָא (בראשית ל\"ה ע\"ב) דְּסֵפֶר עִלָּאָה, אַבָּא דְּכֹלָּא. וּמֵרָזָא דְּסֵפֶר, אִימָּא עִלָּאָה. וְאִיהוּ, מֵרָזָא דְּסִפּוּר. וּבְגִין כַּךְ, מְסַפְּרִים, כִּדְקַאמְרָן. בְּרָזָא דִּתְלַת שְׁמָהָן אִלֵּין, דְּשַׁלְטִין בְּיוֹמָא דְּשַׁבַּתָּא, עַל כָּל שְׁאַר יוֹמִין.</p>\n<p>וּבְגִינֵי כַּךְ תּוּשְׁבַּחְתָּא דָּא, קָאָמַר דָּוִד בְּרוּחַ קֻדְשָׁא, עַל נְהִירוּ וּנְצִיצוּ וְשׁוּלְטָנוּ (נ\"א ושלימו) דְּיוֹמָא דְּשַׁבַּתָּא עַל כָּל שְׁאַר יוֹמִין (ס\"א ותקונא דיליה דאתתקנת ביומא דא מכל שאר יומין) בְּגִין רָזָא דִּשְׁמָא עִלָּאָה, דְּקָא נָהִיר בִּנְהִירוּ, וְנָצִיץ בִּנְצִיצוּ, וְאִשְׁתְּלִים בִּשְׁלִימוּ עֵילָּא וְתַתָּא. וּכְדֵין תּוֹרַת יְיָ' תְּמִימָה, שַׁבָּת דְּמַעֲלֵי שַׁבַּתָּא, (ס\"א רזא דשמור כבוד לילה דהא היא תורת ה' תמימה תורה שבעל פה משה קבל תורה מסיני והא אתערו על תורה שבעל פה דאילו תורה שבכתב הא כתיב ויצו משרז את הלויים וגו' לקוח את ספר התורה. ודא לליואי אתחזי להאי דאחיד בשמשא ומלכא דאתייא מיניה משה נהיר לישראל מ' שנין שמשא ביומוי ותורת ה' דא מעלי שבתא) בְּרָזָא חֲדָא כִּדְקַאמְרָן.</p>"],[9520011715,"<p>וְאַתְקִינוּ (ס\"א אנשי כנסת הגדולה) חַבְרַיָּיא שֵׁירוּתָא דְּתוּשְׁבַּחְתֵּי, מֵאִינּוּן תּוּשְׁבַּחְתָן דְּדָוִד, מֵרָזָא דָּא הַשָּׁמַיִם, דְּאִיהוּ נָטִיל בְּרִישָׁא, וְנָהִיר לְכָל שְׁאָר. וּלְבָתַר הַהוּא נָהָר דְּנָפִיק מֵעֵדֶן, וְדָא אִיהוּ רָזָא, (תהילים ל״ג:א׳) רַנְּנוּ צַדִּיקִים בַּיְיָ' בְּגִין דְּהַאי נָהָר כָּנִישׁ וְנָטִיל כֹּלָּא מֵרָזָא דְּשָׁמַיִם, בְּרָזָא עִלָּאָה, וּמְקוֹרָא דְּחַיֵּי, כֹּלָּא כְּדְקָא יֵאוֹת בְּיוֹמָא דָּא. וְשִׁמְשָׁא אַתְקִין לְאַנְהֲרָא כְּדְקָא יֵאוֹת, בְּיוֹמָא דָּא.</p>"],[9520011716,"<p>וּלְבָתַר סִיהֲרָא דְּקָא מִתְפָּרְשַׁת מִסִּטְרָא אַחֲרָא בְּיוֹמָא דָּא, בְּגִין לְאִתְנָהֲרָא מִן שִׁמְשָׁא, וְדָא אִיהוּ לְדָוִד בְּשַׁנּוֹתוֹ אֶת טַעְמוֹ וְגוֹ'. וּלְבָתַר דְּאִתְפָּרְשַׁת מִנֵּיהּ, הָא אִתְחַבְּרָת בְּשִׁמְשָׁא. וְתוּשְׁבַּחְתָּא דָּא בְּכ\"ב אַתְוָון, דְּאָעִיל בָּהּ שִׁמְשָׁא בְּסִיהֲרָא. וְתוּשְׁבַּחְתָּא דָּא, פְּרִישׁוּ דְּסִיהֲרָא מִסִּטְרָא אַחֲרָא, וְתוּשְׁבַּחְתָּא דְּכ\"ב אַתְוָון בִּנְהִירוּ דְּשִׁמְשָׁא.</p>"],[9520011717,"<p>וּלְבָתַר אִתְחַבְּרוּתָא וּסְלִיקוּ דְּמַטְרוֹנִיתָא עִם בַּעְלָהּ. וְדָא אִיהוּ (תהילים צ׳:א׳) תְּפִלָּה לְמֹשֶׁה אִישׁ הָאֱלֹהִים. אִתְחַבְּרוּתָא וְאִתְדַּבְּקוּתָא דְּאִתְּתָא בְּבַעְלָהּ, לְפָרְשָׂא יְמִינָא וּשְׂמָאלָא לְקַבְּלָא לָהּ, וּלְמֶהֱוֵי כַּחֲדָא בְּחִבּוּרָא חֲדָא. (למהוי חד ברזא חד. וכל אלין שמים מספרים לון ומתקנין לון. מכאן ולהלאה תושבחן אחרנין דחדוה ותיאובתא שלימתא. אבל הני אינון תקונא שלימתא עלאה ברזא דשמא קדישא כדקא יאות ותושבחן אלין אתקינו בתקונא דשבת דאיהו סליק ואתעטר בעטרוי כדקא יאות וסלקין ברזא דשמא קדישא למהר חד ברזא דכבוד אל דשמים מספרים ליה וזהרין ליה כדקאמרן)</p>"],[9520011718,"<p>וְדָא אִיהוּ (תהילים צ״ח:א׳) מִזְמוֹר שִׁירוּ לַיְיָ' שִׁיר חָדָשׁ. תּוּשְׁבַּחְתָּא דָּא הָא (בראשית קכ\"ג ע\"ב) אוֹקִימְנָא. אֲבָל אַף עַל גַּב דְּאִתְּעַרְנָא בֵּיהּ, אַתְּעֲרוּ דְּחַבְרַיָּיא דְּקָא אִתְּעֲרוּ, שַׁפִּיר אִיהוּ, דְּהַנְהוּ <Nonei></i>פָּרוֹת עָלוֹת כַּד הֲווֹ נַטְלֵי אֲרוֹנָא, אִתְּעָרוּ בְּהַאי תּוּשְׁבַּחְתָּא, כְּמָה דְאַתְּ אָמֵר (שמואל א ו׳:י״ב) וַיִּשַּׁרְנָה הַפָּרוֹת בַּדֶּרֶךְ. וּמַה שִּׁירָה הֲווֹ אַמְרֵי. (תהילים צ״ח:א׳) מִזְמוֹר שִׁירוּ לַיְיָ' שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה. רָזָא דָּא אִיהוּ כְּגַוְונָא דִּלְעֵילָּא. בְּשַׁעֲתָא דְּאִינּוּן חַיּוֹת נַטְלֵי (ארונא) כֻּרְסְיָיא, לְאָרָמָא לֵיהּ לְעֵילָּא, אִינּוּן אַמְרֵי תּוּשְׁבַּחְתָּא דָּא.</p>\n<p>וְאִי תֵּימָא, אֲמַאי כְּתִיב הָכָא חָדָשׁ, וְהָא תָּדִיר קָאַמְרֵי תּוּשְׁבַּחְתָּא דָּא. אֶלָּא וַדַּאי חָדָשׁ אִיהוּ, וְחָדָשׁ לָא אִקְרֵי, אֶלָּא בְּאִתְּחַדְתוּתָא דְּסִיהֲרָא, כַּד אִתְנְהִירַת מִן שִׁמְשָׁא, כְּדֵין אִיהוּ חָדָשׁ, וְדָא אִיהוּ שִׁיר חָדָשׁ. הוֹשִׁיעָה לוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ, הָא אִתְּעָרוּתָא דִּימִינָא וּשְׂמָאלָא לְקַבְּלָא לָהּ.</p>\n<p>וְתוּשְׁבַּחְתָּא דָּא, כַּד נַטְלֵי אֲרוֹנָא, קָא מְשַׁבְּחָאן לָהּ. כַּד סַלְּקִין לְבֵית שֶׁמֶשׁ. כְּגַוְונָא דַּעֲגָלוֹת סַלְּקִין לְבֵית שֶׁמֶשׁ. וְכֹלָּא בְּרָזָא חַד סָלְקִין, בְּגִין דִּבְשַׁבָּת אִיהוּ סְלִיקוּ דְּכוּרְסְיָּיא, לְסַלְּקָא לְעֵילָּא. תִּקּוּנָא דְּתוּשְׁבַּחְתָּא דָּא בְּשַׁבָּת אִלֵּין תּוּשְׁבְּחָן כֻּלְּהוּ אַתְקִינוּ בְּשַׁבָּת, לְשַׁבְּחָא לֵיהּ עַמָּא יְחִידָא בְּעָלְמָא.</p>"],[9520011719,"<p>(תהילים צ״ב:א׳) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת, תּוּשְׁבַּחְתָּא דָּא, אָדָם הָרִאשׁוֹן קָאָמַר לָהּ, בְּשַׁעֲתָא דְּאִתְתָּרַךְ מִגִּנְתָּא דְּעֵדֶן, וְאָתָא שַׁבָּת וְאָגִין עָלֵיהּ. וְאוּקְמוּהָ חַבְרַיָּיא, תּוּשְׁבַּחְתָּא דָּא, עָלְמָא תַּתָּאָה קָא מְשַׁבַּח לְגַבֵּי עָלְמָא עִלָּאָה, יוֹמָא (דכלא ביה) דְּאִיהוּ כּוּלּוֹ שַׁבָּת, מַלְכָּא, דִּשְׁלָמָא דִּילֵיהּ. וְדָא אִיהוּ מִזְמוֹר שִׁיר, וְלָא כְּתִיב מַאן קָאָמַר לֵיהּ, כְּמָה דְּאוֹקִימְנָא.</p>\n<p>לְיוֹם הַשַּׁבָּת, יוֹמָא עִלָּאָה, שַׁבָּת עִלָּאָה. דָּא שַׁבָּת וְדָא שַׁבָּת, מַה בֵּין הַאי לְהַאי. אֶלָּא, שַׁבָּת סְתָם, דָּא שַׁבָּת דְּמַעֲלֵי שַׁבַּתָּא. יוֹם הַשַּׁבָּת, דָּא שַׁבָּת דִּלְעֵילָּא. דָּא יוֹם, וְדָא לַיְלָה. (שמות ל״א:ט״ז) וְשָׁמְרוּ בְנִי יִשְׂרָאֵל אֶת הַשַּׁבָּת, הָא לֵילְיָא, רָזָא דְּנוּקְבָּא. (שמותכ) זָכוֹר אֶת יוֹם הַשַּׁבָּת, הָא יוֹם, רָזָא דִּדְכוּרָא. וּבְגִין כַּךְ מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת.</p>\n<p>וְאַשְׁכְּחָן בְּכַמָּה אֲתָר, דְּעָלְמָא תַּתָּאָה לָא סָלִיק בִּשְׁמָא, וְאַתְיָא (ויקרא ק\"ב) סְתָם, כְּגוֹן הַאי, וּכְגוֹן וַיִּקְרָא אֶל מֹשֶׁה, וּכְגוֹן (שמות כ״ד:א׳) וְאֶל (קל\"א ע\"א) מֹשֶׁה אָמַר עֲלֵהּ אֶל יְיָ'. כֻּלְּהוּ סָתִים שְׁמָא, וְלָא סָלִיק בֵּיהּ. (אלא) (ס\"א וכלא) בְּגִין דְּאִית בֵּיהּ דַּרְגָּא עִלָּאָה, וּלְגַבֵּי דַּרְגָּא עִלָּאָה אִיהוּ לָא סָלִיק בִּשְׁמָא. נְהוֹרָא דִּשְׁרָגָּא, לָא סָלִיק בִּימָמָא, בִּנְהוֹרָא דְּשִׁמְשָׁא, וְעַל דָּא לָא סָלִיק בִּשְׁמָא. וְכָל אִלֵּין תּוּשְׁבְּחָן, דְּשַׁבָּת, דְּאִיהִי כְּבוֹד (נ\"א יום השבת דאיהו תושבחתא) יוֹם, אִיהוּ תּוּשְׁבַּחְתָּא עִלָּאָה, עַל כָּל שְׁאַר יוֹמִין. (ס\"א וכל אלין תושבחן אתקינו בתיקונא דשבתא דאיהו סליק לאתעטר בעטרין עלאין אתרין קדישין על כל שאר יומין)</p>"],[9520011720,"<p>נִשְׁמַת כָּל חַי, הָא חַבְרַיָּיא אִתְּעָרוּ ר\"ה בֵּיהּ מִלִּין דִּקְשׁוֹט. אֲבָל אִית לָן לְאַדְכְּרָא, הַאי נִשְׁמְתָא דְּפַרְחָא מֵהַהוּא חַי הָעוֹלָמִים. וּבְגִין דְּאִיהִי דִּילֵיהּ, דְּמִנֵיהּ נַפְקָן כָּל בִּרְכָּאן, וְשַׁרְיָין בֵּיהּ, וְהוּא אַשְׁקֵי וּמְבָרַךְ לְתַתָּא, הַאי נִשְׁמְתָא דְּנָפְקָא מִנֵּיהּ, אִית לָהּ רְשׁוּ לְבָרְכָא לְהַאי אֲתָר.</p>\n<p>וְעַל דָּא פַּרְחִין נִשְׁמָתִין מֵהַהוּא חַי, בְּמַעֲלֵי שַׁבַּתָּא. אִינּוּן נִשְׁמָתִין דְּאִינּוּן פַּרְחָאן, מַמָּשׁ מְבָרְכִין לְהַאי אֲתָר דְּאִקְרֵי שֵׁם מִתַּתָּא. וְהַהוּא אֲתָר דְּנַפְקֵי מִנֵּיהּ מְבָרַךְ לֵיהּ לְעֵילָּא, וְהַאי שֵׁם מְקַבְּלָא בִּרְכָאן, מִתַּתָּא וּמֵעֵילָּא, וְאִתְכְּלִילַת מִכָּל סִטְרִין.</p>\n<p>בְּיוֹמֵי דְּחוֹל, אִיהִי מְקַבְּלָא בִּרְכָאן, מִשְּׁאַר נִשְׁמָתִין, דְּקָא מְבָרְכִין לָהּ מִתַּתָּא. בְּיוֹמָא דְּשַׁבָּת, אִיהִי מְקַבְּלָא בִּרְכָאן מֵאִינּוּן נִשְׁמָתִין עִלָּאִין, דְּקָא מְבָרְכָאן לָהּ בְּאַרְבְּעִין וַחֲמֵשׁ תֵּיבִין, כְּחוּשְׁבָּן מ\"ה. (מנשמת כל חי עד והאחרונים) (ס\"א ברזא דחמשין תיבין, כחושבן מ\"י) כְּמָה (הקדמה ב' ע\"א) דְּאוֹקִימְנָא, בְּרָזָא מ\"ה, וּבְרָזָא מ\"י. דָּא עָלְמָא עִלָּאָה, וְדָא עָלְמָא תַּתָּאָה. נִשְׁמַת כָּל חַי (ס\"א עד האחרונים') מ\"ה. וּמִן וְאִילּוּ פִּינוּ מָלֵא שִׁירָה עַד וּמִלְּפָנִים, סַלְּקָא תּוּשְׁבַּחְתָּא אַחֲרָא חַמְשִׁין תֵּיבִין. וְאַף עַל גַּב דְּלָא קַיְּימָא תַּמָּן מִלָּה בְּחוּשְׁבָּנָא, סַלְּקָא חוּשְׁבָּנָא רָזָא מ\"י. וּמִתַּמָּן וּלְהָלְאָה סַלְּקָא תּוּשְׁבַּחְתָּא אַחֲרָא לְחֶשְׁבּוֹן (מ\"ה) מְאָה תֵּיבִין, תַּשְׁלוּמִין דְּכֹלָּא, וְחַד רְתִיכָא עַל מַה דְּשַׁרְיָא דְּאִיהוּ <Nonei></i>תַּשְׁלוּמָא (ס\"א ההוא שלימא עלאה.)</p>\n<p>וְכָל שְׁבָחָא דָּא, וְכָל מִלִּין אִלֵּין, כֻּלְּהוּ שַׁיְיפִין יְדִיעָן, בְּחוּשְׁבָּנָא לְתַשְׁלוּמָא דְּשַׁבָּת, וּלְאִשְׁתַּלְּמָא מִנַּיְיהוּ, כַּדְקָא חֲזִי. זַכָּאָה עַמָּא, דְּיַדְעֵי לְסַדְּרָא שְׁבָחָא דְמָרֵיהוֹן, כַּדְקָא יֵאוֹת. מִכָּאן וּלְהָלְאָה סִדּוּרָא דִּצְלוֹתָא כְּמָה דְּאִתְתַּקְנַת.</p>"],[9520011721,"<p>כְּתִיב (תהילים כ״ב:כ׳) וְאַתָּה יְיָ' אַל תִּרְחָק אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה. דָּוִד מַלְכָּא אָמַר דָּא, בְּשַׁעֲתָא דְּהֲוָה מְתַקֵּן וּמְסַדֵּר תּוּשְׁבַּחְתָּא דְּמַלְכָּא, בְּגִין לְחַבְּרָא שִׁמְשָׁא בְּסִיהֲרָא. כֵּיוָן דְּהֲוָה מְתַקֵּן וּמְסַדֵּר שְׁבָחִין דִּילֵיהּ לְאִתְחַבְּרָא, אָמַר וְאַתָּה יְיָ' אַל תִּרְחָק.</p>\n<p>וְאַתָּה יְיָ' רָזָא (רנ\"א ע\"א, ק\"מ ע\"א, קע\"ט ע\"ב) דְּחַבְרוּתָא חֲדָא בְּלֹא פִּרוּדָא. אַל תִּרְחָק, כֵּיוָן דְּאִיהִי סַלְּקָא לְאִתְעַטְּרָא בְּבַעְלָהּ, וְכֹלָּא בְּעָלְמָא עִלָּאָה, וּמִתַּמָּן בָּעֵי לְסַלְּקָא לְאֵין סוֹף, לְאִתְקַשְּׁרָא כֹּלָּא לְעֵילָּא לְעֵילָּא, וּבְּגִין כָּךְ אַל תִּרְחָק, לְאִסְתַּלְּקָא מִינָן, לְשַׁבְקָא לָן.</p>\n<p>וּבְגִין כַּךְ, בְּגוֹ סִדּוּרָא דְּתוּשְׁבַּחְתָּא, בָּעָאן יִשְׂרָאֵל לְאִתְכַּלְּלָא תַּמָּן, וּלְאִתְדַּבְּקָא בַּהֲדַיְיהוּ מִתַּתָּא, דְּאִלְמָלֵא יִבְעֵי לְאִסְתַּלְּקָא הַאי כָּבוֹד, הָא יִשְׂרָאֵל לְתַתָּא אֲחִידָן בֵּיהּ וְתַקְפִין בֵּיהּ, דְּלָא שַׁבְקֵי לֵיהּ לְאִתְרַחֲקָא מִנַּיְיהוּ. וְעַל דָּא צְלוֹתָא בְּלָחַשׁ, כְּמַאן דְּמַלִּיל בְּרָזָא עִם מַלְכָּא, וּבְעוֹד דְּאִיהוּ בְּרָזָא עִמֵּיהּ, לָא אִתְרָחֲקָא מִנֵּיהּ כְּלָל.</p>\n<p>אֱיָלוּתִי, מָה אַיָּל וּצְבִי, בְּשַׁעֲתָא דְּאַזְלֵי וּמְרַחֲקֵי, מִיַּד אָהַדְרָן לְהַהוּא אֲתָר דְּשַׁבְקֵי, אוּף קוּדְשָׁא בְּרִיךְ הוּא, אַף עַל גַּב דְּאִסְתַּלָּק לְעֵילָּא לְעֵילָּא בְּאֵין סוֹף, מִיַּד אַהְדָּר לְאַתְרֵיהּ. מַאי טַעְמָא. בְּגִין דְּיִשְׂרָאֵל לְתַתָּא אִתְאַחֲדָן בֵּיהּ, וְלָא שַׁבְקִין לֵיהּ לְאִתְנַשְּׁיָא, (מניה) וּלְאִתְרַחֲקָא מִנַּיְיהוּ. וְעַל דָּא, אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה.</p>\n<p>וּבְגִין כַּךְ בָּעֵינָן לְאִתְאַחֲדָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְאַחֲדָא בֵּיהּ, כְּמַאן דְּאַמְשִׁיךְ מֵעֵילָּא לְתַתָּא, דְּלָא יִשְׁתְּבַק בַּר נָשׁ מִנֵּיהּ, אֲפִילּוּ שַׁעֲתָא חֲדָא. וְעַל דָּא כַּד סָמִיךְ גְּאוּלָה לִתְפִלָּה, בָּעֵי לְאַחֲדָא בֵּיהּ, וּלְאִשְׁתָּעֵי בַּהֲדֵיהּ בִּלְחִישׁוּ, בְּרָזָא, דְּלָא יִתְרְחַק מִינָן, וְלָא יִשְׁתְּבַּק מִינָן, וְעַל דָּא כְּתִיב (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלֹהֵיכֶם חַיִּים כֻּלְכֶם הַיּוֹם. (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ אַשְׁרֵי הָעָם שֶׁיְיָ' אֱלֹהָיו.</p>\n<p>בְּהַהִיא שַׁעֲתָא, קָם רַבִּי שִׁמְעוֹן וְחַבְרַיָּא אוּף הָכִי קָמוּ וְאָזְלוּ. אָמַר רַבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אֲבוּי, אַבָּא, עַד הָכָא הֲוֵינָא יַתְבֵי בְּצִלָּא דְּאִילָנָא דְּחַיֵּי בְּגִנְתָּא דְּעֵדֶן. מִכָּאן וּלְהָלְאָה דְּאֲנָן אָזְלִין, אִצְטְרִיךְ לָן לְמֵיהַךְ בְּאָרְחוֹי דְּנַטְרָן אִילָנָא דָּא. אָמַר לֵיהּ, אַנְתְּ תִּשְׁרֵי בְּשֵׁירוּתָא לְמִפְתַּח בְּאָרְחָא.</p>"],[9520011722,"<p>פָּתַח וְאָמַר, (שמות כ״ה:ב׳) וְיִקְחוּ לִי תְּרוּמָה, כְּמָה דְּאִתְּמַר. בְּמַאי אִיהִי תְּרוּמָה. בְּרָזָא דְּזָהָב, דְּהָא מִתַּמָּן אִתְּזְנַת בְּקַדְמִיתָא, בְּגִין דְּאִיהִי גְּבוּרָה תַּתָּאָה, דְּאַתְיָא מִסִּטְרָא דְּזָהָב. וְאַף עַל גַּב דְּאַתְיָא מִסִּטְרָא דְּזָהָב, כָּל עִקָר לָא אִשְׁתְּאָרַת, אֶלָּא בְּסִטְרָא דְּכֶסֶף, דְּאִיהוּ יְמִינָא.</p>\n<p>וְרָזָא דָּא (הקדמה א' ע\"א) כּוֹס שֶׁל בְּרָכָה, דְּאִצְטְרִיךְ לְקַבְּלָא לֵיהּ בִּימִינָא וּבִשְׂמָאלָא, וְכָל עִקָּר לָא אִשְׁתְּאַר אֶלָּא בִּימִינָא. (ס\"א ושמאלא אתעדי מינה ולא וכו') וּשְׂמָאלָא אִתְּעַר יְמִינָא, וְלָא אִתְדְּבַק בֵּיהּ, בְּגִין דְּאִיהוּ אִתְיְיהִיב בֵּין יְמִינָא וּשְׂמָאלָא, וּשְׂמָאלָא אִתְאֲחִיד תְּחוֹתֵיהּ, וִימִינָא אִתְאֲחִיד בֵּיהּ לְעֵילָּא, כְּמָה דְאַתְּ אָמֵר (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. זָהָב וָכֶסֶף, כְּמָה דְאַתְּ אָמֵר (חגי ב׳:ח׳) לִי הַכֶּסֶף וְלִי הַזָּהָב, וְהָא אִתְּמַר.</p>\n<p>וּנְחוֹשֶׁת, דָּא אִיהוּ גּוָֹון כְּגַוְונָא דְּזָהָב, בְּגִין דְּאִצְטְבְּעַ מִגָּוֶון זָהָב וּמִגָּוֶון דְּכֶסֶף. וְעַל דָּא מִזְבַּח הַנְּחֹשֶׁת קָטָן. אֲמַאי אִיהוּ קָטָן. כְּמָה דְאַתְּ אָמֵר (מלכים א ח׳:ס״ד) כִּי הַמִּזְבֵּחַ אֲשֶׁר לִפְנֵי יְיָ' קָטֹן מֵהָכִיל אֶת הָעוֹלָה וְגוֹ'. כְּמָה דְאַתְּ אָמֵר (שמואל א י״ז:י״ד) וְדָוִד הוּא הַקָּטָן. וְאַף עַל גַּב דְּאִיהוּ קָטָן, כֹּלָּא אִתְאֲחִיד בְּגַוֵּיהּ. וְאִי תֵּימָא מִזְבֵּחַ אַחֲרָא, אִקְרֵי קָטָן. לָאו הָכִי. דְּלָאו קָטָן בַּר הַאי, דִּכְתִּיב, (בראשית א׳:ט״ז) אֶת הַמָּאוֹר הַגָּדוֹל לְמֶמְשֶׁלֶת הַיּוֹם וְאֶת הַמָּאוֹר הַקָּטָן לְמֶמְשֶׁלֶת הַלַּיְלָה. וְדָא אִיהוּ הַמָּאוֹר הַקָּטָן. הַמָּאוֹר הַגָּדוֹל, דָּא מִזְבֵּחַ הַפְּנִימִי דְּאִיהוּ מִזְבַּח הַזָּהָב.</p>\n<p>וּתְכֵלֶת <Nonei></i>דָּא אִיהוּ תְּכֵלֶת דְּצִיצִית. תְּכֵלֶת דָּא אִיהוּ כֻּרְסְיָיא, רָזָא דִּתְפִלָּה דְּיַד. תְּכֵלֶת דָּא אִיהוּ כֻּרְסְיָיא, דְּדַיְינִין בֵּיהּ דִּינִי נְפָשׁוֹת. בְּגִין דְּאִית כֻּרְסְיָיא דְּדַיְינִין בֵּיהּ דִּינִי מָמוֹנוֹת, וְאִית כֻּרְסְיָיא דְּדַיְינִין בֵּיהּ דִּינֵי נְפָשׁוֹת. וְעַל דָּא, כָּל גַּוְונִין (קל\"ה ע\"א, קנ\"ב ע\"א, בראשית נ\"א ע\"ב) טָבִין לְחֶלְמָא, בַּר גּוָֹון תִּכְלָא, בְּגִין דְּיִנְדַּע דְּהָא נִשְׁמָתֵיהּ סָלְקָא בְּדִינָא. וְכַד נִשְׁמְתָא סָלְקָא בְּדִינָא, גּוּפָא אִתְּדָן לְאִשְׁתְּצָאָה וְאִצְטְרִיךְ הַהוּא חֶלְמָא, לְרַחֲמִין סַגִּיאִין.</p>\n<p>תְּכֵלֶת דָּא אִיהוּ כֻּרְסְיָיא, דִּכְתִּיב בֵּיהּ (יחזקאל א׳:כ״ו) כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא, (וכתיב ואש מתלקחת) וּכְתִיב וְנֹגַהּ לוֹ סָבִיב. בְּגִין דְּעַבְדִין בֵּיהּ כְּרִיכִין לְצִיצִית, וְכַד נֹגַהּ לוֹ, אִתְהַדָּר לְגָוְון יָרוֹק, כְּגָוֶן כַּרְתִּי. מֵהַהִיא שַׁעֲתָא וְאֵילֵךְ, אִשְׁתְּרֵי זִמְנָא דִּקְרִיאַת שְׁמַע, דְּהָא אִשְׁתָּנִי גּוָֹון תִּכְלָא מִכְּמַה דְּהֲוָה, וּבְגִין כַּךְ אָסִיר לְמֵידָן דִּינֵי נְפָשׁוֹת בַּלַּיְלָה, בְּגִין דְּשָׁלְטָא הַהוּא גּוָֹון תִּכְלָא בְּהַהוּא זִמְנָא, וְאִתְיְהִיב רְשׁוּ לְמֶחטַף נַפְשָׁא בְּלֹא מִשְׁפָּט. דְּהָא מִשְׁפָּט לָא שָׁלְטָא בְּהַהוּא זִמְנָא.</p>\n<p>כַּד אָתֵי צַפְרָא, וְאִתְּעַר יְמִינָא דִּלְעֵילָּא, נָפִיק הַהוּא נְהוֹרָא, וּמָטֵי עַד הַאי תִּכְלָא, וְאִשְׁתָּנֵי מִכְּמַה דְּהֲוָה, וּכְדֵין שָׁלְטָא עָלֵיהּ, וְאִתְדַּבָּק בֵּיהּ כֻּרְסְיָיא אַחֲרָא קַדִּישָׁא. מֵהַהִיא שַׁעֲתָא וְאֵילֵךְ, זִמְנָא דִּקְרִיאַת שְׁמַע.</p>\n<p>וְאַרְגָּמָן, דָּא כְּנוּפְיָא דִּכָלִילָא כָּל גְּוָונִין כַּחֲדָא. וְתוֹלַעַת שָׁנִי, כְּתִיב שָׁנִי, וּכְתִיב שָׁנִים, דִּכְתִּיב, (משלי ל״א:כ״א) כִּי כָל בֵּיתָה לָבוּשׁ שָׁנִים. אֶלָּא הַאי אִיהוּ גּוָֹון אִקְרֵי שָׁנִי, דְּנָטִיל כָּל גַּוְונִין בֵּיהּ, וְכֹלָּא אִיהוּ חַד, שָׁנִי וְשָׁנִים. שָׁנִים: כַּד כֻּלְּהוּ כְּלִילָן בֵּיהּ כַּחֲדָא. שָׁנִי: דְּנָפִיק מִכֻּרְסְיָיא עִלָּאָה, דְּשַׁלְּטָא עַל תְּכֵלֶת מִסִּטְרָא דִּימִינָא, וְדָא אִיהוּ אַפּוֹטְרוֹפֹּסָא דְּיִשְׂרָאֵל, דִּכְתִּיב בֵּיהּ (דניאל י׳:כ״א) מִיכָאֵל שַׂרֵכֶם. תּוֹלַעַת: דְּחֵילֵיהּ בְּפוּמֵיהּ, כַּתּוֹלַעַת, דִּמְתָּבַּר כֹּלָּא וְעֹקֵר כֹּלָּא.</p>\n<p>תּוֹלַעַת שָׁנִי וָשֵׁשׁ, תְּרֵין גַּוְונִין כַּחֲדָא, דִּימִינָא וּשְׂמָאלָא, חִיוָּר וְסוּמָק. וָשֵׁשׁ: בּוּצָא אִיהוּ. דְּשִׁית חוּטִין מִתְחַבְּרָן, וְדָא אִיהוּ דִּכְתִּיב, (דניאל י׳:ו׳) וּגְוִיָּתוֹ כְתַרְשִׁישׁ. וּבְאִלֵּין תְּרֵין, כְּלִילָן תְּרֵין אָחֲרָנִין.</p>\n<p>וְעִזִּים: גְּבוּרָאן תַּתָּאֵי דִּלְבַר, לְחַפְיָא עַל פְּנִימָאֵי. וְכֹלָּא אִצְטְרִיךְ, וְאִצְטְרִיךְ לְמֵיהַב דּוּכְתָּא לְכֹלָּא, דְּהָא מִסִּטְרָא דְּדַהֲבָא קָאַתְיָין. וְעוֹרוֹת אֵלִים מְאָדָּמִים, מְשִׁיכוּ דִּתְרֵין סִטְרִין, דִּימִינָא וּשְׂמָאלָא, לְחַפְיָיא בְּדוּכְתָּא אַחֲרָא.</p>\n<p>וְעוֹרוֹת תְּחָשִׁים, סִטְרָא חֲדָא אִית דְּרַבֵּי גּוֹ סִטְרָא אַחֲרָא בְּחוּרְבָּא, וְלָא בְּיִשּׁוּבָא אִשְׁתְּכַח, וְדָא אִיהוּ סִטְרָא דַּכְיוּ, וְאִקְרֵי תַּחַשׁ.</p>\n<p>בְּסִפְרָא דְּשְׁלֹמֹה מַלְכָּא אִית גּוֹ הַאי מִזְבַּח הַנְּחֹשֶׁת דְּקַאמְרָן, רָזִין עִלָּאִין. דְּהָא מִזְבַּח אֲדָמָה כְּתִיב, (שמות כ׳:כ״א) מִזְבַּח אֲדָמָה תַּעֲשֶׂה לִי וְגוֹ' וְדָא אִיהוּ רָזָא כְּדְקָא יֵאוֹת. נְחֹשֶׁת, כַּד שַׁלְטִין טוּרִין אַחֲרָנִין, וְאִיהִי צְרִיכָא לְמֵיזַן לוֹן, אִצְטְבַּע בְּהַאי גּוָֹון לְמֵיזַן לוֹן. וְאִינּוּן אִקְרוּן הָרֵי נְחֹשֶׁת.</p>\n<p>וְאִינּוּן (ר\"ס ע\"א) הָרֵי נְחֹשֶׁת אִתְמְשַׁךְ עָלַיְיהוּ רוּחָא חֲדָא מִגּוֹ הַאי מִזְבֵּחַ, וְכַד הַאי מִזְבֵּחַ אִסְתַּלָּק בִּסְלִיקוּ אַחֲרָא, כְּדֵין אִסְתַּלָּק אָת נ', דְּאִיהוּ מִזְבֵּחַ קַדִּישָׁא, וְאִשְׁתְּאַר רוּחָא דְּאִלֵּין טוּרֵי נְחֹשֶׁת. וְכַד הַהוּא רוּחָא אִסְתְּלִיק בְּקִיּוּמֵיהּ, אִקְרֵי תַּחַשׁ, דְּהָא אִסְתַּלָּק מִנֵּיהּ אָת נ'.</p>\n<p>וְהַאי אִתְפְּרַשׁ, לְכַמָּה רוּחִין אַחֲרָנִין, וְאִקְרוּן אוּף הָכִי, וְעַל דָּא אִקְרֵי הַהוּא עַמָּא, תַּחַשׁ. כְּמָה דְאַתְּ אָמֵר (בראשית כ״ב:כ״ד) וְאֶת (קמ\"ז ע\"ב) תַּחַשׁ וְאֶת מַעֲכָה. אִינּוּן הֲווֹ יַדְעֵי בְּהָא חַיָּה דְּמַשְׁכְּנָא, דְּאִקְרֵי עַל שְׁמֵהוֹן.</p>\n<p>וַעֲצֵי שִׁטִּים, אִלֵּין אִינּוּן רָזִין קַדִּישִׁין, דְּאִינּוּן לוּחֵי מַשְׁכְּנָא, וְאִינּוּן אִקְרוּן בְּרָזָא דִּלְהוֹן. כְּתִיב עֲצֵי שִׁטִּים עוֹמְדִים, וּכְתִיב (ישעיהו ו׳:ב׳) שְׂרָפִים עוֹמְדִים.</p>\n<p>מִכָּאן וּלְהָלְאָה שֶׁמֶן לַמָּאוֹר, מְשִׁיכוּ דִּמְשַׁח רְבוּת קַדִּישָׁא לְאַמְשָׁכָא עֲלַיְיהוּ. אַבְנֵי שֹׁהַם וְאַבְנִי מִלּוּאִים, אִלֵּין אַבְנֵי קֻדְשָׁא, יְסוֹדֵי דְּמַקְדְּשָׁא, בִּרְתִיכִין קַדִּישִׁין אִלֵּין, אִזְדַּמְּנָן בִּלְחוֹדַיְיהוּ, לְיַקֵּר וּלְשַׁבְּחָא, בִּלְבוּשׁ יְקָר, לְעַיְּינָא כַּהֲנָא בְּהוּ תַּמָּן, וּלְאַדְכְּרָא (ולברכא) תְּרֵיסַר שְׁבָטִין, וְעַל דָּא תְּרֵיסַר אֲבָנִין כְּמָה דְּאִתְּמַר.</p>\n<p>תְּלֵיסַר זִינִין אִינּוּן, בַּר י\"ב אַבְנִין יַקִּירִין אִלֵּין, וְכֻלְּהוּ סַלְּקִין לְכ\"ה אַתְוָון, <Nonei></i>בְּרָזָא עִלָּאָה דְּיִחוּדָא. וְלָקֳבֵל אִלֵּין, גָּלִיף וְאַתְקִין מֹשֶׁה, כ\"ה אַתְוָון בְּרָזָא דִּפְסוּקָא דְּיִחוּדָא, דִּכְתִּיב, (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְדוָֹד אֱלֹהֵינוּ יְדוָֹד אֶחָד. וְאִינּוּן כ\"ה אַתְוָון, גְּלִיפָן מְחַקְּקָן בְּרָזָא דִּלְעֵילָּא.</p>\n<p>יַעֲקֹב בָּעָא לְאַתְקְנָא לְתַתָּא, בְּרָזָא דְּיִחוּדָא, וְאַתְקִין בְּכ\"ד אַתְוָון, וְאִינּוּן בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וְלָא אַשְׁלִים לְכ\"ה אַתְוָון, בְּגִין דְּעַד לָא אִתְתָּקַּן מַשְׁכְּנָא. כֵּיוָן דְּאִתְתָּקַּן מַשְׁכְּנָא, וְאִשְׁתְּלִים, מִלָּה קַדְמָאָה דְּהֲוָה נָפִיק מִנֵּיה, כַּד אִשְׁתְּלִים, לָא מַלִּיל אֶלָּא בְּכ\"ה אַתְוָון, לְאַחֲזָאָה דְּהָא אִשְׁתְּלִים דָּא כְּגַוְונָא דִּלְעֵילָּא, דִּכְתִּיב, (ויקרא א׳:א׳) וַיְדַבֵּר יְיָ' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר. הָא כ\"ה אַתְוָון.</p>\n<p>וְעַל דָּא כ\"ה זִינִין לְאַשְׁלְמָא תִּקּוּנָא דְמִקְדָשָׁא (ס\"א דמשכנא) וְכָל הָנֵי אַתְוָון, אוֹקִימְנָא בְּאִינּוּן אַתְוָון גְּלִיפָן, דְּאוֹלִיפְנָא מִמַּר. וּבְגִין דְּמַשְׁכְּנָא אִשְׁתְּלִים בְּרָזִין אִלֵּין, אִקְרֵי כ\"ה, בְּיִחוּדָא דִּשְׁלִימוּ דְּמַשְׁכְּנָא, וְעַל דָּא (תהילים קמ״ה:י׳) וַחֲסִידֶיךָ יְבָרְכוּכָה כְּתִיב, רָזָא דִּשְׁלִימוּ דְּכָל מַשְׁכְּנָא וְתִקּוּנָא דִּילֵיהּ. כ\"ה, לָקֳבֵל כ\"ב אַתְוָון, וְאוֹרַיְיתָא וּנְבִיאִים וּכְתוּבִים, דְּאִינּוּן כְּלָלָא חֲדָא, וְרָזָא חֲדָא.</p>\n<p>בְּשַׁעֲתָא דְּיִשְׂרָאֵל קָא מְיַחְדֵי יִחוּדָא בְּהַאי קְרָא, בְּרָזָא דְּכ\"ה אַתְוָון, דְּאִינּוּן שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד, וּבָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, דְּאִינּוּן כ\"ד אַתְוָון, וִיכַוֵּון כָּל חַד בְּהוּ, כֻּלְּהוּ אַתְוָון מִתְחַבְּרָן כַּחֲדָא, וְסַלְּקִין בְּחִבּוּרָא חַד (ס\"א כדין אתפתחו) מ\"ט תַּרְעִין, בְּרָזָא דְּיוֹבְלָא. וּכְדֵין אִצְטְרִיךְ לְסַלְּקָא עַד וְלָא יַתִּיר. וּכְדֵין אִתְפַּתָּחוּ תַּרְעִין, וְחָשִׁיב קוּדְשָׁא בְּרִיךְ הוּא לְהַהוּא בַּר נָשׁ, כְּאִילּוּ קִיֵּים אוֹרַיְיתָא כֻּלָהּ, דְּאִיהִי אַתְיָא בְּמ\"ט פָּנִים.</p>\n<p>(בכלא) וְעַל דָּא אִצְטְרִיךְ לְכַוְּונָא לִבָּא וּרְעוּתָא בְּכ\"ה וּבְכ\"ד, וּלְסַלְּקָא לוֹן בִּרְעוּתָא דְּלִבָּא, לְמ\"ט תַּרְעִין דְּקַאמְרָן. כֵּיוָן דְּאִתְכָּוַּון בְּהַאי, יִתְכַּוָּון בְּהַהוּא יִחוּדָא דְּאָמַר מַר, שְׁמַע יִשְׂרָאֵל וּבָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד כְּלָלָא דְּכָל אוֹרַיְיתָא כֻּלָּהּ. זַכָּאָה חוּלָקֵיהּ מַאן דְּיִתְכַּוָּון בְּהוּ, דְּוַדַּאי כְּלָלָא אִיהוּ דְּכָל אוֹרַיְיתָא דְּעֵילָּא וְתַתָּא. וְדָא אִיהוּ רָזָא דְּאָדָם שְׁלֵימָא, דִּדְכַר וְנוּקְבָּא, וְרָזָא דְּכָל מְהֵימְנוּתָא.</p>\n<p>מַחֲלוֹקֶת דְּשַׁמַּאי וְהִלֵּל בְּקִימָה וּבִשְׁכִיבָה, דִּכְתִּיב, (דברים ו׳:ז׳) בְשָׁכְבְּךָ וּבְקוּמֶךָ, דְּשַׁמַּאי סָבַר בָּעֶרֶב דְּקָא כְּלִילָא נוּקְבָּא בְּשֻׁלְטָנָהָא, אִצְטְרִיךְ לְגַבֵּי נוּקְבָּא דְּקָא יַטּוּ וְיִקְרְאוּ. וּבַבֹּקֶר, דְּקָא שָׁלְטָא דְּכוּרָא בְּשׁוּלְטָנוּתָא דְּעָלְמָא עִלָּאָה, אִצְטְרִיךְ לְמֵיקָם קָמֵיהּ דִּדְכוּרָא, כְּמָה דְּאִצְטְרִיךְ בִּתְפִלָּה מְעוּמָד, וּבְכָל אֲתָר דִּדְכוּרָא אַתְיָא.</p>\n<p>וּבֵית הִלֵּל סָבַר, אִלְמָלֵא אִשְׁתְּכַח דָּא לְחוֹד וְדָא לְחוֹד, הָכִי אִצְטְרִיךְ. אֲבָל כֵּיוָן דַּאֲנָן מְחַבְּרָן לוֹן כַּחֲדָא, בְּחִבּוּרָא בְּמ\"ט פָּנִים, וּמ\"ט תַּרְעִין, לָא אִצְטְרִיכְנָא לְאַפְרְשָׁא דָּא לְחוֹד וְדָא לְחוֹד, אֶלָּא לְאַשְׁגְּחָא דְּכֹלָּא אִיהוּ חַד, בְּלָא פִּרוּדָא. וּכְמָה דְּאִזְדָּמַּן לֵיהּ לְבַר נָשׁ, הָכִי יֵימָא, דְּהָא תַּרְוַויְיהוּ בְּחִבּוּרָא חֲדָא, כְּמָה דְּנַיְחָא לוֹן, וְהָכִי אִצְטְרִיךְ לְאִתְחֲזָאָה.</p>\n<p>וְעַל דָּא דְּכוּרָא, בְּשִׁית סִטְרִין, בַּקְּרָא דִּשְׁמַע יִשְׂרָאֵל, דְּאִינּוּן שִׁית תֵּיבִין. וְנוּקְבָּא בְּשִׁית סִטְרִין בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. דְּאִינּוּן שִׁית תֵּיבִין אַחֲרָנִין, וְסַלְּקִין בְּחִבּוּרָא חֲדָא, בְּרָזָא דְּמ\"ט תַּרְעִין, וַהֲלָכָה כְּבֵית הִלֵּל בְּכָל אֲתָר.</p>"],[9520011723,"<p>רַבִּי שִׁמְעוֹן אָרִים יְדוֹי וּבָרִיךְ לְרַבִּי אֶלְעָזָר בְּרֵיהּ. פָּתַח וְאָמַר, (ישעיהו מ״א:ב׳) מִי הֵעִיר מִמִּזְרָח וְגוֹ'. הַאי קְרָא אוֹקִימְנָא וְאִתְּמַר, אֲבָל רָזָא דְּחָכְמְתָא אִיהוּ, מִ\"י רָזָא דְּעָלְמָא עִלָּאָה אִיהוּ, דְּהָא מִתַּמָּן נָפְקָא שֵׁירוּתָא, לְאִתְגַּלְיָא רָזָא דִּמְהֵימְנוּתָא, וְהָא (בהקדמה ב' ע\"א) אוֹקִימְנָא.</p>\n<p>תּוּ. מִ\"י טְמִירָא דְּכָל טְמִירִין, דְּלָא אִתְיְדַע וְלָא אִתְגַּלְּיָיא כְּלָל. גַּלֵּי יְקָרֵיהּ לְאִשְׁתְּמוֹדְעָא, מֵהַהוּא אֲתָר דְּאִקְרֵי מִזְרָח, דְּהָא מִתַּמָּן שֵׁירוּתָא דְּכָל רָזָא דִּמְהֵימְנוּתָא, וּנְהוֹרָא לְאִתְגַּלְיָיא. וּלְבָתַר צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ, דְּהָא צֶדֶק, גַּלֵּי גְּבוּרְתָּא עִלָּאָה, וְשׁוּלְטָנִיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְהַאי צֶדֶק אַשְׁלְטֵיה עַל עָלְמִין כֻּלְּהוּ, לְדַבְּרָא לוֹן, וּלְאַתְקְנָא לוֹן, כַּדְקָא יֵאוֹת. וְעַל דָּא, (ישעיהו מ״א:ב׳) יִתֵּן לְפָנָיו גּוֹיִם וּמְלָכִים יַרְדְּ, <Nonei></i>דְּהָא כָּל מַלְכִין דְּעָלְמָא, בִּרְשׁוּתָא דְּהַאי צֶדֶק קַיְימִין, כְּמָה דְאַתְּ אָמֵר (תהילים ט׳:ט׳) וְהוּא יִשְׁפּוֹט תֵּבֵל בְּצֶדֶק.</p>\n<p>תּוּ, צֶדֶק יִקְרָאֵהוּ לְרַגְלוֹ, מַאן קָרֵי לְמַאן. אֶלָּא, צֶדֶק אִיהוּ קָארֵי תָּדִיר לְאַסְפָּקְלַרְיָאה דְּנָהֲרָא, וְלָא שָׁכִיךְ לְעָלְמִין, וְצֶדֶק קָאִים תָּדִיר לְרַגְלוֹי, דְּלָא אִתְעָדֵי מִתַּמָּן, וְקָארֵי וְלָא שָׁכִיךְ, הֲדָא הוּא דִכְתִיב, (תהילים פ״ג:ב׳) אֱלֹהִים אַל דֳּמִי לָךְ אַל תֶּחרַשׁ וְאַל תִּשְׁקֹט אֵל. וְהַשְׁתָּא קוּדְשָׁא בְּרִיךְ הוּא אַנְהַר לָן אָרְחָא דָּא בְּגִינָן (ור') אֶלְעָזָר בְּרִי דְּקָרֵי לִנְהוֹרָא עִלָּאָה וְלָא שָׁכִיךְ. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. (ס\"א והשתא אלעזר ברי קרי לנהורא עלאה ולא שכיך וקודשא בריך הוא אנהר לן ארחא דא בגיניה, זכאה חולקיה וזכאה חולקיהון דצדיקיא)</p>"],[9520011724,"<p>רִבִּי אַבָּא פָּתַח קְרָא וְאָמַר, (תהילים ס״ג:א׳) מִזְמוֹר לְדָוִד בִּהְיוֹתוֹ בְּמִדְבַּר יְהוּדָה. מַאי שְׁנָא מִכָּל שְׁאָר תּוּשְׁבְּחָן, דְּלָא קָאָמַר בְּאָן אֲתָר שַׁבַּח לוֹן דָּוִד מַלְכָּא, וּמַאי שְׁנָא הָכָא דְּקָאָמַר בִּהְיוֹתוֹ בְּמִדְבַּר יְהוּדָה. אֶלָּא לָא דָּא בִּלְחוֹדוֹי, דְּהָא אוּף הָכִי נַמֵּי, (תהלים לה) בְּשַׁנּוֹתוֹ אֶת טַעְמוֹ לִפְנִי אֲבִימֶלֶךְ. (תהילים נ״ד:ב׳) בְּבֹא הַזִּיפִים. וְכֵן כֻּלְּהוּ. לְאַחֲזָאָה לְכָל בְּנֵי עָלְמָא, שְׁבָחֵיהּ דְּדָוִד, דְּאַף עַל גַּב דִּבְצַעֲרָא הֲוָה, וַהֲווּ רַדְפֵי אֲבַתְרֵיהּ, הֲוָה מִשְׁתָּדַּל לוֹמַר שִׁירִין וְתוּשְׁבְּחָן לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וְאַף עַל גַּב דִּבְרוּחַ קֻדְשָׁא הֲוָה אָמַר, רוּחַ קֻדְשָׁא לָא הֲוֵי שָׁארֵי עֲלוֹי, עַד דְּאִיהוּ אִשְׁתָּדַּל לְמִשְׁרֵי עֲלוֹי. וְכֵן בְּכָל אֲתָר, לָא שַׁרְיָא רוּחַ קֻדְשָׁא דִּלְעֵילָּא, עַד דְּיִתְּעַר עָלֵיהּ בַּר נָשׁ מִתַתָּא. וְדָוִד אַף עַל גַּב דְּקָא רַדְפֵי אֲבַתְרֵיהּ, וַהֲוָה בְּצַעֲרֵיהּ, לָא הֲוָה שָׁבִיק שִׁירִין וְתוּשְׁבְּחָן מִפּוּמֵיהּ, וּלְשַׁבְּחָא לְמָארֵיהּ עַל כֹּלָּא.</p>\n<p>וְאִי תֵּימָא, הָא דְּתָנֵינָן, (בראשית ל\"ט ע\"ב, ס\"ה ע\"א) מִזְמוֹר לְדָוִד, אוֹ לְדָוִד מִזְמוֹר, וְהָכָא שָרַת עָלֵיהּ רוּחַ קֻדְשָׁא בְּקַדְמִיתָא, בְּגִין דְּאָמַר מִזְמוֹר לְדָוִד. אֶלָּא, אִי אִיהוּ לָא הֲוָה מְכַוֵּין גַּרְמֵיהּ בְּקַדְמִיתָא, לָא שָרַת עָלֵיהּ רוּחַ קֻדְשָׁא.</p>\n<p>(נ' ע\"א, רל\"ח ע\"ב) מִזְמוֹר דָּא רוּחַ קֻדְשָׁא. אֲמַאי אִקְרֵי הָכִי. בְּגִין דְּאִיהִי, מְשַׁבַּחַת תָּדִיר לְמַלְכָּא עִלָּאָה (ס\"א דכל זמנא איהו קא משבח ומזמר ולא שכיך) דְּכָל זִמְנָא הֲוָה קָא מְשַׁבְּחָת וּמְזַמְּרָת, וְלָא שָׁכִיךְ. כֵּיוָן דְּאָתָא דָּוִד אַשְׁכַּח (ק\"ג ע\"ב) גּוּפָא מְתַּתְקְנָא כַּדְקָא יֵאוֹת, וְשָׁרַת עָלֵיהּ, וַהֲווּ מְגַלֵּי בְּהַאי עָלְמָא, לְשַׁבְּחָא וּלְזַמְּרָא לְמַלְכָּא, וְכֹלָּא, בְּגִין דְּיִתְתְּקַן הַאי עָלְמָא, כְּגַוְונָא דִּלְעֵילָּא.</p>\n<p>לְדָוִד. גְּבָר שְׁלִים בְּתִקּוּנוֹי, גְּבָר מְתָקָּנָא, גְּבָר זַכָּאָה. דָּוִד וַדַּאי דְּלָא אִשְׁתָּנֵי לְעָלְמִין. בִּהְיוֹתוֹ בְּמִדְבַּר יְהוּדָה, דָּא שְׁבָחָא דְּדָוִד, אַף עַל גַּב דִּבְצַעֲרֵיהּ הֲוָה, אַף עַל גַּב דַּהֲווֹ רַדְפֵי אֲבַתְרֵיהּ. וּמַאי תּוּשְׁבַּחְתָּא קָאָמַר. תּוּשְׁבַּחְתָּא דְּאִיהוּ רַב וְיַקִּירָא.</p>\n<p>וּשְׁבָחָא דִּילֵיהּ מַאי אִיהִי. (תהילים ס״ג:ב׳) אֱלהִים אֵלִי אַתָּה אֲשַׁחֲרֶךָּ. אֱלֹהִים סְתָם. כֵּיוָן דְּאָמַר אֱלֹהִים, אֲמַאי אֵלִי. אֶלָּא הַהוּא דַּרְגָּא דִּילֵיהּ. תְּלַת דַּרְגִּין הָכָא: אֱלהִים. אֵלִי. אַתָּה. וְאַף עַל גַּב דְּאִינּוּן תְּלַת שְׁמָהָן, חַד דַּרְגָּא אִיהוּ, בְּרָזָא דֶּאֱלהִים חַיִּים. אֱלהִים: לְעֵילָּא, אֱלהִים חַיִּים. אֵלִי: קְצֵה (בראשית א' ע\"ב) הַשָּׁמַיִם עַד קְצֵה הַשָּׁמַיִם. (קל\"ח ע\"ב) אַתָּה: דַּרְגָּא דִּילֵיהּ. וְאַף עַל גַּב דְּכֹלָּא חַד, וּבִשְׁמָא חַד סָלִיק.</p>\n<p>אֲשַׁחֲרֶךָּ, אִי כְּמַשְׁמָעוֹ דִּילֵיהּ, שַׁפִּיר. אֲבָל אֲשַׁחֲרֶךָּ, אַתְקִין נְהוֹרָא דְּנָהִיר בְּשַׁחְרוּתָא. דְּהָא נְהוֹרָא דְּקַיְּימָא בְּשַׁחְרוּתָא, לָא נָהִיר עַד דְּיִתְתַּקְנוּן לֵיהּ לְתַתָּא. וּמַאן דְּאַתְקִין נְהוֹרָא שַׁחֲרָא דָּא, אַף עַל גַּב דְּאִיהִי אוּכָמָא, זָכֵי (בראשית נ\"א ע\"ב) לִנְהוֹרָא חִוָּורָא דְּנָהִיר, וְדָא אִיהִי נְהוֹרָא אַסְפָּקָלַרְיָא דְּנָהֲרָא, וְדָא אִיהוּ בַּר נָשׁ דְּזָכֵי לְעָלְמָא דְּאָתֵי.</p>\n<p>וְרָזָא דָּא (משלי ח׳:י״ז) וּמְשַׁחֲרַי יִמְצָאֻנְנִי, וּמְשַׁחֲרַי: דִּמְתַקְּנִין נְהוֹרָא מְשַׁחֲרַי אוּכָמָא. יִמְצָאֻנְנִי, יִמְצָאוּנִי לָא כְּתִיב, אֶלָּא יִמְצָאֻנְנִי, דְּזָכֵי לִתְרֵין נְהוֹרִין. לִנְהוֹרָא דְּשַׁחֲרָא אוּכָמָא, וְלִנְהוֹרָא חִוָּורָא דְּנָהֲרָא. וְזָכֵי לְאַסְפָּקָלַרְיָאה דְּלָא נָהִיר, וּלְאַסְפָּקָלַרְיָאה דְּנָהִיר. וְדָא אִיהוּ יִמְצָאֻנְנִי. וְעַל דָּא אָמַר דָּוִד אֲשַׁחֲרֶךָּ, אַתְקִין נְהוֹרָא דְּשַׁחֲרָא אוּכָמָא, לְנַהֲרָא עָלֵיהּ נְהוֹרָא חִוָּורָא דְּנָהֲרָא.</p>\n<p>(תהילים ס״ג:ב׳) צָמְאָה לְךָ נַפְשִׁי כָּמַהּ לְךָ בְשָׂרִי, כְּמַאן דְּכָפִין לְמֵיכַל וְצָחֵי לְמִשְׁתֵּי. בְּאֶרֶץ צִיָּה וְעָיֵף בְּלִי מָיִם, בְּגִין דְּאִיהוּ מִדְבַּר, וְלָאו אִיהוּ אֲתָר דְּיִשּׁוּבָא, וְלָאו אִיהוּ אֲתָר דְּקֻדְשָׁא. <Nonei></i>וּבְגִין כַּךְ אִיהוּ אֲתָר בְּלִי מַיִם. וּכְמָה דְּאֲנָן כַּפִין וְצָחָאן לְגַבָּךְ בַּאֲתָר דָּא, כֵּן בַּקֹּדֶשׁ חֲזִיתִיךָ וְגוֹ'. וַאֲנָן כְּמָה דְּאֲנָן צָחָאן לְגַבֵּי דְּמַר, לְמִשְׁתֵּי בְּצָחוּתָא מִלּוֹי בַּאֲתָר דָּא, אוּף הָכִי צָחֵינָן לְמִשְׁתֵּי בְּצָחוּתָא מִלּוֹי, בְּבֵי מַקְדְּשָׁא, אֲתָר דְּאִקְרֵי קֹדֶשׁ. אָמַר רַבִּי שִׁמְעוֹן לְרַ' אַבָּא, מַאן דְּשָׁארִי מִלָּה הַשְׁתָּא יֵימָא.</p>"],[9520011725,"<p>פָּתַח רִבִּי אַבָּא וְאָמַר, (שמות כ״ה:ב׳) וְיִקְחוּ לִי תְּרוּמָה מֵאֵת כָּל אִישׁ וְגוֹ'. מֹשֶׁה בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אַחְמֵי לֵיהּ עוֹבָדָא דְּמַשְׁכְּנָא, הֲוָה קָשֶׁה קָמֵיהּ, וְלָא יָכִיל לְמֵיקָם בֵּיהּ, וְהָא אוּקְמוּהָ. וְהַשְּׁתָּא אִית לָן לְמִקְשֵׁי הָכָא, אִי תְּרוּמָה דָּא, יָהֲבָהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה בִּלְחוֹדוֹי, הֵיךְ יָהֲבָהּ לְאַחֲרָא, וְאָמַר דְּלִבְנֵי יִשְׂרָאֵל יִקְחוּ הַאי תְּרוּמָה.</p>\n<p>אֶלָּא וַדַּאי לְמֹשֶׁה יָהֲבָהּ, וְלָא יָהֲבָהּ לְאַחֲרָא. לְמַלְכָּא דְּהֲוָה בְּגוֹ עַמֵּיהּ, וְלָא הֲוַת מַטְרוֹנִיתָא עִמֵּיהּ דְּמַלְכָּא. כָּל זִמְנָא דְּמַטְרוֹנִיתָא לָא הֲוַת עִמֵּיהּ דְּמַלְכָּא, לָא מִתְיָּאֲשֵׁי עַמָּא בֵּיהּ, וְאִינּוּן לָא יַתְבִין לְרַחֲצָן. כֵּיוָן דְּאָתַת מַטְרוֹנִיתָא, כָּל עַמָּא חֲדָאן, וְיַתְבֵי בְּרוּחְצָּנוּ. כַּךְ בְּקַדְמִיתָא, אַף עַל גַּב דְּקוּדְשָׁא בְּרִיךְ הוּא עָבַד לוֹן נִסִּין וְאָתִין עַל יְדֵי דְּמֹשֶׁה, לָא מִתְיַאֲשֵׁי עַמָּא. כֵּיוָן דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא וְיִקְחוּ לִי תְּרוּמָה, וְנָתַתִּי מִשְׁכָּנִי בְּתוֹכְכֶם. מִיַּד אִתְיָאַשׁוּ כֻּלְּהוּ, וְחַדּוּ בְּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (במדבר ז׳:א׳) וַיְהִי בְּיוֹם כַּלֹּת מֹשֶׁה דְּנַחְתַּת כַּלַּת מֹשֶׁה לְאַרְעָא.</p>\n<p>וְאִי תֵּימָא, וַיְהִי בְּכָל אֲתָר לָאו אִיהוּ אֶלָּא לִישָׁנָא דְּצַעֲרָא, וְהָכָא כְּתִיב וַיְהִי בְּיוֹם. אֶלָּא, בְּהַהוּא יוֹמָא דִּשְׁכִינְתָּא נַחְתַּת לְאַרְעָא, אִשְׁתְּכַח מְקַטְרְגָא לְגַבָּהּ, וְחַפְיָא הַהוּא חָשׁוּךְ קְבַל לְגַבָּהּ, בְּגִין דְּלָא תֵּיחוֹת. וְתָנֵינָן, אֶלֶף וַחֲמֵשׁ מְאָה רִבּוֹא מַלְאָכִין מְקַטְרְגִין, אִשְׁתְּכָחוּ לְגַבָּהּ בְּגִין דְּלָא תֵּיחוֹת.</p>\n<p>וּבְהַהוּא זִמְנָא אִשְׁתְּכָחוּ כָּל כְּנוּפְיָא דְּמַלְאֲכֵי עִלָּאֵי קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. אָמְרוּ קַמֵּיהּ, מָארֵי דְּעָלְמָא, כָּל זִיוָא וְכָל נְהוֹרָא דִּילָן בִּשְׁכִינַת יְקָרָךְ אִיהוּ, וְהַשְׁתָּא תֵּיחוֹת לְגַבֵּי תַּתָּאֵי. בְּהַהִיא שַׁעֲתָא אִתַּתְקְפַת שְׁכִינְתָּא, וְתַבְרַת הַהוּא חָשׁוּךְ קְבַל, כְּמַאן דְּמִתְּבָּר גְּזִּיזִין תַּקִּיפִין, וְנַחְתַּת לְאַרְעָא. כֵּיוָן דְּחָמוּ כֻּלְּהוּ כַּךְ, פָּתְחוּ וְאָמְרוּ (תהילים ח׳:ב׳) יְיָ' אֲדוֹנֵינוּ מַה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ. אַדִּיר וַדַּאי, דְּתַבְרַת כַּמָה גְּזִּיזִין וְחֵילִין תַּקִּיפִין, וְנַחְתַּת לְאַרְעָא, וּשְׁלִיטַת בְּכֹלָּא. וְעַל דָּא כְּתִיב וַיְהִי, צַעֲרָא דְּקַבִּילוּ כַּמָה חַיָּילִין וּמַשִּׁירְיָין, בְּיוֹמָא דְּכַלַּת מֹשֶׁה נַחְתַּת לְאַרְעָא.</p>\n<p>וּבְגִין כַּךְ וְיִקְחוּ לִי תְּרוּמָה וְגוֹ'. וְיִקְחוּ לִי וּתְרוּמָה לָא כְּתִיב, אֶלָּא וְיִקְחוּ לִי תְּרוּמָה, לְאַחֲזָאָה דְּכֹלָּא חַד בְּלָא פִּרוּדָא. וְעוֹבָדָא דְּמַשְׁכְּנָא כְּגַוְונָא דִּלְעֵילָּא, דָּא לָקֳבֵל דָּא, לְאִתְכַּלְּלָא שְׁכִינְתָּא מִכָּל סִטְרִין עֵילָּא וְתַתָּא, הָכָא בְּהַאי עָלְמָא עוֹבָדָא דִּילֵיהּ, כְּעוֹבָדָא דְּגוּפָא, לְאִתְכַּלְּלָא רוּחָא בְּגַוֵּיהּ, וְדָא אִיהִי שְׁכִינְתָּא, דְּאִתְכְּלִילַת לְעֵילָא וְתַתָּא, וְאִיהִי רוּחַ קֻדְשָׁא.</p>\n<p>וּלְעוֹלָם אִתְמַשְּׁכָת וְעָאלַת גּוֹ רָזָא דְּגוּפָא, לְאַשְׁרָאָה מוֹחָא גּוֹ קְלִיפָא כֹּלָּא כְּמָה דְּאִתְחָזֵי. הַאי רוּחָא דְּקֻדְשָׁא, אִתְעָבִיד בְּגוּפָא, לְאִתְכַּלְּלָא בְּגַוִּיהּ רוּחַ אַחֲרָא עִלָּאָה, דָּקִיק וְנָהִיר, וְכֹלָּא הָכִי אִתְאֲחִיד וְאִתְכְּלִיל דָּא בְּדָא, וְעָאל דָּא בְּדָא, עַד דְּאִתְאֲחִיד בְּהַאי עָלְמָא, דְּאִיהוּ קְלִיפָה בַּתְרָאָה דִּלְבַר.</p>\n<p>קְלִיפָה תַּקִּיפָא אִיהִי לְגוֹ מִקְלִיפָה דְּהַאי עָלְמָא. כְּגַוְונָא דֶּאֱגוֹזָא, דְּהַאי קְלִיפָה דִּלְבַר לָאו אִיהִי תַּקִּיפָא, קְלִיפָה דְּאִיהִי לְגוֹ מִינָּהּ, אִיהִי קְלִיפָה תַּקִּיפָא. אוּף הָכִי לְעֵילָּא, קְלִיפָה תַּקִּיפָא, אִיהִי רוּחָא אַחֲרָא דְּשָׁלְטָא בְּגוּפָא. לְגוֹ מִנֵּיהּ, אִיהִי קְלִיפָה קְלִישָׁא. לְגוֹ מִנֵּיהּ מוֹחָא.</p>"],[9520011726,"<p>בְּאַרְעָא קַדִּישָׁא, מְתַתְקְנָא כֹּלָּא בְּגַוְונָא אַחֲרָא, דְּהָא קְלִיפָה תַּקִּיפָא אִתַּבְּרַת מֵהַהוּא אֲתָר, וְלָא שַׁלְטָא (קע\"ג ע\"א) בֵּיהּ כְּלַל. קְלִיפָה תַּקִּיפָא אִתַּבְּרַת תְּבִיר, (ד\"א מההוא יותר תדיר) וְאִתְפַּתְחַת מֵהַאי סִטְרָא (ס\"א עד דאתאחיד ברזא דמשכנא. בהאי עלמא קליפה בתראה איהי לכרז קליפה תקיפא איהי לגו כגוונא דא אוף הכא לעילא קליפה תקיפא איהי לבר לגו מיניה איהי קליפה קלישא ולא שלטא ביה כלל ואתפתחת מהאי סטרא) (נ\"ט ע\"ב) וּמֵהַאי סִטְרָא.</p>\n<p>וְהַהִיא פְּתִיחוּ הֲוָה בְּאַרְעָא קַדִּישָׁא, בְּכָל זִמְנָא דְּפָלְחִין פּוּלְחָנָא <Nonei></i>כְּדְקָא יֵאוֹת. כֵּיוָן דְּגָרְמוּ חוֹבִין, מְשִׁיכוּ הַהוּא פְּתִיחוּ לְהַאי סִטְרָא וּלְהַאי סִטְרָא, עַד דְּאִתְקָרָב קְלִיפָה, כֹּלָּא כַּחֲדָא. כֵּיוָן דְּאַסְתִּים קְלִיפָה לְמוֹחָא, כְּדֵין שַׁלְטָא (ר\"ג ע\"א) הַהִיא קְלִיפָה עָלַיְיהוּ וְדָחָה לוֹן לְבַר מֵהַהוּא דּוּכְתָּא.</p>\n<p>וְעִם כָּל דָּא אַף עַל גַּב דְּדָּחָה לוֹן לְבַר, לָא יָכִיל הַהִיא קְלִיפָה תַּקִּיפָא לְשַׁלְּטָאָה בְּהַהוּא דּוּכְתָּא קַדִּישָׁא, דְּלָאו אַתְרֵיהּ אִיהוּ. וְאִי תֵּימָא, אִי הָכִי, הוֹאִיל וְלָא יָכִיל הַהִיא קְלִיפָה תַּקִּיפָא לְשַׁלְּטָאָה בְּהַהוּא דּוּכְתָּא קַדִּישָׁא, אֲמַאי קַיְּימָא חָרוּב, דְּהָא חָרְבָּא לָא הֲוֵי בְּעָלְמָא, אֶלָּא מִסִּטְרָא דְּהַהִיא קְלִיפָה תַּקִּיפָא.</p>\n<p>אֶלָּא וַדַּאי כַּד אִתְחָרַב, לָא אִתְחָרַב אֶלָּא מֵהַהוּא סִטְרָא, בְּשַׁעֲתָא דְּאַסְתִּים לְמוֹחָא, וְקוּדְשָׁא בְּרִיךְ הוּא עָבֵד דְּלָא תִּשְׁלוֹט הַהִיא קְלִיפָה תַּקִּיפָא עַל הַהוּא דּוּכְתָּא. וְכַד דָּחָה לוֹן לְיִשְׂרָאֵל מִנֵּיהּ, הַהִיא קְלִיפָה אִתְהַדְּרַת וְאִתְפַּתְחַת כְּמִלְּקַדְּמִין. וּבְגִין (נ\"ח, ע\"ח ע\"ב) דְּעַמָּא קַדִּישָׁא לָא הֲווֹ תַּמָּן, חַפְיָא עַל הַהוּא פְּתִיחוּ, חוּפָּאָה קַדִּישָׁא דְּפָרוֹכְתָּא קְלִישָׁא, לְנַטְרָא הַהוּא אֲתָר, דְּלָא יִסְתּוֹם לֵיהּ הַהִיא קְלִיפָה תַּקִּיפָא, וְאָחִיד בְּכָל סִטְרוֹי.</p>\n<p>לְמֶהֱוֵי רְבוּת קֻדְשָׁא עַל אַרְעָא כְּמִלְקַדְּמִין, לָא יָכִיל, דְּהָא הַהוּא חוּפָּאָה קְלִישָׁא אָחִיד, דְּלָא יֵחוּת לְתַתָּא, דְּהָא עַמָּא קַדִּישָׁא לָאו תַּמָּן. וְעַל דָּא לָא אִתְבְּנֵי חָרְבַּן, מִיּוֹמָא דְּאִתְחֲרִיבוּ. לְשַׁלְּטָאָה הַהִיא קְלִיפָה תַּקִּיפָא, לָא יַכְלָא, דְּהָא הַהוּא חוּפָּאָה קְלִישָׁה אָחִיד בֵּיהּ בְּכָל סִטְרוֹי בְּהַהוּא פְּתִיחוּ דְּלָא תִּשְׁלוֹט תַּמָּן, וְלָא תַּסְתִּים מוֹחָא, בְּהַהוּא חוּפָּאָה דְּפָרוֹכְתָּא קְלִישָׁא, דְּאִיהוּ מִגּוֹ מְשִׁיכוּ דְּפָרוֹכְתָּא קַדִּישָׁא דִּלְעֵילָּא, דְּנָטִיר הַהוּא אֲתָר.</p>\n<p>וּבְגִין כַּךְ, כָּל אִינּוּן נִשְׁמָתִין דִּשְׁאַר עַמִּין, דְּדַיְירִין בְּאַרְעָא, כַּד נָפְקִין מֵהַאי עָלְמָא, לָא מְקַבְּלָא לוֹן, וְדָחֵי לוֹן לְבַר, וְאַזְלִין וְשָׁטָאן וּמִתְגַּלְגְּלִין בְּכַמָּה גִּלְגּוּלִין, עַד דְּנַפְקֵי מִכָּל אַרְעָא קַדִּישָׁא, וְסָחֲרָן (לסוחרנייהו) לְסִטְרַיְיהוּ, בִּמְסָאֲבוּ דִּלְהוֹן. וְכָל אִינּוּן נִשְׁמָתִין דְּיִשְׂרָאֵל דְּנָפְקִין תַּמָּן, סַלְּקִין, וְהַהוּא חוּפָּאָה קְלִישָׁא מְקַבְּלָא לוֹן, וְעָאלִין לִקְדוּשָּׁא עִלָּאָה, בְּגִין דְּכָל זִּינָא אַזְלָא לְזִינֵיהּ.</p>\n<p>וְנִשְׁמָתֵיהוֹן דְּיִשְׂרָאֵל דְּנַפְקֵי לְבַר מֵאַרְעָא, בִּרְשׁוּתָא דְּהַהִיא קְלִיפָה תַּקִּיפָא, אַזְלָא וְסָחֲרָא וּמִתְגַּלְגְּלָא, עַד דְּתָבַת לְדּוּכְתָּהָא, וְעָאלַת לַאֲתָר דְּאִתְחָזֵי לָהּ. זַכָּאָה חוּלָקֵיהּ, מַאן דְּנִשְׁמָתֵיהּ נָפְקָא בִּרְשׁוּ קַדִּישָׁא, בְּהַהוּא פְּתִיחוּ דְּאַרְעָא קַדִּישָׁא.</p>\n<p>מַאן דְּנִשְׁמָתֵיהּ נַפְקַת בְּאַרְעָא קַדִּישָׁא, אִי אִתְקְבַּר בְּהַהוּא יוֹמָא, לָא שַׁלְטָא עָלֵיהּ רוּחָא מְסַאֲבָא כְּלַל. וְעַל דָּא כְּתִיב בִּצְלִיבָא, (דברים כ״א:כ״ג) כִּי קָבוֹר תִּקְבְּרֶנּוּ בַּיוֹם הַהוּא וְלֹא תְטַמֵּא אֶת אַדְמָתְךָ. בְּגִין דִּבְלֵילְיָא אִתְיְהִיב רְשׁוּ לְרוּחַ מְסַאֲבָא לִמְשַׁטְּטָא. וְאַף עַל גַּב דְּאִתְיְהִיב לוֹן רְשׁוּ, לָא עָאלִין בְּאַרְעָא קַדִּישָׁא, בַּר אִי אַשְׁכְּחָן תַּמָּן מָנָא לְאַעֲלָא בֵּיהּ.</p>\n<p>(ק\"ל ע\"א) אֵבָרִין וּפְדָרִין דְּמִתְאַכְּלָן בְּלֵילְיָא, לְאַתְּזְנָא זִינִין אַחֲרָנִין, לָאו דְּעַיְילִין בְּאַרְעָא, וְלָא לְאַמְשָׁכָא לוֹן בְּאַרְעָא, אֶלָּא, בְּגִין דְּלָא תִּשְׁלוֹט סִטְרָא אַחֲרָא גּוֹ אַרְעָא, וְלָא יִתְמַשְׁכָא לְאַעֲלָא תַּמָּן. וּבְגִין כַּךְ, תְּנָנָא מִנַּיְיהוּ הֲוָה סָלִיק (ק\"ל ע\"א) עֲקִימָא, וּמִתְגַּלְגְּלָא לְבַר, וְאָזִיל (תקיף) בִּבְהִילוּ, עַד דְּעָאל לְנוּקְבָּא דְּצָפוֹן, דְּתַמָּן מָדוֹרִין דְּכָל סִטְרִין אַחֲרָנִין, וְתַמָּן עָאל תְּנָנָא, וְכֻלְּהוּ אִתְּזָנוּ תַּמָּן.</p>\n<p>תְּנָנָא דִּימָמָא, הֲוָה סָלִיק לְדוּכְתֵּיהּ בְּאֹרַח מֵישַׁר, וְאִתְּזָן מַה דְּאִתְּזָן. וּמֵהַהוּא פְּתִיחוּ, (ק\"ט ע\"ב) אִתְּזָנוּ כָּל סִטְרֵי קְלִיפָה תַּקִּיפָא, דְּאִיהִי לְבַר מֵאַרְעָא קַדִּישָׁא, וּמֵהַהִיא תְּנָנָא גַּסָּה כְּמָה דְּאוֹקִימְנָא.</p>\n<p>גּוּפֵיהוֹן דְּצַדִּיקַיָּיא, דְּלָא אִתְמְשָׁכוּ בְּהַאי עָלְמָא בָּתַר הֲנָאִין דְּהַהִיא קְלִיפָה תַּקִּיפָא, לָא שַׁלְטָא עָלַיְיהוּ רוּחַ מְסָאֲבוּ כְּלָל, דְּהָא לָא אִשְׁתַּתְפוּ אֲבַתְרֵיהּ כְּלוּם בְּהַאי עָלְמָא. כְּמָה דְּגוּפָא דְּרַשִׁיעַיָּיא (נ\"א גופיהון דצדיקייא דלא אתמשכו בתר הנאין וכסופין דהאי עלמא ההיא קליפה תקיפא לא שלטא עלייהו דהא לא אתמשכו אבתריה בהאי עלמא דהא כמה דגופיה דרשיעיא) אִתְמְשָׁךְ בְּהַאי עָלְמָא בָּתַר הַהִיא קְלִיפָה תַּקִּיפָא, וַהֲנָאִין וְעִנּוּגִין דִּילֵיהּ וְתִיקּוּנִין דִּילֵיהּ, הָכִי אִסְתְּאָב, בָּתַר דְּנַפְקָת נִשְׁמָתֵיהּ מִנֵּיהּ.</p>\n<p>גּוּפֵיהוֹן דְּצַדִּיקַיָּא, דְּלָא מִתְעַנְּגֵי בְּהַאי <Nonei></i>עָלְמָא, אֶלָּא מִתַּעֲנוּגֵי דְּמִצְוָה, וּסְעוּדָתֵי שַׁבָּתִין וְחַגִּין וּזְמָנִין, הַהוּא רוּחַ מְסַאֲבָא לָא יָכִיל לְשַׁלְטָאָה עָלַיְיהוּ, דְּהָא לָא אִתְעֲנְּגוּ מִדִילֵיהּ כְּלוּם. וְהוֹאִיל וְלָא נַטְלוּ מִדִילֵיהּ, לֵית לֵיהּ רְשׁוּ עֲלֵיהוֹן כְּלַל. זַכָּאָה אִיהוּ מַאן דְּלָא אִתְהֲנֵי מִדִילֵיהּ כְּלוּם.</p>\n<p>מַאן דְּנִשְׁמָתֵיהּ נָפְקָא לְבַר מֵאַרְעָא קַדִּישָׁא, וְהַהוּא גּוּפָא אִסְתְּאַב בְּהַהוּא רוּחַ מְסָאֲבוּ, הַהוּא רוּחַ מְסָאֲבוּ אִשְׁתְּאִיב בְּגַוִּיהּ, עַד דְּתָב לֵיהּ עַפְרָא. (נ\"א דאתבלי גופא בעפרא) וְאִי הַהוּא (ויקרא ע\"ב ע\"ב) גּוּפָא, דְּאִשְׁתְּאִיב בֵּיהּ הַהוּא רוּחַ מְסַאֲבָא, סַלְּקִין לֵיהּ לְאִתְקַבְּרָא גּוֹ אַרְעָא קַדִּישָׁא, עָלֵיהּ כְּתִיב, (ירמיהו ב׳:ז׳) וַתָּבֹאוּ וַתְּטַמְּאוּ אֶת אַרְצִי וְנַחֲלָתִי שַׂמְתֶּם לְתוֹעֵבָה. אַרְצִי, דְּלָא שַׁלְטָא עָלָהּ רוּחַ מְסָאֲבוּ, בְּהַהוּא גּוּפָא דִּלְכוֹן, דְּאִשְׁתְּאִיב בֵּיהּ רוּחַ מְסָאֲבוּ, דְּקָא מַיְיתִין לְקָבְרָא לֵיהּ בְּאַרְצִי, אַתּוּן מְסָאָבִין לָהּ, לְאִסְתָּאֲבָא בֵּיהּ. אִי לָא דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא אַסְוָותָא לְאַרְעָא, דְּהָא כֵּיוָן דְּאִתְבַּלֵי הַהוּא גּוּפָא, נָשִׁיב קוּדְשָׁא בְּרִיךְ הוּא רוּחָא מִלְּעֵילָּא, וְדָחֵי לֵיהּ לְהַהוּא רוּחַ מְסַאֲבָא לְבַר, דְּהָא אִיהוּ חָס עַל אַרְעֵיהּ.</p>\n<p>יוֹסֵף, לָא שַׁלִּיט עַל גּוּפֵיהּ רוּחַ מְסַאֲבָא לְעָלְמִין, אַף עַל גַּב דְּנִשְׁמָתֵיהּ נָפְקָת בִּרְשׁוּ אַחֲרָא. מַאי טַעְמָא. בְּגִין דְּלָא אִתְמְשִׁיךְ בְּחַיּיוֹי בָּתַר רוּחַ מְסַאֲבָא. וְעִם כָּל דָּא, לָא בָּעָא דְּגוּפֵיהּ יְסַלְּקוּן לֵיהּ לְאִתְקַבְּרָא בְּאַרְעָא קַדִּישָׁא, אֶלָּא אָמַר, (בראשית נ׳:כ״ה) וְהַעֲלִיתֶם אֶת עַצְמוֹתַי, וְלָא גּוּפִי.</p>\n<p>יַעֲקֹב לָא מִית, וְגוּפֵיהּ אִתְקָיָּים בְּקִיּוּמָא תָּדִיר, וְלָא דָּחִיל לְסִטְרָא אַחֲרָא, דְּהָא עַרְסֵיהּ הֲוָה שְׁלִים, בִּשְׁלִימוּ דִּנְהוֹרָא עִלָּאָה, בִּנְהִירוּ דִּתְרֵיסָר שְׁבָטִין, וּבְשִׁבְעִים נֶפֶשׁ, בְּגִין כַּךְ לָא דָּחִיל לְסִטְרָא אַחֲרָא, וְלָא יָכִיל לְשַׁלְּטָאָה עָלֵיהּ. וְתוּ, דְּאִיהוּ גּוּפָא דְּדִיּוּקְנָא עִלָּאָה, דִּשְׁפִּירוּ דִּילֵיהּ אָחִיד לְכָל סִטְרִין, וְכָל אִינּוּן שַׁיְיפִין דְּאָדָם קַדְמָאָה הֲווֹ אֲחִידָן בֵּיהּ. וְעַל דָּא כְּתִיב בֵּיהּ, (בראשית מ״ז:ל׳) וְשָׁכַבְתִּי עִם אֲבוֹתַי וּנְשָׂאתַנִי מִמִּצְרַיִם, גּוּפָא שְׁלִים. וְעַל דָּא וַיַּחַנְטוּ הָרוֹפְאִים אֶת יִשְׂרָאֵל, דְּגוּפֵיהּ יְהֵא קָאִים בְּקִיּוּמָא. וְהָכִי אִצְטְרִיךְ. שְׁאַר בְּנֵי עָלְמָא דְּנַפְקָת נִשְׁמָתַיְיהוּ בְּאַרְעָא קַדִּישָׁא, נַפְשָׁא וְגוּפָא אִשְׁתֵּזִּיב מִכֹּלָּא.</p>"],[9520011727,"<p>תְּלַת שְׁמָהָן אִקְרֵי נִשְׁמְתָא דְּבַר נָשׁ, נֶפֶשׁ, רוּחָא, וְנִשְׁמָתָא. וְכֻלְּהוּ כְּלִילָן דָּא בְּדָא, וּבִתְלַת דּוּכְתֵּי אִשְׁתְּכַח חֵילַיְיהוּ. נֶפֶשׁ דָּא, אִשְׁתְּכַחַת גּוֹ קִבְרָא, עַד דְּגוּפָא אִתְבְּלֵי בְּעַפְרָא, וּבְדָא מִתְגַּלְגְּלָת הַאי עָלְמָא, לְאִשְׁתַּכְּחָא גּוֹ חַיַּיָא, וּלְמִנְדַּע בְּצַעֲרָא דִּלְהוֹן, וּבְשַׁעֲתָא דִּי אִצְטְרִיכוּ, בָּעָאת רַחֲמֵי עָלַיְיהוּ.</p>\n<p>רוּחָא דָּא, אִיהוּ דְּעָאל בְּגִּנְתָּא דִּי בְּאַרְעָא, וְאִצְטַיָיר תַּמָּן, בְּדִיּוּקְנָא דְּגוּפָא דְּהַאי עָלְמָא, בְּחַד מַלְבּוּשָׁא דְּמִתְלַבְּשָׁא תַּמָּן. וְדָא אִתְהֲנֵי תַּמָּן בַּהֲנָאִין וְכִסּוּפִין בְּזִיוָא דִּבְגִּנְתָּא. וּבְשַׁבָּתֵי וְיַרְחֵי וּזְמָנֵי, סַלְּקָא לְעֵילָּא, (קל\"ו ע\"א, צ\"ט ע\"ב) וְאִתְהֲנֵי תַּמָּן, וְתָב לְאַתְרֵיהּ. וְעַל דָּא כְּתִיב, (קהלת י״ב:ז׳) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. תָּשׁוּב וַדַּאי, בְּהָנֵי זִמְנִין דְּקַאמְרָן.</p>\n<p>נְשָׁמָה אִיהִי סַלְּקָא מִיָּד לְאַתְרָהָא, לְהַהוּא אֲתָר דְּנַפְקָת מִתַּמָּן, וְדָא אִיהִי דִּבְגִינָהּ אִתְנְהִירַת בּוּצִינָא, לְאַנְהָרָא לְעֵילָּא. דָּא לָא נַחְתַּת לְתַתָּא לְעָלְמִין, בְּדָא אִתְכְּלִילַת, מַאן דְּאִתְכְּלִילַת מִכָּל סִטְרִין מֵעֵילָּא וּמִתַּתָּא. וְעַד דְּהַאי לָא סַלְּקָא לְאִתְקַשְּׁרָא (נ\"א בדוכתהא) בְּכוּרְסְיָּיא, לָא מִתְעַטְּרָא רוּחַ בְּגִּנְתָּא דִּי בְּאַרְעָא, וְנֶפֶשׁ לָא מִתְיַשְּׁבָא בְּדוּכְתָּהָא. כֵּיוָן דְּאִיהִי סַלְּקָא, כֻּלְּהוּ אִית לְהוּ נַיְיחָא.</p>\n<p>וְכַד אִצְטְרִיךְ לִבְנֵי עָלְמָא, כַּד אִינּוּן בְּצַעֲרָא, וְאָזְלֵי לְבֵי קִבְרֵי, הַאי נֶפֶשׁ אִתְּעָרַת, וְאִיהִי אַזְלָא וּמְשַׁטְּטָא, וְאִתְּעָרַת לְרוּחַ, וְהַהוּא רוּחַ אִתְּעַר לְגַבֵּי אֲבָהָן, וְסָלִיק וְאִתְּעַר לְגַבֵּי נְשָׁמָה, וּכְדֵין, קֻדְשָׁא בְּרִיךְ הוּא חַיִּיס עַל עָלְמָא, וְהָא אוֹקִימְנָא. וְאַף עַל גַּב דְּהָא אִתְּעָרוּ מִלִּין אִלֵּין דְּנִשְׁמְתָא בִּגְוָונִין אַחֲרָנִין, כֻּלְּהוּ סַלְּקִין בְּמַתְקְלָא, דָּא, וְדָא אִיהוּ בְּרִירָה דְּמִלָּה, וְכֹלָּא חַד.</p>\n<p>וְכַד נִשְׁמְתָא אִתְעַכְּבָת מִלְסַלְּקָא לְדוּכְתָּהָא, רוּחָא אַזְלָא וְקַיְּימָא בְּפִתְחָא דְּגִּנְתָּא דְּעֵדֶן, וְלָא פַּתְחִין לָהּ פִּתְחָא, <Nonei></i>וְאָזְלָא וּמְשַׁטְּטָא, וְלֵית מַאן דְּיִשְׁגַּח בָּהּ. נֶפֶשׁ אַזְלָא וּמְשַׁטְּטָא בְּעָלְמָא, חָמָאת לְגוּפָא דְּסַלְּקָא תּוֹלָעִין, וּבְהַהוּא דִּינָא דְּקִבְרָא, וּמִתְאַבְּלָת עָלֵיהּ, כְּמָה דְּאוּקְמוּהָ דִּכְתִּיב, (איוב י״ד:כ״ב) אַךְ בְּשָׂרוֹ עָלָיו יִכְאָב וְנַפְשׁוֹ עָלָיו תֶּאֱבָל. וְכֹלָּא אִיהוּ בְּעוֹנְשָׁא. עַד דִּנְשָׁמָה אִתְקָשָׁרַת בְּדוּכְתָּהָא לְעֵילָּא, וּכְדֵין כּוּלְּהוּ מִתְקַשְּׁרִין בְּדוּכְתַּיְיהוּ.</p>\n<p>בְּגִין דְּכָל הָנֵי תְּלַת, קִשּׁוּרָא חֲדָא אִינּוּן, כְּגַוְונָא דִּלְעֵילָּא, בְּרָזָא דְּנֶפֶשׁ רוּחַ וּנְשָׁמָה, דְּכֹלָּא חַד, וְקִשּׁוּרָא חַד. נֶפֶשׁ: לֵית לָהּ נְהוֹרָא מִגַּרְמָהּ כְּלוּם, וְדָא אִיהוּ דְּמִשְׁתַּתְּפָא בְּרָזָא דְּגוּפָא חַד, לְאַעְנְגָא וּלְמֵיזָן לֵיהּ, בְּכָל מָה דְּאִצְטְרִיךְ, כְּמָה דְאַתְּ אָמֵר (משלי ל״א:ט״ו) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. בֵּיתָה, דָּא אִיהוּ גּוּפָא, דְּאִיהִי זָנָא לֵיהּ. וְנַעֲרוֹתֶיהָ, אִלֵּין אִינּוּן שַׁיְיפִין דְּהַאי גּוּפָא.</p>\n<p>רוּחַ: דָּא אִיהוּ דְּרָכִיב עַל הַאי נֶפֶשׁ, וְשָׁלִיט עָלָהּ, וְנָהִיר לָהּ בְּכָל מָה דְּאִצְטְרִיךְ, וְנֶפֶשׁ אִיהוּ כֻּרְסְיָּיא לְהַאי רוּחַ. נְשָׁמָה: אִיהִי דְּאַפִּיקַת לְהַאי רוּחָא, וּשְׁלִיטַת עֲלֵיהּ, וְנָהִירַת לֵיהּ בְּהַהוּא נְהוֹרָא דְּחַיִּין, וְהַהוּא רוּחַ תַּלְיָא בְּהַאי נְשָׁמָה, וְאִתְנְהִיר מִנָּהּ בְּהַהוּא נְהוֹרָא דְּנָהִיר. הַהוּא נְפֶשׁ, תַּלְיָא בְּהַאי רוּחַ, וְאִתְנְהִירַת מִנֵּיהּ, וְאִתְּזָנַת מִנֵּיהּ, וְכֹלָּא קִשּׁוּרָא חַד.</p>\n<p>וְעַד דְּהַאי נְשָׁמָה עִלָּאָה, לָא סַלְּקָא גּוֹ נְבִיעוּ דְּעַתִּיקָא דְּעַתִּיקִין. סְתִימָא דְּכָל סְתִימִין, וְאִתְמַלְיָא מִנֵּיהּ, בְּגִין דְּלָא פָּסִיק. רוּחַ דָּא לָא עָאל בְּגִּנְתָּא דְּעֵדֶן, דְּאִיהוּ נֶפֶשׁ, וּלְעוֹלָם רוּחַ לָא שַׁרְיָא אֶלָּא בְּגִּנְתָּא דְּעֵדֶן, וּנְשָׁמָה לְעֵילָּא. נֶפֶשׁ דָּא אִתְיַשְׁבָת (ס\"א לא אתישבת) בְּדוּכְתָּהָא גּוֹ גּוּפָא לְתַתָּא.</p>\n<p>כְּגַוְונָא דָּא, כֹּלָּא לְתַתָּא הָכִי מִתְפָּרְשָׁן בְּבַר נָשׁ, וְאַף עַל גַּב דְּכֻלְּהוּ קִשּׁוּרָא חֲדָא, נְשָׁמָה סַלְּקָא לְעֵילָּא, גּוֹ נְבִיעוּ דְּבֵירָא. רוּחַ עָאל בְּגִּנְתָּא דְּעֵדֶן, (ויקרא ע' ע\"ב) כְּגַוְונָא דִּלְעֵילָּא. נֶפֶשׁ אִתְיַשְׁבָא גּוֹ קִבְרָא. וְאִי תֵּימָא, נֶפֶשׁ לְעֵילָּא, דְּאִתְיַשְׁבַת גּוֹ גּוּפָא בְּקִבְרָא, אָן הוּא קִבְרָא. אֶלָּא גּוֹ הַהוּא קְלִיפָה תַּקִּיפָא, וְעַל דָּא, נֶפֶשׁ כְּגַוְונָא דָּא לְתַתָּא, וְכֹלָּא דָּא כְּגַוְונָא דָּא. וּבְגִין כַּךְ, תְּלַת דַּרְגִּין מִתְפָּרְשָׁן, וְאִינּוּן קִשּׁוּרָא חֲדָא וְרָזָא חֲדָא.</p>\n<p>וּבְכָל זִמְנָא דְּגַרְמֵי אִשְׁתְּכָחוּ גּוֹ קִבְרָא, הַאי נֶפֶשׁ אִשְׁתְּכָחַת תַּמָּן. רָזָא הָכָא לְאִינוּן דְּיַדְעֵי אֹרַח קְשׁוֹט, דַּחֲלֵי חַטָּאָה. בְּשַׁעֲתָא דְּנִשְׁמְתָא מִתְעַטְּרָא לְעֵילָּא, גּוֹ עִטְרָא קַדִּישָׁא, וְרוּחָא קָאִים בִּנְהִירוּ עִלָּאָה, בְּשַׁבָּתֵי וְיַרְחֵי וּזְמָנֵי, הַאי נֶפֶשׁ בְּשַׁעֲתָא דְּרוּחַ נַחְתָּא מִגּוֹ נְהִירוּ עִלָּאָה, לְדַיָּירָא בְּגִּנְתָּא דְּעֵדֶן נָהִיר וְנָצִיץ, אִיהוּ (ד\"א ל\"ג כ\"ד) קַיָּימָא גּוֹ קִבְרָא וְאִתְגְלִימַת בְּדִיּוּקְנָא, דַּהֲוַת גּוֹ גּוּפָא בְּקַדְמִיתָא, וְכָל אִינּוּן גַּרְמֵי בְּהַהוּא דִּיּוּקְנָא סַלְקָן, וּמְשַׁבְּחָאן וְאוֹדָן לְקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (תהילים ל״ה:י׳) כָּל עַצְמוֹתַי תֹּאמַרְנָה יְיָ' מִי כָמוֹךָ. אוֹמְרוֹת לָא כְּתִיב, אֶלָּא תֹּאמַרְנָּה.</p>\n<p>וְאִלְמָלֵי אִתְיְהִיב רְשׁוּ לְעֵינָא לְמֵחמֵי וְחָמֵי בְּלֵילְיָא דְּעָיִיל (נ\"א דנפיק) שַׁבְּתָא, וְלֵילֵי יַרְחֵי וּזְמָנֵי, כְּדִיּוּקְנִין עַל גַּבֵּי קִבְרֵי, אוֹדָן וּמְשַׁבְּחָן לְּקוּדְשָׁא בְּרִיךְ הוּא. אֲבָל טִפְּשׁוּ דִּבְנֵי נָשָׁא, קָא מְעַכְּבָא לְהוּ, דְּלָא יַדְעִין, וְלָא מַשְׁגִּיחִין עַל מָה קַיְימִין בְּהַאי עָלְמָא, וְלָא חַשְׁשִׁין לְאַשְׁגְּחָא בִּיקָרָא דְּמַלְכָּא עִלָּאָה בְּהַאי עָלְמָא, כָּל שֶׁכֵּן לְאַשְׁגְּחָא בִּיקָרָא דְּהַהוּא עָלְמָא, וְעַל מָה קַיְּימָא, וְאֵיךְ מִתְפָּרְשָׁן מִלִּין.</p>\n<p>בְּיוֹמָא דְּרֹאשׁ הַשָּׁנָה, דְּעָלְמָא אִתְּדָּן, וְכֻרְסְיָא דְּדִינָא קַיְּימָא, לְגַבֵּי מַלְכָּא עִלָּאָה, לְמֵידָן עָלְמָא. כָּל נֶפֶשׁ וְנֶפֶשׁ מְשַׁטְטָן, וּבָעָאן רַחֲמֵי עַל חַיֵּי. בְּלֵילְיָא דְּנָפְקָא יוֹמָא דְּדִינָא, אַזְלִין וְקָא מְשַׁטְטִין לְמִשְׁמַע וּלְמִנְדַּע מַאן הוּא דִּינָא דְּאִתְּדָּן עַל עָלְמָא, וּלְזִמְנִין דְּקָא מוֹדִיעִין בְּחֶזְוָוא לְחַיָּיָא, כְּמָה דְאַתְּ אָמֵר (איוב ל״ג:ט״ו) בַּחֲלוֹם חֶזְיוֹן לַיְלָה בִּנְפוֹל תַּרְדֵּמָה עַל אֲנָשִׁים וְגוֹ', אָז יִגְלֶה אֹזֶן אֲנָשִׁים וּבְמוֹסָרָם יַחְתּוֹם. מַאי מוֹסָרָם. דָּא נֶפֶשׁ, דְּאִיהִי קַיְּימָא וְחָתִים לִבְנֵי נָשָׁא מִלִּין, לְקַבְּלָא מוּסָר. (ויחי רכ\"א)</p>\n<p>בְּלֵילְיָא בַּתְרָאָה דְּחַגָּא, דְּקָא נַפְקָן פִּתְקִין מִבֵּי מַלְכָּא, וְהַהוּא צֵל אַעְדִּיאוּ מִבְּנֵי גְּרִיעוּ דְּהַאי עָלְמָא, הַהוּא נֶפֶשׁ דְּקַאמָרָן, אַזְלָא <Nonei></i>וּמְשַׁטְּטָא, (קכ\"ט ע\"א) וְחַד מְמָנָא סָרְכָא, בְּרָזָא גְּלִיפָא בְּעִזְקָא בִּכְתַב מְפֹרָשׁ, יְדוּמִיעָ\"ם, דְּפָקִיד בִּכְתַב דְּזִיוָא גְּלִיפָא, וּבְגוֹ חִזְוָון עִלָּאִין. בְּהַהוּא לֵילְיָא נָחִית, וְכַמָּה אֶלֶף אַלְפִין וְרִבּוֹא רִבְוָון עִמֵּיהּ, וְנַטְלִין לְהַהוּא צֵל מִכָּל חַד וְחַד, וְסַלְּקִין, לֵיהּ לְעֵילָּא.</p>\n<p>וְהַהִיא נֶפֶשׁ דְּקַאמָרָן, אַזְלָא וּמְשַׁטְּטָא וְחָמָאת לְהַהוּא צֵל, וְתָב לְאַתְרֵיהּ גּוֹ קִבְרָא, וְקָא מַכְרֶזֶת לִשְׁאַר מֵתַיָּיא, פְּלוֹנִי אָתֵי לְגַבָּן, פְּלוֹנִי אָתֵי לְגַבָּן. אִי זַכָּאָה טָבָא אִיהוּ, כֻּלְּהוּ חַדָּאן, וְאִי לָאו, כֻּלְּהוּ אַמְרֵי וַוי. כַּד סַלְּקִין הַהוּא צֵל, סַלְּקִין לֵיהּ לְגַבֵּי הַהוּא עֶבֶד מְהֵימָן, דִּשְׁמֵיהּ מְטַטְרוֹ\"ן, וְנָטִיל הַהוּא צֵל לְגַבֵּיהּ, וְסַלִיק לֵיהּ לְאַתְרִיהּ, כְּמָה דְאַתְּ אָמֵר, (איוב ז׳:ב׳) כְּעֶבֶד יִשְׁאַף צֵל, יִשְׁאַף צֵל וַדַּאי.</p>\n<p>מֵהַהִיא שַׁעֲתָא וְאֵילָךְ, מְתַתְקְנָא דּוּכְתָּא לְהַהִיא נְשָׁמָה דְּהַהוּא בַּר נָשׁ, וְדוּכְתָּא לְרוּחַ בְּגִּנְתָּא דְּעֵדֶן. וְדוּכְתָּא לְנֶפֶשׁ לְנַיְיחָא וּלְאִתְהֲנָאָה, בְּשַׁעֲתָא דִּמְשַׁטְּטָא וְאַזְלָא. בְּגִין דְּאִית (ויקרא קע\"ב ע\"ב) נֶפֶשׁ דְּלֵית לָהּ נַיְיחָא. וְאִית נֶפֶשׁ דְּאִישְׁתְּצִיאַת עִם גּוּפָא.</p>\n<p>וְהַאי אִיהִי דְּלֵית לָהּ נַיְיחָא, וְהַאי אִיהִי דִּכְתִּיב בָּהּ, (שמואל א כ״ה:כ״ט) וְאֶת נֶפֶשׁ אוֹיְבֶיךָ יְקַלְעֶנָּה בְּתוֹךְ כַּף הַקָּלַע. דְּדָא אִיהִי אַזְלָא וּמְשַׁטְּטָא וּמִתְגַּלְגְּלָא בְּכָל עָלְמָא, וְלֵית לָהּ נַיְיחָא כְּלַל יְמָמָא וְלֵילֵי, וְדָא אִיהוּ עוֹנְשָׁא יַתִּיר מִכֹּלָּא וְהַהִיא דְּתִשְׁתְּצִי עִם גוּפָה, (ההיא דכתיב בה (ויקרא י״ז:י׳) והכרתי אותה מקרב עמה ולהאי לית לה דוכרנו כלל ואית נפשא דלא תשתצי עם גופה) וְתִשְׁתְּצֵי מֵאֲתָר אַחֲרָא, (ס\"א עלאה) הַהִיא דִּכְתִּיב בָּהּ, (ויקרא כ״ב:ג׳) וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מִלְּפָנַי אֲנִי יְיָ'. מַאן מִלְּפָנַי. דְּלָא שַׁרְיָא עָלָהּ רוּחָא. וְכַד רוּחָא לָא שַׁרְיָא עָלָהּ, לֵית לָהּ שׁוּתָּפוּ כְּלַל בְּמָה דִּלְעֵילָּא, וְלָא יַדְעַת מֵאִינּוּן מִלִּין דְּהַהוּא עָלְמָא כְּלַל, וְהַאי אִיהִי נֶפֶשׁ כִּבְעִירֵי.</p>\n<p>נֶפֶשׁ דְּלֵית (ד\"א נפש דאית) לָהּ נַיְיחָא, הַאי אִיהִי כַּד אַזְלָא וּמְשַׁטְּטָא, אִעֲרְעַת בְּהַאי מְמַנָא יְדוּמִיעָ\"ם, וּבְאִינּוּן סַרְכִין דִּילֵיהּ, וְנַטְלִין לָהּ, וְאָעלִין לָהּ בְּכָל פִּתְחֵי גַּן עֵדֶן, וְאַחְזְיָין לָהּ יְקָרָא דְּצַדִּיקַיָּא, וִיקָרָא דְּהַהוּא רוּחַ דִּילָהּ, וְאִיהִי מִתְדַּבְּקָא בֵּיהּ בְּנַיְיחָא, גּוֹ הַהוּא לְבוּשָׁא, וּכְדֵין יַדְעַת בְּאִינּוּן מִלִּין דְּעָלְמָא.</p>\n<p>וְכַד הַהוּא רוּחַ סַלְּקָא לְאִתְעַטְּרָא גּוֹ נְשָׁמָה עִלָּאָה לְעֵילָּא, הַהִיא נֶפֶשׁ מִתְקַשְּׁרָא בְּהַהוּא רוּחַ, וְאִתְנְהִירַת מִנֵּיהּ, כְּסִיהֲרָא כַּד אִתְנְהִירַת מִשִׁמְּשָׁא. וְרוּחַ מִתְקַשְּׁרָא גּוֹ הַהִיא נִשְׁמְתָא. וְהַהִיא נִשְׁמְתָא מִתְקַשְּׁרָא, גּוֹ סוֹף מַחֲשָׁבָה, דְּאִיהִי רָזָא דְּנְפֶשׁ דִּלְעֵילָּא.</p>\n<p>וְהַהִיא נֶפֶשׁ, אִתְקָשָּׁרַת גּוֹ הַהוּא רוּחַ עִלָּאָה, וְהַהוּא רוּחַ אִתְקָשָּׁר גּוֹ הַהִיא נְשָׁמָה עִלָּאָה. וְהַהִיא נְשָׁמָה אִתְקָשָּׁרַת בְּאֵין סוֹף. וּכְדֵין אִיהוּ נַיְיחָא דְּכֹלָּא, וְקִשּׁוּרָא דְּכֹלָּא עֵילָּא וְתַתָּא, כֹּלָּא בְּרָזָא חֲדָא, וְגַוְונָא חֲדָא.</p>\n<p>וּכְדֵין דָּא אִיהוּ נַיְיחָא דְּנֶפֶשׁ דִּלְתַתָּא, וְעַל דָּא כְּתִיב, (שמואל א כ״ה:כ״ט) וְהָיְתָה נֶפֶשׁ אֲדֹנִי צְרוּרָה בִּצְרוֹר הַחַיִּים אֵת יְיָ' אֱלֹהֶיךָ. בְּגַוְונָא חֲדָא, וּבְרָזָא חֲדָא, דְּהַהוּא אֵת, דָּא כְּגַוְונָא דָּא.</p>\n<p>כַּד נַחְתָּא סִיהֲרָא, רָזָא דְּנֶפֶשׁ עִלָּאָה, נְהוֹרָא מִכָּל סִטְרִין. אִיהִי נַהֲרָא לְכָל רְתִיכִין וּמַשִּׁרְיָין, וְעָבִיד לוֹן גּוּפָא חֲדָא שְׁלֵימָא, דְּנָהִיר בִּנְהִירוּ בְּזִיוָא עִלָּאָה. אוּף הָכִי כְּגַוְונָא דָּא, נַחְתָּא הַאי נֶפֶשׁ תַּתָּאָה, נְהִירָא מִכָּל סִטְרִין מִגּוֹ נְהִירוּ דְּנְשָׁמָה, וּמִגּוֹ נְהִירוּ דְּרוּחַ, וְנַחְתָּא וְנַהֲרָא לְכָל אִינּוּן רְתִיכִין וּמַשִּׁרְיָין, דְּאִינּוּן שַׁיְיפִין וְגַרְמִין, וְעָבִיד לוֹן גּוּפָא שְׁלֵימָא, דְּנָהִיר בִּנְהִירוּ.</p>\n<p>הֲדָא הוּא דִּכְתִּיב, (ישעיהו נ״ח:י״א) וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךָ, נַפְשֶׁךָ מַמָּשׁ, וּלְבָתַר וְעַצְמוֹתֶיךָ יַחֲלִיץ, דְּעָבִיד מִנַּיְיהוּ גּוּפָא שְׁלֵימָא, וְנָהִיר בִּנְהִירוּ, וְקָם וְאוֹדֵי וּמְשַׁבַּח לְקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאִתְּמַר דִּכְתִּיב, (תהילים ל״ה:י׳) כָּל עַצְמוֹתַי תֹּאמַרְנָה יְיָ' מִי כָמוֹךָ. וְדָא אִיהוּ נַיְיחָא דְּנֶפֶשׁ וַדַּאי מִכָּל סִטְרִין.</p>\n<p>זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּדַחֲלִין לְמָארֵיהוֹן בְּעָלְמָא דֵּין, לְמִזְכֵּי בִּתְלַת נְיָיחֵי לְעָלְמָא דְּאָתִי. אָתָא רַבִּי שִׁמְעוֹן וּבַרְכֵיהּ לְרַבִּי אַבָּא. אָמַר רַבִּי שִׁמְעוֹן, זַכָּאִין אַתּוּן בָּנַי, וְזַכָּאָה אֲנָא דְּעֵינַי חָמוּ בְּכַךְ. כַּמָה <Nonei></i>דּוּכְתִּין עִלָּאִין מְתַּתְקְנָן לָן, וּנְהִירִין לָן, לְעָלְמָא דְּאָתֵי.</p>"],[9520011728,"<p>פָּתַח וְאָמַר, (תהילים קכ״ה:א׳) שִׁיר הַמַּעֲלוֹת הַבּוֹטְחִים בַּיְיָ' כְּהַר צִיּוֹן לֹא יִמּוֹט לְעוֹלָם יֵשֵׁב, הַאי קְרָא אוּקְמוּהָ. אֲבָל שִׁיר הַמַּעֲלוֹת תּוּשְׁבַּחְתָּא דְּקַאמְרֵי אִינּוּן דַּרְגִּין קַדִּישִׁין עִלָּאִין, מִסִּטְרָא דִּגְבוּרָן עִלָּאִין, וְאִינּוּן כְּגַוְונָא דְּלֵוָאֵי לְתַתָּא, וְאִינּוּן מַעֲלוֹת, דַּרְגִּין עַל דַּרְגִּין, וּפָלְחִין בְּרָזָא דְּחַמְשִׁין שְׁנִין. וְהַאי אִיהוּ שִׁיר הַמַּעֲלוֹת הַבֹּטְחִים בַּיְיָ' כְּהַר צִיּוֹן דָּא אִינּוּן צַדִּיקַיָּיא, דְּאִינּוּן מִתְרַחֲצָן בֵּיהּ בְּעוֹבָדִין דִּלְהוֹן.</p>\n<p>כְּמָה דְאַתְּ אָמֵר (משלי כ״ח:א׳) וְצַדִּיקִים כִּכְפִיר יִבְטָח. וְאִי תֵּימָא הָא צַדִּיקַיָּיא לָא מִתְרַחֲצָן בְּעוֹבָדֵיהוֹן כְּלַל, וְתָדִיר דַּחֲלִין, כְּאַבְרָהָם, דִּכְתִּיב בֵּיהּ (בראשית י״ב:י״א) וַיְהִי כַּאֲשֶׁר הִקְרִיב לָבֹא מִצְרָיְמָה וְגוֹ'. כְּיִצְחָק, דִּכְתִּיב בֵּיהּ, (בראשית כ״ו:ז׳) כִּי יָרֵא לֵאמֹר אִשְׁתִּי. כְּיַעֲקֹב, דִּכְתִּיב בֵּיהּ, (בראשית ל״ב:ח׳) וַיִּירָא יַעֲקֹב מְאֹד וְיֵצֶר לוֹ. וְאִי הָנֵי לָא אִתְרְחִיצוּ בְּעוֹבָדֵיהוֹן, כָּל שֶׁכֵּן שְׁאַר צַדִּיקֵי עָלְמָא, וְאַת אָמַרְתָּ וְצַדִּיקִים כִּכְפִיר יִבְטָח.</p>\n<p>אֶלָּא וַדַּאי, כִּכְפִיר כְּתִיב, דְּהָא מִכָּל אִינּוּן שְׁמָהָן, לָא כְּתִיב אֶלָּא כְּפִיר, וְלָא כְּתִיב, לָא אַרְיֵה, וְלָא שָׁחַל, וְלָא שָׁחַץ, אֶלָּא כְּפִיר. דְּאִיהוּ חַלְשָׁא וּזְעִירָא מִכֻּלְּהוּ. וְלָא אִתְרְחִיץ בְּחֵילֵיהּ, אַף עַל גַּב דְּאִיהוּ תַּקִּיף. כַּךְ צַדִּיקַיָּיא לָא אִתְרְחִיצוּ בְּעוֹבָדֵיהוֹן הַשְׁתָּא, אֶלָּא כִּכְפִיר. אַף עַל גַּב דְּיַדְעִין דְּתַקִיף חֵילָא דְּעוֹבָדֵיהוֹן לָא אִתְרַחֲצָן אֶלָּא כִּכְפִיר, וְלָא יַתִּיר.</p>\n<p>וּבְגִינֵי כַּךְ הַבֹּטְחִים בַּיְיָ' כְּהַר צִיּוֹן וְגוֹ', לָא כִּכְפִיר וְלָא כְּאַרְיֵה, וְלָאו כְּכֻלְּהוּ שְׁמָהָן. אֶלָּא כְּהַר צִיּוֹן, וְאוּקְמוּהָ מַה הַר צִיּוֹן אִיהוּ תַּקִּיף, וְלָא יִמּוֹט תָּדִיר, אוּף הָכִי בְּהַהוּא זִמְנָא, לֶהֱווֹ כְּהַר צִיּוֹן. וְלָא כְּהַשְׁתָּא, דְּלָא אִתְרְחִיצוּ אֶלָּא כִּכְפִיר, דְּדָחִיל וְלָא אִתְרְחִיץ בְּחֵילֵיהּ. וְאָתּוּן בְּנֵי קַדִּישֵׁי עֶלְיוֹנִין, רָחְצָנוּתָא דִּלְכוֹן כְּהַר צִיּוֹן, וַדַּאי זַכָּאִין אָתוּן בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.</p>\n<p>אָזְלוּ, כַּד מָטוּ לְמָתָא, אִתְחֲשָׁךְ לֵילְיָא. אָמַר רִבִּי שִׁמְעוֹן, כְּמָה דְּיוֹמָא דָּא, אַנְהִיר לָן בְּהַאי אָרְחָא, לְמִזְכֵּי בֵּיהּ בְּעָלְמָא דְּאָתִי, אוּף הָכִי הַאי לֵילְיָא, יַנְהִיר לָן, לְמִזְכֵּי לָן לְעָלְמָא דְּאָתִי, וּלְאַעֲטְּרָא מִלִּין דִּימָמָא בְּלֵילְיָא דָּא קָמֵי עַתִּיק יוֹמִין דְּהָא כְּיוֹמָא דָּא שְׁלִים, לָא יִשְׁתְּכַּח בְּכָל דָּרִין אַחֲרָנִין. זַכָּאָה חוּלָקָנָא בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי.</p>\n<p>עָאלוּ לְבֵיתֵיהּ דְּרַבִּי שִׁמְעוֹן, וְרַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְרַבִּי יוֹסִי עִמְּהוֹן. בָּתּוֹ עַד דְּאִתְפְּלַג לֵילְיָא. כֵּיוָן דְּאִתְפְּלַג לֵילְיָא, אָמַר רַבִּי שִׁמְעוֹן לְחַבְרַיָּא, עִידָּן אִיהוּ לְאַעְטְּרָא רְתִיכָא קַדִּישָׁא לְעֵילָּא, בְּאִשְׁתַּדְּלוּתָא דִּילָן. אָמַר לֵיהּ לְרַבִּי יוֹסִי, אַנְתְּ דְּלָא אִשְׁתְּמָעוּ מִילָךְ בְּהַאי יוֹמָא בֵּינָנָא, אַנְתְּ הֲוֵי שֵׁירוּתָא, לְאַנְהָרָא לֵילְיָא, דְּהָא הַשְׁתָּא עִידָּן רְעוּתָא אִיהוּ, לְאַנְהָרָא עֵילָּא וְתַתָּא.</p>"],[9520011729,"<p>פָּתַח רַבִּי יוֹסִי וְאָמַר, שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה. שִׁירָתָא דָּא אִתְּעַר לָהּ שְׁלֹמֹה מַלְכָּא, כַּד אִתְבְּנִי בֵּי מַקְדְּשָׁא, וְעָלְמִין כֻּלְּהוּ אִשְׁתְּלִימוּ, עֵילָּא וְתַתָּא בִּשְׁלְמוּתָא חֲדָא. וְאַף עַל גַּב דְּחַבְרַיָּיא פְּלִיגָּן בְּהַאי, (נ\"א מתי אתמר) אֲבָל שִׁירָתָא דָּא לָא אִתְּמַר, אֶלָּא בִּשְׁלִימוּ, כַּד סִיהֲרָא אִתְמַלְיָא בִּשְׁלִימוּ, וּבֵי מַקְדְּשָׁא אִתְבְּנִי כְּגַוְונָא דִּלְעֵילָּא בְּשַׁעֲתָא דְּאִתְבְּנֵי בֵּי מַקְדְּשָׁא לְתַתָּא, לָא הֲוָה חֶדְוָה קָמֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא, כְּהַהוּא יוֹמָא.</p>\n<p>מִשְׁכָּן דְּעָבַד מֹשֶׁה בְּמַדְבְּרָא, לְנַחְתָּא שְׁכִינְתָּא לְאַרְעָא, בְּהַהוּא יוֹמָא מִשְׁכָּן אַחֲרָא אִתּוּקַם עִמֵּיהּ לְעֵילָּא, כְּמָה דְּאוּקְמוּהָ דִּכְתִּיב, (שמות מ׳:י״ז) הוּקַם הַמִּשְׁכָּן, הַמִּשְׁכָּן: מִשְׁכָּן אַחֲרָא (קנ\"ט ע\"א) דְּאִתְקַם עִמֵּיהּ, וְדָא מִשְׁכָּן דְּנַעַר מְטַטְרוֹ\"ן, וְלָא יַתִּיר. בַּיִת רִאשׁוֹן כַּד אִתְבְּנֵי, בַּיִת רִאשׁוֹן אַחֲרָא אִתְבְּנֵי עִמֵּיהּ, וְאִתְקָיַּים בְּעָלְמִין כֻּלְּהוּ, וְאַנְהִיר (ד\"א בעלמא ואנהיר) לְכָל עָלְמִין, וְאִתְבָּסַם עָלְמָא, וְאִתְפָּתְחוּ כָּל מַשְׁקוֹפֵי עִלָּאִין לְאַנְהָרָא, וְלָא הֲוָה חֶדְוָה בְּכָל עָלְמִין כְּהַהוּא יוֹמָא, כְּדֵין פָּתְחוּ עִלָּאֵי וְתַתָּאֵי וְאָמְרוּ שִׁירָתָא, וְהַיְינוּ שִׁיר הַשִּׁירִים. שִׁירָתָא דְּאִינּוּן מְנַגְּנִין דִּמְנַגְנָן לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p><Nonei></i>דָּוִד מַלְכָּא אָמַר שִׁיר הַמַּעֲלוֹת, שְׁלמֹה מַלְכָּא אָמַר שִׁיר הַשִּׁירִים, שִׁיר מֵאִינּוּן מְנַגְּנִין. מָה בֵּין הַאי לְהַאי, דְּהָא אִשְׁתְּמַע דְּכֹלָּא חַד. אֶלָּא וַדַּאי כֹּלָּא חַד, אֲבָל בְּיוֹמֵי דְּדָוִד מַלְכָּא, לָא הֲווֹ כָּל אִינּוּן מְנַגְּנִין מְתַּתְקְנָן בְּדוּכְתַּיְיהוּ, לְנַגְּנָא כְּדְקָא יֵאוֹת, וּבֵי מַקְדְּשָׁא לָא אִתְבְּנֵי, וּבְּגִין כָּךְ לָא אִתְתָּקָנוּ לְעֵילָּא בְּדוּכְתַּיְיהוּ. דְּהָא כְּמָה דְּאִית תִּקּוּנִי דְּמִשְׁמָרוֹת בְּאַרְעָא, אוּף הָכִי בִּרְקִיעָא, וְקַיְימִין אִלֵּין לָקֳבֵל אִלֵּין.</p>\n<p>וּבְיוֹמָא דְּאִתְבְּנִי בֵּי מַקְדְּשָׁא, אִתְתָּקָנוּ כֻּלְּהוּ בְּדוּכְתַּיְיהוּ, וְשַׁרְגָּא דְּלָא נַהֲרָא שָׁרִיאַת לְאַנְהָרָא. וְשִׁירָתָא דָּא אִתְתַּקְנַת לְגַבֵּי מַלְכָּא עִלָּאָה, מַלְכָּא דִּשְׁלָמָא דִּילֵיהּ. וְתוּשְׁבְּחָא דָּא אִיהִי מְעַלְּיָא, מִכָּל תּוּשְׁבְּחָן קַדְמָאֵי. יוֹמָא דְּאִתְגְלֵי תּוּשְׁבַּחְתָּא דָּא (בעלמא) בְּאַרְעָא, הַהוּא יוֹמָא אִשְׁתְּכַח שְׁלִימוּ בְּכֹלָּא, וְעַל דָּא אִיהוּ קֹדֶשׁ קֳדָשִׁים.</p>\n<p>בְּסִפְרָא דְּאָדָם קַדְמָאָה, הֲוָה כְּתִיב בֵּיהּ. בְּיוֹמָא דְיִתְקָם בֵּי מַקְדְּשָׁא (ד\"א דיתבני בי מקדשא') יִתְּעֲרוּן אֲבָהָן שִׁירָתָא, עֵילָּא וְתַתָּא. וּבְגִין כַּךְ אַשְׁכַּחְנָא שִׁין מֵאַתְוָון רַבְרְבָן. וְאִלֵּין אִינּוּן דְּקָא אַתְּעָרוּ, לָאו דְּאִינּוּן מְנַגְּנָן, אֶלָּא דְּאִינּוּן מִתְעָרֵי לְגַבֵּי עֵילָא. (ד\"א ל\"ג כביכול) שִׁיר דְּאִינּוּן שִׁירִין רַבְרְבָן, דִּמְמָנָן עַל עָלְמִין כֻּלְּהוּ.</p>\n<p>וְתָנִינָן, בְּהַהוּא יוֹמָא קָם יַעֲקֹב שְׁלֵימָא, וְעָאל בְּגִנְתָּא דְּעֵדֶן, בְּחֵידוּ, עַל דּוּכְתֵּיהּ. כְּדֵין גִּנְתָּא דְּעֵדֶן, שָׁאֲרִי לְנַגְּנָא, וְכָל אִינּוּן בּוּסְמִין דְּגִנְתָּא. מַאן גָּרִים שִׁירָתָא דָּא, וּמַאן אָמַר לָהּ. הֲוֵי אֵימָא דָּא יַעֲקֹב, דְּאִלְמָלֵא אִיהוּ לָא עָאל בְּגִּנְתָּא דְּעֵדֶן, לָא אָמַר גִּנְתָּא שִׁירָתָא.</p>\n<p>שִׁירָתָא דָּא שִׁירָתָא, דְּאִיהִי כְּלָלָא דְּכָל אוֹרַיְיתָא. שִׁירָתָא דְּעִלָאֵי וְתַתָּאֵי מִתְעָרֵי לְגַבָּהּ. שִׁירָתָא דְּאִיהִי כְּגַוְונָא דְּעָלְמָא דִּלְעֵילָּא, דְּאִיהוּ שַׁבָּת עִלָּאָה. שִׁירָתָא דִּשְׁמָא קַדִּישָׁא עִלָּאָה, אִתְעַטַּר בְּגִינֵיהּ. וְעַל דָּא אִיהוּ קֹדֶשׁ קֳדָשִׁים. מַאי טַעְמָא. בְּגִין דְּכָל מִלּוֹי בִּרְחִימוּ וּבְחֶדְוָה כֹּלָּא. (ודא) בְּגִין דְּכוֹס שֶׁל בְּרָכָה אִתְיְהִיב בִּימִינָא, כֵּיוָן דְּאִתְיְהִיב בִּימִינָא, כְּדֵין כָּל חֵידוּ וְכָל רְחִימוּ אִשְׁתְּכַח. וּבְגִין כַּךְ בִּרְחִימוּ וּבְחֶדְוָה כָּל מִלּוֹי.</p>\n<p>בְּזִמְנָא דְּהַאי יְמִינָא אִתְהַדָּר לַאֲחוֹרָא, כְּמָה דְאַתְּ אָמֵר (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ, כְּדֵין כּוֹס שֶׁל בְּרָכָה אִתְיְהִיב בִּשְׂמָאלָא. כֵּיוָן דְּאִתְיְהִיב בִּשְׂמָאלָא, שָׁרִיאוּ עִלָּאֵי וְתַתָּאֵי לְמִפְתַּח עָלֵיהּ קִינָה. וּמַאי קָאַמְרֵי. אֵיכָה, אֵי כָּה, אֵי כּוֹס שֶׁל בְּרָכָה, דַּאֲתָר עִלָּאָה דַּהֲוֵית יָתְבָא בְּגַוֵּיהּ אִתְמָנַּע וְאִתְגְרַע מִנָּהּ בְּגִינֵי כַּךְ שִׁיר הַשִּׁירִים, דְּהֲוָה מִסִּטְרָא דִּימִינָא, כָּל מִלּוֹי רְחִימוּ וְחֶדְוָה. אֵיכָה, דְּחָסִיר יְמִינָא, וְאִשְׁתְּכַח שְׂמָאלָא, כָּל מִלּוֹי אִינּוּן קַנְטוּרִין וְקִינִין.</p>\n<p>וְאִי תֵּימָא, הָא כָּל חִידוּ, וְכָל חֶדְוָה, וְכָל שִׁיר, מִסִּטְרָא דִּשְׂמָאלָא אִיהוּ, וְעַל דָּא לֵוָאֵי מִסִּטְרָא דִּשְׂמָאלָא מְנַגְנֵי שִׁירָתָא. אֶלָּא, כָּל חִידוּ דְּאִשְׁתְּכַח מִסִּטְרָא דִּשְׂמָאלָא, לָא אִשְׁתְּכַח אֶלָּא בְּזִמְנָא דִּימִינָא אִתְדַּבָּק בַּהֲדֵיהּ. וּבְזִמְנָא דִּימִינָא אִתְּעַר וְאִתְדַּבָּק בַּהֲדֵיהּ, כְּדֵין הַהוּא חֶדְוָה מִימִינָא, אִיהוּ דְּקָא אוֹטִיב לְרִתְּחָא, וְכַד רִתְחָא אִשְׁתְּכַּךְ, וְחִדוּ אִיהוּ מִסִּטְרָא דִּימִינָא, כְּדֵין חֶדְוָה שְׁלֵימָתָא אָתֵי מֵהַאי סִטְרָא.</p>\n<p>וְכַד יְמִינָא לָא אִשְׁתְּכַח, רִתְחָא דִּשְׂמָאלָא נָּפִישׁ, וְלָא שָׁכִיךְ, וְלָא אוֹטִיב, וְלָא חַדֵּי. כְּדֵין אֵיכָה, אֵי כָּה. כּוֹס שֶׁל בְּרָכָה מָה תְּהֵא עָלֶיהָ, דְּקָא יָתְבָא בִּשְׂמָאלָא, וְרִתְּחָא נָּפִישׁ, וְלָא שָׁכִיךְ. וַדַּאי קַנְטוּרִין וְקִינִין מִתְעָרִין.</p>\n<p>אֲבָל שִׁיר הַשִּׁירִים, וַדַּאי כּוֹס שֶׁל בְּרָכָה דְּאִתְיְהִיב בִּימִינָא, וְאִתְמְסָר בְּגַוֵּיהּ, וְעַל דָּא כָּל רְחִימוּ וְכָל חִידוּ אִשְׁתְּכַח. וּבְגִין כַּךְ כָּל מִלּוֹי בִּרְחִימוּ וּבְחֶדְוָה, וְלָא אִשְׁתְּכַח בִּשְׁאַר כָּל שִׁירִין דְּעָלְמָא הָכִי. וּבְגִין דָּא מִסִּטְרָא דַּאֲבָהָן אִתְּעַר שִׁירָתָא דָּא.</p>\n<p>יוֹמָא דְּאִתְגְלֵי שִׁירָתָא דָּא, הַהוּא יוֹמָא נַחְתַּת שְׁכִינְתָּא לְאַרְעָא, דִּכְתִּיב, (מלכים א ח׳:י״א) וְלָא יָכְלוּ הַכֹּהֲנִים לַעֲמוֹד לְשָׁרֵת וְגוֹ'. מַאי טַעֲמָא. בְּגִין כִּי מָלֵא כְבוֹד יְיָ' אֶת בֵּית יְיָ'. בְּהַהוּא יוֹמָא מַמָּשׁ, אִתְגְּלִיאַת תּוּשְׁבַּחְתָּא <Nonei></i>דָּא, וְאָמְרָה שְׁלמֹה בְּרוּחַ קֻדְשָׁא.</p>\n<p>תּוּשְׁבַּחְתָּא דְּשִׁירָתָא דָּא, אִיהִי כְּלָלָא דְּכָל אוֹרַיְיתָא. כְּלָלָא דְּכָל עוֹבָדָא דִּבְרֵאשִׁית, כְּלָלָא דְּרָזָא דַּאֲבָהָן, כְּלָלָא דְּגָלוּתָא דְּמִצְרַיִם. וְכַד נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם. וְתוּשְׁבַּחְתָּא דְּיַמָּא. כְּלָלָא דְּיוֹ\"ד אֲמִירָן. וְקִיּוּמָא דְּהַר סִינַי. וְכַד אָזְלוּ יִשְׂרָאֵל בְּמַדְבְּרָא, עַד דְּעָאלוּ לְאַרְעָא, וְאִתְבְּנֵי בֵּי מַקְדְּשָׁא. כְּלָלָא דְּעִטוּרָא דִּשְׁמָא קַדִּישָׁא עִלָּאָה, בִּרְחִימוּ וּבְחֶדְוָה. כְּלָלָא דְּגָלוּתְהוֹן דְּיִשְׂרָאֵל בֵּינֵי עֲמַמְיָא, וּפוּרְקָנָא דִּלְהוֹן. כְּלָלָא דִּתְחִיַית הַמֵּתִים, עַד יוֹמָא דְּאִיהִי שַׁבָּת לַיְיָ'. מַאי דְּהֲוָה, וּמַאי דַּהֲוֵי, וּמַאי דְּזַמִּין לְמֶהֱוֵי, לְבָתַר בְּיוֹמָא שְׁבִיעָאָה, כַּד יְהֵא שַׁבָּת לַיְיָ', כֹּלָּא אִיהוּ בְּשִׁיר הַשִּׁירִים.</p>\n<p>וְעַל דָּא תָּנֵינָן, כָּל מַאן דְּאַפִּיק פְּסוּקָא דְּשִׁיר הַשִּׁירִים, וְאָמַר לֵיהּ בְּבֵי מִשְׁתַּיָּא. אוֹרַיְיתָא אִיהִי חֲגִירַת שָׂק, וְסַלְּקָא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאָמְרָה קַמֵּיהּ, עָבְדוּ לִי בָּנֶיךָ מָחוֹךְ בְּבֵי מִשְׁתַּיָּא. וַדַּאי אוֹרַיְיתָא סַלְקַת וְקָאַמְרָת הָכִי, בְּגִין דָּא אִצְטְרִיךְ לְנַטְרָא, וּלְסַלְּקָא עִטָּרָא עַל רֵישֵׁיהּ דְּבַר נָשׁ, כָּל מִלָּה וּמִלָּה דְּשִׁיר הַשִּׁירִים.</p>\n<p>וְאִי תֵּימָא אֲמַאי אִיהִי בֵּין הַכְּתוּבִים, הָכִי הוּא וַדַּאי, בְּגִין דְּאִיהוּ שִׁיר תּוּשְׁבַּחְתָּא דִּכְנְסֶת יִשְׂרָאֵל, קָא מִתְעַטְּרָא לְעֵילָּא. וּבְגִין כַּךְ, כָּל תּוּשְׁבְּחָן דְּעָלְמָא, לָא סַלְּקָא רְעוּתָא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, כְּתוּשְׁבַּחְתָּא דָּא.</p>\n<p>הָכִי אוֹלִיפְנָא, שִׁיר, חַד. הַשִּׁירִים, תְּרֵין. אֲשֶׁר, הָא תְּלָת. וְרָזָא דָּא, דְּאִתְיְהִיב כּוֹס שֶׁל בְּרָכָה וְאִתְנְטִיל בֵּין יְמִינָא וּשְׂמָאלָא. וְכֹלָּא אִתְּעַר לְגַבֵּי מַלְכָּא דִּשְׁלָמָא דִּילֵיהּ. וּבְהַאי אִסְתַּלָּק רְעוּתָא לְעֵילָּא לְעֵילָּא בְּרָזָא דְּאֵין סוֹף. רְתִיכָא קַדִּישָׁא הָכָא אִשְׁתְּכַח. דְּהָא אֲבָהָן אִינּוּן רְתִיכָא, דָּוִד מַלְכָּא אִתְחֲבָּר עִמְּהוֹן, אִינּוּן אַרְבַּע רָזָא דִּרְתִיכָא קַדִּישָׁא עִלָּאָה. וּבְגִין כַּךְ, אַרְבַּע תֵּיבִין בְּהַאי קְרָא קַדְמָאָה, רָזָא דִּרְתִיכָא קַדִּישָׁא שְׁלֵימָתָא.</p>\n<p>תּוּ רָזָא דָּא, שִׁיר: דָּא רָזָא דְּדָוִד מַלְכָּא, דְּאִיהוּ רָזָא לְסַלְּקָא בְּשִׁיר. הַשִּׁירִים: אִלֵּין אֲבָהָן, רָזָא דִּמְמָנָן רַבְרְבָן, רְתִיכָא שְׁלֵימָתָא כַּדְקָא יֵאוֹת. אֲשֶׁר לִשְׁלֹמֹה: רָזָא מַאן דְּרָכִיב עַל רְתִיכָא שְׁלֵימָתָא דָּא.</p>\n<p>וּבְהַאי קְרָא אִשְׁתְּכַח שְׁלִימוּ דְּרָזָא, מִן (ויצא קנ\"ג ע\"ב) הָעוֹלָם וְעַד הָעוֹלָם, רָזָא דְּכָל מְהֵימְנוּתָא. וְכֹלָּא אִיהוּ רְתִיכָא שְׁלֵימָתָא לְמַאן דִּיְדִיעַ, וּלְמַאן דְּלָא אִתְיְדַע, וְלֵית מַאן דְּקָאִים לְמִנְדַּע בֵּיהּ. וְעַל דָּא אִתְּמַר הַאי קְרָא בְּד' תֵּיבִין, רָזָא דִּרְתִיכָא שְׁלֵימָתָא מִכָּל סִטְרִין. מִכָּאן וּלְהָלְאָה, רָזָא לְחַכִּימִין אִתְמְסָר.</p>\n<p>וְתוּ אִית בֵּיהּ רָזָא פְּנִימָאָה, דְּתָנֵינָן, מַאן דְּחָמֵי עַנְבִין בְּחֶלְמֵיהּ, אִי חִיוָּרִין אִינּוּן טָבִין. אוּכָמִין, בִּזְמַנָן טָבִין, דְּלָא בִּזְמַנָן צְרִיכִין רַחֲמֵי. מַאי שְׁנָא חִיוָּרֵי, וּמַאי שְׁנָא אוּכָמֵי, וּמַאי שְׁנָא בִּזְמַנָן, וּמַאי שְׁנָא דְּלָא בִּזְמַנָן. וְתוּ, תָּנֵינָן אָכְלָן לְאִינוּן אוּכָמֵי, מוּבְטַח לֵיהּ דְּהוּא בֶּן עָלְמָא דְּאָתֵי, אֲמַאי.</p>\n<p>אֶלָּא תָּנֵינָן, אִילָנָא דְּחָב בֵּיהּ אָדָם קַדְמָאָה, עֲנָבִין הֲווֹ, דִּכְתִּיב, (דברים לכ) עֲנָבֵמוֹ עִנְּבֵי רוֹשׁ. וְאִלֵּין אִינּוּן עֲנָבִין אוּכָמִין, בְּגִין דְּאִית עֲנָבִין אוּכָמִין, וְאִית עֲנָבִין חִוָּורִין. חִוָּורִין טָבִין, דְּהָא מִסְּטָר דְּחַיֵּי אִינּוּן. אוּכָמִין צְרִיכִין רַחֲמֵי, דְּהָא מִסִּטְרָא דְּמוֹתָא אִינּוּן. בִּזְמַנָן טָבִין, מַאי טַעֲמָא. בְּגִין דִּבְזִמְנָא דְּחִוָּורֵי שַׁלְטָן, כֹּלָּא אִתְבְּסָם, דְּהָא בְּהַהוּא זִמְנָא כֹּלָּא אִצְטְרִיךְ לְתִקּוּנָא, וְכֹלָּא אִיהוּ שַׁפִּיר, וְכֹלָּא תִּקּוּנָא חֲדָא, אוּכָמָא וְחִוָּורָא. וּבִזְמְנָא דְּחִוָּורֵי לָא שַׁלְטָאן, וְאוּכָמֵי אִתְחָזוּן, לְמִינְדַּע דְּהָא בְּדִינָא דְּמוֹתָא סָלִיק, וְאִצְטְרִיךְ רַחֲמֵי, דְּהָא אִילָנָא דְּחָב בֵּיהּ אָדָם קַדְמָאָה, וְגָרִים מוֹתָא לֵיהּ וּלְכָל עָלְמָא חָמָא.</p>\n<p>הָכָא אִית לְאִסְתַּכְּלָא, וְאִי לָאו דְּמַר הָכָא, לָא אֵימָא. תָּנֵינָן דְּעָלְמָא דָּא, אִיהוּ כְּגַוְונָא דְּעָלְמָא דִּלְעֵילָּא, וְעָלְמָא דִּלְעֵילָּא כָּל מַה דְּהֲוָה בְּהַאי עָלְמָא, הָכִי אִיהוּ לְעֵילָּא, אִי נָחָשׁ גָּרִים מוֹתָא לְאָדָם לְתַתָּא, לְעֵילָּא אֲמַאי. <Nonei></i>אִי תֵּימָא, (עוד) לְאִתְּתָא, (ס\"א לתתא) דִּבְגִין נָחָשׁ אִגְרַע נְהוֹרָא, דְּהָא סִיהֲרָא גָּרַע נְהוֹרָא לְזִמְנִין, וּבְהַהוּא זִמְנָא אִיהִי מִיתַת. דְּכוּרָא אֲמַאי. דְּאִי נִימָא דְּסִיהֲרָא בְּעֶטְיוֹ דְּהַאי נָחָשׁ מִיתַת, בִּגְרִיעוּ דִּנְהוֹרָא. הָא תָּנֵינָן, דְּלָא בְּגִין נָחָשׁ הֲוָה. אֶלָּא דְּאָמְרָה סִיהֲרָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא וְכוּ', הָא לָא הֲוָה בְּגִין נָחָשׁ. וְאִי תֵּימָא דְּבַעְלָהּ הָכִי הוּא, חַס וְשָׁלוֹם דִּגְרִיעוּ הֲוִי לְעֵילָּא.</p>\n<p>אֶלָּא כָּל דָּא סִתְרֵי אוֹרַיְיתָא, וְנָחָשׁ בְּכֹלָּא אַתְקִין גְּרִיעוּ. תָּא חֲזֵי וְהָכִי אוֹלִיפְנָא, כָּל מָה דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא עֵילָּא וְתַתָּא, כֹּלָּא בְּרָזָא דִּדְכַר וְנוּקְבָּא אִיהוּ, וְכַמָּה דַּרְגִּין אִינּוּן לְעֵילָּא, מְשַׁנְיָין אִלֵּין מֵאִלֵּין. וּמִדַרְגָּא עַד דַּרְגָּא רָזָא דְּאָדָם, וְאִינּוּן דַּרְגִּין דְּאִינּוּן זִינָא חֲדָא, עָבַד לוֹן קוּדְשָׁא בְּרִיךְ הוּא דִּיּוּקְנָא דְּחָד גּוּפָא, עַד דְּסַלְּקִין בְּרָזָא דְּאָדָם.</p>\n<p>וְתָנִינָן, בְּיוֹמָא תִּנְיָינָא דְּעוֹבָדָא דִּבְרֵאשִׁית, דְּאִתְבְּרֵי בֵּיהּ גֵּיהִנָם, אִתְעָבִיד חַד גּוּפָא בְּרָזָא דְּאָדָם, וְאִינּוּן שַׁיְיפִין מְמָנָן דְּמִתְקָרְבִין לְאֶשָּׁא, וּמֵתִין וּמְהַדְּרָן כְּמִלְּקַדְּמִין. וְדָא בְּגִין דְּאִינּוּן אִתְקְרִיבוּ לְגַבֵּי הַאי חִוְיָא, וְאִיהוּ אָדָם קַדְמָאָה דְּאִתְפַּתָּא גּוֹ מַשְׁכְּנָא בְּהַאי חִוְיָא, וְעַל דָּא מִית, וְחִוְיָא גָּרִים לֵיהּ מוֹתָא דְּאִיהוּ קָרִיב לֵיהּ.</p>\n<p>וּבְכָל אֲתָר אָדָם דְּכַר וְנוּקְבָּא אִיהוּ, אֲבָל (תצא רמ\"ז ע\"ב) אָדָם דְּאִיהוּ קַדִּישָׁא עִלָּאָה, אִיהוּ שַׁלְטָא עַל כֹּלָּא, דָּא יָהִיב מְזוֹנָא וְחַיִּין לְכֹלָּא. וְעִם כָּל דָּא בְּכֹלָּא מָנַע נְהוֹרָא הַאי חִוְיָא תַּקִּיפָא. כַּד מַסְאִיב מִשְׁכְּנָא נוּקְבָּא דְּהַהוּא אָדָם כִּדְקָאָמַר מִיתַת, וּדְכוּרָא מִית, וְסַלְּקִין כְּמִלְּקַדְּמִין. וְעַל דָּא כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא.</p>\n<p>אֲכַל אִינּוּן עֲנָבִין אוּכָמִין, מוּבְטַח לֵיהּ דְּהוּא בֶּן עָלְמָא דְּאָתֵי, בְּגִין דְּשֵׁיצֵי, וְשָׁלִיט עַל הַהוּא אֲתָר, (נ\"א ואעבר) וְאִתְגַּבָּר עָלֵיהּ, וְאַדָק לֵיהּ, כְּמָה דְאַתְּ אָמֵר (דניאל ז) אָכְלָא וּמַדְּקָא. כֵּיוָן דְּאַעְבַּר הַהִיא קְלִיפָה תַּקִּיפָא, הָא אִתְקְרַב לְגַבֵּי עָלְמָא דְּאָתֵי, וְלֵית מַאן דְּמָחֵי בִּידֵיהּ. וְעַל דָּא, מַאן דְּחָמֵי בְּחֶלְמֵיהּ דְּאִינּוּן עֲנָבִין אוּכָמִין אָכִל וּמְהַדֵק מוּבְטַח לֵיהּ וְכוּ'.</p>\n<p>כְּגַוְונָא דָּא, לָא הֲוֵי שִׁיר בְּבֵיתָא דְּדָוִד, עַד דְּאִתְעַבָּרוּ אִינּוּן עֲנָבִין אוּכָמִין, וְשַׁלְטָא עָלַיְיהוּ, וּכְדֵין אִתְּמַר שִׁיר הַשִּׁירִים, כְּמָה דְּאִתְּמַר. וַאֲפִילּוּ בְּאֲתָר דָּא אִקְרֵי עֲנָבִים, כְּמָה דְאַתְּ אָמֵר (הושע ט׳:י׳) כַּעֲנָבִים בַּמִּדְבָּר וְגוֹ', וְאִלֵּין אִינּוּן עֲנָבִים חִוָּורִין.</p>\n<p>שִׁירָתָא דָּא אִיהִי מְעַלְּיָא עַל כָּל שְׁאַר שִׁירִין דְּקַדְמָאֵי. כָּל שִׁירִין דְּקַדְמָאֵי אָמְרוּ, לָא סְלִיקוּ אֶלָּא גּוֹ שִׁירִין דְּמַלְאֲכֵי עִלָּאֵי אַמְרֵי. וְאַף עַל גַּב דְּהָא אוּקְמוּהָ, אֲבָל כְּתִיב שִׁיר הַמַּעֲלוֹת לְדָוִד, שִׁיר הַמַּעֲלוֹת שִׁיר דְּמַלְאֲכֵי עִלָּאֵי אַמְרֵי. דְּאִינּוּן מַעֲלוֹת וְדַרְגִּין. אַמְרֵי לְמַאן. לְדָוִד. לְבַקְשָׁא טַרְפָּא וּמְזוֹנָא מִנֵּיהּ.</p>\n<p>תּוּ שִׁיר הַמַּעֲלוֹת, כְּמָה דְאַתְּ אָמֵר (תהילים מ״ו:א׳) עַל עֲלָמוֹת שִׁיר. (שיר השירים א׳:ג׳) עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. לְדָוִד, בְּגִין דָּוִד מַלְכָּא עִלָּאָה, דְּאִיהוּ (ויחי רנ\"א ע\"א) מְשַׁבַּח תָּדִיר לְמַלְכָּא עִלָּאָה.</p>\n<p>כֵּיוָן דְּאָתָא שְׁלמֹה מַלְכָּא, אָמַר שִׁיר דְּאִיהוּ עִלָּאָה לְעֵילָּא. דְּרַבְרְבֵי עָלְמָא עִלָּאִין, קָאַמְרֵי לְגַבֵּי מַלְכָּא עִלָּאָה, דִּשְׁלָמָא כֹּלָּא דִּילֵיהּ. כֻּלְּהוּ דְּאַמְרֵי שִׁירָתָא, לָא סְלִיקוּ בְּהַהִיא שִׁירָתָא לוֹמַר, אֶלָּא הַהוּא שִׁירָתָא דְּמַלְאֲכֵי עִלָּאֵי קָאַמְרֵי. בַּר שְׁלֹמֹה מַלְכָּא, דְּסָלִיק בְּהַהִיא שִׁירָתָא לְמַּה דְּרַבְרְבִין עִלָּאִין עַמּוּדֵי עָלְמָא קָאַמְרֵי. כָּל בְּנֵי עָלְמָא בִּרְתִיכִין תַּתָּאִין, שְׁלֹמֹה מַלְכָּא בִּרְתִיכִין עִלָּאִין.</p>\n<p>וְאִי תֵּימָא, מֹשֶׁה דְּסָלִיק בְּדַרְגָּא דִּנְבוּאָה וּבַחֲבִיבוּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, עַל כָּל בְּנֵי עָלְמָא, הַהִיא שִׁירָתָא דְּקָאָמַר בִּרְתִיכִין תַּתָּאִין הֲוָה, וְלָא סָלִיק יַתִּיר. תָּא חֲזִי, שִׁירָתָא דְּקָאָמַר מֹשֶׁה, סָלִיק לְעֵילָּא וְלָא לְתַתָּא. אֲבָל לָא אָמַר שִׁירָתָא כִּשְׁלֹמֹא מַלְכָּא, וְלָא הֲוָה בַּר נָשׁ דְּסָלִיק בְּשִׁירָתָא כִּשְׁלֹמֹה.</p>\n<p>מֹשֶׁה סָלִיק בְּתוּשְׁבַּחְתֵּיהּ לְעֵילָּא, וְתוּשְׁבַּחְתָּא דִּילֵיהּ הֲוָה, לְמֵיהַב תּוּשְׁבְּחָן וְהוֹדָאָן לְמַלְכָּא עִלָּאָה, דְּשֵׁזִיב לוֹן לְיִשְׂרָאֵל, וְעָבִיד לוֹן נִסִּין וּגְבוּרָאן בְּמִצְרַיִם, וְעַל יַמָּא. אֲבָל דָּוִד מַלְכָּא, וּשְׁלֹמֹה בְּרֵיהּ, אָמְרוּ שִׁירָתָא <Nonei></i>בְּגַוְונָא אַחֲרָא. דָּוִד אִשְׁתָּדַּל לְאַתְקְנָא עוּלֶמְתָּן, וּלְקַשְׁטָא לוֹן בְּמַטְרוֹנִיתָא, לְאִתְחֲזָאָה מַטְרוֹנִיתָא וְעוּלֶמְתָהָא בִּשְׁפִירוּ, וְעַל דָּא אִשְׁתָּדַּל בְּאִינּוּן שִׁירִין וְתוּשְׁבְּחָן דְּגַבֵייהוּ, עַד דְּאַתְקִין וְקָשִׁיט כֻּלְּהוּ עוּלֶמְתָּן וּמַטְרוֹנִיתָא.</p>\n<p>כֵּיוָן דְּאָתָא שְׁלמֹה, אַשְׁכַּח לְמַטְרוֹנִיתָא מִתְקַשְּׁטָא, וְעוּלֶמְתָּהָא בִּשְׁפִירוּ, אִשְׁתָּדַּל לְמֵיעָל לָהּ לְגַבֵּי חָתָן, וְאָעִיל הֶחָתָן לַחוּפָּה בְּמַטְרוֹנִיתָא, וְאָעִיל מִלִּין דִּרְחִימוּ בֵּינַיְיהוּ, בְּגִין לְחַבְּרָא לוֹן כַּחֲדָא, וּלְמֶהוֵי תַּרְוַויְיהוּ בִּשְׁלִימוּ חֲדָא בְּחָבִיבוּ שְׁלִים. וְעַל דָּא שְׁלֹמֹה סָלִיק בְּתוּשְׁבַּחְתָּא עִלָּאָה, עַל כָּל בְּנֵי עָלְמָא.</p>\n<p>מֹשֶׁה, זִוֵּוג לְמַטְרוֹנִיתָא בְּהַאי עָלְמָא לְתַתָּא, לְמֶהוֵי בְּהַאי עָלְמָא בְּזִוּוּגָא שְׁלִים בְּתַתָּאֵי. שְׁלמֹה, זִוֵּוג לָהּ לְמַטְרוֹנִיתָא בְּזִוּוּגָא שְׁלֵימָא לְעֵילָּא, וְאָעִיל הֶחָתָן לַחוּפָּה בְּקַדְמִיתָא, וּלְבָתַר עָאל לְתַרְוַויְּיהוּ בְּהַאי עָלְמָא, וְזַמִּין לוֹן בְּחֶדְוָה בְּבֵי מַקְדְּשָׁא דְּאִיהוּ בָּנָה.</p>\n<p>וְאִי תֵּימָא, הֵיךְ עָיִיִל מֹשֶׁה לְמַטְרוֹנִיתָא בִּלְחוֹדָהָא בְּהַאי עָלְמָא, דְּהָא אִתְחָזֵי פִּרוּדָא. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא זִוֵּוג לָהּ בְּמֹשֶׁה בְּקַדְמִיתָא, וְאִיהוּ הֲוַות כַּלַּת מֹשֶׁה, כְּמָה דְּאִתְּמַר. כֵּיוָן דְּאִזְדַּוְּוגַת בֵּיהּ בְּמֹשֶׁה, נַחְתַּת בְּהַאי עָלְמָא. בְּזִוּוּגָא דְּהַאי עָלְמָא, וְאִתְתַּקָּנַת בְּהַאי עָלְמָא, מָה דְּלָא הֲוָות מִקַּדְמַת דְּנָא, וּלְעוֹלָם לָא הֲוָות בְּפֵרוּדָא.</p>\n<p>אֲבָל לָא הֲוָה בַּר נָשׁ בְּעָלְמָא מִיּוֹמָא דְּאִתְבְּרֵי אָדָם, דְּיֵעִיל רְחִימוּ וְחָבִיבוּ, וּמִלִּין דְּזִוּוּגָא לְעֵילָּא, בַּר שְׁלמֹה מַלְכָּא, דְּאִיהוּ אַתְקִין זִוּוּגָא דִּלְעֵילָּא בְּקַדְמִיתָא, וּלְבָתַר זַמִין לוֹן כַּחֲדָא בְּבֵיתָא דְּאַתְקִין לוֹן. זַכָּאִין אִינּוּן דָּוִד וּשְׁלֹמֹה בְּרֵיהּ, דְּאִינּוּן אַתְקִינוּ זִוּוּגָא דִּלְעֵילָּא. מִיּוֹמָא דְּאָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא לְסִיהֲרָא, זִילִי וְאַזְעִירִי גַּרְמִיךְ, לָא אִזְדַּוְּוגַת בְּזִוּוּגָא שְׁלִים בְּשִׁמְשָׁא, בַּר כַּד אָתָא שְׁלמֹה מַלְכָּא.</p>\n<p>שִׁיר הַשִּׁירִים, הָא הָכָא חָמֵשׁ דַּרְגִּין, לְאִתְדַּבְּקָא בְּעָלְמָא דְּאָתֵי. שִׁיר, חַד. הַשִּׁירִים, תְּרֵין, הָא תְּלַת. אֲשֶׁר, הָא אַרְבְּעָה. לִשְׁלֹמֹה, הָא חַמְשָׁה. בְּחַמִשָׁאָה אִיהוּ. דְּהָא יוֹמָא דְּחַמְשִׁין, רָזָא דְּיוֹבְלָא אִיהוּ.</p>\n<p>תָּא חֲזֵי, זִוּוּגָא דִּלְעֵילָּא לָא יָכִיל שְׁלֹמֹה לְאַתְקְנָא, אֶלָּא בְּגִין דְּאִשְׁתְּכַח זִוּוּגָא לְתַתָּא, מִקַּדְמַת דְּנָא. וּמַאן אִיהוּ. זִוּוּגָא דְּמֹשֶׁה. דְּאִי לָא הֲוֵי זִוּוּגָא דְּנָא, לָא אִתְתָּקַּן זִוּוּגָא דִּלְעֵילָּא. וְכֹלָּא בְּרָזָא עִלָּאָה אִיהוּ, לְחַכִּימֵי לִבָּא.</p>\n<p>כְּתִיב (מלכים א ה׳:י״ב) וַיְדַבֵּר שְׁלֹשֶׁת אֲלָפִים מָשָׁל וַיְהִי שִׁירוֹ חֲמִשָּׁה וָאָלֶף, הַאי קְרָא אוּקְמוּהָ חַבְרַיָּיא. אֲבָל וַיְדַבֵּר שְׁלֹשֶׁת אֲלָפִים מָשָׁל, וַדַּאי עַל כָּל מִלָּה וּמִלָּה דְּאִיהוּ הֲוָה אָמַר, הֲווֹ בֵּיהּ תְּלַת אֶלֶף מְשָׁלֵי, כְּגוֹן סִפְרָא דְּקֹהֶלֶת, דְּאִיהוּ בְּרָזָא עִלָּאָה, וְאִיהוּ בְּאֹרַח מָשָׁל, דְּלֵית בֵּיהּ קְרָא דְּלָאו אִיהוּ בְּחָכְמְתָא עִלָּאָה, וּבְאֹרַח מָשָׁל, אֲפִילּוּ קְרָא זְעִירָא דְּבֵיהּ.</p>\n<p>דְּכַד הֲוָה מָטֵי רַב הַמְנוּנָא סָבָא קַדְמָאָה לְהַאי קְרָא, (קהלת י״א:ט׳) שְׂמַח בָּחוּר בְּיַלְדוּתֶךָ וִיטִיבְךָ לִבְּךָ בִּימֵי בְחוּרוֹתֶךָ הֲוָה בָּכִי. וְאָמַר וַדַּאי הַאי קְרָא יֵאוֹת הוּא, וְאִיהוּ בְּאֹרַח מָשָׁל, וּמַאן יָכִיל לְמֶעְבַּד דְּרָשָׁא בְּמָשָׁל דָּא. וְאִי אִיהוּ דְּרָשָׁא לֵית בֵּיהּ דְּרָשָׁא, אֶלָּא כְּמָה דַּחֲמֵינָן בְּעַיְינִין. וְאִי חָכְמְתָא אִיהוּ, מַאן יָכִיל לְמִנְדַּע לָהּ.</p>\n<p>מִיָּד הֲוָה תָּב וְאָמַר, כְּתִיב, (בראשית ל״ז:ב׳) אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף בֶּן שֶׁבַע עֶשְׂרֵה שָׁנָה וְגוֹ', הַאי קְרָא דְּקֹהֶלֶת, אִיהוּ מָשָׁל לְחָכְמְתָא דִּקְרָא דָּא דְּאוֹרַיְיתָא, וְדָא מָשָׁל לְדָא. שְׂמַח בָּחוּר בְּיַלְדוּתֶךָ, וְהוּא נַעַר. וִיטִיבְךָ לִבְּךָ, הָיָה רֹעֶה אֶת אֶחָיו בַּצֹּאן. בִּימֵי בְחוּרוֹתֶיךָ, אֶת בְּנֵי בִלְהָה וְאֶת בְּנֵי זִלְפָּה נְשֵׁי אָבִיו. וְדָע כִּי עַל כָּל אֵלֶּה, וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה. יְבִיאֲךָ אֱלֹהִים בַּמִּשְׁפָּט, אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף. יוֹסֵף אִתְכְּלִיל בְּיַעֲקֹב, וְרָזִין דְּסִתְרֵי תּוֹרָה, מַאן יָכִיל לְמִנְדַּע לוֹן.</p>\n<p>וְהַאי מָשָׁל אִתְפָּשַׁט לִתְלַת אֶלֶף מְשָׁלִים, וְכֻלְּהוּ <Nonei></i>בְּהַאי מָשָׁל, בְּשַׁעֲתָא דְּיוֹסֵף אִתְכְּלִיל בְּיַעֲקֹב, תְּלַת אֶלֶף אִינּוּן, בְּאַבְרָהָם יִצְחָק וְיַעֲקֹב, דְּכֻלְּהוּ בְּהַאי מָשָׁל בְּרָזָא דְּחָכְמְתָא. וְכָאן, כָּמָה טַיָיעִין אִינּוּן בְּטוֹעַנִין דִּטְמִירוּ, בְּהוּ דַּיָּירֵי תְּרִיסִין, דְּלֵית לְהוֹן חוּשְׁבָּנָא לִטְמִירִין דְּחָכְמְתָא.</p>\n<p>וַיְהִי שִׁירוֹ חֲמִשָּׁה וָאָלֶף, הָכִי אוֹקִימְנָא, וַיְהִי שִׁירוֹ שֶׁל מָשָׁל, וְכֹלָּא חַד, בֵּין מַאן דְּאָמַר וַיְהִי שִׁירוֹ דִּשְׁלֹמֹה, בֵּין מַאן דְּאָמַר וַיְהִי שִׁירוֹ שֶׁל מָשָׁל, כֹּלָּא אִיהוּ חַד, וְכֹלָּא אִיהוּ קָאָמַר, וַיְהִי שִׁירוֹ, דָּא שִׁיר הַשִּׁירִים. וְכִי חֲמִשָּׁה וָאֶלֶף אִיהוּ שִׁיר הַשִּׁירִים. וַדַּאי הָכִי הוּא, חֲמִשָּׁה אִינּוּן תַּרְעִין וּפַתְחִין דְּמִתְפַּתְּחֵי בְּמַלְכָּא דִּשְׁלָמָא דִּילֵיהּ. וְאִינּוּן חֲמֵשׁ מֵאָה שְׁנִין דְּאִילָנָא דְּחַיֵּי. חַמְשִׁין שְׁנִין דְּיוֹבְלָא.</p>\n<p>וָאָלֶף, דָּא אִיהוּ אִילָנָא דְּחַיֵּי, חָתָן דְּנָפִיק מִסִּטְרֵיהּ, וְאִיהוּ יָרִית כָּל אִינּוּן חֲמִשָּׁה, לְמֵיתֵי לְגַבֵּי כַּלָּה. יוֹמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא אֶלֶף שְׁנִין אִיהוּ, וְדָא אִיהוּ נָהָר דְּנָגִיד וְנָפִיק מֵעֵדֶן. יוֹסֵף זַכָּאָה. דְּאִקְרֵי צַדִּיק, עַל שְׁמָא דְּסִיהֲרָא. כְּמַה דְּאַתְנִי בָּהּ קוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין כַּךְ שִׁיר הַשִּׁירִים, קֹדֶשׁ קֳדָשִׁים.</p>\n<p>וְלֵית לְךָ קְרָא בְּשִׁיר הַשִּׁירִים, דְּלָא אִית בֵּיהּ רָזָא דְּחֲמִשָּׁה וָאֶלֶף וַדַּאי. שִׁיר הַשִּׁירִים וַדַּאי הָכִי הוּא. חֲמֵשׁ דַּרְגִּין אִינּוּן בְּהַאי קְרָא, כְּמָה דְּאִתְּמַר. וְאִי תֵּימָא, הָאֶלֶף אֲמַאי לָא אִדְכַּר הָכָא. וַדַּאי הַהוּא אֶלֶף טְמִירָא הֲוָה, וּטְמִירָא אִיהוּ עַד דְּאִתְחֲבָּרַת אִתְּתָא בְּבַעְלָהּ. וְעַל דָּא אִשְׁתָּדַּל שְׁלמֹה, לְמֵיתֵי הַהוּא אֶלֶף לְגַבֵּי כַּלָּה, בִּטְמִירוּ דְּגוּשְׁפַּנְקָא דְּחָכְמְתָא עִלָּאָה.</p>\n<p>כֵּיוָן דְּעָבַד קֹדֶשׁ הַקֳּדָשִׁים לְתַתָּא, גָּנִיז וְטָמִיר, וְעָאל רָזָא דְּקֹדֶשׁ הַקֳּדָשִׁים לְתַמָּן, לְמֶעְבַּד גְּנִיזוּ דְּשִׁמּוּשָׁא שְׁלִים, עֵילָּא וְתַתָּא כְּדְקָא יֵאוֹת. קֹדֶשׁ (קכ\"א ע\"א) הַקָּדָשִׁים אִיהוּ לְעֵילָּא, רָזָא דְּחָכְמְתָא עִלָּאָה, וְיוֹבְלָא. כְּגַוְונָא דָּא יָרְתִין חָתָן וְכַלָּה, יָרוּתָא דְּאַבָּא וְאִמָא.</p>\n<p>וְאִתְהַדְּרוּ אַחֲסָנַת יְרוּתָא בְּגַוְונָא אַחֲרָא. יְרוּתָא דְּאַבָּא, יָרְתָא בְּרַתָּא, בִּסְלִיקוּ דִּשְׁמָא קַדִּישָׁא דָּא, וְאִתְקְרֵי אוּף הָכִי קֹדֶשׁ, חָכְמָה. יָרוּתָא דְּאִמָא, יָרִית בְּרָא, וְאִקְרֵי קֳדָשִׁים, בְּגִין דְּנָטִיל כָּל אִינּוּן קֳדָשִׁים עִלָּאִין, וְכָנִישׁ לוֹן לְגַבֵּיהּ. וּבָתַר יָהִיב לוֹן, וְאָעִיל לוֹן לְגַבֵּי כַּלָּה.</p>\n<p>וְעַל דָּא אָמַר שִׁיר הַשִּׁירִים. שִׁיר, לְגַבֵּי קֹדֶשׁ. הַשִּׁירִים, לְגַבֵּי קֳדָשִׁים, לְמֶהוֵי כֹּלָּא קֹדֶשׁ קֳדָשִׁים, בְּרָזָא חֲדָא כְּמָה דְּאִתְחָזֵי. אֲשֶׁר לִשְׁלֹמֹה הָא אִתְּמַר לְמַלְכָּא דִּשְׁלָמָא דִּילֵיהּ.</p>\n<p>וְאִי תֵּימָא שְׁבָחָא דָּא דִּילֵיהּ הוּא. לָא תֵּימָא הָכִי, אֶלָּא שְׁבָחָא בַּאֲתָר עִלָּאָה אִיהוּ סַלְּקָא. אֲבָל הָכָא הוּא רָזָא. כַּד מְתַּתְקְנָן דְּכָר וְנוּקְבָּא כַּחֲדָא, תְּחוֹת מַלְכָּא עִלָּאָה, כְּדֵין הַהוּא מַלְכָּא אִסְתַּלִיק לְעֵילָּא, וְאִתְמַלְיָא מִכָּל קִדוּשִׁין, וּמִכָּל בִּרְכָּאן, דְּנַגְדִּן לְתַתָּא, וְאִתְמְלֵי וְאָרִיק לְתַתָּא, וְדָא אִיהוּ תִּיאוּבְתֵּיהּ דְּמַלְכָּא עִלָּאָה, כַּד אִתְמְלֵי קִדּוּשָׁן וּבִרְכָּאן, וְאָרִיק לְתַתָּא.</p>\n<p>וְעַל דָּא אִיהוּ צְלוֹתִין וּבָעוּתִין, דְּיִתְתָּקַּן וְאִתְמַלְיָא הַהוּא מַבּוּעָא עִלָּאָה. דְּכֵיוָן דְּאִיהוּ מִתְתָּקַּן כַּדְקָא יֵאוֹת, מֵחֵיזוּ דִּילֵיהּ, וּמֵחֵיזוּ דְּהַהוּא תִּקּוּנָא, מִתְתַּקְנָא עָלְמָא תַּתָּאָה, וְעוּלֶמְתָּהָא. וְלָא אִצְטְרִיךְ עָלְמָא תַּתָּאָה לְאִתְתַּקְנָא, אֶלָּא מֵחֵיזוּ דְּעָלְמָא עִלָּאָה. סִיהֲרָא, לֵית לָהּ חֵיזוּ מִגַרְמָהָא כְּלַל, בַּר כַּד אִתְתָּקַּן בְּשִׁמְשָׁא וְאַנְהִיר, וּמֵחֵיזוּ דְּשִׁמְשָׁא וְתִקּוּנָא דִּילֵיהּ אִתְתַּקְנַת סִיהֲרָא וְאִתְנְהִירַת.</p>\n<p>מַה דְּאִצְטְרִיךְ צְלוֹתִין וּבָעוּתִין, דְּיִתְנְהִר וְיִתְתָּקַן הַהוּא אֲתָר דְּנָפְקָא מִנֵּיהּ נְהוֹרָא, דְּכֵיוָן דְּהַהוּא אֲתָר מִתְתָּקְנָא, מֵחֵיזוּ דִּילֵיהּ, אִתְתָּקַּן כָּל מַאן דִּלְתַתָּא. וּבְגִין כַּךְ תּוּשְׁבַּחְתָּא דְּקָאָמַר שְׁלֹמֹה, לָא אִשְׁתָּדַּל אֶלָּא בְּגִין מַלְכָּא דִּשְׁלָמָא דִּילֵיהּ, דְּיִתְתָּקַּן. כֵּיוָן דְּאִיהוּ אִתְתָּקַּן, מֵחֵיזוּ דִּילֵיהּ, כֹּלָּא יִתְתָּקַּן. וְאִי אִיהוּ לָא אִתְתָּקַּן, לֵית לָהּ תִּקּוּנָא לְסִיהֲרָא לְעָלְמִין, וּבְגִין כַּךְ אֲשֶׁר לִשְׁלֹמֹה. דְּיִתְתָּקַּן וְיִתְמַלֵי כַּדְקָא יֵאוֹת בְּקַדְמִיתָא, כְּמָה דְּאִתְּמַר.</p>"],[9520011730,"<p><Nonei></i>(שמות כ״ה:ב׳) וְיִקְחוּ לִי תְּרוּמָה מֵאֵת כָּל אִישׁ וְגוֹ', רָזָא דְּרָזִין לְיַדְעֵי חָכְמְתָא, כַּד אִסְתַּלָּק בִּרְעוּתָא דְּסִתְרָא דְּכָל סִתְרִין לְמֶעְבַּד יְקָרָא לִיקָרֵיהּ, אַנְשִׁיב רוּחָא מִנְקוּדָה עִלָּאָה, דְּנָגִיד מִלְּעֵילָּא לְתַתָּא, וְשַׁוֵּי תְקּוּנֵיהּ, לְאִתְיַשְּׁבָא בְּהַאי עָלְמָא. אֲמַאי. בְּגִין דְּאִי לָא יְהֵא עִקָּרָא וְשָׁרְשָׁא בְּהַאי עָלְמָא, לָא יְהֵא מָאנָא לְאַרְקָא בְּהַאי עָלְמָא כְּלַל. וְאִי לָא יָרִיק לְהַאי עָלְמָא, מִיָּד אִתְאֲבִיד, וְלָא יָכִיל לְקַיְּימָא אֲפִילּוּ רִגְעָא חֲדָא. אֲבָל בְּגִין דְּתִקוּנֵיהּ אִיהוּ מֵהַאי עָלְמָא אִתְמְלֵי מִסִּטְרָא חֲדָא לְאַרְקָא לְהַאי עָלְמָא, וּמִסִּטְרָא אַחֲרָא לְאַרְקָא לְמַלְאֲכֵי עִלָּאֵי. וְכֹלָּא אִתְּזָנוּ מִנֵּיהּ כַּחֲדָא.</p>\n<p>שְׁלִימוּ דְּתִקּוּנָא דְּהַאי רוּחָא, רוּחֵיהוֹן דְּצַדִּיקַיָּא בְּהַאי עָלְמָא. רוּחָא דָּא אִשְׁתְּלִים, בְּזִמְנָא דַּחֲנוֹךְ וְיֶּרֶד וּמַהֲלַלְאֵל הֲווֹ בְּעָלְמָא וְכַד אַסְגִּיאוּ חַיָּיבֵי עָלְמָא, אַעְדּוּ הַהוּא שְׁלִימוּ מִנֵּיהּ. לְבָתַר דְּאִתְאֲבִידוּ, אָתָא נֹחַ וְאַשְׁלִים לֵיהּ. אָתָא דּוֹר הַפְּלָגָה, אַעְדּוּ הַהוּא שְׁלִימוּ מִנֵּיהּ. אָתָא אַבְרָהָם וְאַשְׁלִים לֵיהּ. אָתוּ אַנְשֵׁי סְדוֹם וְאַעֲדוּ לֵיהּ. אָתָא יִצְחָק וְאַשְׁלִים לֵיהּ. אָתוּ פְּלִשְׁתִּים וְחַיָּיבֵי דָּרָא וְאַעֲדוּ לֵיהּ מִנֵּיהּ. אָתָא יַעֲקֹב וּבְנוֹי, עַרְסָא שְׁלֵימָא, וְאַשְׁלִימוּ לֵיהּ.</p>\n<p>נָפְקוּ מֵאַרְעָא קַדִּישָׁא וְנַחְתּוּ לְמִצְרַיִם, וּבְגִינַיְיהוּ אִתְעַכָּבַת תַּמָּן. וּבְגִין דְּאָהַדְרִי תַּמָּן יִשְׂרָאֵל לְעוֹבָדִין דְּמִצְרָאֵי, אִתְכַּפְיָא וְאִתְעָדֵי הַהוּא שְׁלִימוּ, עַד דְּנַפְקוּ מִמִּצְרָיִם, וְאָתוּ לְמֶעְבַּד מַשְׁכְּנָא. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, רְעוּתִי לְדַיְּירָא בֵּינַיְיכוּ, אֲבָל לָא יָכִילְנָא עַד דִּתְתַקְנוּן הַהוּא רוּחָא דִּילִי, דְּיִשְׁרֵי בְּגַּוַויְיכוּ. הֲדָא הוּא דִכְתִיב, וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם.</p>\n<p>וְדָא אִיהוּ רָזָא דִּכְתִּיב, וְיִקְחוּ לִי תְּרוּמָה. אָמַר מֹשֶׁה לְקוּדְשָׁא בְּרִיךְ הוּא מַאן יָכִיל לְמֵיסַב לָהּ וּלְמֶעְבַּד לָהּ. אֲמַר לֵיהּ, מֹשֶׁה, לָא כְּמָה דְּאַתְּ חָשִׁיב, אֶלָּא מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ וְגוֹ', מֵהַהוּא רְעוּתָא וְרוּחָא דִּלְהוֹן, תִּסְבּוּן לָהּ, וְתַשְׁלִמוּן לָהּ.</p>\n<p>כַּד אָתָא שְׁלֹמֹה, אַתְקִין לְהַהוּא רוּחָא בִּשְׁלִימוּ דִּלְעֵילָּא, דְּהָא מִן יוֹמָא דְּאִשְׁתְּלִים לְתַתָּא בְּיוֹמוֹי דְּמֹשֶׁה, לָא אַעְדִּיאוּ הַהוּא שְׁלִימוּ מִנֵּיהּ. (עד דאתא שלמה) כֵּיוָן דְּאָתָא שְׁלמֹה, אִשְׁתָּדַּל לְאַשְׁלְמָא לֵיהּ לְעֵילָּא, וְשַׁאֲרִי לְאַתְקְנָא חֵיזוּ דְּעָלְמָא עִלָּאָה, לְאִתְתַּקְנָא מֵהַהוּא חֵיזוּ עָלְמָא תַּתָּאָה, וְדָא אִיהוּ אֲשֶׁר לִשְׁלֹמֹה.</p>"],[9520011731,"<p>(שמות כ״ה:ג׳) וְזֹאת הַתְּרוּמָה, הָא אִתְּמַר, דְּכַד קוּדְשָׁא בְּרִיךְ הוּא אִתְגְּלֵי עַל טוּרָא דְּסִינַי, כַּד אִתְיְהִיבַת אוֹרַיְיתָא לְיִשְׂרָאֵל בְּעֶשֶׂר אֲמִירָן. כָּל אֲמִירָה וַאֲמִירָה עָבִיד קַלָּא, וְהַהוּא קַלָּא אִתְפְּרַשׁ לְע' קַלִין, וַהֲווּ כֻּלְּהוּ נְהִירִין וְנָצְצִין לְעֵינַיְיהוּ דְּיִשְׂרָאֵל כֻּלְּהוּ, וַהֲווּ חֲמָאן עַיְינִין בְּעַיְינִין זִיו יְקָרָא דִּילֵיהּ, הֲדָא הוּא דִּכְתִּיב, (שמות כ׳:ט״ו) וְכָל הָעָם רוֹאִים אֶת הַקּוֹלֹת. רוֹאִים וַדַּאי.</p>\n<p>וְהַהוּא קַלָּא הֲוָה אַתְרֵי בֵּיהּ בְּכָל חַד וְחַד מִיִּשְׂרָאֵל, וְאָמַר לוֹן, תְּקַבְּלֵנִי עֲלָךְ, בְּכַךְ וְכַךְ פִּקּוּדִין דִּבְאוֹרַיְיתָא, וְאָמְרוּ הִין. אַהְדָּר לֵיהּ עַל רֵישֵׁיהּ, וּמִתְגַּלְגְּלָא עָלֵיהּ, וַהֲוָה אַתְרֵי בֵּיהּ, וְאָמַר לֵיהּ, תְּקַבְּלֵנִי עָלָךְ בְּכַךְ עוֹנָשִׁין דִּבְאוֹרַיְיתָא, וַהֲוָה אָמַר הִין. לְבָתַר אַהְדָּר הַהוּא קַלָּא, וְנָשִׁיק לֵיהּ בְּפוּמֵיהּ, הֲדָא הוּא דִכְתִיב, (שיר השירים א׳:ב׳) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ.</p>\n<p>וּכְדֵין כָּל מָה דַּהֲווֹ חֲמָאן יִשְׂרָאֵל בְּהַהוּא זִמְנָא, הֲווֹ חֲמָאן גּוֹ חַד נְהוֹרָא, דְּקַבִּיל כָּל אִינּוּן נְהוֹרִין אַחֲרָנִין, וַהֲווּ תָּאָבִין לְמֵחמֵי. אָמַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא, הַהוּא נְהוֹרָא דְּחָמִיתוּ בְּטוּרָא דְּסִינַי, דְּקַבִּיל כָּל אִינּוּן גְּוָונֵי נְהוֹרִין, וְתִיאוּבְתָּא דִּלְכוֹן עָלֵיהּ, תְּקַבְּלוּן לָהּ וְתִסְבוּן לָהּ לְגַּבַּיְיכוּ, וְאִינּוּן גַּוְונִין דְּאִיהִי מְקַבְּלָא, אִלֵּין אִינּוּן זָהָב וָכֶסֶף וּנְחֹשֶׁת וְגוֹ'.</p>\n<p>דָּבָר אַחֵר יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ, מַאי קָא חָמָא שְׁלֹמֹה מַלְכָּא, דְּאִיהוּ אָעִיל מִלֵּי דִּרְחִימוּ בֵּין עָלְמָא עִלָּאָה לְעָלְמָא תַּתָּאָה, וְשֵׁירוּתָא דְּתוּשְׁבַּחְתָּא דִּרְחִימוּ דְּאָעִיל בֵּינַיְיהוּ, יִשָּׁקֵנִי אִיהוּ. אֶלָּא הָא אוּקְמוּהָ (קכ\"ד ע\"ב) וְהָכִי אִיהוּ, דְּלֵית רְחִימוּ דִּדְבֵיקוּת דְּרוּחָא <Nonei></i>בְּרוּחָא, בַּר (רנ\"ו ע\"ב) נְשִׁיקָה. וּנְשִׁיקָה בְּפוּמָא, דְּאִיהִי מַבּוּעָא דְּרוּחָא, וּמַפְקָנוּ דִּילֵיהּ. וְכַד נַשְׁקִין דָּא לְדָא, מִתְדַּבְּקָן רוּחִין אִלֵּין בְּאִלֵּין, וַהֲווּ חַד, וּכְדֵין אִיהוּ רְחִימוּ חַד.</p>\n<p>בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא קַדְמָאָה, הֲוָה אָמַר עַל הַאי קְרָא, נְשִׁיקָה דִּרְחִימוּ אִתְפָּשַׁט לְד' רוּחִין, וְד' רוּחִין מִתְדַּבְּקָן כַּחֲדָא, וְאִינּוּן גּוֹ רָזָא דִּמְהֵימְנוּתָא וְסַלְּקִין בְּד' אַתְוָון, וְאִינּוּן אַתְוָון דִּשְׁמָא קַדִּישָׁא תָּלֵי בְּהוּ, וְעִלָּאִין וְתַתָּאִין תַּלְיָין בְּהוּ. וְתוּשְׁבַּחְתָּא דְּשִׁיר הַשִּׁירִים תָּלֵי בְּהוּ. וּמַאן אִיהוּ. אַהֲבָ\"ה. וְאִינּוּן רְתִיכָא עִלָּאָה. וְאִינּוּן חַבְרוּתָא וּדְבֵקוּתָא וּשְׁלִימוּ דְּכֹלָּא.</p>\n<p>אִלֵּין אַתְוָון. ד' רוּחִין אִינּוּן. וְאִינּוּן רוּחִין דִּרְחִימוּ וְחֶדְוָה דְּכָל שַׁיְיפֵי גּוּפָא בְּלָא עֲצִיבוּ כְּלַל. ד' רוּחִין אִינּוּן בִּנְשִׁיקָה, כָּל חַד וְחַד כָּלִיל בְּחַבְרֵיהּ. וְכַד הַאי רוּחָא כָּלִיל בְּאַחֲרָא, וְהַהוּא אַחֲרָא כָּלִיל בְּהַאי. אִתְעָבִידוּ תְּרֵין רוּחִין כַּחֲדָא. וּכְדֵין מִתְחַבְּרָן בִּדְבִּיקוּ חַד, אִינּוּן אַרְבַּע בִּשְׁלִימוּ, וְנַבְעִין דָּא בְּדָא, וְאִתְכְּלִילוּ דָּא בְּדָא.</p>\n<p>וְכַד מִתְפַּשְּׁטָן, (נ\"א מתפרשן) אִתְעָבִיד מֵאִינּוּן אַרְבַּע רוּחִין חַד אִיבָּא, וְאִיהוּ רוּחָא חֲדָא דְּכָלִיל מְד' רוּחִין. וְדָא סָלִיק וּבָקַע רְקִיעִין, עַד (רכ\"ג ע\"ב) דְּסָלִיק וְיָתִיב לְגַבֵּי חַד הֵיכָלָא. דְּאִתְקְרֵי הֵיכָלָא דְּאַהֲבָה, וְאִיהוּ הֵיכָלָא דְּכָל רְחִימוּ תַּלְיָא בֵּיהּ. וְהַהִיא רוּחָא הָכִי אִקְרֵי אַהֲבָה, וְכַד הַאי רוּחָא סָלִיק אִתְּעַר לְהַהוּא הֵיכָלָא, לְאִתְחַבְּרָא לְעֵילָּא.</p>\n<p>ד ' אַתְוָון אִינּוּן, לְגַבֵּי ד' רוּחִין. וְאִינּוּן אַהֲבָה. וְאִיבָּא דִּלְהוֹן אַהֲבָה. כַּד מִתְחַבְּרָן דָּא בְּדָא, מִיַּד אִתְּעַר דָּא בִּסְטַר דָּא וְדָא בִּסְטַר דָּא. א'. מִיָּד נָפִיק ה', וְאִתְחַבָּר בְּא', מִתְדָּבַק בִּדְבִיקוּ בִּרְחִימוּ. וְאִתְעֲבִידוּ (נ\"א ואתערו) תְּרֵין אַתְוָון אַחֲרָנִין, ב' ה', וְאִתְכְּלִילוּ רוּחִין בְּרוּחִין בִּדְבִּיקוּ דִּרְחִימוּ, וּפַרְחִין אִלֵּין אַתְוָון מִנַּיְיהוּ, בְּהַהוּא רוּחָא דְּסָלִיק, וּמִתְעַטְּרָן בֵּיהּ כְּדְקָא יֵאוֹת.</p>\n<p>כֵּיוָן דְּאָזִיל וְסָלִיק הַהוּא אַהֲבָה שְׁלֵימָא, כְּלִילָא בְּכָל אִינּוּן אַרְבַּע רוּחִין, פָּגַע בְּחַד מְמָנָא עִלָּאָה רַבְרְבָא, דִּי מְמָנָא עַל אֶלֶף וּתְשַׁע מֵאָה וְתִשְׁעִין רְקִיעִין, וְאִיהוּ מְמָנָא עַל נְגִידוּ דִּתְלֵיסָר נַהֲרֵי אֲפַרְסְמוֹנָא דַּכְיָא, דְּנַגְדָּא מֵרָזָא דְּטַלָא דִּלְעֵילָּא. וְהַהוּא נְגִידוּ אִתְקְרֵי מַיִם רַבִּים. כֵּיוָן דְּפָגַע לְגַבֵּי הַהוּא רַב מַשְׁרְיָין קָאִים לְגַבֵּיהּ, וְלָא יָכִיל לְאַעְכָּבָא לֵיהּ, וְאַעֳבַר בְּהוּ עַד דְּאָעִיל לְגַבֵּי הֵיכָל אַהֲבָ\"ה.</p>\n<p>עַל דָּא אָמַר שְׁלֹמֹה, בְּסִיוּם שְׁבָחֵיהּ, (שיר השירים ח׳:ז׳) מַיִם רַבִּים לא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה. מַיִם רַבִּים: אִלֵּין מַיִם עִלָּאִין דְּנַגְדִּין גּוֹ (ס\"א מגו) טַלָּא עִלָּאָה. וּנְהָרוֹת לָא יִשְׁטְפוּהָ: אִלֵּין אִינּוּן נַהֲרֵי אֲפַרְסְמוֹנָא דַּכְיָא, דְּאִינּוּן תְּלֵיסַר. הַהוּא מְמָנָא אִיהוּ מַלְאָכָא דְּשָׁלִיחַ מִן קֳדָם יְיָ', וְדָא אִיהוּ רַב מַשִּׁרְיָין דְּקָשִׁיר כִּתְרִין לְמָארֵיהּ, רָזָא אַכְתָרִיאֵ\"ל, מְעַטֵּר עִטְרִין לְמָארֵיהּ, בִּשְׁמָא גְּלִיפָא מְחֻקָּקָא, יְהוָֹה יָהּ צְבָאוֹת.</p>\n<p>כֵּיוָן דְּאָעִיל לְגַבֵּי הֵיכָל (נ\"א דאזיל וסליק ההוא) אַהֲבָה, אִתְעַר רְחִימוּ דְּנְשִׁיקִין עִלָּאִין, דִּכְתִּיב, (בראשית כ״ט:י״א) וַיִּשַּׁק יַעֲקֹב לְרָחֵל, לְמֶהֱוֵי נְשִׁיקִין דִּרְחִימוּ עִלָּאָה כְּדְקָא יֵאוֹת, וְאִינּוּן נְשִׁיקִין שֵׁירוּתָא דְּאִתְעֲרוּ דְּכָל רְחִימוּ, וְאִתְדַּבְּקוּתָא וְקִשּׁוּרָא דִּלְעֵילָּא. וּבְּגִין כָּךְ שֵׁירוּתָא דְּתוּשְׁבַּחְתָּא דְּשִׁירָתָא דָּא אִיהוּ יִשָּׁקֵנִי.</p>\n<p>מַאן יִשָּׁקֵנִי. הַהוּא דְּסָתִים גּוֹ סְתִימוּ עִלָּאָה. וְאִי תֵּימָא, סְתִימָא דְּכָל סְתִימִין בֵּיהּ תַּלְיָין נְשִׁיקִין וְנָשִׁיק לְתַתָּא. תָּא חֲזֵי, סְתִימָא דְּכָל סְתִימִין, לֵית מַאן דְּיָדַע לֵיהּ, וְאִיהוּ גַּלֵּי מִנֵּיהּ נְהִירוּ חַד דָּקִיק סָתִים, דְּלָא אִתְגְּלֵי בַּר בְּחַד שְׁבִיל דָּקִיק דְּאִתְפָּשַּׁט מִגַּוֵיהּ, וְאִיהוּ נְהִירוּ דְּנָהִיר לְכֹלָּא. וְדָא אִתְּעֲרוּ דְּכָל רָזִין עִלָּאִין. וְאִיהוּ סָתִים. לְזִמְנִין סָתִים, לְזִמְנִין אִתְגַּלְיָא. וְאַף עַל גַּב דְּלָא אִתְגַּלְיָא כְּלַל. וְאִתְּעֲרוּ דִּסְלִיקוּ דְּנְשִׁיקִין בֵּיהּ תַּלְיָין. וּמִגּוֹ דְּאִיהוּ סָתִים, שֵׁירוּתָא דְּתוּשְׁבַּחְתָּא בְּאֹרַח סָתִים אִיהוּ.</p>\n<p>וְאִי בֵּיהּ תַּלְיָין מַה בָּעֵי יַעֲקֹב הָכָא, דְּהָא בֵּיהּ תַּלְיָין נְשִׁיקִין. אֶלָּא וַדַּאי הָכִי הוּא. יִשָּׁקֵנִי, הַהוּא דְּסָתִים לְעֵילָּא. וּבְמָּה. <Nonei></i>בְּהַהוּא רְתִיכָא (נ\"א בוצינא) עִלָּאָה, דְּכָל גַּוְונִין תַּלְיָין וּמִתְחַבְּרָן בֵּיהּ. וְהַאי אִיהוּ יַעֲקֹב. כְּמָה דְּאַמְרִינָן, דְּבֵיקוּתָא לְאִתְדַּבְּקָא בְּמַלְכָּא בִּבְרָא דִּילֵיהּ הוּא. וְעַל דָּא כְּתִיב (שיר השירים א׳:ב׳) מִנְּשִׁיקוֹת פִּיהוּ.</p>\n<p>כִּי טוֹבִים דּוֹדֶיךָ, אַהְדָּר לְגַבֵּי שִׁמְשָׁא, דְּאַנְהִיר לָהּ לְסִיהֲרָא, מִגּוֹ נְהִירוּ דְּאִינּוּן בּוּצִינִין עִלָּאִין, וְאִיהוּ נָטִיל נְהוֹרָא דְּכֻלְּהוּ, וְאַנְהִיר לְסִיהֲרָא. וְאִינּוּן בּוּצִינִין (נ\"א נשיקין) עִלָּאִין, וְאִיהוּ נָטִיל נְהוֹרָא דְּכֻלְּהוּ, וְאַנְהִיר לְסִיהֲרָא וְאִינּוּן בּוּצִינִין דְּמִזְדַּוְּוגִין בֵּיהּ, מֵאָן אֲתָר נַהֲרִין. הָדָר וְאָמַר מִיָּיִן, מֵהַהוּא יַיִן דְּמִנְטְרָא, מֵהַהוּא יַיִן דְּאִיהוּ חֶדְוָה דְּכָל חֶדְוָון. וּמַאן אִיהוּ הַהוּא יַיִן, דְּיָהִיב חַיִּין וְחֶדְוָה לְכֹלָּא. דָּא אֱלהִים חַיִּים, יַיִן, דְּיָהִיב חַיִּין וְחֶדְוָה לְכֹלָּא.</p>\n<p>תּוּ מִיָּיִן, מֵהַהוּא שְׁמָא דְּאִקְרֵי ידִוִֹ\"ד, דָּא אִיהוּ יַיִן דְּחֶדְוָה דִּרְחִימוּ דְּרַחֲמֵי, וּמִן דָּא, כֻּלְּהוּ נְהִירִין וְחַדָּאן. אָתוּ חַבְרַיָּיא וְנָשִׁיקוּ לֵיהּ בְּרֵישֵׁיהּ. (כד מטו לגבי דרבי שמעון סדרו מילין קמיה)</p>\n<p>בָּכָה רַבִּי שִׁמְעוֹן, וְאָמַר, יָדַעְנָא וַדַּאי דְּרוּחָא קַדִּישָׁא עִלָּאָה קָא מְכַשְׁכְּשָׁא (ד\"א מנצצא) בְּכוּ, זַכָּאָה דָּרָא דָּא, דְּהָא לָא יְהֵא כְּדָרָא דָּא, עַד זִמְנָא דְּיֵיתֵי מַלְכָּא מְשִׁיחָא. דְּהָא אוֹרַיְיתָא אִתְהַדְּרַת לְעַתִּיקוּתָהָא. זַכָּאִין אִינּוּן צַדִּיקַיָּא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.</p>"],[9520011732,"<p>(שמות כ״ה:ג׳) וְזֹאת הַתְּרוּמָה אֲשֶׁר תִּקְחוּ מֵאִתָּם. רַבִּי אֶלְעָזָר אָמַר, הַאי קְרָא אוּקְמוּהָ, וְרָזִין דִּילֵיהּ הָא אִתְּמַר. אֲבָל (פשטא) רָזָא דִּקְרָא הָכִי אוֹלִיפְנָא, וְקַשְׁיָין קְרָאֵי, דְּאִי אִינּוּן בְּרָזָא דִּלְתַתָּא קַשְׁיָין אֲהַדְדֵי. וְאִי בְּרָזָא דִּלְעֵילָּא לָא אִינּוּן בִּנְהִירוּ. (אלא הכי הוא) דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִקְחוּ לִי תְּרוּמָה שַׁפִּיר. תִּקְחוּ אֶת תְּרוּמָתִי קַשְׁיָא. וְזֹאת הַתְּרוּמָה אֲשֶׁר תִּקְחוּ מֵאִתָּם קַשְׁיָא וְדָּא (ס\"א ודאי) כֹּלָּא, עֵילָּא וְתַתָּא כַּחֲדָא.</p>\n<p>אֶלָּא הָכִי אִיהוּ, וְיִקְחוּ לִי תְּרוּמָה. מַאן. בְּנֵי יִשְׂרָאֵל. מֵאֵת כָּל אִישׁ: אִלֵּין מַלְאָכִין עִלָּאִין לְעֵילָּא, בְּגִין דְּעַלֵיהוֹן אִיהִי תְּרוּמָה, אַרָמוּתָא דְּאִינּוּן אָרִימוּ לָהּ תָּדִיר לְגַבֵּי מַלְכָּא עִלָּאָה דְּהָא אִינּוּן סַלְּקִין לָהּ תָּדִיר, לְגַבֵּי מַלְכָּא עִלָּאָה. וְכַד יִשְׂרָאֵל זַכָּאִין, אִינּוּן נַטְלִין לָהּ מִנַּיְיהוּ, וְנַחְתִּין לָהּ לְתַתָּא, הֲדָא הוּא דִכְתִיב, מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ. וּמַאן אִינּוּן. אִינּוּן אַרְבַּע דְּאָרִימוּ לָהּ לְעֵילָּא. דְּהַהוּא לֵב אִתְרְעֵי בְּהוּ. וְהַהִיא תְּרוּמָה. אִיהִי זַקְפָא עָלַיְיהוּ.</p>\n<p>וְאַף עַל גַּב דְּאִיהִי קַיָּימָא עָלַיְיהוּ, וּמַנְחָא עַל גַּבַּיְיהוּ. תִּקְחוּ: תִּסְבוּן לָהּ מִנַּיְיהוּ לְנַחְתָּהָא לְתַתָּא. וּבְמַה. בְּזִמְנָא דָּא, בְּאִינּוּן עוֹבָדִין דְּכַשְׁרָאן, בִּצְלוֹתִין וּבְבָעוּתִין, לְמֶעְבַּד פִּקּוּדֵי אוֹרַיְיתָא. בְּהַהוּא זִמְנָא, בְּאִינּוּן גַּוְונִין דְּאִתְחַזְיָין לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא, בְּאִינּוּן פּוּלְחָנִין (אחרנין.) וְאִינּוּן גַּוְונִין אַמְשְׁכָאן לְתַתָּא הַהוּא אַרָמוּתָא, וְנַצְחָן גַּוְונִין דִּלְתַתָּא, לְאִינוּן גַּוְונִין דִּלְעֵילָּא, וּמַשְׁכִין לוֹן גַּוְונִין אִלֵּין, לִגְוָונִין עִלָּאִין, וְעַיְילִין אִלֵּין בְּאִלֵּין, וְאִתְעָבִידוּ אִלֵּין גּוּפָא לְאִלֵּין, וְעַל דָּא תִּקְחוּ מֵאִתָּם כְּתִיב.</p>\n<p>זָהָב דְּאִתְכְּלִיל בְּגַּבְרִיאֵל, זָהָב לְעֵילָּא, גַּבְרִי\"אֵל נָטִיל לֵיהּ לְתַתָּא. וְשִׁבְעָה זִינֵי זָהָב אִתְפָּרְשָׁאן לְתַתָּא מִן דָּא. וָכֶסֶף לְעֵילָּא, וְאִתְכְּלִיל בְּמִיכָאֵל לְתַתָּא, וְשַׁרְיָא דָּא עַל דָּא. וּנְחֹשֶׁת לְעֵילָּא, וְנָפְקָא מִן זָהָב, בְּגִין דְּזָהָב וְאֶשָּׁא בְּרָזָא חֲדָא קַיְימִין וְאַזְלִין, אֶשָּׁא אַפִּיק נְחֹשֶׁת. וּמֵחֵילָא וְתֻּקְפָּא דָּא, אִתְבַּדְרָן (נ\"א אתערון) נְחָשִׁים שְׂרָפִים דְּנַפְקֵי מֵאֶשָּׁא. וְעַל דָּא, נְחֹשֶׁת אִיהוּ סוּמָקָא כְּאֶשָּׁא וְאִתְכְּלִיל בְּאוּרִי\"אֵל (נ\"א נוריא\"ל) וְאִתְעָבִיד דָּא גּוּפָא לְגַבֵּי דָּא.</p>\n<p>וּתְכֵלֶת שַׁרְיָא בְּדָא וּבְדָא, בַּנְּחֹשֶׁת וּבַזָּהָב, וּבְגִין דְּאִתְתָּקַּף בִּתְרֵין סִטְרִין. תְּכֵלֶת אִיהוּ תַּקִּיפָא, וְלֵית מַאן דְּשַׁלְטָא (קנ\"ב ע\"א) עָלֵיהּ לְחַיִין, דְּאִיהוּ כֻּרְסְיָּיא דְּדִינָא לְשַׁרְיָא בֵּיהּ דִּינָא תַּקִּיפָא, וְדָא אִיהוּ ב\"ו א\"ל ב\"ו א\"ל דִּכְתִּיב, (תהלים ז) וְאֵל זוֹעֵם בְּכָל יוֹם. וְכַד אִתְהַדְרָן בְּנִי נָשָׁא בְּתִיוּבְתָּא שְׁלֵימָתָא, (ר\"ס ע\"ב, ר\"י ע\"א) אִתְהַדָּר שְׁמֵיהּ רְפָאֵ\"ל, דְּהָא אַסְוָותָא אִזְדָּמַן לְהוּ מֵהַהוּא דִּינָא <Nonei></i>קַשְׁיָא.</p>\n<p>וְאַרְגָּמָן: דָּא זָהָב וָכֶסֶף, דְּאִתְהַדְרָן לְאַכְלְלָא כַּחֲדָא, מִיכָאֵל וְגַבְרִיאֵל אִתְכְּלִילוּ דָּא עִם דָּא, מְשֻׁלְּבָאן דָּא בְּדָא. וְעַל דָּא כְּתִיב, (איוב כ״ה:ב׳) עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. וּבְגִין דְּאִינּוּן מְשֻׁלְּבָאן דָּא בְּדָא, אִתְעָבִידוּ גּוּפָא חַד.</p>\n<p>וְתוֹלַעַת שָׁנִי לְעֵילָּא, וְאִתְכְּלִיל בְּאוּרִיאֵ\"ל כְּמִלְּקַדְּמִין, לְמֶהוֵי אֲחִידוּ גּוֹ תְּכֵלֶת, וּבְגוֹ אַרְגָּמָן. וְשֵׁשׁ אִיהוּ לְעֵילָּא, וְאִתְכְּלִיל כְּמִלְּקַדְּמִין בְּרָזָא דִּרְפָאֵל, לְאִתְאַחֲדָא בַּכֶּסֶף וּבַזָּהָב.</p>\n<p>עַד הָכָא, רָזָא דְּז' עַמּוּדִין לְעֵילָּא, גּוֹ ז' עַמּוּדִים דִּלְתַתָּא. קְלִיפָּה גּוֹ קְלִיפָּה, לִנְטוּרָא. וְעִזִּים: הָא אוֹקִימְנָא דְּהָא אִלֵּין ז', מוֹחָא לְמוֹחָא, וְדָא אִיהוּ קְלִיפָּה לְמוֹחָא.</p>\n<p>(שמות כ״ה:ה׳) וְעוֹרוֹת אֵלִים מְאָדָּמִים, אִלֵּין אִינּוּן מָארֵי תְּרִיסִין, עַיְינִין מְלַהֲטִין בְּטִיסִין דְּנוּרָא, כְּמָה דְאַתְּ אָמֵר, (דניאל י׳:ו׳) וְעֵינָיו כְּלַפִּידֵי אֵשׁ. וְאִקְרוּן רְקִיעִין לְבַר בְּגוֹ קְלִיפָה. (שמות כ״ה:ה׳) וְעוֹרוֹת תְּחָשִׁים, אִלֵּין אִינּוּן לְגוֹ בְּסִטְרָא קַדִּישָׁא, וְאִתְאַחֲדָן בִּקְדוּשָׁה, וְלָא אִתְאַחֲדָן.</p>\n<p>כְּמָה (קל\"ט ע\"א) דְּאַמָרָן דְאַבְרָהָם הָא אוֹלִיד בְּאִינְתוּ אַחֲרָא תַּחַשׁ כְּמָה דְאַתְּ אָמֵר (קל\"ט א') וְאֶת תַּחַשׁ וְאִלֵּין אִינּוּן בְּאִימָא דְיִשְׁמָעֵאל אֲחוּהוֹן דְיִשְׁמָעֵאל דְּכְּמָה דְּאִית דַּרְגָּא בְּעֵשָׂו הֲכִי נָמֵי אִית דַּרְגָּא בְּיִשְׁמָעֶאל. אִימָא דְיִשְׁמָעֵאל אוֹלִידת לְתָּחַשׁ וּמִסִּטְרָא דְאַבְרָהָם קַאֲתָּת דְהָא נְהוֹרָא קַדְמָאָה (ויקרא רצ\"ב ב') מצפ\"ץ בְּשַׁעֲתָא דְּנָפַק נְהוֹרִין לְכָל סִטְרִין. כֵּיוָן דְּאִתְבְּסָם הַהוּא נְהוֹרָא קַדְמָאָה גָּנִיז לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא וּלְמָאן גָּנִיז לֵיהּ (שם צ\"א ב') לְצַדִּיקַיָּיא. וּמָאן אִינּוּן. צַדִּיק וְצֶדֶק בְּגִין לְמֶעְבָּד בְּהַהוּא נְהוֹרָא קַדְמָאָה אִיבִּין לְעָלְמָא. וְאִינּוּן אִיבִּין דִּזְמִינִין לְמֵיתֵי לְעָלְמָא. דְהָא אַבְרָהָם וְשָׂרָה עָבְדוּ (ס\"א ואברהם ושרה מההוא נהורא עבדו) אִיבִּין וְנַפְשִׁין דִּכְתִיב (בראשית י״ב:ה׳) וְאֶת הַנֶּפֶשׁ אֲשֶׁר עֲשׂוּ בְּחָרָן. וּכְּמָה דְּעָבְדוּ נַפְשָׁן בְּסִטְרָא דִקְדוּשָׁה הֲכִי (שלח קס\"ח א') נָמֵי עֲבָד נֶפֶשׁ בְּסִטְרָא אַחֲרָא דְּאִלְמָלֵא הַהוּא אִתְעָרוּ דְּאִתְעָר אַבְרָהָם בְּסִטְרָא אַחֲרָא לָא אִשְׁתְּכָחוּ גִיוּרִין בְּעָלְמָא כְּלָל. (שמות כ״ה:ה׳) וַעֲצֵי שִׁטִּים, הָא אוֹקִימְנָא דְּאִינּוּן שְׂרָפִים עוֹמְדִים, כְּמָה דְאַתְּ אָמֵר (ישעיהו ו׳:ב׳) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ. מַאי מִמַּעַל לוֹ. מִמַּעַל לְהַהִיא קְלִיפָה. וְאִי תֵּימָא, הַאי קְרָא בְּקוּדְשָׁא בְּרִיךְ הוּא אִתְּמַר, וְהָא אִתְּמַר (ישעיה ו) וָאֶרְאֶה אֶת יְיָ', אֶת דַּיְיקָא, כְּגַוְונָא דָּא דִּכְתִּיב בְּהַאי קְרָא, דִּכְתִּיב, (ישעיהו ו׳:א׳) וְשׁוּלָיו מְלֵאִים אֶת הַהֵיכָל, אֶת דַּיְיקָא לְאַסְּגָאָה הַהִיא קְלִיפָּה. כֵּיוָן דְּאָמַר רָזָא דְּהַהִיא קְלִיפָּה, כְּתִיב שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ, מִמַּעַל לְהַהִיא קְלִיפָּה.</p>\n<p>(שמות כ״ה:ו׳) שֶׁמֶן לַמָּאוֹר, דָּא מְשַׁח רְבוּת עִלָּאָה, דְּאַתְיָא מִלְּעֵילָּא. תְּרֵין שֶׁמֶן אִינּוּן. וְאִינּוּן תְּרֵי, (ד\"א חד) לְעֵילָּא, דְּאִקְרֵי שֶׁמֶן הַמָּאוֹר. וְחַד לְתַתָּא דְּאִקְרֵי שֶׁמֶן לַמָּאוֹר. שֶׁמֶן הַמָּאוֹר אִיהוּ עִלָּאָה, דְּקַיְּימָא בְּוַדַּאי, וְלָא פָּסִיק לְעָלְמִין, וְתָדִיר מַלְיָא רְבוּת קֻדְשָׁא, וְכָל בִּרְכָּאן, וְכָל נְהוֹרִין, וְכָל בּוּצִינִין, כֹּלָּא אִתְבָּרְכָאן וְאִתְנַהֲרָן מִתַּמָּן. שֶׁמֶן לַמָּאוֹר, לְזִמְנִין אִתְמַלְיָא וּלְזִמְנִין לָא.</p>\n<p>תּוּ, הָא תָּנֵינָן, כְּתִיב (בראשית א׳:ט״ז) וַיַּעַשׂ אֱלֹהִים אֶת שְׁנִי הַמְּאֹרֹת הַגְּדוֹלִים וְגוֹ', וְאַף עַל גַּב דְּהָא אוּקְמוּהָ חַבְרַיָּיא, וְהָכִי אִיהוּ. אֲבָל שְׁנֵי הַמְּאֹרֹת הַגְּדוֹלִים אִלֵּין: שֶׁמֶן הַמָּאוֹר, וְשֶׁמֶן לַמָּאוֹר. עָלְמָא עִלָּאָה, וְעָלְמָא תַּתָּאָה. חַד דְּכַר, וְחַד נוּקְבָּא. וְכָל זִמְנָא דִּדְכוּרָא וְנוּקְבָּא אַתְיָין כַּחֲדָא, (בראשית מ\"ט ע\"א) תַּרְוַויְיהוּ קַרְיָין בְּלִישְׁנָא דִּדְכוּרָא. וּבְגִין דְּעָלְמָא עִלָּאָה אִקְרֵי גָּדוֹל, בְּגִינֵיהּ עָלְמָא תַּתָּאָה דְּאִתְחַבָּר בַּהֲדֵיהּ בִּכְלָלָא, אִקְרֵי גָּדוֹל.</p>\n<p>כֵּיוָן דְּאִתְפְּרַשׁ דָּא מִן דָּא, אִדְכָּרוּ בִּפְרַט, כָּל חַד וְחַד כַּדְקָא חֲזִי לֵיהּ. דָּא אִקְרֵי גָּדוֹל, וְדָא אִקְרֵי קָטָן. וּבְּגִין כָּךְ אָמְרוּ קַדְמָאֵי, דְּלִיהֱוֵי בַּר נָשׁ זַנְבָא לְאַרְיָוָותָא, וְלָא רֵישָׁא לְשׁוּעָלַיָא. דְּכַד אִיהוּ קַיְימָא גּוֹ אַרְיְוָותָא, אִקְרֵי כֹּלָּא בִּכְלָלָא דְּאַרְיָוָותָא. זַנְבָא דְּאַרְיָא אַרְיָא אִיהוּ, בְּלָא פִּרוּדָא. וְאִי בְּגוֹ שׁוּעָלִים, אֲפִילּוּ אִיהוּ <Nonei></i>רֵישָׁא. רֵישָׁא דְּשׁוּעָל שׁוּעָל אִיהוּ, בְּלָא פִּרוּדָא, וְשׁוּעָל אִקְרֵי.</p>\n<p>וְרָזָא דָּא הַאי קְרָא, דְּהָא בְּקַדְמִיתָא כַּד יַתְבִין כַּחֲדָא, שְׁנֵי הַמְּאוֹרוֹת הַגְּדוֹלִים אִתְקְרוּן, אַף עַל גַּב דְּדָא זַּנְבָא לְגַבֵּי דְּעִלָּאָה. כֵּיוָן דְּדָא אִתְפְּרַשׁ מֵעִלָּאָה, כִּבְיָכוֹל לְמֶהוֵי רֵישָׁא לְשׁוּעָלִים, כְּדֵין אִקְרֵי קָטָן. וְעַל רָזָא דָּא שֶׁמֶן הַמָּאוֹר, דְּלָא פָּסִיק לְעָלְמִין, וְקַיְּימָא בִּסְלִיקוּ עִלָּאָה לְמִשְׁלַט בִּימָמָא. שֶׁמֶן לַמָּאוֹר פָּסִיק, וְאִקְרֵי קָטָן, וְשָׁלְטָא בְּלֵילְיָא.</p>\n<p>וְחָמֵשׁ בּוּסְמִין אִינּוּן לְגוֹ שֶׁמֶן וּקְטֹרֶת, וְאַף עַל גַּב דְּאִיהִי חַד אִינּוּן תְּרִין וְכֹלָּא חַד. (שמות כ״ה:ז׳) אַבְנֵי שֹׂהַם וְגוֹ'. כָּל הָנֵי תְּלֵיסַר אִינּוּן וְאִינּוּן תִּקּוּנָא דְּמַשְׁכְּנָא.</p>\n<p>וְאָהֲדַרְנָא לְמִלֵּי קַדְמָאֵי, זָהָב הָא אִתְּמַר דְּשִׁבְעָה זִינִי זָהָב אִינּוּן. וְאִי תֵּימָא דְּזָהָב אִיהוּ דִּינָא, וְכֶסֶף אִיהוּ רַחֲמֵי, וְאִסְתַּלָּק זָהָב לְעֵילָּא מִנֵּיהּ. לָאו הָכִי, דְּוַדַּאי זָהָב סָלִיק יַתִּיר אִיהוּ עַל כֹּלָּא, אֲבָל זָהָב בְּאֹרַח סְתָם אִיהוּ, וְדָא זָהָב עִלָּאָה, דְּאִיהוּ שְׁבִיעָאָה מִכָּל אִינּוּן זִינִי זָהָב, וְדָא אִיהוּ זָהָב דְּנָהִיר וְנָצִיץ לְעַיְינִין, וְדָא אִיהוּ דְּכַד נָפִיק לְעָלְמָא, (ד\"א ל\"ג נפיק) מַאן דְּאִדְבַּק לֵיהּ, טָמִיר לֵיהּ בְּגַוֵּיהּ, וּמִתַּמָּן נַפְקֵי וְאִתְמַשְּׁכָן כָּל זִינִי זָהָב.</p>\n<p>אֵימָתַי אִקְרֵי זָהָב, מַאן דְּאִקְרֵי זָהָב. כַּד אִיהוּ בִּנְהִירוּ, וְאִסְתַּלָּק בִּיקָר דְּחִילוּ, וְאִיהוּ בְּחֶדְוָה עִלָּאָה, לְמֶחדֵי לְתַתָּאֵי. וְכַד אִיהוּ בְּדִינָא, כַּד אִשְׁתַּנֵי מֵהַהוּא גּוָֹון, לְגָוֶון תִּכְלָא אוּכָם וְסוּמָק, כְּדֵין אִיהוּ בְּדִינָא תַּקִּיפָא. אֲבָל זָהָב, בְּחֶדְוָה אִיהוּ, וּבִסְלִיקוּ דִּדְחִילוּ דְּחֶדְוָה קַיְּימָא, וּבְאִתְעָרוּתָא דְּחֶדְוָה.</p>\n<p>וָכֶסֶף לְתַתָּא, רָזָא דְּרוֹעָא יְמִינָא, דְּהָא רֵישָׁא עִלָּאָה זָהָב אִיהוּ, דִּכְתִּיב, (דניאל ב) אַנְתְּ הוּא רֵישָׁא דְּדַהֲבָא. (דניאל ב׳:ל״ב) חַדוֹהִי וּדְרָעוֹהִי דִּי כְסַף לְתַתָּא. (נ\"א ואימתי אישתלים כסף כד אתכליל וכו') וְכַד אִשְׁתְּלִים כֶּסֶף, כְּדֵין אִתְכְּלִיל בַּזָּהָב, וְרָזָא דָּא (משלי כ״ה:י״א) תַּפּוּחֵי זָהָב בְּמַּשְׂכִיּוֹת כָּסֶף. אִשְׁתְּכַח דְּכֶסֶף אִתְהַדָּר לְזָהָב, וּכְדֵין אִשְׁתְּלִים אַתְרֵיהּ. (נ\"א אלים אריה) וְעַל דָּא ז' זִינֵי זָהָב אִינּוּן.</p>\n<p>וּנְחֹשֶׁת נָפְקָא מִזָּהָב, וְאִשְׁתָּנֵי לְגִרְעוֹנָא, דְּרוֹעָא שְׂמָאלָא. וּתְכֵלֶת יַרְכָא שְׂמָאלָא. וְתוֹלַעַת שָׁנִי, יַרְכָא יְמִינָא, וְאִתְכְּלִיל בִּשְׂמָאלָא. וְשֵׁשׁ, דָּא נָהָר דְּנָגִיד וְנָפִיק, דְּאִיהוּ נָטִיל כָּל שִׁית סִטְרִין. כְּגַוְונָא דָּא לְתַתָּא, וְהָא אוּקְמוּהָ וְאִתְּמַר.</p>\n<p>הָא הָכָא שֶׁבַע דְּיוֹבֵל, וְאִינּוּן ז' דִּשְׁמִיטָּה. וְאַף עַל גַּב דְּאִינּוּן שִׁית, אִינּוּן תְּלֵיסַר, בִּשְׁבִיעָאָה, דְּאִיהוּ רֵישָׁא עָלַיְיהוּ, הָא תְּלֵיסַר. רִישָׁא דְּקַיְּימָא עַל כָּל גּוּפָא לְתַתָּא, רֵישָׁא דְּקַיְּימָא עַל כָּל שַׁיְיפֵי גּוּפָא, אִיהוּ זָהָב. מַה בֵּין הַאי לְהַאי. זָהָב עִלָּאָה, אִיהוּ בְּרָזָא סְתִימָא, וּשְׁמָא דִּילֵיהּ אִיהוּ זָהָב סָגוּר. סָגוּר וְסָתוּם מִכֹּלָּא, וְעַל כֵּן אִקְרֵי סָגוּר, דְּאִיהוּ סָגוּר מֵעֵינָא דְּלָא שַׁלְטָא בֵּיהּ. זָהָב תַּתָּאָה אִיהוּ בְּאִתְגַּלְּיָא יַתִּיר. (ושמא דיליה איקרי זהב ירקרק וכו'.)</p>"],[9520011733,"<p>לְשַׁעֲתָא הֲוָה, דִּכְתִּיב, (דברי הימים ב כ״ד:כ׳) וְרוּחַ אֱלֹהִים לָבְשָׁה אֶת זְכַרְיָה. וְאִם תֹּאמַר, הָא יִרְמְיָהוּ, דִּכְתִּיב בֵּיהּ, (ירמיהו א׳:ה׳) בְּטֶרֶם אֱצָרְךָ בַבֶּטֶן יְדַעְתִּיךָ. וְהָא אַחֲרָנִין. אֶלָּא כֻּלְּהוּ לָא זָכוּ לִנְבוּאָה וְלִכְהוּנָה עִלָּאָה כְּאַהֲרֹן, דְּהָא אַהֲרֹן זָכָה בִּנְּבוּאָה עִלָּאָה, עַל כָּל שְׁאַר כַּהֲנִי. זָכָה בִּכְהוּנָה עַל כֻּלְּהוּ.</p>\n<p>מֹשֶׁה זָכָה בִּנְּבוּאָה, וְשִׁמֵּשׁ בִּכְהוּנָה עִלָּאָה. שְׁמוּאֵל זָכָה בְּתַרְוַויְיהוּ. מַה מֹשֶׁה הֲוָה קָרֵי, וְקוּדְשָׁא בְּרִיךְ הוּא אָתִיב לֵיהּ מִיַּד. אוּף שְׁמוּאֵל כְּתִיב בֵּיהּ, (שמואל א י״ב:י״ז) הֲלֹא קְצִיר חִטִּים הַיּוֹם אֶקְרָא אֶל יְיָ' וְיִתֵּן קוֹלוֹת וְגוֹ'. אֲבָל לָא סָלִיק לְדַרְגָּא עִלָּאָה כְּמֹשֶׁה. מַה אַהֲרֹן הֲוָה מְשַׁמֵּשׁ בִּכְהוּנָה גַּבֵּי קוּדְשָׁא בְּרִיךְ הוּא, אוּף שְׁמוּאֵל הֲוָה מְשַׁמֵּשׁ קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, אֲבָל לָא סָלִיק בְּשִׁמוּשָׁא עִלָּאָה כְּאַהֲרֹן.</p>\n<p>וּמִלָּה הָכִי הוּא. תְּלָתָא אִינּוּן דַּהֲווֹ נְבִיאֵי מְהֵימְנֵי, וְשִׁמְּשׁוּ בִּכְהוּנָה. חַד מֹשֶׁה, וְחַד אַהֲרֹן, וְחַד שְׁמוּאֵל. וְאִי תֵּימָא שְׁמוּאֵל לֹא מָשִׁיךְ (ס\"א שמש) בִּכְהוּנָה, אֶלָּא אַחֲרָא הֲוָה דְּשִׁמֵּשׁ בִּכְהוּנָה, וּמַנּוּ <Nonei></i>יִרְמְיָהוּ. לָאו הָכִי, דְּהָא כְּתִיב, (ירמיהו א׳:א׳) מִן הַכֹּהֲנִים אֲשֶׁר (ויחי רמ\"ט ע\"ב) בַּעֲנָתוֹת. מִן הַכֹּהֲנִים הֲוָה, אֲבָל לָא שִׁמֵּשׁ. וּשְׁמוּאֵל בְּיוֹמֵי דְּעֵלִי שִׁמֵּשׁ. וּמֹשֶׁה זִמְנָא חֲדָא, כָּל אִינּוּן ז' יְמֵי מִלּוּאִים.</p>\n<p>שְׁמוּאֵל זָכָה לְנַעַר, דִּכְתִּיב, (שמואל א א׳:כ״ד) וְהַנַעַר נָעַר. (שמואל א ב׳:י״ח) וּשְׁמוּאֵל מְשָׁרֵת. וּבְגִין דְּקַיְּימָא בְּהַאי דַּרְגָּא, וַדַּאי אִיהוּ כְּמֹשֶׁה וְאַהֲרֹן. מַאן דְּנָטִיל לְהַאי נַעַר, וְזָכֵי בֵּיהּ, זָכֵי בְּאִינּוּן דַּרְגִּין עִלָּאִין, דְּקַיְימִן בְּהוּ מֹשֶׁה וְאַהֲרֹן.</p>"],[9520011734,"<p>כְּרוּבִים אִינּוּן זָהָב, כְּמַה דְּאוּקְמוּהָ, בְּגִין דְּנַפְקֵי מִסִּטְרָא דְּזָהָב, וְלָא אִתְעֲרָב בְּהוּ כֶּסֶף, וְלָא גּוָֹון אַחֲרָא, וְדָא אִיהוּ גּוָֹון זָהָב יְרַקְרָק. בַּמִשְׁכָּן מִתְעָרְבִין גְּוָונִין, זָהָב וָכֶסֶף לְמֵיהַךְ כַּחֲדָא, לְמֶהֱוֵי רָזָא דִּלְעֵילָּא בְּחַד. תּוּ נְחֹשֶׁת לְמֶהוֵי בַּהֲדַיְיהוּ, וּלְמֵיזַל בֵּינַיְיהוּ כָּל סִטְרִין, לְאִשְׁתַּכְחָא שְׁלִימוּ בְּכֹלָּא כַּחֲדָא, דִּכְתִיב זָהָב וָכֶסֶף וּנְחֹשֶׁת.</p>\n<p>דָּבָר אַחֵר זָהָב וָכֶסֶף. זָהָב דְּאִתְהַדָר לְכֶסֶף, וְכֶסֶף לְזָהָב, וְכֹלָּא אִתְכְּלִיל כַּחֲדָא, וּבְדוּכְתָּא חֲדָא. בִּתְלַת גַּוְונִין אִתְהַדָּר, כַּד אִצְטְרִיךְ לְחֶדְּוָותָא וְלָא דִּינָא, זָהָב. כַּד אִצְטְרִיךְ לְרַחֲמֵי, כֶסֶף. כַּד אִצְטְרִיךְ תֻּקְפָּא דְּדִינָא, נְחֹשֶׁת.</p>\n<p>וְעַל דָּא אִסְתָּכַּל מֹשֶׁה, בְּעוֹבָדָא דִּנְחַשׁ הַנְּחֹשֶׁת, דִּכְתִּיב (במדבר כ״א:ט׳) וַיַּעַשׂ מֹשֶׁה נְחַשׁ נְחֹשֶׁת, וַהֲוָה יָדַע אֲתָר דְּהִתוּכָא דְּזָהָב בְּהַהוּא נְחֹשֶׁת, בְּגִין דְּנָחָשׁ כְּלִישָׁנָא דִּילֵיהּ הוּא, וְאַתְרֵיהּ הֲוָה יָדַע. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא לָא אָמַר לֵיהּ אֶלָּא עֲשֵׂה לְךָ שָׂרָף, וְאִיהוּ אָתָא וַעֲבַד נְחַשׁ נְחֹשֶׁת, דְּכְתִּיב וַיַּעַשׂ מֹשֶׁה נְחַשׁ נְחֹשֶׁת. מַאי טַעֲמָא.</p>\n<p>אֶלָּא אֲתָר הֲוָה יָדַע, וְעִקָרָא דְּמִלְתָּא הֲוָה, דְּהָא בְּקַדְמִיתָא כְּתִיב, (במדבר כ״א:ו׳) וַיְשַׁלַּח יְיָ' בָּעָם אֶת הַנְּחָשִׁים הַשְֹּׂרָפִים, וּכְתִיב (דברים ח׳:ט״ו) נָחָשׁ שָׂרָף. עִקָּרָא דִּלְהוֹן נָחָשׁ אִיהוּ. וּבְגִין דְּמֹשֶׁה הֲוָה יָדַע עִקָּרָא וְשָׁרָשָׁא וִיסוֹדָא מֵהַהוּא אֲתָר, עֲבַד נָחָשׁ וְאִסְתְּמִיךְ עָלֵיהּ. מַאי טַעְמָא. בְּגִין דְּיִשְׂרָאֵל חָטְאוּ בְּלִישָׁנֵהוֹן, דְּכְתִּיב (במדבר כ״א:ה׳) וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמֹשֶׁה, וְעַל דָּא וַיְשַׁלַּח יְיָ' בָּעָם אֶת הַנְּחָשִׁים הַשְּׂרָפִים.</p>\n<p>וּמֹשֶׁה לָא אָזַל אֶלָּא בָּתַר עִקָּרָא, וַעֲבַד נְחַשׁ נְחֹשֶׁת, בְּהַהוּא גַּוְונָא דְּאִצְטְרִיךְ לֵיהּ, דְּהָא אַתְרֵיהּ נְחֹשֶׁת אִיהוּ. וְקוּדְשָׁא בְּרִיךְ הוּא לָא אֲמַר לֵיהּ מִמָּה יִתְעֲבִיד, וּמֹשֶׁה אִסְתָּכַּל וַעֲבַד לֵיהּ מִנְחֹשֶׁת, כְּמָה דְּאִצְטְרִיךְ לְאַתְרֵיהּ. מְנָלָן. דִּכְתִּיב וַיַּעַשׂ מֹשֶׁה נְחַשׁ נְחֹשֶׁת וַיְשִׂימֵהוּ עַל הַנֵּס. מַאי עַל הַנֵּס. עַל הַהוּא רְשִׁימוּ דְּאִיהוּ לְעֵילָּא.</p>\n<p>וְהָא תָּנֵינָן, בְּכָל אֲתָר הַאי נָחָשׁ אַזְלָא בָּתַר רָזָא דְּאֵשֶׁת חַיִל, וּבַעְיָא אֵשֶׁת זְנוּנִים לְאִתְתַּקְנָא גַּרְמָהּ כְּגַוְונָא דִּילָהּ, וְלָא יָכִילַת. אֵשֶׁת חַיִל, הַהוּא רְשִׁימוּ וְאָת דִּילָהּ, אִיהוּ אָת ה', וְהָכִי אִתְחָזֵי לָהּ. אֵשֶׁת זְנוּנִים הַהוּא רְשִׁימָא וְאָת דִּילָהּ אִיהוּ כְּהַהוּא גַּוְונָא (נ\"א דאצטריך') וְלָא אִתְתָּקַּן לְמֶהֱוֵי הָכִי, וְאָת דִּילָהּ ק', (קנ\"ב ע\"א) אָת דִּילָהּ אִתְתַּקְנָא בְּתִקּוּנָא דְּאָת ה', (ס\"א את ק' בההוא גוונא דה' ולא אתתקנא למהוי הכי את דילה אתתקנא בתקונא דאת ה') כְּגַוְונָא דְּקוֹפָא אֵצֶל בְּנֵי נָשָׁא, דְּאַזְלָא בָּתַר בְּנֵי נָשָׁא, וְלָא אִתְתָּקַּן לְמֶעְבַּד הָכִי. כְּגַוְונָא דָּא עֲבַד מֹשֶׁה הַהוּא נָחָשׁ, עַל הַהוּא רְשִׁימוּ דְּאִתְחָזֵי לֵיהּ, וְתָדִיר אִתְתָּקַּן לְאַבְאָשָׁא, וְעָלֵיהּ חָב אָדָם, וְאִתְתָּרַךְ מִגִּנְתָּא דְּעֵדֶן, דְּהֲוָה אֲתָר דִּיוֹרֵיהּ כְּגַוְונָא דְּדִיוּרָא דִּלְעֵילָּא. (אמרו המגיהים בהרבה העתקות נמצאות כתובות כאן השבעה היכלות ושבעה מדורות וכבר נדפסו בפרשת בראשית דף ל\"ח כי שם ביתם)</p>"],[9520011735,"<p>כְּתִיב (בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. אָמַר רַבִּי יוֹסִי, הַהוּא אוֹר אִתְגְּנִיז וְאִיהוּ אִזְדָּמַן לְגַבֵּי צַדִיקַיָּא לְעָלְמָא דְּאָתֵי. כְּמָה דְּאוּקְמוּהָ, דִּכְתִּיב, (תהילים צ״ז:י״א) אוֹר זָרוּעַ לַצַּדִיק. לַצַּדִיק וַדַאי סְתָם. וְהַהוּא אוֹר לָא שִׁמֵשׁ בְּעָלְמָא, בַּר יוֹמָא קַדְמָאָה. וּלְבָתַר אִתְגְנִיז, וְלָא שִׁמֵּשׁ יַתִיר.</p>\n<p>רַבִּי יְהוּדָה אוֹמֵר, אִלְמָלֵי אִתְגְּנִיז מִכֹּל <Nonei></i>וָכֹל, לָא קָאִים עָלְמָא אֲפִילּוּ רִגְעָא חֲדָא, אֶלָּא אִתְגְּנִיז וְאִזְדְּרַע כְּהַאי זַרְעָא דְּעָבִיד תּוֹלָדִין וּזְרָעִין וְאֵיבִין, וּמִנֵּיהּ אִתְקָיָּים עָלְמָא. וְלֵית לָךְ יוֹמָא, דְּלָא נָפִיק מִנֵּיהּ בְּעָלְמָא, וּמְקַיֵים כֹּלָּא דְּבֵיהּ זָן קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא. וּבְכָל אֲתָר דְּלָעָאן בְּאוֹרַיְיתָא בְּלֵילְיָא, חַד חוּטָא נָפִיק מֵהַהוּא אוֹר גָנִיז, וְאִתְמְשִׁיךְ עַל אִינּוּן דְּלָעָאן בָּהּ, הֲדָא הוּא דִּכְתִּיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. וְהָא אוֹקִימְנָא.</p>\n<p>יוֹמָא דְּאִתְקָם מַשְׁכְּנָא לְתַתָּא, מָה כְּתִיב (שמות מ׳:ל״ה) וְלָא יָכוֹל מֹשֶׁה לָבֹא אֶל אֹהֶל מוֹעֵד כִּי שָׁכַן עָלָיו הֶעָנָן. מַאי הֶעָנָן. חַד חוּטָא הֲוָה (נ\"א עמודא דעננא) מֵהַהוּא סִטְרָא דְּאוֹר קַדְמָאָה, דְּנָפַק בְּחֶדְוָה בְּכֹלָּא (דכלה), עָאלַת לְמַשְׁכְּנָא דִּלְתַתָּא. וּמֵהַהוּא יוֹמָא (קדמאה). לָא אִתְגְּלֵי, אֲבָל שִׁמּוּשָׁא קָא מְשַׁמֵּשׁ בְּעָלְמָא, וְאִיהוּ מְחַדֵּשׁ בְּכָל יוֹמָא עוֹבָדָא דִּבְרֵאשִׁית.</p>\n<p>רַבִּי יוֹסִי הֲוָה לָעֵי בְּאוֹרַיְיתָא, וַהֲווּ עִמֵּיהּ רַבִּי יִצְחָק וְרִבִּי חִזְקִיָּה. אָמַר רִבִּי יִצְחָק, הָא חֲמֵינָן דְּעוֹבָדָא דְּמַשְׁכְּנָא, כְּגַוְונָא דְּעוֹבָדָא דְּשָׁמַיִם וָאָרֶץ, וְהָא אִתְּעָרוּ חַבְרַיָּיא בְּרָזִין דִּלְהוֹן זְעִירוּ, דְּלָא יָכִיל בַּר נָשׁ לְמֵיכַל בְּפוּמֵיהּ, וּלְמֵישַׁט יְדֵיהּ לְגוֹ פּוּמֵיהּ וּלְמִבְלַע.</p>\n<p>אָמַר רִבִּי יוֹסִי, מִלִּין אִלֵּין נְסַלֵּק לוֹן לְגוֹ (נ\"א לגביה) בּוּצִינָא קַדִּישָׁא, דְּאִיהוּ מְתַקֵּן תַּבְשִׁילִין מְתִיקִין, כְּמַה דְּאַתְקִין לוֹן עַתִּיקָא קַדִּישָׁא, סְתִימָא דְּכָל סְתִימִין, וְאִיהוּ אַתְקִין תַּבְשִׁילִין, דְּלֵית בְּהוּ אֲתָר, לְמֵיתֵי אַחֲרָא, לְמִשְׁדֵּי בְּהוּ מִלְחָא. וְתוּ, דְּיָכִיל בַּר נָשׁ לְמֵיכַל וּלְמִשְׁתֵּי וּלְאַשְׁלְמָא כְּרִסוֹי מִכָּל עִדוּנִין דְּעָלְמָא וּלְאִשְׁתַּאֲרָא, וּבֵיהּ יִתְקָיָּים, (מלכים ב ד׳:מ״ד) וְיִתֵּן לִפְנֵיהֶם וַיֹּאכְלוּ וַיוֹתִירוּ כִּדְבַר יְיָ'.</p>"],[9520011736,"<p>פָּתַח וְאָמַר, (מלכים א ה׳:כ״ו) וַיְיָ', נָתַן חָכְמָה לִשְׁלֹמֹה כַּאֲשֶׁר דִּבֶּר לוֹ וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה וַיִכְרְתוּ בְרִית שְׁנֵיהֶם. הַאי קְרָא הָא אִתְּמַר בְּכַמָּה דּוּכְתֵּי. אֲבָל וַיְיָ', אִסְתַּכְּמוּתָא דִּלְעֵילָּא וְתַתָּא כַּחֲדָא. וַיְיָ' אִיהוּ וּבֵי דִּינֵיהּ. נָתַן חָכְמָה, נָתַן: כְּמַאן דְּיָהִיב נְבִזְבְּזָא וּמַתָּנָה לִרְחִימֵיהּ. כַּאֲשֶׁר דִּבֶּר לוֹ, שְׁלִימוּ דְּחָכְמְתָא, בְּעוּתְרָא, וּבִשְׁלָם, וּבְשֻׁלְטָנוּ, הֲדָא הוּא דִכְתִיב כַּאֲשֶׁר דִּבֶּר לוֹ.</p>\n<p>וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה, מַאי טַעְמָא. בְּגִין דַּהֲווֹ יַדְעֵי דָּא לְדָא, סְתִימוּ דְּמִלִּין דַּהֲווֹ אַמְרֵי, וּבְנֵי נָשָׁא אַחֲרָנִין לָא הֲווֹ יַדְעֵי לְאִסְתַּכְּלָא וּלְמִנְדַּע בְּהוּ כְּלַל, וּבְגִינַיְיהוּ, אִתְהַדָּר חִירָם לְאוֹדָאָה לִשְׁלֹמֹה בְּכָל מִלּוֹי.</p>\n<p>שְׁלמֹה מַלְכָּא, אִסְתָּכַּל וַהֲוָה חָמֵי, דְּהָא אֲפִילּוּ בְּהַהוּא דָּרָא, דְּהֲוָה שְׁלִים מִכָּל דָּרִין אַחֲרָנִין, לָא הֲוָה רְעוּתָא דְּמַלְכָּא עִלָּאָה, דְּיִתְגְּלֵי חָכְמָה כָּל כַּךְ עַל יְדֵיהּ, (נ\"א ולא אתגליא) דְּאִתְגְּלֵי אוֹרַיְיתָא דְּהֲוָה סְתִימָא בְּקַדְמִיתָא, וּפָתַח לָהּ פִּתְחִין. וְאַף עַל גַּב דְּפָתַח, סְתִימִין אִינּוּן, בַּר לְאִינּוּן חַכִּימִין דְּזָכוּ, וּמִתְגַמְגְמֵי בְּהוּ, וְלָא יַדְעֵי לְמִפְתַּח בְּהוּ פּוּמָא. וְדָרָא דָּא דְּרַבִּי שִׁמְעוֹן שַׁרְיָא בְּגַוֵּיהּ, רְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגִינֵיהּ דְּרַבִּי שִׁמְעוֹן, דְּיִתְגַּלְיָין מִלִּין סְתִימִין עַל יְדוֹי.</p>\n<p>אֲבָל תַּוַוהְנָא עַל חַכִּימֵי דָּרָא, הֵיךְ שַׁבְקִין אֲפִילּוּ רִגְעָא חֲדָא, לְמֵיקָם קָמֵי דְּרַבִּי שִׁמְעוֹן לְמִלְעֵי בְּאוֹרַיְיתָא, בְּעוֹד דְּרַבִּי שִׁמְעוֹן קָאִים בְּעָלְמָא, אֲבָל בְּדָרָא דָּא לָא יִתְנְשֵׁי חָכְמְתָא מֵעָלְמָא, וַוי לְדָרָא כַּד יִסְתָּלַק אִיהוּ, וְחַכִּימִין יִתְמַעֲטוּן, וְחָכְמְתָא יִתְנְשֵׁי מֵעָלְמָא.</p>\n<p>אָמַר רִבִּי יִצְחָק, וַדַּאי הָכִי אִיהוּ, דְּהָא יוֹמָא חַד הֲוֵינָא אָזִיל עִמֵּיהּ בְּאָרְחָא, וּפָתַח פּוּמֵיהּ בְּאוֹרַיְיתָא, וַחֲמֵינָא עַמּוּדָא דַּעֲנָנָא נָעִיץ מֵעֵילָּא לְתַתָּא, וְחַד זִיהֲרָא זָהִיר גּוֹ עַמּוּדָא. דָּחִילְנָא דְּחִילוּ סַגִּי אַמִינָא זַכָּאָה אִיהוּ בַּר נָשׁ, דְּהָכִי אִזְדָּמַן לֵיהּ בְּהַאי עָלְמָא.</p>\n<p>מַה כְּתִיב בֵּיהּ בְּמֹשֶׁה, (שמות ל״ג:י׳) וְרָאָה כָּל הָעָם אֶת עַמּוּד הֶעָנָן עוֹמֵד פֶּתַח הָאֹהֶל וְקָם כָּל הָעָם וְהִשְׁתַּחֲווּ אִישׁ פֶּתַח אָהֳלוֹ. יֵאוֹת הוּא לְמֹשֶׁה, דְּאִיהוּ נְבִיאָה מְהֵימָנָא עִלָּאָה עַל כָּל נְבִיאֵי עָלְמָא, וְדָרָא הַהוּא דְּקַבִּילוּ אוֹרַיְיתָא עַל טוּרָא דְּסִינַי, וְחָמוּ כַּמָה נִסִּין וְכַמָּה גְּבוּרָאן בְּמִצְרַיִם וְעַל יַמָּא. אֲבָל הָכָא בְּדָרָא דָּא, זְכוּתָא עִלָּאָה דְּרַבִּי שִׁמְעוֹן קָא עָבִיד, לְאִתְחֲזָאָה נִסִּין עַל יְדוֹי.</p>"],[9520011737,"<p><Nonei></i>(שמות כה) וּתְכֵלֶת, אָמַר רַבִּי יִצְחָק, תְּכֵלֶת מֵהַהוּא נוּנָא דְּיַמָּא דְּגִינוֹסָר, דְּאִיהוּ בְּעַדְבֵיהּ דִּזְבוּלוּן. וְאִצְטְרִיךְ גַּוְונָא דָּא לְעוֹבָדָא דְּמַשְׁכְּנָא לְאִתְחֲזָאָה הַאי גּוָֹון.</p>\n<p>פָּתַח וְאָמַר, (בראשית א׳:ו׳) וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיְהִי מַבְדִּיל בֵּין מַיִם לָמָיִם. הַאי רְקִיעַ אִתְבְּרֵי בַּשֵּׁנִי, דְּעוֹבָדָא דָּא מִסִּטְרָא דִּשְׂמָאלָא אִיהוּ. וּבְיוֹמָא תִּנְיָינָא דְּאִיהוּ סְטָר שְׂמָאלָא, אִתְבְּרֵי בֵּיהּ גֵּיהִנָּם, דְּאִיהוּ נָפִיק מִגּוֹ הִתּוּכָא דְּנוּרָא דִּשְׂמָאלָא, וּבְיַמָא אִצְטְבַע בָּהּ גּוָֹון תִּכְלָא, דְּאִיהוּ כּוּרְסְיָּיא דְּדִינָא.</p>\n<p>וְנָטִיל הַאי יוֹמָא מַיִם דַּהֲווֹ מִסִּטְרָא דִּימִינָא, וְאִינּוּן מַיִם דַּהֲווֹ מִסִּטְרָא דִּימִינָא, לָא אִתְגַּלּוּ אֶלָּא בְּיוֹם שֵׁנִי. בְּיוֹמָא דִּילֵיהּ, לָא אִתְגְּלֵי מַיִם, אֶלָּא אִתְחַלָּף, בְּגִין דְּאִתְכְּלִיל דָּא בְּדָא, וְאִתְבָּסַּם דָּא בְּדָא. אוֹר דְּיוֹמָא קַדְמָאָה, נְהִירוּ קַדְמָאָה מִכָּל שִׁיתָא נְהוֹרִין אִיהוּ. וְהַאי אוֹר בְּסִטְרָא דְּאֶשָּׁא הֲוָה, דִּכְתִּיב, (ישעיהו י׳:י״ז) וְהָיָה אוֹר יִשְׂרָאֵל לְאֵשׁ. וְהַהוּא אוֹר דְּיִשְׂרָאֵל מִסִּטְרָא דִּימִינָא הֲוָה, אִתְכְּלִיל בְּאֶשָּׁא.</p>\n<p>וְיוֹמָא קַדְמָאָה מֵאִינּוּן שִׁיתָא יוֹמִין, מַיִם אִיהוּ, וְלָא שִׁמֵּשׁ עוֹבָדָא דְּמַיִם, אֶלָּא עוֹבָדָא דְּאוֹר, דְּאִיהוּ מִסִּטְרָא דְּאֵשׁ, דְּאִיהוּ יוֹם שֵׁנִי. לְאַחֲזָאָה דְּקוּדְשָׁא בְּרִיךְ הוּא לָא בָּרָא עָלְמָא, אֶלָּא עַל שָׁלוֹם, וּבְאֹרַח שָׁלוֹם הֲוָה כֹּלָּא. יוֹמָא קַדְמָאָה כָּל מַה דַּעֲבַד, מִסִּטְרָא דְּחַבְרֵיהּ עָבֵד. יוֹמָא תִּנְיָינָא בְּסִטְרָא דְּיוֹמָא קַדְמָאָה עֲבַד הַהוּא אוּמָנָא, וְשִׁמֵּשׁ בָּהּ, דְּכָל חַד שִׁמֵּשׁ בְּעוֹבָדָא דְּחַבְרֵיהּ, לְאַחֲזָאָה, דְּהָא אִתְכְּלִילוּ דָּא בְּדָא. יוֹמָא תְּלִיתָאָה, הֲוָה בְּסִטְרָא דְּתַרְוַויְיהוּ, וּבֵיהּ הֲוָה אַרְגָּמָן, וְעַל דָּא כְּתִיב, כִּי טוֹב כִּי טוֹב תְּרֵי זִמְנֵי בְּיוֹמָא תְּלִיתָאָה.</p>\n<p>תְּכֵלֶת, דָּא יוֹמָא תִּנְיָינָא, אִצְטְבַע בְּב' גַּוְונִין סוּמָק וְאוּכָם. וּתְכֵלֶת, סוּמָק אִיהוּ דִּילֵיהּ, מִיּוֹמָא תִּנְיָינָא מַמָּשׁ, כְּעֵין גּוָֹון אֶשָּׁא, וְדָא אִיהוּ אֱלהִים, וְיָרִית גּוָֹון דְּדַהֲבָא, דְּכֹלָּא גַּוְונָא חֲדָא. תְּכֶלְתָּא נָפִיק מִגּוֹ הַהוּא גּוָֹון סוּמָק, וְכַד נָחִית לְתַתָּא, אִתְרְחַק גּוָֹון סוּמָק, וְעָאל גּוֹ הַהוּא אֲתָר דְּאִיהוּ יַמָּא, וְאִצְטְבַע גּוָֹון תִּכְלָא. הַהוּא סוּמָקָא עָיֵיל גּוֹ יַמָּא, וְאִתְחַלָּשׁ גּוָֹון דִּילֵיהּ, וְאִתְהַדָּר תִּכְלָא, וְדָא אִיהוּ אֱלהִים, אֲבָל לָאו אִיהוּ תַּקִּיפָא כְּקַדְמָאָה.</p>\n<p>אוּכָם, גּוָֹון דָּא נָפִיק מֵהִתּוּכָא דְּסוּמָקָא, כַּד אִתְהֲתָּךְ וְאִתְחַלָּשׁ לְתַתָּא בְּהִתּוּכָא דְּזוּהֲמָא, וְנָחִית לְתַתָּא, וְנָפִיק מֵהַהוּא זוּהֲמָא גּוָֹון סוּמָק, מִזּוֹהֲמָא תַּקִּיפָא, וּמִגּוֹ זוּהֲמָא תַּקִּיפָא, אִתְהַדָּר לְאוּכָם. וְכֹלָּא מֵהַהוּא סוּמָקָא קַדְמָאָה (ס\"א עלאה) אִתְהֲתָּךְ. וְכָל דָּא אִתְבְּרֵי בַּשֵּׁנִי, וְהַאי אִקְרֵי אֱלֹהִים אֲחֵרִים.</p>\n<p>הַאי אוּכָם אִיהוּ חָשׁוּךְ יַתִּיר, דְּלָא אִתְחָזֵי גּוָֹון דִּילֵיהּ מִגּוֹ חֲשׁוֹכָא. בּוּצִינָא קַדִּישָׁא הָכִי אָמַר, דְּהַאי גּוָֹון אוּכָם חָשׁוּךְ, בְּאָן אֲתָר אִצְטְבַע. אֶלָּא כַּד הַהוּא סוּמָקָא אִתְהֲתָּךְ בְּגוֹ תִּכְלָא, וְאִתְעָרְבוּ גַּוְונִין, אִתְהֲתָּךְ הִתּוּכָא דְּזוּהֲמָא לְגוֹ תְּהוֹמֵי, וְאִתְעָבִיד מִתַּמָּן רֶפֶשׁ וָטִיט. כְּמָה דְאַתְּ אָמֵר (ישעיהו נ״ז:כ׳) וַיִּגְרְשׁוּ מֵימָיו רֶפֶשׁ וָטִיט. וּמִגּוֹ הַהוּא טִינָא דִּתְהוֹמֵי, נָפַק הַהוּא חָשׁוּךְ דְּאִיהוּ אוּכָם, וְלָא אוּכָם אֶלָּא חָשׁוּךְ יַתִּיר, הֲדָא הוּא דִכְתִיב, (בראשית א׳:ב׳) וְחֹשֶׁךְ עַל פְּנִי תְהוֹם. אֲמַאי אִקְרֵי חֹשֶׁךְ, בְּגִין דְּגָוֶון דִּילֵיהּ חָשׁוּךְ, וְאַחְשִׁיךְ אַנְפֵּי בִּרְיָין. וְדָא אִיהוּ סוּמָק וְאוּכָם, וּבְגִין דָּא לָא כְּתִיב בַּשֵּׁנִי כִּי טוֹב.</p>"],[9520011738,"<p>וְאִי תֵּימָא, וְהָא כְּתִיב (בראשית א׳:ל״א) וְהִנִּה טוֹב מְאֹד דָּא מַלְאָךְ הַמָּוֶת, וְהָכָא אַמָרְתְּ דְּלָא אִתְּמַר בְּגִינִיהּ כִּי טוֹב. אֶלָּא רָזָא דְּרָזִין הָכָא, דְּהָא וַדַּאי מַלְאָךְ הַמָּוֶת אִיהוּ טוֹב מְאֹד. מַאי טַעְמָא. בְּגִין דְּהָא כָּל בְּנֵי עָלְמָא יַדְעֵי דִּימוּתוּן וְיִתְהַדְרוּן לְעַפְרָא, וְסַגִּיאִין אִינּוּן דִּמְהַדְּרֵי בְּתִיּוּבְתָא לְמָארֵיהוֹן, בְּגִין דְּחִילוּ דָּא, וְדַחֲלֵי לְמֶחטֵי קַמֵּיהּ. סַגִּיאִין דַּחֲלֵי מִן מַלְכָּא, מִגּוֹ דְּתַלְיָא רְצוּעָה לְקָמַיְיהוּ. כַּמָה טָבָא הַהִיא רְצוּעָה לְגַבֵּי בַּר נָשׁ, דְּעַבְדַּת לוֹן טָבִין וְקָשִׁיטִין, וּמְתַקְּנִין בְּאָרְחַיְיהוּ כַּדְקָא יֵאוֹת. וְעַל דָּא וְהִנֵּה טוֹב מְאֹד. מְאֹד וַדַּאי.</p>\n<p><Nonei></i>רָזָא דְּרָזִין, דְּאוֹלִיפְנָא מִגּוֹ בּוּצִינָא קַדִּישָׁא וְהִנֵּה טוֹב, דָּא מַלְאָךְ חַיִּים. מְאֹד, דָּא מַלְאָךְ הַמָּוְת, דְּאִיהוּ יַתִּיר. אֲמַאי מַלְאָךְ הַמָּוֶת אִיהוּ טוֹב מְאֹד. אֶלָּא כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, כֹּלָּא הֲוָה מִתְתָּקַּן עַד לָא יֵיתֵי אָדָם, דְּאִיהוּ מַלְכָּא דְּהַאי עָלְמָא. כֵּיוָן דְּאִתְבְּרֵי אָדָם, עֲבַד לֵיהּ מִתְתַּקָּן בְּאֹרַח קְשׁוֹט, הֲדָא הוּא דִכְתִיב, (קהלת ז׳:כ״ט) אֲשֶׁר עָשָׂה הָאֱלֹהִים אֶת הָאָדָם יָשָׁר וְהֵמָה בִקְשׁוּ חִשְּׁבוֹנוֹת רַבִּים, עֲבַד לֵיהּ יָשָׁר, וּלְבָתַר סָרַח, וְאִטְרִיד מִגִּנְתָּא דְּעֵדֶן.</p>\n<p>גַּן עֵדֶן אִיהוּ בְּאַרְעָא, נָטִיעַ בְּאִינּוּן נְטִיעָן דְּנָטַע לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְאַתְּ אָמֵר (בראשית ב׳:ח׳) וַיִּטַּע יְיָ' אֱלהִים גַּן בְּעֵדֶן מִקֶּדֶם, אִיהוּ נָטַע לֵיהּ בִּשְׁמָא שְׁלִים, כְּגַוְונָא עִלָּאָה לְעֵילָּא. וְכָל דִּיוּקְנִין עִלָּאִין כֻּלְּהוּ, מְרֻקְּמָן וּמִתְצַיְירָן בְּהַאי גַּן עֵדֶן דִּלְתַתָּא, וְתַמָּן אִינּוּן כְּרוּבִים. לָאו אִינּוּן גְּלִיפִין בִּגְלִיפוֹי דִּבְנֵי נָשָׁא מִדַּהֲבָא אוֹ מִמִּלָּה אַחֲרָא, אֶלָּא כֻּלְּהוּ נְהוֹרִין דִּלְעֵילָּא, גְּלִיפִין וּמִתְצַיְּירִין בְּצִיּוּרָא מְרֻקְּמָא, עוֹבָדֵי יְדֵי אוּמָנָא דִּשְׁמָא שְׁלִים דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ מְחֻקְּקָן תַּמָּן. וְכָל דִּיוּקְנִין וְצִיּוּרִין דְּהַאי עָלְמָא, כֻּלְּהוּ מִתְצַיְּירָן תַּמָּן, וּגְּלִיפָן וּמִתְחַקְקָן תַּמָּן, כֻּלְּהוּ כְּגַוְונָא דְּהַאי עָלְמָא.</p>\n<p>וַאֲתָר דָּא אִיהוּ מָדוֹרָא לְרוּחִין קַדִּישִׁין, בֵּין אִינּוּן דְּאָתוּ לְהַאי עָלְמָא, בֵּין אִינּוּן דְּלָא אָתוּ לְהַאי עָלְמָא, וְאִינּוּן דִּזְמִינִין לְמֵיתֵי לְהַאי עָלְמָא. כֻּלְּהוּ רוּחִין מִתְלַבְּשָׁן בִּלְבוּשִׁין וְגּוּפִין וּפַרְצוּפִין כְּגַוְונָא דְּהַאי עָלְמָא, וּמִסְתַּכְּלָן תַּמָּן בְּזִיו יְקָרָא דְּמָארֵיהוֹן, עַד דְּאַתְיָין לְהַאי עָלְמָא.</p>\n<p>בְּשַׁעֲתָא דְּנַפְקֵי מִתַּמָּן, לְמֵיתֵי לְהַאי עָלְמָא, מִתְפַּשְּׁטִין אִינּוּן רוּחִין, מֵהַהוּא גּוּפָא וּלְבוּשָׁא דְּתַמָּן, וּמִתְלַבְּשִׁין בְּגוּפָא וּבִלְבוּשָׁא דְּהַאי עָלְמָא, וְעַבְדִין דִּיּוּרֵיהוֹן בְּהַאי עָלְמָא, בִּלְבוּשָׁא וְגוּפָא דָּא, דְּאִיהוּ מִטִּפָּה סְרוּחָה.</p>\n<p>וְכַד מָטֵי זִמְנֵיהּ לְמֵיהַךְ וּלְנָפְקָא מֵהַאי עָלְמָא, לָא נָפִיק עַד דְּהַאי מַלְאָךְ הַמָּוֶת אַפְשִׁיט לֵיהּ לְבוּשָׁא דְּגוּפָא דָּא. כֵּיוָן דְּאִתְפָּשַּׁט הַאי גּוּפָא מֵהַהוּא רוּחָא, עַל יְדֵי דְּהַהוּא מַלְאָךְ הַמָּוֶת, אַזְלָא וּמִתְלַּבְּשָׁא בְּהַהוּא גּוּפָא אַחֲרָא דִּבְגִנְתָּא דְּעֵדֶן, דְּאִתְפְּשִׁיט כַּד אָתֵי לְהַאי עָלְמָא. וְלֵית חִדוּ לְרוּחָא, בַּר בְּהַהוּא גּוּפָא דְּתַמָּן, וְחַדֵּי עַל דְּאִתְפָּשַּׁט מֵהַאי גּוּפָא דְּהַאי עָלְמָא, וְאִתְלָבַּשׁ בִּלְבוּשָׁא אַחֲרָא שְׁלִים, כְּגַוְונָא דְּהַאי (נ\"א דההוא) עָלְמָא, וּבֵיהּ יָתִיב וְאָזִיל וְאִסְתָּכַּל לְמִנְדַּע בְּרָזִין עִלָּאִין, מַה דְּלָא יָכִיל לְמִנְדַּע וּלְאִסְתַּכְּלָא בְּהַאי עָלְמָא בְּגוּפָא דָּא.</p>\n<p>וְכַד אִתְלַבְּשַׁת נִשְׁמְתָא בְּהַהוּא לְבוּשָׁא דְּהַהוּא עָלְמָא, כַּמָה עִדוּנִין, כַּמָה כִּסוּפִין דִּילָהּ תַּמָּן. מַה גָּרִים לְגוּפָא דָּא, לְאִתְלַבְּשָׁא בֵּיהּ רוּחָא. הֲוֵי אֵימָא הַהוּא דְּאַפְשִׁיט לֵיהּ לְבוּשִׁין אִלֵּין. וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד טִיבוּ עִם בִּרְיָין, דְּלָא אַפְשִׁיט לֵיהּ לְבַר נָשׁ לְבוּשִׁין אִלֵּין, עַד דְּאַתְקִין לֵיהּ לְבוּשִׁין אַחֲרָנִין יַקִּירִין וְטָבִין מֵאִלֵּין.</p>\n<p>בַּר לְאִינּוּן חַיָּיבֵי עָלְמָא, דְּלָא אָהַדְרוּ בְּתִיּוּבְתָא שְׁלֵימָתָא לְמָארֵיהוֹן, דְּעַרְטִילָאִין אָתוּ לְהַאי עָלְמָא, וְעַרְטִילָאִין יְתוּבוּן תַּמָּן. וְנִשְׁמְתָא אַזְלָא בְּכִסּוּפָא לְגַבֵּי אַחֲרָנִין, דְּלֵית לָהּ לְבוּשִׁין כְּלַל, וְאִתְּדָנַת בְּהַהוּא גֵּיהִנָּם דִּבְאַרְעָא, מִגּוֹ הַהוּא אֶשָּׁא דִּלְעֵילָּא. וְאִית מִנְּהוֹן דִּמְצַפְצְפֵי וְסַלְקֵי, וְאִלֵּין אִינּוּן חַיָּיבֵי עָלְמָא, דְחַשְׁבִי בְּלִבַּיְיהוּ תְּשׁוּבָה, וּמִיתוּ, וְלָא יָכִילוּ לְמֶעְבַּד לָהּ. אִלֵּין אִתְדָּנוּ תַּמָּן בְּגֵיהִנָּם, וּלְבָתַר מְצַפְצְפֵי וְסַלְּקִין.</p>\n<p>חָמֵי כַּמָה רַחֲמָנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא עִם בִּרְיוֹהִי, דְּאֲפִילּוּ דְּאִיהוּ חַיָּיבָא יַתִּיר, וְהִרְהֵר תְּשׁוּבָה, וְלָא (ויקרא ר\"כ ע\"ב) יָכִיל לְמֶעְבַּד תְּשׁוּבָה, וּמִית, הַאי בְּוַדַּאי, מְקַבֵּל עוֹנְשָׁא, עַד דְּאָזִיל בְּלָא תְּשׁוּבָה. לְבָתַר הַהוּא רְעוּתָא דְּשַׁוֵּי לְמֶעְבַּד תְּשׁוּבָה, לָא אַעְדִּיאַת מִקַּמֵּי מַלְכָּא עִלָּאָה, וְקוּדְשָׁא בְּרִיךְ הוּא אַתְקִין לְהַהוּא חַיָּיבָא דּוּכְתָּא, בְּמָדוֹרָא דִּשְׁאוֹל, וְתַמָּן מְצַפְצְפָא תְּשׁוּבָה. דְּהָא הַהוּא רְעוּתָא נָחִית מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְתָבַר כָּל גְּזִּיזִין (ס\"א לבתר דקביל עונשיה ההוא רעותא טבא דשוי ההוא חייבא למעבד תשובה סלקא קמי מלכא עילאה ולא אעדיאת מתמן עד דקודשא בריך הוא אתקין לההוא חייבא דוכתא במדורת שאול וכדין ההוא ריעותא נחתא מקמי קודשא בריך הוא ותברת כל גזיזין) דְּתַרְעֵי מָדוֹרֵי גֵּיהִנָּם, וּמָטֵי לְהַהוּא אֲתָר דְּהַהוּא חַיָּיבָא תַּמָּן, וּבָטַשׁ בֵּיהּ, וְאִתְּעַר לֵיהּ הַהוּא רְעוּתָא כְּמִלְּקַדְּמִין. וּכְדֵין מְצַפְצְפָא <Nonei></i>הַהִיא נִשְׁמְתָא, לְסַלְּקָא מִגּוֹ מָדוֹרָא דִּשְׁאוֹל.</p>\n<p>וְלֵית רְעוּתָא טָבָא דְּיִתְאֲבִיד מִקַּמֵּי מַלְכָּא קַדִּישָׁא. וּבְגִין כַּךְ, זַכָּאָה אִיהוּ מַאן דִּמְהַרְהֵר הִרְהוּרִין טָבִין לְגַבֵּי מָארֵיהּ, דְּאַף עַל גַּב דְּלָא יָכִיל לְמֶעְבַּד לוֹן, קוּדְשָׁא בְּרִיךְ הוּא סָלִיק לֵיהּ רְעוּתֵיהּ כְּאִילּוּ עָבִיד. דָּא לְטָב. אֲבָל רְעוּתֵיהּ לְבִישׁ, לָא. בַּר הִרְהוּרָא דְכּוֹכָבִים וּמַזָּלוֹת, וְהָא אוּקְמוּהָ חַבְרַיָּיא.</p>\n<p>אִינּוּן דְּלָא הִרְהָרוּ תְּשׁוּבָה, נַחְתֵּי לִשְׁאוֹל, וְלָא סַלְקֵי מִתַּמָּן לְדָרֵי דָּרִין. עָלַיְיהוּ כְּתִיב, (איוב ז׳:ט׳) כָּלָּה עָנָן וַיֵּלַךְ כֵּן יוֹרֵד שְׁאוֹל לא יַעֲלֶה. עַל קַדְמָאֵי כְּתִיב (שמואל א ב׳:ו׳) יְיָ' מֵמִית וּמְחַיֶּה מוֹרִיד שְׁאוֹל וַיָּעַל.</p>"],[9520011739,"<p>אָמַר רַבִּי יְהוּדָה, דִּינָא דְּעוֹנְשֵׁי דְּגֵיהִנָּם, הָא אוֹלִיפְנָא, דְּאִיהוּ לְמֵידָן תַּמָּן לְחַיָּיבַיָּא, עַל מָה אִתְדָּנוּ בְּנוּרָא דְּגֵיהִנָּם. אֶלָּא גֵּיהִנָּם אִיהוּ נוּר דָּלִיק יְמָמֵי וְלֵילֵי, כְּגַוְונָא דְּחַיָּיבַיָּא מִתְחַמְמָן בְּנוּרָא דְּיֵצֶר הָרָע, לְמֶעְבַּר עַל פִּתְגָּמֵי אוֹרַיְיתָא. בְּכָל חִמוּמָא וְחִמוּמָא דְּאִינּוּן מִתְחַמְּמָן בְּיֵצֶר הָרָע, הָכִי אִתּוֹקַד נוּרָא דְּגֵיהִנָּם.</p>\n<p>זִמְנָא חֲדָא לָא אִשְׁתְּכַח יֵצֶר הָרָע בְּעָלְמָא, דְּאֲעִילוּ לֵיהּ גּוֹ גּוּשְׁפַּנְקָא דְּפַרְזְלָא, בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא. וְכָל הַהוּא זִמְנָא, כָּבָה נוּרָא דְּגֵיהִנָּם, וְלָא אִתּוֹקַד כְּלַל. אַהְדָּר יֵצֶר הָרָע לְאַתְרֵיהּ, שָׁארוּ חַיָּיבֵי עָלְמָא לְאִתְחַמְמָא בֵּיהּ, שָׁאֲרִי נוּרָא דְּגֵיהִנָּם לְאִתּוֹקְדָא, דְּהָא גֵּיהִנָּם לָא אִתּוֹקַד אֶלָּא בְּחֲמִימוּ דְּתּוּקְפָּא דְּיֵצֶר הָרָע דְּחַיָּיבַיָּא. וּבְהַהוּא חֲמִימוּ, נוּרָא דְּגֵיהִנָּם אִתּוֹקַד יְמָמֵי וְלֵילֵי, וְלָא שָׁכִיךְ.</p>\n<p>שִׁבְעָה פִּתְחִין אִינּוּן לַגֵּיהִנָּם, וְשִׁבְעָה מָדוֹרִין אִינּוּן תַּמָּן. שִׁבְעָה זִינֵי חַיָּיבִין אִינּוּן: רַע. בְּלִיַּעַל. חוֹטֵא. רָשָׁע. מַשְׁחִית. לֵץ. יָהִיר. וְכֻלְּהוּ לָקֳבְלַיְיהוּ אִית מָדוֹרִין לַגֵּיהִנָּם, כָּל חַד וְחַד כַּדְקָא חֲזִי לֵיהּ. וּכְפוּם הַהוּא דַּרְגָּא דְּחָטָא בֵּיהּ הַהוּא חַיָּיבָא, הָכִי יַהֲבִין לֵיהּ מָדוֹרָא בְּגֵיהִנָּם.</p>\n<p>וּבְכָל מָדוֹרָא וּמָדוֹרָא, אִית מַלְאָךְ מְמָנָא עַל הַהוּא אֲתָר, תְּחוֹת יְדָא דְּדוּמָה. וְכַמָּה אֶלֶף וְרִבּוֹא עִמֵּיהּ, דְּדַיְינִין לוֹן לְחַיָּיבַיָּא, כָּל חַד וְחַד כְּמָה דְּאִתְחָזֵי לֵיהּ בְּהַהוּא מָדוֹרָא דְּאִיהוּ תַּמָּן.</p>\n<p>(ס\"א אשא דגיהנם דלעילא, מטי להאי גיהנם דלתתא) אֶשָּׁא דְּגֵיהִנָּם לְתַתָּא, מָטֵי מִגּוֹ אֶשָּׁא דְּגֵיהִנָּם דִּלְעֵילָּא, וּמָטֵי לְהַאי גֵּיהִנָּם דִּלְתַתָּא, וְאִתּוֹקַד, בְּהַהוּא אִתְּעֲרוּ דְּחֲמִימוּ דְּחַיָּיבַיָּא, דְּקָא מְחַמְמֵי גַּרְמַיְיהוּ גּוֹ יֵצֶר הָרָע, וְכָל אִינּוּן מָדוֹרִין דְּלִיקִין תַּמָּן.</p>\n<p>אֲתָר אִית בְּגֵיהִנָּם, וְדַרְגִּין תַּמָּן דְּאִקְרוּן (רנ\"ב ע\"א, רס\"ה ב', פנחס רנ\"ח ע\"א) צוֹאָה רוֹתַחַת, וְתַמָּן אִיהוּ זוּהֲמָא דְּנִשְׁמָתִין, אִינּוּן דְּמִתְלַכְלְכָן מִכָּל זוּהֲמָא דְּהַאי עָלְמָא. וּמִתְלַּבְּנָן וְסַלְּקִין, וְאִשְׁתְּאָרַת הַהוּא זוּהֲמָא תַּמָּן, וְאִינּוּן דַּרְגִּין בִּישִׁין דְּאִתְקְרוּן צוֹאָה רוֹתַחַת, אִתְמָנָן עַל הַהוּא זוּהֲמָא. וְנוֹרָא דְּגֵיהִנָּם שַׁלְטָא, בְּהַהוּא זוּהֲמָא דְּאִשְׁתְּאָרַת.</p>\n<p>וְאִית חַיָּיבִין, אִינּוּן דְּמִתְלַכְלְכָן בְּחוֹבַיְיהוּ תָּדִיר, וְלָא אִתְלַבְּנָן מִנַּיְיהוּ, וּמִיתוּ בְּלֹא תְּשׁוּבָה, וְחָטוּ וְהֶחטִיאוּ אַחֲרָנִין, וַהֲווּ קְשֵׁי קְדַל תָּדִיר, וְלָא אִתְבָּרוּ קָמֵי מָארִיהוֹן בְּהַאי עָלְמָא. אִלֵּין (וישב ק\"צ ע\"ב) אִתְדָּנוּ תַּמָּן בְּהַהוּא זוּהֲמָא, וּבְהַהִיא צוֹאָה רוֹתַחַת, דְּלָא נָפְקִין מִתַּמָּן לְעָלְמִין. אִינּוּן דִּמְחַבְּלִין אָרְחַיְיהוּ עַל אַרְעָא, וְלָא חַשְׁשׁוּ לִיקָרָא דְּמָארֵיהוֹן בְּהַאי עָלְמָא, כָּל אִינּוּן אִתְדָּנוּ תַּמָּן לְדָרֵי דָּרִין, וְלָא נַפְקֵי מִתַּמָּן.</p>\n<p>בְּשַׁבָּתֵי וּבְיַרְחֵי וּבִזְמַנֵּי וּבְחַגֵּי, בְּהַהוּא אֲתָר נוּרָא אִשְׁתְּכַךְ, וְלָא אִתְדָּנוּ, אֲבָל לָא נַפְקֵי מִתַּמָּן, כִּשְׁאַר חַיָּיבִין דְּאִית לְהוּ נַיְיחָא. כָּל אִינּוּן דִּמְחַלְּלֵי שַׁבָּתוֹת וּזְמָנֵי, וְלָא חַיְישֵׁי לִיקָרָא דְּמָארֵיהוֹן כְּלַל, בְּגִין לְמֵטָר לוֹן, אֶלָּא מְחַלְּלֵי בְּפַרְהֶסְיָא, כְּמָה דְּאִינּוּן לָא נַטְרֵי שַׁבָּתֵי וּזְמָנִי בְּהַאי עָלְמָא, הָכִי נָמֵי לָא נַטְרִין לֵיהּ בְּהַהוּא עָלְמָא, וְלֵית לוֹן נַיְיחָא.</p>\n<p>אָמַר רִבִּי יוֹסִי, לָא תֵּימָא הָכִי, אֶלָּא נַטְרֵי שַׁבָּתֵי וּזְמָנִי תַּמָּן בְּגֵיהִנָּם בְּעַל כָּרְחַיְיהוּ. אָמַר רַבִּי יְהוּדָה, אִלֵּין אִינּוּן עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, דְּלָא אִתְפְּקָדוּ, דְּלָא נַטְרֵי שַׁבָּת בְּהַאי עָלְמָא, נַטְרֵי לֵיהּ תַּמָּן בַּעַל כָּרְחַיְיהוּ.</p>\n<p>בְּכָל מַעֲלֵי שַׁבְּתָא כַּד יוֹמָא אִתְקַדָּשׁ, כָרוֹזִין <Nonei></i>אָזְלִין בְּכָל אִינּוּן מָדוֹרִין דְּגֵיהִנָּם: סְלִיקוּ דִּינָא דְּחַיָּיבַיָּא, דְּהָא מַלְכָּא קַדִּישָׁא אַתְיָא, וְיוֹמָא אִתְקַדָּשׁ, וְאִיהוּ אַגִּין עַל כֹּלָּא. וּמִיַּד דִּינִין אִסְתָּלָקוּ, וְחַיָּיבַיָּא אִית לוֹן נַיְיחָא. (וכל אינון מחללי שבתות וזמני בפרהסיא דינין סלקין מנייהו (נ\"א ואפילו עובדי כוכבים ומזלות דלא אתפקדו למיטר שבתי וזמני תמן נטרין בעל כרחם)) אֲבָל נוּרָא דְּגֵיהִנָּם לָא אִשְׁתְּכַּךְ, מֵעָלַיְיהוּ דְּלָא נַטְרֵי שַׁבָּת לְעָלְמִין. וְכָל חַיָּיבֵי גֵּיהִנָּם שָׁאֲלֵי עָלַיְיהוּ, מַאי שְׁנָא אִלֵּין דְּלֵית לוֹן נַיְיחָא, מִכָּל חַיָּיבִין דְּהָכָא. אִינּוּן מָארֵיהוֹן דְּדִינָא תַּיְיבִין לוֹן, אִלֵּין אִינּוּן חַיָּיבִין דְּכָּפְרוּ בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְעָבְרוּ עַל אוֹרַיְיתָא כֻּלָּא, בְּגִין דְּלָא נַטְרוּ שַׁבָּת תַּמָּן, בְּגִין כַּךְ לֵית לְהוּ נַיְיחִין לְעָלְמִין.</p>\n<p>וְאִינּוּן חַיָּיבִין כֻּלְּהוֹן, נָפְקִין מִדּוּכְתַּיְיהוּ, וְאִתְיְיהִיב לוֹן רְשׁוּ לְמֵיהַךְ לְמֵחֱמֵי בְּהוּ. וּמַלְאַךְ חַד דִּי שְׁמֵיהּ סַנְטִרִי\"אֵל, אָזִיל וְאַפִּיק לְהַהוּא גּוּפָא דִּלְהוֹן, וְעָיִיל לֵיהּ לַגֵּיהִנָּם, לְעֵינֵיהוֹן דְּחַיָּיבַיָּא, וְחַמָּן לֵיהּ דְּסַלְּקָא תּוֹלָעִין, וְנִשְׁמְתָא לֵית לָהּ נַיְיחָא בְּנוּרָא דְּגֵיהִנָּם.</p>\n<p>וְכָל אִינּוּן חַיָּיבַיָּא דְּתַּמָּן, סָחֲרִין לְהַהוּא גּוּפָא, וּמַכְרִיזֵי עָלֵיהּ, דָּא אִיהוּ פְּלַנְיָא חַיָּיבָא, דְּלָא חָיִישׁ לִיקָרָא דְּמָארֵיהּ, כָּפַר בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְכָפַר בְּכָל אוֹרַיְיתָא כֻּלָּא, וַוי לֵיהּ, טָב דְּלָא יִתְבְּרֵי, וְלָא יֵיתֵי לְדִינָא דָּא, וּלְכִּסּוּפָא דָּא, הֲדָא הוּא (רי\"ב ע\"א) דִּכְתִּיב, (ישעיהו ס״ו:כ״ד) וְיָּצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי כִּי תוֹלַעְתָּם לא תָמוּת וְאִשָּׁם לא תִכְבֶּה וְהָיוּ דֵרָאוֹן לְכָל בָּשָׂר. כִּי תוֹלַעְתָּם לֹא תָמוּת, מִן גּוּפָא. וְאִשָּׁם לא תִכְבֶּה, מִן נִשְׁמְתָא. וְהָיוּ דֵרָאוֹן לְכָל בָּשָׂר, וְהָיוּ דַּי רָאוֹן, עַד דְּכָל חַיָיבִין דְּגֵיהִנָּם דְּתַּמָּן, יִיִמְרוּן, דַּי רְאִיָה דָּא.</p>\n<p>רִבִּי יוֹסִי אָמַר, וַדַּאי הָכִי הוּא, בְּגִין דְּשַׁבָּת אִיהוּ לָקֳבֵל אוֹרַיְיתָא כֻּלָּא, וְאוֹרַיְיתָא אִיהִי אֵשׁ, בְּגִין דְּעָבְרוּ עַל אֵשׁ דְּאוֹרַיְיתָא, הָא אֵשׁ דְּגֵיהִנָּם דָּלִיק, דְּלָא שָׁכִיךְ מֵעָלַיְיהוּ לְעָלְמִין.</p>\n<p>אָמַר רַבִּי יְהוּדָה, לְבָתַר כַּד נָפִיק שַׁבְּתָא, אָתֵי הַהוּא מַלְאָךְ, וּמְהַדֵר הַהוּא גּוּפָא לְקִבְרֵיהּ, וְאִתְּדָנוּ תַּרְוַויְיהוּ, דָּא לְסִטְרֵיהּ וְדָא לְסִטְרֵיהּ. וְכָל דָּא, בְּעוֹד דְּגוּפָא קַיָּימָא עַל בּוּרְיֵיהּ, דְּהָא כֵּיוָן דְּגוּפָא אִתְאַכָּל, לֵית לֵיהּ לְגוּפָא כָּל אִלֵּין דִּינִין, וְקוּדְשָׁא בְּרִיךְ הוּא (תהילים ע״ח:ל״ח) לא יָעִיר כָּל חֲמָתוֹ כְּתִיב בֵּיהּ.</p>\n<p>כָּל חַיָּיבִין דְּעָלְמָא, בְּעוֹד דְּגוּפָא שְׁלִים בְּכָל שַׁיְיפוֹי גּוֹ קִבְרָא, אִתְדָּנוּ גּוּפָא וְרוּחָא, כָּל חַד דִּינָא כַּדְקָא חֲזִי לֵיהּ. כֵּיוָן דְּגוּפָא אִתְעַכָּל, דִּינָא דְּרוּחָא אִשְׁתְּכַךְ. מַאן דְּאִצְטְרִיךְ לְנָפְקָא, נָפִיק. וּמַאן דְּאִצְטְרִיךְ לְמֶהֱוֵי עָלַיְיהוּ נַיְיחָא, אִית לוֹן נַיְיחָא. וּמַאן דְּאִצְטְרִיךְ לְמֶהֱוֵי קִטְמָא וְעַפְרָא תְּחוֹת רַגְלֵי דְּצַדִּיקַיָּיא. כָּל חַד וְחַד, כַּדְקָא חֲזִי לֵיהּ, אִתְעָבִיד לֵיהּ.</p>\n<p>וְעַל דָּא, כַּמָה טָב לוֹן, בֵּין לְצַּדִיקֵי, בֵּין לְחַיָּיבֵי, לְמֶהוֵי גּוּפָא דִּלְהוֹן דָּבִיק בְּאַרְעָא, וּלְאִתְעַכְּלָא גּוֹ עַפְרָא לִזְמַן קָרִיב, וְלָא לְמֶהֱוֵי בְּקִיּוּמָא כָּל הַהוּא זִמְנָא סַגִּי, בְּגִין לְאִתְדְּנָא גּוּפָא וְנַפְשָׁא וְרוּחָא תָּדִיר. דְּהָא לֵית לָךְ כָּל צַדִּיק וְצַדִּיק בְּעָלְמָא, דְּלֵית לֵיהּ דִּינָא דְּקִבְרָא. בְּגִין דְּהַהוּא מַלְאָךְ דִּמְמָנָא עַל קִבְרֵי, קָאִים עַל גּוּפָא, וְדָן לֵיהּ בְּכָל יוֹמָא וְיוֹמָא. אִם לַצַדִּיקִים כַּךְ, לְחַיָיבִים עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>וּבְזִמְנָא דְּגוּפָא אִתְעַכָּל וְאִתְבְּלֵי בְּעַפְרָא, הָא דִּינָא אִשְׁתְּכַךְ מִכֹּלָּא, בַּר מֵאִינּוּן חֲסִידֵי קַיָימִין דְּעָלְמָא, דְּאִינּוּן אִתְחָזוּן לְסַלְּקָא נִשְׁמָתְהוֹן לְהַהוּא אֲתָר עִלָּאָה דְּאִתְחָזֵי לוֹן, וּזְעִירִין אִינּוּן בְּעָלְמָא.</p>\n<p>כָּל אִינּוּן מֵתִין דְּעָלְמָא, כֻּלְּהוּ מֵתִין עַל יְדֵי דְּמַלְאָכָא מְחַבְּלָא, בַּר אִינּוּן דְּמֵתִין בְּאַרְעָא קַדִּישָׁא, (וכולהו מתין על ידי דמלאכא מחבלא דאיהו מלאך המות, וכל אינון מתין די בארעא קדישא) לָא מֵתִין עַל יְדוֹי, אֶלָּא עַל יְדֵי דְּמַלְאָכָא דְּרַחֲמֵי דְּשַׁלִּיט בְּאַרְעָא.</p>\n<p>אָמַר רַבִּי יִצְחָק, אִי הָכִי, מַאי שְׁבָחָא אִיהוּ לְמֹשֶׁה וּלְאַהֲרֹן וּמִרְיָם, דִּכְתִּיב בְּהוּ (במדבר לג דברים לה) עַל פִּי יְיָ', דְּאִלֵּין לָא מִיתוּ עַל יְדֵי דְּהַהוּא מַלְאָךְ מְחַבְּלָא, וְאַת אַמָרְתְּ, דְּכוּלֵי עָלְמָא אִינּוּן דְּמִיתוּ בְּאַרְעָא דְּיִשְׂרָאֵל, לָא מֵתִין עַל יְדוֹי דְּדָא.</p>\n<p>אָמַר <Nonei></i>לֵיהּ, הָכִי הוּא וַדַּאי, וּשְׁבָחָא דְּמֹשֶׁה אַהֲרֹן וּמִרְיָם, הֲוָה יַתִּיר מִכָּל בְּנֵי עָלְמָא, דְּאִינּוּן מִיתוּ לְבַר מֵאַרְעָא קַדִּישָׁא, דְּמֹשֶׁה אַהֲרֹן וּמִרְיָם לְבַר מֵאַרְעָא קַדִּישָׁא מִיתוּ, וְכֻלְּהוּ מִיתוּ עַל יְדֵי דְּהַהוּא מְחַבְּלָא, בַּר אִינּוּן מֹשֶׁה וְאַהֲרֹן וּמִרְיָם, דְּלָא מִיתוּ אֶלָּא עַל יְדֵי דְּקוּדְשָׁא בְּרִיךְ הוּא. אֲבָל אִינּוּן דְּמֵתִין בְּאַרְעָא קַדִּישָׁא, לָא מֵתִין עַל יְדֵי דְּהַהוּא מְחַבְּלָא, דְּהָא אַרְעָא קַדִּישָׁא לָא קַיְּימָא בִּרְשׁוּ אַחֲרָא, אֶלָּא בִּרְשׁוּ דְּקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי.</p>\n<p>וְעַל דָּא כְּתִיב, (ישעיהו כ״ו:י״ט) יִחְיוּ מֵתֶיךָ נְבֵלָתִי יְקוּמוּן הָקִיצוּ וְרַנְּנוּ שׁוֹכְנֵי עָפָר וְגוֹ'. יִחְיוּ מֵתֶיךָ, אִלֵּין דְּמֵתִין בְּאַרְעָא קַדִּישָׁא, דְּאִינּוּן מֵתִין דִּילֵיהּ, וְלָא מֵאַחֲרָא, דְּלָא שַׁלְטָא תַּמָּן סִטְרָא אַחֲרָא כְּלַל, וְעַל דָּא כְּתִיב מֵתֶיךָ. נְבֵלָתִי יְקוּמוּן, אִינּוּן דְּמִיתוּ בְּאַרְעָא נוּכְרָאָה אַחֲרָא, עַל יְדֵי דְּהַהוּא מְחַבְּלָא.</p>\n<p>וְעַל דָּא אִקְרוּן נְבֵלָה, מַה נְבֵלָה מְטַמְּאָה בְּמַשָּׂא, אוּף אִינּוּן דְּמֵתִין לְבַר מֵאַרְעָא קַדִּישָׁא, מְטַמְאִין בְּמַשָּׂא. (נ\"א במגע) וְעַל דָּא אִינּוּן נְבֵלָה. כָּל שְׁחִיטָה דְּאִיפְסִיל, אִקְרֵי נְבֵילָה, בְּגִין שְׁחִיטָה הָא אִיהִי מִסִּטְרָא אַחֲרָא, וּמִיַּד דְּאִיפְסִיל שַׁרְיָא עָלָהּ סִטְרָא אַחֲרָא. וּבְגִין דְּאִיהִי דִּילֵיהּ, וְשַׁרְיָא עָלָהּ אִקְרֵי נְבֵלָה. וְרָזָא דָּא (ס\"א כשמו כן הוא) נָבָל הוּא, (שמואל א כ״ה:כ״ה) וְנָבָל שְׁמוֹ וּנְבָלָה עִמּוֹ.</p>\n<p>וְעַל דָּא בְּכָל אֲתָר דְּאִיהוּ שַׁרְיָא, אִקְרֵי נְבֵלָה. מְנוּוָל דָּא לָא שַׁרְיָא, אֶלָּא בְּאֲתָר פְּסִילוּ, וְעַל דָּא שְׁחִיטָה דְּאַפְסִיל, הָא דִּילֵיהּ הוּא, וְאִקְרֵי עַל שְׁמֵיהּ. וּבְגִין כַּךְ, מֵתִין דְּאִינּוּן לְבַר מֵאַרְעָא קַדִּישָׁא, תְּחוֹת רְשׁוּ אַחֲרָא, וְשַׁרְיָא עָלַיְיהוּ סִטְרָא אַחֲרָא, אִקְרוּן נְבֵלָה.</p>\n<p>הָקִיצוּ וְרַנְּנוּ שׁוֹכְנֵי עָפָר, שׁוֹכְנֵי, דַּיְירִין דְּמִיכִין, וְלָא מֵתִין. וּמַאן אִינּוּן. דְּמִיכִין דְּחֶבְרוֹן, דְּאִינּוּן לָא מֵתִין, אֶלָּא דְּמִיכִין. וְעַל דָּא כְּתִיב בְּהוּ גְּוִיעָה, כְּמַאן דְּגָוַוע, וְאִית בֵּיהּ קִיוּמָא לְאַנְעֲרָא. אוּף הָכִי אִינּוּן ד' זוּגֵי דְּחֶבְרוֹן, דְּמִיכִין אִינּוּן וְלָא מֵתִין, וְכֻלְּהוּ קַיְימוּ בְּקִיוּמַיְיהוּ בְּאִינּוּן גּוּפִין דִּלְהוֹן, וְיַדְעֵי סִתְרִין גְּנִיזִין, יַתִּיר מִשְּׁאָר בְּנֵי נָשָׁא. גְּנִיזִין הֲווֹ תַּמָּן גּוֹ פִּתְחָא דְּגַּן עֵדֶן אִינּוּן גּוּפִין דִּלְהוֹן, וְאִלֵּין אִינּוּן שׁוֹכְנֵי עָפָר. וְעַל דָּא כָּל אִינּוּן דְּנַפְקוּ נִשְׁמָתַיְיהוּ בְּאַרְעָא קַדִּישָׁא, לָא נָפִיק עַל יְדֵי דְּהַהוּא מְחַבְּלָא, וְלָא שַׁלְטָא תַּמָּן, אֶלָּא עַל יְדֵי דְּמַלְאָכָא דְּרַחֲמֵי, דְּאַרְעָא קַדִּישָׁא קַיְּימָא בְּעַדְבֵיהּ.</p>"],[9520011740,"<p>אֲתָר אִית בְּיִשּׁוּבָא, דְּלָא שַׁלְטָא בֵּיהּ הַהוּא מְחַבְּלָא, וְלָא אִתְיְיהִיב לֵיהּ רְשׁוּ לְאַעֲלָא תַּמָּן, וְכָל אִינּוּן דְּדַיְירֵי תַּמָּן, לָא מֵתִין, עַד דְּנָפְקִין לְבַר מִקַּרְתָּא. וְלֵית לָךְ בַּר נָשׁ מִכָּל דְּדַיְירִין תַּמָּן, דְּלָא מֵתִין, וְכֻלְּהוּ מֵתִין כִּשְׁאַר בְּנֵי נָשָׁא, אֲבָל לָאו בְּמָתָא. מַאי טַעְמָא. בְּגִין דְּלָא יַכְלִין לְמֵיתַב תָּדִיר בְּמָתָא, אֶלָּא אִלֵּין נָפְקִין, וְאִלֵּין עָאלִין, וְעַל דָּא כֻּלְּהוּ מֵתִין.</p>\n<p>מַאי טַעְמָא לָא שַׁלְטָא תַּמָּן הַהוּא מַלְאָךְ מְחַבְּלָא. אִי תֵּימָא דְּלָא קַיְּימָא בִּרְשׁוּתֵיהּ, הָא אַרְעָא קַדִּישָׁא דְּלָא קַיְּימָא בִּרְשׁוּ אַחֲרָא, וּמֵתִין, בְּהַהוּא אֲתָר אֲמַאי לָא מֵתִין. אִי תֵּימָא בְּגִין קְדוּשָּׁה, לֵית אֲתָר בִּקְדוּשָׁה בְּכָל יִשׁוּבָא כְּגַוְונָא דְּאֶרֶץ יִשְׂרָאֵל. וְאִי תֵּימָא, בְּגִין הַהוּא גַּבְרָא דְּבָנֵי לָהּ. כַּמָה בְּנֵי נָשָׁא הֲווֹ דִּזְכוּתֵיהוֹן יַתִּיר מִדִילֵיהּ. אָמַר רַבִּי יִצְחָק, אֲנָא לָא שְׁמַעְנָא וְלָא אֵימָא.</p>\n<p>אָתוּ שָׁאִילּוּ לֵיהּ לְרַבִּי שִׁמְעוֹן, אָמַר לוֹן, וַדַּאי הַהוּא אֲתָר לָא שַׁלְטָא עָלֵיהּ מַלְאָךְ הַמָּוֶת, וְקוּדְשָׁא בְּרִיךְ הוּא לָא בָּעֵי דִּבְהַהוּא אֲתָר יְמוּת בַּר נָשׁ לְעָלְמִין, וְאִי תֵּימָא, דְּקֹדֶם לָכֵן בְּהַהוּא דּוּכְתָּא, עַד לָא אִתְבְּנֵי, מִיתוּ בֵּיהּ בְּנֵי נָשָׁא, לָאו הָכִי. אֶלָּא מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא, אִתְתָּקַּן הַהוּא אֲתָר, לְקִיּוּמָא, וְרָזָא דְּרָזִין הָכָא, לְאִינּוּן דְּמִסְתַּכְּלֵי בְּרָזָא דְּחָכְמְתָא.</p>\n<p>כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, בָּרָא לֵיהּ בְּרָזָא (מקץ ר\"ד ע\"א) דְּאַתְוָון, וְאִתְגַּלְגְּלוּ אַתְוָון, וּבָרָא עָלְמָא, בְּגִלּוּפֵי דִּשְׁמָא קַדִּישָׁא. אִתְגַּלְגְּלוּ אַתְוָון, וְאַסְחֲרוּ עָלְמָא בְּגִלּוּפֵי וְכַד אִתְגְּלֵי וְאִתְפָּשַּׁט עָלְמָא וְאִתְבְּרֵי, וַהֲווּ אַתְוָון סָחֲרָן לְמִבְרֵי, אָמַר קוּדְשָׁא בְּרִיךְ הוּא דְּיִסְתַּיֵּים בְּיוֹ\"ד, אִשְׁתְּאָרַת אָת ט' (נ\"א יתגלגלו אתוון, ואסחרו עלמא בגלופא דשמא קדישא וכד אתגלגלו אתוון והוו סחרן למברי, אמרז קודשא בריך הוא די יסתיים ביו\"ד, אשתארת את ט' בלחודהא) בְּהַהוּא דּוּכְתָּא, <Nonei></i>תַּלְיָא בַּאֲוֵירָא, כֵּיוָן דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא דַּי יִסְתַּיֵּים בְּיוֹ\"ד, אִשְׁתְּאָרַת אָתְ טֵי\"ת בִּלְחוֹדָהָא תַּלְיָא בַּאֲוֵירָא עַל גַּבֵּי הַהוּא דּוּכְתָּא טֵי\"ת, אִיהוּ אָת, דִּנְהִירוּ חַיִּין, בְּגִין כַּךְ, מַאן דְּחָמֵי טֵי\"ת בְּחֶלְמֵיהּ, סִימָנָא טָבָא הוּא לֵיהּ, וְחַיִּין אִתְתָּקָנוּ לֵיהּ. וְעַל דָּא בְּגִין דְּהֲוָה ט' תַּלְיָא עַל גַּבֵּי הַהוּא אֲתָר, לָא שַׁלְטָא בֵּיהּ מוֹתָא.</p>\n<p>כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְקַיְּימָא עָלְמָא, זָרִיק חַד צְרוֹרָא גּוֹ מַיָּא, גָּלִיף בְּרָזָא דְּע\"ב (נ\"א דכ\"ב) אַתְוָון, וּמִתַּמָּן שָׁאֲרִי לְמֵיהַךְ הַהוּא צְרוֹרָא, וְלָא אַשְׁכַּח אֲתָר לְאִתְקַיְּימָא בֵּיהּ, בַּר אַרְעָא קַדִּישָׁא, (נ\"א בבי מקדשא) וּמַיָּא הֲווֹ אַזְלִין אֲבַתְרֵיהּ, עַד דְּמָטָא הַהוּא צְרוֹרָא תְּחוֹת הַמִּזְבֵּחַ, וְתַמָּן אִשְׁתְּקַע, וְאִתְקָיָּים כָּל עָלְמָא.</p>\n<p>וְאִי תֵּימָא, אִי הָכִי דִּבְהַהוּא אֲתָר שַׁרְיָין חַיִּים, אֲמַאי לָא אִתְבְּנֵי תַּמָּן בֵּי מַקְדְּשָׁא, לְמֵיהַב חַיִּין לְיַתְבָהָא. אֶלָּא הָכָא בְּהַאי אֲתָר אִתְקָיָּים בְּגִין אָת חַד דְּשַׁרְיָא עָלֵיהּ. בְּבֵי מַקְדְּשָׁא כָּל אַתְוָון כֻּלְּהוּ שָׁרָאן בֵּיהּ, וּבְהוּ אִתְבְּרֵי אִיהוּ בִּלְחוֹדוֹי, כְּגַוְונָא דְּכָל עָלְמָא.</p>\n<p>וְתוּ, דְּאַרְעָא קַדִּישָׁא (נ\"א בבי מקדשא) יָהִיב חַיִּין וְכַפָּרָה לְיָתְבָהָא בְּהַהוּא עָלְמָא, וַאֲתָר דָּא לָאו הָכִי, יָהִיב חַיִּין לְהַהוּא אֲתָר בְּהַאי (בראשית נ' ע\"א, לקמן ר\"ל ע\"א) עָלְמָא, וְלָא בְּעָלְמָא דְּאָתֵי. וּבֵי מַקְדְּשָׁא בְּהִפּוּכָא מִתַּמָּן, בְּגִין דְּאִית חוּלָקָא לְיִשְׂרָאֵל בְּהַהוּא עָלְמָא, וְלָא בְּעָלְמָא דָּא. וְעַל דָּא קַיְּימָא בֵּי מַקְדְּשָׁא לְכַפָּרָא חוֹבִין, וּלְמִזְכֵּי לוֹן לְיִשְׂרָאֵל לְעָלְמָא דְּאָתֵי.</p>\n<p>תָּא חֲזֵי, טֵי\"ת נְהִירוּ דְּחַיִּין בְּכָל אֲתָר, וְעַל דָּא פָּתַח בָּהּ קְרָא כִּי טוֹב. דִּכְתִּיב, (בראשית א׳:ד׳) וַיַּרְא אֱלהִים אֶת הָאוֹר כִּי טוֹב. מֵהַאי אָת, (נ\"א מאתר דא) עָרִיק מַלְאָכָא מְחַבְּלָא. לָא תֵּימָא עָרִיק, אֶלָּא דְּלָא אִתְיְיהִיב לֵיהּ רְשׁוּ לְאַעֲלָא תַּמָּן.</p>\n<p>אָת דָּא מְשַׁנְיָא מֵאָת ק', ק' לָא מִתְיַישְּׁבָא (נ\"א מאת ח', ח' לא מתיישבא) כְּלַל בְּדוּכְתָּא בְּעָלְמָא, וְסִימָנִךְ (תהילים ק״מ:י״ב) אִישׁ לָשׁוֹן בַּל יִכּוֹן בָּאָרֶץ אָת טֵי\"ת אִתְיַישְׁבָא בְּכָל דּוּכְתָּא, וְאִתְתַּקָּנַת לְאִתְיַישְּׁבָא כְּדְקָא יֵאוֹת, וּבְּגִין כָּךְ בְּכָל דּוּכְתָּא דְּאָת ט' תַּמָּן, לֵית יִשׁוּבָא לְאָת ק' תַּמָּן לְאִתְיַישְּׁבָא בֵּיהּ. וְעַל דָּא אֲתָר דָּא לָא שַׁלְטָא בֵּיהּ כְּלַל סִטְרָא אַחֲרָא, וְיָהִיב חַיִּים דְּהַאי עָלְמָא לְיַתְבֵי תְּחוֹתֵיהּ דְּאָת דָּא, וְלָא יִפּוּק לְבַר, וְכַד נָפִיק לְבַר, אִית רְשׁוּ לְסִטְרָא אַחֲרָא לְשַׁלְּטָאָה בֵּיהּ. כְּמָה דְּאָת דָּא שַׁלְטָא בְּאֲתָר דָּא, הָכִי נָמֵי שַׁלְטָא אָת אַחֲרָא בְּאֲתָר דְּגֵיהִנָּם, וּמַאן אִיהִי, (ק\"פ ע\"ב) אָת ק'.</p>"],[9520011741,"<p>וּבְסִפְרָא דְּרַב הַמְנוּנָא סָבָא, הָכָא אִינּוּן תְּרֵין אַתְוָון: ח', ט'. וְעַל דָּא לָא הֲווֹ כְּתִיבִין גּוֹ אַבְנִי בּוּרְלָא, אֲבָנִין דְּאַשְׁלָמוּתָא, וּשְׁבָטִין דְּיִשְׂרָאֵל, תְּרֵין אַתְוָון אִלֵּין אִתְמְנָעוּ מִנַּיְיהוּ, בְּגִין דְּלָא יְהֵא רָשִׁים בְּגַּוַּויְיהוּ חֵ\"ט.</p>\n<p>בְּאֲתָר דְּבֵי מַקְדְּשָׁא תַּלְיָין כָּל אַתְוָון דְּאַלְפָא בֵּיתָא, בְּרָזִין גְּלִיפָן דִּשְׁמָהָן קַדִּישִׁין, קְשִׁירִין, מְרֻקָּמָן עָלֵיהּ, וְכָל עָלְמָא דִּלְעֵילָּא וְתַתָּא, כֹּלָּא בְּרָזָא דְּאַתְוָון מִּתְחַמְמָן (נ\"א מתחקקן) וּגְּלִיפָא, וְרָזִין דִּקְדֻשָׁא (ס\"א דשמא קדישא) עִלָּאָה, עָלַיְיהוּ אִתְגְּלִיף.</p>\n<p>בְּמַשְׁכְּנָא אִתְגְּלִיפוּ וְאִתְצָיָירוּ אַתְוָון כַּדְקָא חֲזִי. דְּהָא בְּצַלְאֵל הֲוָה יָדַע חָכְמְתָא, לְצָרְפָא אַתְוָון דְּאִתְבְּרִיאוּ בְּהוּ שְׁמַיָא וְאַרְעָא. וְעַל חָכְמְתָא דִּילֵיהּ, (נ\"א דא) אִתְבְּנֵי מַשְׁכְּנָא עַל יְדֵיהּ, וְאִתְבְּרִיר מִכָּל עַמָּא דְּיִשְׂרָאֵל.</p>\n<p>וּכְמָה דְּאִיהוּ אִתְבְּרִיר לְעֵילָּא, הָכִי בָּעָא קוּדְשָׁא בְּרִיךְ הוּא דְּיִתְבְּרִיר לְתַתָּא. לְעֵילָּא כְּתִיב, (שמות ל״א:ב׳) רְאֵה קָרָאתִי בְשֵׁם בְּצַלְאֵל. לְתַתָּא (שמות ל״ה:ל׳) רְאוּ קָרָא יְיָ' בְּשֵׁם בְּצַלְאֵל. וּשְׁמֵיהּ בְּרָזָא עִלָּאָה אִקְרֵי הָכִי בְּצַלְאֵל: בְּצֵל אֵל. וּמַאן אִיהוּ. דָּא צַדִּיק. דְּאִיהוּ יָתִיב בְּצֵל אֵל, הַהוּא דְּאִקְרֵי אֵל (לך לך ע\"ז ע\"א) עֶלְיוֹן. וְאִיהוּ יָתִיב כְּגַוְונָא דְּהַהוּא אֵל. הַהוּא אֵל נָטִיל שִׁית סִטְרִין, הַהוּא צַדִּיק נָטִיל לוֹן. אוּף הָכִי, הַהוּא אֵל אַנְהִיר לְעֵילָּא, הַאי צַדִּיק אַנְהִיר לְתַתָּא. הַהוּא אֵל, כְּלָלָא דְּכֻלְּהוּ שִׁית סִטְרִין. הַהוּא צַדִּיק, כְּלָלָא דְּכֻלְּהוּ שִׁית סִטְרִין.</p>\n<p>בֶּן אוּרִי: בֶּן אוֹר קַדְמָאָה, דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא בְּעוֹבָדָא דִּבְרֵאשִׁית. בֶּן חוּר: בֶּן חִירוּ דְּכֹלָּא. דָּבָר אַחֵר, בֶּן חוּר: בֶּן חִוָּור מִכָּל גַּוְונִין. וְדָא אִתְמָנֵי לְמַטֵּה יְהוּדָה, כֹּלָּא כַּדְקָא יֵאוֹת.</p>"],[9520011742,"<p>כָּל גַּוְונִין טָבִין לְחֶלְמָא, בַּר תִּכְלָא, כְּמָה (קל\"ט ע\"א) דְּאִתְּמַר. בְּגִין דְּאִיהוּ כֻּרְסְיָיא, לְמֵידָן דִּינִין דְּנִשְׁמָתִין. וְהָא הַאי דַּרְגָּא (נ\"א חדא) חִוָּורָא אִיהוּ. אֶלָּא בְּשַׁעֲתָא דְּקַיְּימָא בְּדִינֵי דְּנַפְשָׁאן, כְּדִין אִיהוּ גּוָֹון תִּכְלָא. וְהָא <Nonei></i>אוֹקִימְנָא.</p>\n<p>בְּשַׁעֲתָא דְּחָמֵי בַּר נָשׁ לְהַאי גּוָֹון, אִדְכַּר בַּר נָשׁ לְמֶעְבַּד פִּקּוּדִין דְּמָארֵיהּ. כְּגַוְונָא דִּנְחַשׁ הַנְּחֹשֶׁת, בְּשַׁעֲתָא דַּהֲווֹ חֲמָאן לֵיהּ, הֲווֹ דַּחֲלֵי מִקַּמֵּי דְּקוּדְשָׁא בְּרִיךְ הוּא, וּמְנַטְרָן גַּרְמַיְיהוּ מִכָּל חוֹבִין, וּבְשַׁעֲתָא דְּהַהוּא דְּחִילוּ דְּקוּדְשָׁא בְּרִיךְ הוּא סַלְּקָא עָלַיְיהוּ, מִיָּד אִתָּסְיָין. מַאן גָּרִים לוֹן לְדַּחֲלָא מִקָּמֵי קוּדְשָׁא בְּרִיךְ הוּא, הַהוּא נָחָשׁ, הַהִיא רְצוּעָה דְּמִסְתַכְּלָן בָּהּ. אוּף הָכִי תְּכֵלֶת (במדבר ט״ו:ל״ט) וּרְאִיתֶם אוֹתוֹ וּזְּכַרְתֶּם אֶת כָּל מִצְוֹת יְיָ'. מֵהַהוּא דְּחִילוּ דִּילֵיהּ, וְעַל דָּא תְּכֵלֶת בְּמַשְׁכְּנָא.</p>\n<p>אָמַר רַבִּי יִצְחָק, הַאי דְּאָמַר מַר תְּכֵלֶת כֻּרְסְיָיא דְּדִינָא אִיהִי, וְכַד אִיהִי קַיְּימָא בְּגַוְונָא דָּא, כְּדֵין אִיהִי כֻּרְסְיָיא לְמֵידָן דִּינֵי נַפְשָׁאן. אֵימָתַי אִיהִי בְּרַחֲמֵי. אָמַר לֵיהּ, בְּשַׁעֲתָא דִּכְרוּבִים מְהַדְרָן אַנְפַּיְיהוּ דָּא עִם דָּא, וּמִסְתַּכְּלָן אַנְפִּין בְּאַנְפִּין. כֵּיוָן דְּאִינּוּן כְּרוּבִים מִסְתַּכְּלָן אַנְפִּין בְּאַנְפִּין כְּדֵין כָּל גַּוְונִין מִתְתַּקְנָן, וְאִתְהַפָּךְ גּוָֹון תִּכְלָא לְגָוְון אַחֲרָא. מִתְהַפָּךְ גּוָֹון יָרוֹק, לְגָוְון זָהָב.</p>\n<p>(נ\"א חוור) וְעַל דָּא, בְּהִפּוּכָא דִּגְוָונִין, אִתְהַפַּךְ מִדִּינָא לְרַחֲמֵי, וְכֵן מֵרַחֲמֵי לְדִינָא, וְכֹלָּא בְּהִפּוּכָא דִּגְוָונִין. כְּמָה דִּמְסַדְרִין יִשְׂרָאֵל תִּקּוּנַיְיהוּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, הָכִי קַיָּימָא כֹּלָּא, וְהָכִי אִתְסָדַר. וְעַל דָּא כְּתִיב (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר, בְּאִינּוּן גַּוְונִין דִּכְלִילָן דָּא בְּדָא, שְׁפִירוּ דְּכֻלְּהוּ. (חסר כאן)</p>"],[9520011743,"<p>(שמות כ״ה:כ״ג) וְעָשִׂיתָ שֻׁלְחָן עֲצֵי שִׁטִּים וְגוֹ'. רַבִּי יִצְחָק פָּתַח, (דברים ח׳:י׳) וְאָכַלְתָּ וְשָבָעְתָּ וּבֵרַכְתָּ אֶת יְיָ' אֱלֹהֶיךָ וְגוֹ', כַּמָה זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ, וְקָרִיב לוֹן לְגַבֵּיהּ מִכָּל עַמִּין, וּבְגִינֵהוֹן דְּיִשְׂרָאֵל, יָהִיב מְזוֹנָא וְשַׂבְעָא, לְכָל עָלְמָא. וְאִלְמָלֵא יִשְׂרָאֵל, לָא יָהִיב קוּדְשָׁא בְּרִיךְ הוּא מְזוֹנָא לְעָלְמָא, וְהַשְׁתָּא דְּיִשְׂרָאֵל אִינּוּן בְּגָלוּתָא, עַל אַחַת כַּמָּה וְכַמָּה דְּנַטְלֵי מְזוֹנָא עַל חַד תְּרֵין.</p>\n<p>בְּזִמְנָא דַּהֲווֹ יִשְׂרָאֵל בְּאַרְעָא קַדִּישָׁא, הֲוָה נָחִית לוֹן מְזוֹנָא מֵאֲתָר עִלָּאָה, וְאִינּוּן יָהֲבֵי חוֹלָק תַּמְצִית לְעַמִּין עוֹבְדֵי כּוֹכָבִים, וְעַמִּין כֻּלְּהוּ לָא אִתְּזָנוּ אֶלָּא מִתַּמְצִית. וְהַשְׁתָּא דְּיִשְׂרָאֵל אִינּוּן בְּגָלוּתָא, אִתְהַפַּךְ בְּגַוְונָא אַחֲרָא.</p>\n<p>מְתַל לְמַלְכָּא, דְּאַתְקִין סְעוּדָתָא לִבְנֵי בֵּיתֵיהּ, כָּל זִמְנָא דְּאִינּוּן עַבְדֵי רְעוּתֵיהּ, אַכְלֵי סְעוּדָתָא עִם מַלְכָּא, וְיָהֲבֵי לְכַלְבֵּי חוּלָק גַּרְמִין לְמִגְרַר. בְּשַׁעֲתָא דִּבְנִי בֵּיתֵיהּ לָא עַבְדֵי רְעוּתָא דְּמַלְכָּא, מַלְכָּא יָהִיב כָּל סְעוּדָתָא לְכַלְבֵּי, וְסָלִיק לוֹן גַּרְמֵי.</p>\n<p>כְּגַוְונָא דָּא, כָּל זִמְנָא דְּיִשְׂרָאֵל עַבְדֵי רְעוּתָא דְּמָארֵיהוֹן, הָא עַל פָּתוֹרָא דְּמַלְכָּא אִינּוּן אַכְלֵי, וְכָל סְעוּדָתָא אִתְתָּקַּן לְהוֹן. וְאִינּוּן, מֵהַהוּא חֶדְוָה דִּלְהוֹן, יָהֲבֵי גַּרְמֵי דְּאִיהוּ תַּמְצִית לְעוֹבָדֵי כּוֹכָבִים. וְכָל זִמְנָא דְּיִשְׂרָאֵל לָא עַבְדֵי רְעוּתָא דְּמָארֵיהוֹן, אַזְלֵי בְּגָלוּתָא, וְהָא סְעוּדָתָא לְכַלְבֵּי, וְאִסְתַּלָּק לוֹן תַּמְצִית (יחזקאל ד׳:י״ג) כָּכָה יֹאכְלוּ בְּנֵי יִשְׂרָאֵל אֶת לַחְמָם טָמֵא בַּגּוֹיִם, דְּהָא תַּמְצִית דְּגִעוּלֵיהוֹן אַכְלֵי. וַוי לִבְרָא דְּמַלְכָּא, דְּיָתִיב וּמְצַפֶּה לְפָתוֹרָא דְּעַבְדָא, מַה דְּאִשְׁתְּאַר מִגּוֹ פָּתוֹרָא אִיהוּ אָכִיל.</p>\n<p>דָּוִד מַלְכָּא אָמַר, (תהילים כ״ג:ה׳) תַּעֲרֹךְ לְפָנַי שֻׁלְחָן נְגֶד צוֹרְרָי דִּשַּׁנְתָּ בַשֶּׁמֶן רֹאשִׁי כּוֹסִי רְוָיָה. תַּעֲרוֹךְ לְפָנַי שֻׁלְחָן, דָּא סְעוּדָתָא דְּמַלְכָּא. נֶגֶד צוֹרְרָי, אִינּוּן כַּלְבֵּי דְּיַתְבֵי קָמֵי פָּתוֹרָא, מְצַפָּאן לְחוּלָק גַּרְמִין, וְאִיהוּ יָתִיב עִם מַלְכָּא בְּעִנוּגָא דִּסְעוּדָתָא בְּפָתוֹרָא.</p>\n<p>דִּשַּׁנְתָּ בַשֶּׁמֶן רֹאשִׁי, דָּא רֵישָׁא דִּסְעוּדָתָא, דְּכָל מִשְׁחָא, וְשַׁמְנוּנָא, וְתִקוּן סְעוּדָתָא, אִתְיְיהִיב בְּקַדְמִיתָא לִרְחִימָא דְּמַלְכָּא. מַה דְּאִשְׁתְּאַר, לְבָתַר אִתְיְיהִיב לְכַלְבֵּי, וּלְאִינּוּן פַּלְחֵי פָּתוֹרָא. כּוֹסִי רְוָיָה, מַלְיָא כַּסָּא קָמֵי רְחִימָא דְּמַלְכָּא תָּדִיר, דְּלָא יִצְטְרִיךְ לְמִשְׁאַל. וְעַל רָזָא דָּא, הֲווֹ יִשְׂרָאֵל תָּדִיר, עִם שְׁאַר עַמִּין.</p>\n<p>רַבִּי חִיָּיא הֲוָה אָזִיל לְגַבֵּי דְּרַבִּי שִׁמְעוֹן לִטְבֶרְיָה, וַהֲווּ עִמֵּיהּ רַבִּי יַעֲקֹב בַּר אִידִי, וְרַבִּי יֵיסָא זְעִירָא, עַד דַּהֲווֹ אַזְלֵי, אָמַר רַבִּי יֵיסָא לְרַבִּי חִיָּיא, תֵּימָה מָה דִּכְתִּיב, (מלכים א ב׳:ז׳) וְלִבְנַי בַרְזִיּלַי הַגִּלְעָדִי תַּעֲשֶׂה חֶסֶד וְהָיוּ בְּאוֹכְלֵי שֻׁלְחָנֶךָ וְגוֹ'. אִי הָכִי כָּל טִיבוּ וּקְשׁוֹט, לְמֵיכַל עַל פָּתוֹרֵיהּ וְלָא יַתִּיר, מִדְּקָאָמַר הָכָא וְהָיוּ בְּאוֹכְלֵי שֻׁלְחָנְךָ. וְתוּ, לָאו יְקָרָא דְּמַלְכָּא אִיהוּ, לְמֵיכַל בַּר נָשׁ אָחֳרָא <Nonei></i>עַל פָּתוֹרֵיהּ דְּמַלְכָּא, וְלָא אִצְטְרִיךְ דָּא, אֶלָּא מַלְכָּא בִּלְחוֹדוֹי, וְכֻלְּהוּ רַבְרְבָנוֹהִי סַחֲרָנֵיהּ, לְתַתָּא מִנֵּיהּ.</p>\n<p>אָמַר רַבִּי חִיָּיא לָא שְׁמַעְנָא בְּהַאי מִידִי, וְלָא אֵימָא. אֲמַר לֵיהּ לְרַבִּי יַעֲקֹב בַּר אִידִי, וְאַתְּ שָׁמַעְתָּ בְּהַאי מִידִי. אֲמַר לֵיהּ, אַתּוּן דְּיַנְקִין בְּכָל יוֹמָא מִדֻּבְשָׁא דְּמִשְׁחָא עִלָּאָה, לָא שְׁמַעְתּוּן, כָּל שֶׁכֵּן אֲנָא. אָמַר לֵיהּ לְרַבִּי יֵיסָא, וְאַתְּ שָׁמַעְתָּ מִידִי בְּהַאי. אֲמַר לֵיהּ אַף עַל גַּב דַּאֲנָא רַבְיָא וּמִיּוֹמִין זְעִירִין אֲתֵינָא לְגַבַּיְיכוּ, וְלָא זָכֵינָא מִקַּדְמַת דְּנָא, אֲנָא שְׁמַעְנָא.</p>\n<p>פָּתַח וְאָמַר (תהילים קל״ו:כ״ה) נוֹתֵן לֶחֶם לְכָל בָּשָׂר כִּי לְעוֹלָם חַסְדּוֹ. מַאי קָא חָמָא דָּוִד דְּסִיוּם הַלֵּלָא רַבָּא, סִיֵּים הָכִי בְּהַאי קְרָא. אֶלָּא תְּלַת שַׁלִּיטִין אִינּוּן לְעֵילָּא, דְּקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּמוֹדְעָא בְּהוּ, וְאִינּוּן רָזָא יַקִּירָא דִּילֵיהּ, וְאִלֵּין אִינּוּן: מוֹחָא, וְלִבָּא, וְכַבְדָּא. וְאִינּוּן בְּהִפּוּכָא דְּהַאי עָלְמָא. לְעֵילָּא, מוֹחָא נָטִיל בְּרֵישָׁא, וּבָתַר יָהִיב לְלִבָּא, וְלִבָּא נָטִיל וְיָהִיב לְכַבְדָּא, וּלְבָתַר כַּבְדָא יָהִיב חוּלָק לְכָל אִינּוּן מְקוֹרִין דִּלְתַתָּא, כָּל חַד וְחַד כַּדְקָא חֲזִי לֵיהּ. לְתַתָּא, כַּבְדָא נָטִיל בְּרֵישָׁא, וּלְבָתַר אִיהוּ מְקָרַב כֹּלָּא לְלִבָּא, וְנָטִיל לִבָּא שְׁפִירוּ דְּמֵיכְלָא. כֵּיוָן דְּנָטִיל, וְאִתְתָּקַף מֵהַהוּא תֻּקְפָּא וּרְעוּ דְּקָא נָטִיל, יָהִיב וְאִתְּעַר לְגַבֵּי מוֹחָא. וּלְבָתַר אַהְדָּר כַּבְדָא, וּפָלִיג מְזוֹנָא לְכָל מְקוֹרִין דְּגוּפָא. (ביומא דבר נש אתער בתעניתא, אתער לעילא כגוונא ההוא ממש, וביומא דשבעא, לאו הכי)</p>\n<p>בְּיוֹמָא דְּתַעֲנִיתָא, בַּר נָשׁ מְקָרַב מֵיכְלָא וּמִשְׁתְּיָּא לְגַבֵּי כַּבְדָא עִלָּאָה, וּמַאי אִיהוּ מְקָרַב. חֶלְבֵּיהּ וְדָמֵיהּ וּרְעוּתֵיהּ. הַהוּא כַּבְדָא נָטִיל כֹּלָּא בִּרְעוּתָא. כֵּיוָן דְּכֹלָּא אִיהוּ לְגַבֵּיהּ, נָטִיל וּמְקָרַב כֹּלָּא לְקָמֵי לִבָּא, דְּאִיהוּ רַב וְשָׁלִיט עָלֵיהּ. כֵּיוָן דְּלִבָּא נָטִיל וְאִתְתָּקַף בְּרַעֲוָא, מְקָרֵב כֹּלָּא לְגַבֵּי מוֹחָא, דְּאִיהוּ שַׁלִּיטָא עִלָּאָה עַל כָּל גּוּפָא, לְבָתַר אַהְדָּר כַּבְדָא וּמְפַלֵג חוּלָקִין לְכָל אִינּוּן מְקוֹרִין וְשַׁיְיפִין דִּלְתַתָּא. בְּזִמְנָא אָחֲרָא, כַּד (ד\"א כלא) מוֹחָא נָטִיל בְּקַדְמִיתָא, וּלְבָתַר יָהִיב לְלִבָּא, וְלִבָּא יָהִיב לְכַבְדָּא, וְכַבְדָּא יָהִיב לְכֻלְּהוּ מְקוֹרִין וְשַׁיְיפִין דִּלְתַתָּא, וּלְבָתַר כַּד בָּעֵי לְפַלְּגָא מְזוֹנָא לְהַאי עָלְמָא, בְּרֵישָׁא יָהִיב לְלִבָּא, דְּאִיהוּ מַלְכָּא דִּי בְּאַרְעָא. וּפָתוֹרָא דְּמַלְכָּא, אִתְּעַר בְּקַדְמִיתָא מִכָּל שְׁאַר בְּנֵי עָלְמָא.</p>\n<p>זַכָּאָה אִיהוּ, מַאן דַּהֲוֵי בְּחוּשְׁבָּנָא דְּפָתוֹרָא דְּמַלְכָּא, דְּהָא אִשְׁתְּמוֹדְעָא לְאוֹטָבָא לֵיהּ בְּהַהוּא טִיבוּ דִּלְעֵילָּא.</p>\n<p>(ובגיני כך) וְדָא אִיהוּ טִיבוּ וּקְשׁוֹט, דַּעֲבַד דָּוִד לִבְנֵי בַרְזִיּלַי, דִּכְתִּיב וְהָיוּ בְּאֹכְלֵי שֻׁלְחָנֶךָ. וְאִי תֵּימָא דִּבְשֻׁלְחָנָא דְּמַלְכָּא, אָכִיל בַּר נָשׁ אָחֳרָא בַּר מִנֵּיהּ. לָא. אֶלָּא מַלְכָּא אָכִיל בְּרֵישָׁא, וּבָתַר כָּל עַמָּא. וְאִינּוּן דְּאַכְלֵי עִם מַלְכָּא, בְּשַׁעֲתָא דְּאִיהוּ אָכִיל אִינּוּן דְּחָבִיבִין עָלֵיהּ מִכֻּלְּהוּ, וְאִינּוּן אִתְמְנוּן מִשֻׁלְחָנָא דְּמַלְכָּא.</p>\n<p>וְאִי תֵּימָא, הָא כְּתִיב, (שמואל ב ט׳:י״ג) עַל שֻׁלְחָן הַמֶּלֶךְ תָּמִיד הוּא אוֹכֵל. בְּגִין דְּכָל מְזוֹנָא דִּילֵיהּ, לָא עָבִיד חוּשְׁבָּנָא אָחֳרָא, אֶלָּא עַל שֻׁלְחָן הַמֶּלֶךְ, דְּמִתַּמָּן הֲוָה אָתֵי מְזוֹנָא וּמֵיכְלָא דִּילֵיהּ. וְדָא אִיהוּ עַל שֻׁלְחָן הַמֶּלֶךְ תָּמִיד הוּא אוֹכֵל. אָתָא רַבִּי חִיָּיא, וּנְשָׁקֵיהּ עַל רֵישֵׁיהּ, אָמַר לֵיהּ רַבְיָא אַנְתְּ, וְחָכְמְתָא עִלָּאָה שַׁרְיָא בְּלִבָּךְ. אַדְּהָכִי, חָמוּ לֵיהּ לְרַבִּי חִזְקִיָּה דְּהֲוָה אָתֵי. אֲמַר לֵיהּ רַבִּי חִיָּיא, וַדַּאי בְּחַבְרוּתָא דָּא, קוּדְשָׁא בְּרִיךְ הוּא יִתְחַבָּר עָלָנָא, דְּהָא מִלִּין חַדְתִּין דְּאוֹרַיְיתָא יִתְחַדְתּוּן הָכָא.</p>\n<p>יָתְבוּ לְמֵיכַל. אָמְרוּ, כָּל חַד וְחַד לֵימָא מִלֵּי דְּאוֹרַיְיתָא בְּהַאי סְעוּדָתָא, אָמַר רַבִּי יֵיסָא, סְעוּדַת עֲרַאי אִיהִי, וְעִם כָּל דָּא סְעוּדָה אִקְרֵי. וְלָא עוֹד, אֶלָּא דְּהַאי אִקְרֵי סְעוּדָתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְהֲנֵי מִינָּהּ. וְעַל דָּא כְּתִיב, (יחזקאל מ״א:כ״ב) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי יְיָ', דְּהָא מִלִּין דְּאוֹרַיְיתָא יִסְחֲרוּן לְהַאי אֲתָר.</p>"],[9520011744,"<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, (דברים ח׳:י׳) וְאָכַלְתָּ וְשָבָעְתָּ וּבֵרַכְתָּ אֶת יְיָ' אֱלֹהֶיךָ וְגוֹ'. וְכִי עַד לָא אָכִיל בַּר נָשׁ לְשַׂבְעָא, וְיִתְמְלֵי כְּרִיסֵיהּ, לָא יְבָרֵךְ לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, (ד\"א ל\"ג אי הכי) <Nonei></i>בְּמַאי נוֹקִים וְאָכַלְתָּ וְשָבָעְתָּ, וּבָתַר וּבֵרַכְתָּ. אֶלָּא אֲפִילּוּ לָא יֵיכוּל בַּר נָשׁ אֶלָּא כְּזַיִת, וּרְעוּתֵיהּ אִיהוּ עָלֵיהּ, וְיִשָׁוֵי לֵיהּ לְהַהוּא מֵיכְלָא עִקָרָא דְּמֵיכְלֵיהּ, שָׂבְעָא אִקְרֵי. דִּכְתִּיב, (תהילים קמ״ה:ט״ז) פּוֹתֵחַ אֶת יָדֶיךָ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן. לְכָל חַי אֲכִילָה לָא כְּתִיב, אֶלָּא רָצוֹן. הַהוּא רְעוּתָא דְּשַׁוֵּי עַל הַהוּא מֵיכְלָא, שָׂבְעָא אִקְרֵי, וַאֲפִילּוּ דְּלֵית קָמֵיהּ דְּבַר נָשׁ אֶלָּא הַהוּא זְעֵיר בִּכְזַיִת, וְלָא יַתִּיר הָא רְעוּתָא דְּשָׂבְעָא שַׁוֵּי עָלֵיהּ. וּבְגִין כַּךְ, וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן, רָצוֹן כְּתִיב, וְלָא אֲכִילָה. וְעַל דָּא וּבֵרַכְתָּ וַדַּאי, וְאִתְחַיָיב בַּר נָשׁ לְבָרְכָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין לְמֵיהַב חֶדְוָה לְעֵילָּא.</p>\n<p>פָּתַח רַבִּי חִזְקִיָּה, בְּהַאי קְרָא אֲבַתְרֵיהּ וְאָמַר, וְאָכַלְתָּ וְשבָעְתָּ. מֵהָכָא, דְּשִׁכּוֹר שָׁרֵי לֵיהּ לְבָרְכָא בִּרְכְתָא דִּמְזוֹנָא, (ויגש ר\"ז ע\"ב) מַה דְּלֵית הָכִי בִּצְלוֹתָא. דִּצְלוֹתָא לָאו הָכִי, דְּהָא צְלוֹתָא מָעַלְיָא בְּלָא אֲכִילָה אִיהִי, מַאי טַעֲמָא, בְּגִין דִּצְלוֹתָא סַלְּקָא לְעֵילָּא לְעֵילָּא, אֲתָר דְּלֵית בֵּיהּ לָא אֲכִילָה וְלָא שְׁתִיָּה. וְעַל דָּא תָּנִינָן, עָלְמָא דְּאָתֵי לֵית בֵּיהּ אֲכִילָה וּשְׁתִיָּה וְכוּ'.</p>\n<p>אֲבָל שְׁאַר דַּרְגִּין דִּלְתַתָּא אִית בְּבִרְכַּת מְזוֹנָא, אִשְׁתְּכַח גַּוְונָא אָחֳרָא וּמָעַלְיָא, הַהוּא בִּרְכְתָא דְּאִשְׁתְּכַח בְּשַׂבְעָא. בְּגִין דְּבִרְכַּת מְזוֹנָא, אִיהִי בַּאֲתָר דְּאִית בֵּיהּ אֲכִילָה וּשְׁתִיָּה, וּמִנֵּיהּ נָפַק מְזוֹנָא וְשַׂבְעָא לְתַתָּא, וְעַל דָּא אִצְטְרִיךְ לְאַחֲזָאָה קָמֵיהּ שָׂבְעָא וְחֶדְוָה. (ובגין כך האי איהו אתר דאית ביה אכילה ושתיה ומניה נפיק מזונא לתתא ואצטריך לאחזאה קמיה שבעא וחדוה) בַּאֲתָר דִּצְלוֹתָא, לָאו הָכִי, דְּהָא סַלְּקָא יַתִּיר לְעֵילָּא לְעֵילָּא וְעַל דָּא, שִׁכּוֹר לָא יִצְלֵי צְלוֹתָא.</p>\n<p>בְּבִרְכַּת מְזוֹנָא, שִׁכּוֹר שָׁרֵי לֵיהּ לְבָרְכָא בִּרְכַּת מְזוֹנָא. מַשְׁמַע מֵהַאי קְרָא, דִּכְתִּיב וְאָכַלְתָּ וְשָבָעְתָּ וּבֵרַכְתָּ. וְאָכַלְתָּ: זוֹ אֲכִילָה. וְשָׂבָעְתָּ: זוֹ שְׁתִיָּה דְּהָא שָׂבְעָא, בְּחַמְרָא אִיהִי רַוֵּי. חַמְרָא שָׂבְעָא וַדַּאי, וְדָא אִיהוּ שִׁכּוֹר. דִּכְתִּיב וּבֵרַכְתָּ אֶת דַּיְיקָא, דְּמַשְׁמַע דְּבִרְכַּת מְזוֹנָא אִצְטְרִיךְ חֶדְוָה וְשַׂבְעָא. עַל הָאָרֶץ הַטּוֹבָה. מַאי טוֹבָה. שָׂבְעָא. כְּמָה דְאַתְּ אָמֵר, (ירמיה מה) וַנִּשְׂבַּע לֶחֶם וַנִּהְיֶה טוֹבִים בְּגִין כַּךְ אִצְטְרִיךְ חֶדְוָה וְשַׂבְעָא.</p>"],[9520011745,"<p>פָּתַח רַבִּי יֵיסָא וְאָמַר (שמות כ״ה:כ״ג) וְעָשִׂיתָ שֻׁלְחָן עֲצֵי שִׁטִּים וְגוֹ', שֻׁלְחָן דָּא אִיהוּ קַיְּימָא לְגוֹ בְּמַשְׁכְּנָא. וּבִרְכְתָא דִּלְעֵילָּא שַׁרְיָא עָלֵיהּ, וּמִנֵּיהּ נָפִיק מְזוֹנָא לְכָל עָלְמָא. וְשֻׁלְחָן דָּא לָא אִצְטְרִיךְ לְמֶהֱוֵי בְּרֵיקַנְיָּא, אֲפִילּוּ רִגְעָא חֲדָא, אֶלָּא לְמֶהֱוֵי עָלֵיהּ מְזוֹנָא, דְּהָא בִּרְכְתָא לָא אִשְׁתְּכַח עַל אֲתָר רֵיקָנַיָּא. וּבְגִין כַּךְ אִצְטְרִיךְ לְמֶהוֵי עָלֵיהּ נַהֲמָא תָּדִיר, דְּלֶהוֵי תָּדִיר בִּרְכְתָא עִלָּאָה מִשְׁתַּכְּחָא בֵּיהּ, וּמִגּוֹ הַהוּא שֻׁלְחָן, נַפְקֵי בִּרְכָּאן וּמְזוֹנֵי לְכָל שְׁאַר פָּתוִֹרִי דְּעָלְמָא, דְּאִתְבָּרְכָאן בְּגִינֵיהּ.</p>\n<p>שֻׁלְחָן דְּכָל בַּר נָשׁ אִצְטְרִיךְ לְמֶהֱוֵי הָכִי קָמֵיהּ, בְּשַׁעֲתָא דְּקָא מְבָרַךְ לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּתִשְׁרֵי עָלֵיהּ בִּרְכְתָא מִלְּעֵילָּא, וְלָא יִתְחָזֵי בְּרֵיקַנְיָּא, דְּהָא בִּרְכָּאן דִּלְעֵילָּא לָא שַׁרְיָין בְּאֲתָר רֵיקָנַיָּא, דִּכְתִּיב, (מלכים ב ד׳:ב׳) הַגִּידִי לִי מַה יֶשׁ לָכְי בַּבָּיִת, וְהָא אוּקְמוּהָ חַבְרַיָּיא.</p>\n<p>שֻׁלְחָן דְּלָא אִתְּמַר עָלֵיהּ מִלֵּי דְּאוֹרַיְיתָא, (בס\"א אינו, ולא בריך על ההוא מזונא לקודשא בריך הוא) עָלֵיהּ כְּתִיב, (ישעיהו כ״ח:ח׳) כִּי כָּל שֻׁלְחָנוֹת מָלְאוּ קִיא צוֹאָה בְּלִי מָקוֹם. וְאָסוּר לְבָרְכָא עַל הַהוּא שֻׁלְחָן. מַאי טַעְמָא. בְּגִין דְּאִית שֻׁלְחָן, וְאִית שֻׁלְחָן. שֻׁלְחָן אִיהוּ דְּקָא מְסַדְּרָא קָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא לְעֵילָּא, וְאִיהוּ קַיְּימָא תָּדִיר לְסַדְּרָא בֵּיהּ פִּתְגָּמֵי אוֹרַיְיתָא, וּלְאַכְלְלָא בֵּיהּ אַתְוָון דְּמִלֵּי דְּאוֹרַיְיתָא, (בס\"א אינו, דא הוא ברכתא דמזונא, דאית פסוקי ומלי דאוריתא ואינון אתוון דמלי אורייתא אתכלילן ביה בההוא שלחן) וְאִיהוּ לָקִיט לוֹן לְגַבֵּיהּ, וְכָלִיל כֻּלְּהוּ בְּגַוֵּיהּ, וּבְהוּ אִשְׁתְּלִים, וְחַדֵּי, וְאִית לֵיהּ חֶדְוָה. וְעַל שֻׁלְחָן דָּא כְּתִיב, (יחזקאל מ״א:כ״ב) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי יְיָ', לִפְנֵי יְיָ', וְלָא (ק\"ב ע\"ב) מִלִפְנֵי יְיָ'.</p>\n<p>שֻׁלְחָן אָחֲרָא אִית, דְּלָא אִית בֵּיהּ חוּלָקָא דְּאוֹרַיְיתָא, וְלֵית לֵיהּ חוּלָקָא בִּקְדוּשָׁה דְּאוֹרַיְיתָא, וְהַהוּא שֻׁלְחָן אִקְרֵי קִיא צוֹאָה, וְדָא אִיהוּ בְּלִי <Nonei></i>מָקוֹם, דְּלֵית לֵיהּ חוּלָקָא בְּסִטְרָא דִּקְדוּשָׁה כְּלוּם. בְּגִין כַּךְ, שֻׁלְחָן דְּלָא אִתְּמַר עָלֵיהּ מִלֵּי דְּאוֹרַיְיתָא, אִיהוּ שֻׁלְחָן דְּקִיא צוֹאָה. אִיהוּ שֻׁלְחָן דְּטַעֲוָא אָחֲרָא. לֵית בְּהַהוּא שֻׁלְחָן חוּלָקָא בְּרָזָא דֶּאֱלָהָא עִלָּאָה.</p>\n<p>שֻׁלְחָן דְּמִלֵּי אוֹרַיְיתָא אִתְּמָרוּ עָלֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא נָטִיל הַהוּא שֻׁלְחָן, וְשַׁוִּי לֵיהּ לְחוּלְקֵיהּ. וְלָא עוֹד, (ר\"ג ע\"ד, רכ\"ג ע\"א) אֶלָּא סוּרְיָ\"א רַב מְמָנָא, נָטִיל כָּל אִינּוּן מִלִּין, וְשַׁוֵּי דִּיּוּקְנָא דְּהַהוּא שֻׁלְחָן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. וְכָל אִינּוּן מִלִּין דְּאוֹרַיְיתָא דְּאִתְמָרוּ עָלֵיהּ, סַלְּקִין עַל הַהוּא פָּתוֹרָא, וְאִתְעַטָּר (ס\"א ואתעתד) קָמֵי מַלְכָּא קַדִּישָׁא. מַשְׁמַע דִּכְתִּיב זֶה הַשֻׁלְחָן אֲשֶׁר לִפְנֵי יְיָ' דְּאִתְעַטָּר (ס\"א דאתעתד) קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. שֻׁלְחָן דְּבַר נָשׁ, קַיְּימָא לְדַכְּאָה לֵיהּ לְבַר נָשׁ, מִכָּל חוֹבוֹי. זַכָּאָה אִיהוּ, מַאן דְּאִלֵּין תְּרֵין קַיְימִין עַל פָּתוֹרֵיהּ. מִלֵּי דְּאוֹרַיְיתָא. וְחוּלָקָא לְמִסְכְּנִין, מֵהַהוּא שֻׁלְחָן.</p>\n<p>כַּד סַלְּקִין הַהוּא פָּתוֹרָא מִקָּמֵיהּ דְּבַר נָשׁ, תְּרֵין מַלְאָכִין קַדִּישִׁין אִזְדַּמְּנָן תַּמָּן, חַד מִימִינָא, וְחַד מִשְּׂמָאלָא. חַד אָמַר דָּא אִיהוּ שֻׁלְחָן דְּמַלְכָּא קַדִּישָׁא, דִּפְלַנְיָא קָא מְסַדֵּר קָמֵיהּ, מְסַדָּר יְהֵא תָּדִיר פָּתוֹרָא דָּא, בְּבִרְכָּאן עִלָאִין, וּמִשְׁחָא וּרְבוּ עִלָּאָה, קוּדְשָׁא בְּרִיךְ הוּא יִשְׁרֵי עֲלוֹי. וְחַד אָמַר, דָּא אִיהוּ שֻׁלְחָן דְּמַלְכָּא קַדִּישָׁא, דִּפְלַנְיָא קָא מְסַדֵּר קָמֵיהּ, דָּא פָּתוֹרָא דִּי עִלָּאֵי וְתַתָּאֵי יְבָרְכוּן לֵיהּ, מְסַדָּר יְהֵא הַאי פָּתוֹרָא קָמֵי עַתִּיק יוֹמִין, בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי.</p>\n<p>רִבִּי אַבָּא, כַּד הֲוָה סַלְּקִין פָּתוֹרָא מִקָמֵיהּ, הֲוָה חָפֵי לֵיהּ, וַהֲוָה אָמַר סְלִיקוּ הַאי פָּתוֹרָא בִּצְנִיעוּ, דְּלָא יְהֵא בְּכִסּוּפָא קָמֵי שְׁלוּחֵי מַלְכָּא. שֻׁלְחָן דְּבַר נָשׁ זָכֵי לֵיהּ לְעָלְמָא דְּאָתֵי, וְזָכֵי לֵיהּ לִמְזוֹנָא דְּהַאי עָלְמָא, וְזָכֵי לֵיהּ לְאִשְׁתְּמוֹדְעָא לְטָב קָמֵי עַתִּיק יוֹמִין, וְזָכֵי לֵיהּ לְאִתּוֹסְפָא חֵילָא וּרְבוּ בַּאֲתָר דְּאִצְטְרִיךְ. זַכָּאָה אִיהוּ חוּלָקֵיהּ דְּהַהוּא בַּר נָשׁ, בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי.</p>\n<p>רַבִּי יַעֲקֹב אָמַר, כְּתִיב (שמואל א י׳:י״א) וַיְהִי כָּל יוֹדְעוֹ מֵאִתְמוֹל שִׁלְשֹׁם וְגוֹ', הֲגַם שָׁאוּל בַּנְבִיאִים. וְכִי שָׁאוּל בְּחִיר יְיָ' מִקַּדְמַת דְּנָא הֲוָה, דִּכְתִּיב, (שמואל א י׳:י״א) הַרְאִיתֶם אֲשֶׁר בָּחַר בּוֹ יְיָ', אֲשֶׁר בּוֹחֵר בּוֹ לָא כְּתִיב, אֶלָּא אֲשֶׁר בָּחַר בּוֹ מִקַּדְמַת דְּנָא. וּבְשַׁעֲתָא דְּאָתָא וְעָאל בֵּין נְבִיאֵי וְאִתְנַבֵּי בֵּינַיְיהוּ, אֲמַאי תַּוְוהוּ.</p>\n<p>אֶלָּא, כַּד קוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בֵּיהּ, לָא אִתְרְעֵי בֵּיהּ אֶלָּא לְמַלְכוּ, אֲבָל לִנְבוּאָה לא. דְּהָא תְּרֵין אִלֵּין, לָא אִתְמְסָרוּ כַּחֲדָא בְּבַר נָשׁ בְּעָלְמָא, בַּר מִמֹּשֶׁה מְהֵימָנָא עִלָּאָה, דְּזָכָה לִנְבוּאָה ומַלְכוּ כַּחֲדָא, וְלָא אִתְיְיהִיב לְבַר נָשׁ אָחֲרָא תַּרְוַויְיהוּ כַּחֲדָא.</p>\n<p>וְאִי תֵּימָא, הָא שְׁמוּאֵל דְּזָכָה לְתַרְוַויְּיהוּ, לִנְבוּאָה ומַלְכוּ. לָאו הָכִי. לִנְבוּאָה זָכָה, דִּכְתִּיב, (שמואל א ג׳:כ׳) וַיֵּדַע כָּל יִשְׂרָאֵל מִדָּן וְעַד בְּאֵר שָׁבַע כִּי נְאֱמָן שְׁמוּאֵל לְנָבִיא. לְנָבִיא וְלָא לְמֶלֶךְ. נָבִיא וְדַיָּין הֲוָה, דְּאִי מֶלֶךְ הֲוָה, לָא שָׁאַלוּ יִשְׂרָאֵל מֶלֶךְ. אֲבָל אִיהוּ לָא הֲוָה אֶלָּא נְבִיאָה מְהֵימָנָא, וַהֲוָה דָּאִין דִּינֵהוֹן דְּיִשְׂרָאֵל, דִּכְתִּיב, (שמואל א ז) וְשָׁפַט אֶת יִשְׂרָאֵל. וְעַל דָּא כַּד הֲוָה שָׁאוּל בַּנְּבוּאָה, תַּוְוהוּ עָלֵיהּ.</p>\n<p>וְאִי תֵּימָא, אֲמַאי שָׁרָא עָלֵיהּ נְבוּאָה, הוֹאִיל וְזָכָה לְמַלְכוּ. אֶלָּא תַּרְוַויְיהוּ לָא זָכָה בְּהוּ כַּחֲדָא. (ובגין (נ\"א דנבואה) דמלכו יהיב ליה קודשא בריך הוא ואודי ליה עלה עד לא הוי מלכא) וּבְגִין דְּמַלְכוּ אִתְיָשָׁב עַל אַתְּעָרוּתָא דְּרוּחַ קֻדְשָׁא, הֲוָה בְּאִתְעָרוּ דִּנְבוּאָה קֹדֶם לָכֵן. אֲבָל כַּד סָלִיק לְמַלְכוּ, לָא הֲוָה בֵּיהּ נְבוּאָה, אֶלָּא אִתְּעָרוּ דְּרוּחַ סָכְלְתָנוּ, לְמֵידָן קְשׁוֹט, אִתְּעַר עָלֵיהּ, דְּהָכִי אִתְחָזֵי לְמַלְכָּא. וּבְעוֹד דְּהֲוָה גּוֹ אִינּוּן נְבִיאֵי, שָׁרָא עָלֵיהּ נְבוּאָה, לְבָתַר דְּאִתְפְּרַשׁ מִנַּיְיהוּ, לָא הֲוָה בֵּיהּ נְבוּאָה.</p>\n<p>וַאֲנָא, מַאן יָהִיב לִי אִתְעָרוּתָא דְּרוּחַ קֻדְשָׁא, לְמֶהֱוֵי בְּגוֹ נְבִיאֵי מְהֵימְנֵי, תַּלְמִידֵי דְּרִבִּי שִׁמְעוֹן בֶּן יוֹחָאי, דְּעִלָּאִין וְתַתָּאִין זָעִין מִנֵּיהּ, כָּל שֶׁכֵּן אֲנָא, לְמֶהוֵי בֵּינַיְיכוּ.</p>\n<p>פָּתַח וְאָמַר, וְעָשִׂיתָ (שמות כ״ה:כ״ג) שֻׁלְחָן וְגוֹ'. שֻׁלְחָן דָּא אִיהוּ לְתַתָּא, לְשַׁוָּאָה עָלֵיהּ לֶחֶם דְּאֲפָּיָא מַאן עָדִיף דָּא מִן דָּא, לֶחֶם אוֹ שֻׁלְחָן. אִי תֵּימָא דְּכֹלָּא <Nonei></i>אִיהוּ חַד. הָא (ס\"א אי תימא לחם עדיף דהא) שֻׁלְחָן מִתְסַדְרָא לְגַבֵּי הַהוּא לֶחֶם. וְתוּ, שֻׁלְחָן לְתַתָּא וְלֶחֶם עָלֵיהּ. לָאו הָכִי, אֶלָּא שֻׁלְחָן אִיהוּ עִקָּרָא, בְּסִדּוּרָא דִּילֵיהּ, לְקַבְּלָא בִּרְכָּאן דִּלְעֵילָּא וּמְזוֹנָא לְעָלְמָא. וּמֵרָזָא דְּהַאי שֻׁלְחָן, נָפִיק מְזוֹנָא לְעָלְמָא כְּמָה דְּאִתְיְהִיב בֵּיהּ מִלְּעֵילָּא.</p>\n<p>וְהַהוּא לֶחֶם, אִיהוּ אִיבָּא וּמְזוֹנָא דְּקָא נָפִיק מֵהַאי שֻׁלְחָן לְאַחֲזָאָה דְּהָא מִשֻׁלְחָן דָּא, נַפְקֵי פֵּרִין וְאִבִין וּמְזוֹנָא לְעָלְמָא. אִי לָא אִשְׁתְּכַח כֶּרֶם, עֲנָבִין דְּאִינּוּן אִיבָּא דְּנַפְקֵי מִנֵּיהּ, לָא יְהוֹן מִשְׁתַּכְּחִין. אִי אִילָנָא לָא יְהֵא, אִיבָּא לָא יִשְׁתְּכַּח בְּעָלְמָא, בְּגִין כַּךְ, שֻׁלְחָן אִיהוּ עִקָּרָא, מְזוֹנָא דְּנָפִיק מִנֵּיהּ, אִיהוּ הַהוּא לֶחֶם הַפָּנִים.</p>\n<p>וְכַהֲנֵי הֲווֹ לַקְטֵי אִיבָּא דְּשֻׁלְחָן מְעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת, (ד\"א משבת לשבת) לְאַחֲזָאָה דְּהָא מְזוֹנָא עִלָּאָה נָפִיק מִגּוֹ הַהוּא דְּשֻׁלְחָן. בְּגִין הַהוּא לֶחֶם דַּהֲווֹ לַקְטֵי כַּהֲנִי, אִתְבָּרְכָא כָּל מְזוֹנָא וּמְזוֹנָא דְּאַכְלֵי וְשָׁתָאן, דְּלָא לְקַטְרְגָא בְּהוּ יֵצֶר הָרָע, דְּהָא יֵצֶר הָרָע לָא אִשְׁתְּכַח, אֶלָּא מִגּוֹ מֵיכְלָא וּמִשְׁתְּיָּא. הֲדָא הוּא דִכְתִיב, (משלי ל׳:ט׳) פֶּן אֶשְׂבַּע וְכִחַשְׁתִּי וְגוֹ', דְּמִגּוֹ מֵיכְלָא וּמִשְׁתְּיָּא יֵצֶר הָרָע מִתְרַבֵּי בִּמְעוֹי דְּבַר נָשׁ.</p>\n<p>לֶחֶם דָּא, מְזוֹנָא דְּקָא נָפִיק מִגּוֹ שֻׁלְחָן, מְבָרֵךְ מְזוֹנָא דְּכַהֲנֵי, דְּלָא יִשְׁתְּכַּח בְּהוּ מְקַטְרְגָא לְקַטְרְגָא לוֹן, לְמִפְלַח בְּלִבָּא שְׁלִים לְקוּדְשָׁא בְּרִיךְ הוּא. וְדָא אִצְטְרִיךְ לְכַהֲנֵי יַתִּיר מִכָּל עָלְמָא. וּבְגִין כַּךְ, שֻׁלְחָן אִיהוּ עִקָּרָא, וְאִיבָּא וּמְזוֹנָא דְּקָא נָפִיק מִנֵּיהּ, אִיהוּ הַהוּא לֶחֶם.</p>\n<p>שֻׁלְחָן דָּא, אִצְטְרִיךְ סִדּוּרָא דִּילֵיהּ לְאִתְתָּקְנָא, בְּסִטְרָא דְּצָפוֹן, דִּכְתִּיב וְהַשֻּׁלְחָן תִתֵּן עַל צֶלַע צָפוֹן. מַאי טַעְמָא. בְּגִין דְּמִתַּמָּן שֵׁירוּתָא דְּחֶדְוָה. שְׂמָאלָא נָטִיל מִימִינָא תָּדִיר בְּקַדְמִיתָא, וּלְבָתַר אִיהוּ אִתְּעַר לְגַבֵּי נוּקְבָּא, וּבָתַר קָרִיבַת לֵיהּ יְמִינָא לְגַבֵּיהּ, וְאִתְדַּבְּקַת בֵּיהּ.</p>\n<p>מַיִם אִינּוּן מִימִינָא, וְאִיהוּ חֶדְוָה, מִיָּד יָהִיב לִשְׂמָאלָא, וְאִתְדָּבָּקוּ בֵּיהּ אִינּוּן מַיִם, וְחַדָּאן לֵיהּ. וּבָתַר אִתְכְּלִיל אִיהוּ לִימִינָא, וְאִתְּעַר לְנוּקְבָּא בְּהַהוּא חֶדְוָה. וְסִימָנָךְ, מַאן דְּנָטִיל מַיָּא בִּידֵיהּ יְמִינָא בְּמָאנָא, קַדְמָאָה לְאַרְקָא מַיָּא בִּשְׂמָאלָא אִיהוּ, וְלָא מִשְּׂמָאלָא לִימִינָא, דְּהָא מַיָּא מִימִינָא נָטִיל לוֹן שְׂמָאלָא.</p>\n<p>וּבְּגִין כָּךְ מַיָּא לָא אִשְׁתְּכָחוּ, אֶלָּא מִסִּטְרָא דִּשְׂמָאלָא. כֵּיוָן דְּנָטִילוּ מַיָּא לְגַבֵּיהּ, הָא אִתְּעָרוּ לְגַבֵּי נוּקְבָּא בְּאִינּוּן מַיִם. וְעַל דָּא גְּבוּרוֹת גְּשָׁמִים תָּנִינָן. וּבְגִין כַּךְ וְהַשֻּׁלְחָן תִתֵּן עַל צֶלַע צָפוֹן, דְּמֵהַהוּא סְטָר אִיבִין אִשְׁתְּכָחוּ בֵּיהּ יַתִּיר, מִסִּטְרָא אָחֳרָא. בְּאִתְעָרוּ דְּחֶדְוָה דִּילֵיהּ בְּקַדְמִיתָא, כְּמָה דְאַתְּ אָמֵר (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי לְבָתַר וִימִינוֹ תְּחַבְּקֵנִי.</p>\n<p>שֻׁלְחָן דְּבַר נָשׁ אִצְטְרִיךְ לְאִשְׁתַּכְּחָא בִּנְקִיוּתָא דְּגוּפָא, דְּלָא יִתְקָרֵב לְמֵיכַל מְזוֹנָא דִּילֵיהּ, אֶלָּא בִּנְקִיוּתָא דְּגַרְמֵיהּ. וְעַל דָּא אִצְטְרִיךְ בַּר נָשׁ, לְפַנָּאָה גַּרְמֵיהּ בְּקַדְמִיתָא, עַד לָא יֵיכוּל מְזוֹנָא דְּשֻׁלְחָנָא דַּכְיָא, דְּהַהוּא מְזוֹנָא דְּאַתְקִין לֵיהּ, בֵּיהּ אִתְרְעֵי קוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּלָא יִתְקָרֵב עַל הַהוּא שֻׁלְחָן קִיא צוֹאָה, דְּאִיהוּ מֵרָזָא דְּסִטְרָא אַחֲרָא וְסִטְרָא אַחֲרָא לָא יְקַבֵּל מֵהַהוּא מְזוֹנָא דְּשֻׁלְחָן דָּא כְּלוּם.</p>\n<p>לְבָתַר דְּאָכִיל בַּר נָשׁ, וְאִתְעַנָּג, אִצְטְרִיךְ לְמֵיהַב חוּלָקָא דְּתַמְצִית לְהַהוּא סִטְרָא. וּמַאן אִיהוּ. מַיִם אַחֲרוֹנִים. הַהוּא זוּהֲמָא דְּיָדִין, דְּאִצְטְרִיךְ לְמֵיהַב לְהַהוּא סִטְרָא, חוּלָקָא דְּאִצְטְרִיךְ לֵיהּ. וְעַל דָּא וַדַּאי אִינּוּן חוֹבָה, חוֹבָה אִינּוּן, וּבַאֲתָר דְּחוֹבָה שַׁרְיָין. וְאִיהוּ חִיוּבָא עַל בַּר נָשׁ, לְמֵיהַב לֵיהּ חוּלָקָא דָּא. וְעַל דָּא לָא אִצְטְרִיךְ לְבָרְכָא כְּלַל, דְּהָא בְּרָכָה לָאו אִיהוּ בְּהַהוּא סִטְרָא.</p>\n<p>וּבְגִין כַּךְ אִצְטְרִיךְ בַּר נָשׁ, דְּלָא יָהִיב מְזוֹנָא דְעַל גַּבֵּי פָּתוֹרֵיהּ, לְהַהוּא קִיא צוֹאָה, וְכָּל שֶׁכֵּן בְּמֵעוֹי, וְכָּל שֶׁכֵּן דְּאִיהוּ דַּכְיוּ (טב) לְבַר נָשׁ וּבְרִיאוּ וְתִקּוּנָא דְּגוּפֵיהּ. וְעַל דָּא, שֻׁלְחָן אִיהוּ לְמֵיכַל בֵּיהּ בְּדַכְיוּ, כְּמָה דְּאִתְּמַר.</p>\n<p>שֻׁלְחָן דָּא דְּקַיְּימָא בְּבֵי מַקְדְּשָׁא, בְּגִין לְאִשְׁתַּכְּחָא בֵּיהּ מְזוֹנָא, וּלְאַפָּקָא מִנֵּיהּ מְזוֹנָא, וְעַל דָּא אֲפִילּוּ <Nonei></i>רִגְעָא חֲדָא, לָא (קל\"ו ע\"א) אִצְטְרִיךְ לְקַיְּימָא בְּרֵיקָנַיָּא. שֻׁלְחָן אָחֳרָא, אִיהוּ שֻׁלְחָן דְּרֵיקָנַיָּא, וְלָא אִצְטְרִיךְ לְמֵיהַב לֵיהּ דּוּכְתָּא בַּאֲתָר קַדִּישָׁא. וְעַל דָּא, שֻׁלְחָן דְּמַקְדְּשָׁא, אֲפִילּוּ רִגְעָא חֲדָא לָא יָתִיב בְּלָא מְזוֹנָא. וְיִצְטְרִיךְ דְּלָא יִשְׁתְּכַּח אֲתָר גְּרִיעָ, דְּהָא בִּרְכְּתָא דִּלְעֵילָּא לָא מִשְׁתַּכְּחָא בַּאֲתָר גְּרִיעָ, דָּא שֻׁלְחָן דְּקָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא. שֻׁלְחָן דְּבַר נָשׁ דְּקָא מְבָרָךְ עָלֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, אוּף הָכִי לָא אִצְטְרִיךְ לְמֶהוֵי בְּרֵיקָנַיָּא, דְּהָא לֵית בִּרְכְּתָא בַּאֲתָר רֵיקָנַיָּא.</p>\n<p>נָהֲמֵי דְּעַל גַּבֵּי שֻׁלְחָן דְּקוּדְשָׁא בְּרִיךְ הוּא, אִינּוּן תְּרֵיסַר. וְהָא אוֹקִימְנָא רָזָא דְּנָהֲמֵי, דְּאִינּוּן רָזָא דְּפָּנִים. וְעַל דָּא אִקְרֵי לֶחֶם הַפָּנִים, דְּהָא מְזוֹנָא וְסִפּוּקָא דְּעָלְמָא, מֵאִינּוּן פָּנִים עִלָּאִין קָאַתְיָיא. וּבְגִין כַּךְ, לֶחֶם דָּא, אִיהוּ פְּנִימָאָה דְּכֹלָּא, אִיהוּ בְּרָזָא עִלָּאָה, כְּדְקָא יֵאוֹת.</p>\n<p>לֶחֶם הַפָּנִים, מֵיכְלָא דְּאִינּוּן פָּנִים, מְזוֹנָא וְסִפּוּקָא דְּנָפִיק לְעָלְמָא, מִנַּיְיהוּ אָתֵי, וְשַׁרְיָא עַל הַהוּא פָּתוֹרָא, וּבְגִין דְּשֻׁלְחָן דָּא, מְקַבְּלָא מְזוֹנָא וְסִפּוּקָא מֵאִינּוּן פָּנִים דִּלְעֵילָּא, וְאִיהִי אַפִּיקַת מְזוֹנִין וְסִפּוּקִין מֵאִינּוּן פָּנִים פְּנִימָאִין, וּמְזוֹנָא דְּאַפִּיקַת, אִיהוּ הַהוּא לֶחֶם, כִּדְקָאמָרָן, חוֹם הֲוָה מִתְקָרֵב, וְחוֹם הֲוָה מִתְעֲדֵי מִתַּמָּן, וְהָא אוּקְמוּהָ, דִּכְתִּיב, (שמואל א כ״א:ז׳) בְּיוֹם הִלָּקְחוֹ וּבְגִין שֻׁלְחָן דָּא אִית לְבַר נָשׁ לְנַטְרָא רָזִין דְּשֻׁלְחָן דִּילֵּיהּ בְּכָל אִינּוּן גַּוְונִין כִּדְקָאמָרָן.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (קהלת ט׳:ח׳) בְּכָל עֵת יִהְיוּ בְגָדֶיךָ לְבָנִים וְשֶׁמֶן עַל רֹאשְׁךָ אַל יֶחְסָר. הַאי קְרָא אוּקְמוּהָ וְאִתְּמַר, אֲבָל תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא בָּרָא לֵיהּ לְבַר נָשׁ בְּרָזָא דְּחָכְמְתָא, וְעָבִיד לֵיהּ בְּאוּמְנוּתָא סַגִּי, וְנָפַח בְּאַפּוֹי נִשְׁמְתָא דְּחַיֵּי, לְמִנְדַּע וּלְאִסְתַּכְּלָא בְּרָזִין דְּחָכְמְתָא, לְמִנְדַּע בִּיקָרָא דְּמָארֵיהּ, כְּמָה דְאַתְּ אָמֵר, (ישעיהו מ״ג:ז׳) כֹּל הַנִּקְרָא בִשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו. וְלִכְבוֹדִי בְּרָאתִיו דַּיְיקָא, וְרָזָא דָּא וְלִכְבוֹדִי בְּרָאתִיו אוֹלִיפְנָא, דְּהָא כָּבוֹד דִּלְתַתָּא רָזָא דְּכוּרְסְיָּיא קַדִּישָׁא לָא (נח נ\"ח ע\"ב) אִתְתָּקַּן לְעֵילָּא, אֶלָּא מִגּוֹ תִּקּוּנָא דִּבְנֵי עָלְמָא.</p>\n<p>כַּד אִינּוּן בְּנֵי נָשָׁא, זַכָּאִין וַחֲסִידִין, וְיַדְעֵי לְתַקְּנָא תִּקּוּנֵי, הֲדָא הוּא דִכְתִיב וְלִכְבוֹדִי בְּרָאתִיו. בְּגִין דְּהַאי כְבוֹדִי, לְתַקְּנָא לֵיהּ בְּעַמוּדִין תַּקִּיפִין, וּלְקַשְׁטָא לֵיהּ בְּתִקּוּנָא וְקִשׁוּטָא דִּלְתַתָּא, בְּגִין דְּהַאי כְבוֹדִי יִסְתָּלַּק, (ביקרא) בִּזְכוּ דְּצַדִּיקַיָּא דִּי בְּאַרְעָא.</p>\n<p>בְּגִין כַּךְ בְּרָאתִיו. כְּגַוְונָא דְּכָבוֹד עִלָּאָה, דְּתִקוּנִין אִלֵּין בֵּיהּ. (צ\"ע ועיין ר\"ח ע\"א, קצ\"ח ע\"ב) בְּרִיאָה לִסְטַר שְׂמָאלָא יְצִירָה בִּימִינָא כְּמָה דְאַתְּ אָמֵר יוֹצֵר אוֹר וּבּוֹרֵא חֹשֶׁךְ עֲשִׂיָּה בְּאֶמְצָעִיתָא כְּמָה דְאַתְּ אָמֵר אֲנִי יְיָ עֹשֶׂה כָּל וּכְתִיב וּכְתִיב עוֹשֶׂה שָׁלוֹם וּבּוֹרֵא רַע וּכְתִיב עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו וְעַל דָא בְּרָאתִיו יְּצָרְתִיו אַף עֲשִׂיתִּיו כְּתִקּוּנָא עִילָאָה. וְעַל דָּא, הוֹאִיל וְאָדָם אִיהוּ בְּאַרְעָא, וְאִית לֵיהּ לְתַקְּנָא הַהוּא כְבוֹדִי עֲבָדִית בֵּיהּ תִּקּוּנִין דְּכָבוֹד עִלָּאָה, דְּאִית בֵּיהּ אוּף הָכִי בְּרִיאָה, וְעַל דָּא בְּרָאתִיו.</p>\n<p>בְּהַהוּא כָּבוֹד עִלָּאָה, אִית בֵּיהּ יְצִירָה, וְעַל דָּא יְצַרְתִּיו, תִּקּוּנָא דָּא יָהַבִית בֵּיהּ בָּאָדָם, לְמֶהֱוֵי אִיהוּ בְּאַרְעָא, כְּגַוְונָא דְּהַהוּא כָּבוֹד עִלָּאָה. בְּהַהוּא כָּבוֹד עִלָּאָה, אִית בֵּיהּ עֲשִׂיָּיה, וְעַל דָּא אוּף הָכִי בְּבַר נָשׁ, כְּתִיב עֲשִׂיתִיו, לְמֶהֱוֵי אִיהוּ כְּגַוְונָא דְּהַהוּא כָּבוֹד עִלָּאָה, דִּמְתַקֵן וּבָרִיךְ לִכְבוֹד תַּתָּאָה.</p>\n<p>מְנָלָן, דְּהַהוּא כָּבוֹד עִלָּאָה אִית בֵּיהּ תְּלַת אִלֵּין. דִּכְתִּיב בֵּיהּ, יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ עוֹשֶׂה שָׁלוֹם. יוֹצֵר אוֹר, הָא יְצִירָה. וּבוֹרֵא חֹשֶׁךְ, הָא בְּרִיאָה. עוֹשֶׂה שָׁלוֹם הָא עֲשִׂיָּה. וְדָא אִיהוּ כָּבוֹד עִלָּאָה, דְּקָא מְתַקֵּן וּבָרִיךְ וְסָפִּיק בְּכָל צְרָכָיו לִכְבוֹד תַּתָּאָה.</p>\n<p>כְּגַוְונָא דָּא, בָּרָא אָדָם בְּאַרְעָא, דְּאִיהוּ כְּגַוְונָא דְּהַהוּא כָּבוֹד עִלָּאָה, לְתַקְּנָא לְהַאי כָּבוֹד, וּלְאִתְכַּלְלָא מִכָּל סִטְרִין. כָּבוֹד עִלָּאָה אִית בֵּיהּ תְּלַת אִלֵּין, אָדָם לְתַתָּא אִית בֵּיהּ תְּלַת אִלֵּין. וּלְאִתְכַּלְלָא הַהוּא כָּבוֹד תַּתָּאָה, מֵעֵילָּא וּמִתַּתָּא, לְמֶהֱוֵי שְׁלִים בְּכָל סִטְרִין. זַכָּאָה אִיהוּ בַּר נָשׁ, דְּזָכֵי בְּעוֹבָדוֹי לְמֶהֱוֵי כְּגַוְונָא דָּא. וְעַל דָּא כְּתִיב, (קהלת ט׳:ח׳) בְּכָל עֵת יִהְיוּ בְגָדֶיךָ לְבָנִים וְשֶׁמֶן עַל רֹאשְׁךָ אַל יֶחְסָר.</p>\n<p>מַה לִכְבוֹד עִלָּאָה, הַהוּא מִשְׁחָא רְבוּת קֻדְשָׁא לָא אִתְמָנַּע מִנֵּיהּ, מֵרָזָא דְּעָלְמָא דְּאָתֵי. אוּף הָכִי לְבַר נָשׁ, דְּעוֹבָדוֹי מִתְלַבְּנָן תָּדִיר, הַהוּא <Nonei></i>מְשַׁךְ רְבוּת קֻדְשָׁא, לָא יִתְמְנַע מִנֵּיהּ תָּדִיר.</p>\n<p>בְּמָאי זָכֵי בַּר נָשׁ, לְאִתְעַדְנָא בְּהַהוּא עִדּוּנָא עִלָּאָה. בְּשֻׁלְחָן דִּילֵיהּ. כְּמָה דְּאִיהוּ מְעַדֵן עַל פָּתוֹרֵיהּ נַפְשָׁאן דְּמִסְכְּנֵי, דִּכְתִּיב, (ישעיהו נ״ח:י׳) וְנֶפֶשׁ נַעֲנָה תַּשְׂבִּיעַ, מָה כְּתִיב בַּתְרֵיהּ, אָז תִּתְעַנַּג עַל יְיָ' וְגוֹ', דְּאוֹף הָכִי קוּדְשָׁא בְּרִיךְ הוּא רַוֵי לֵיהּ, בְּכָל אִינּוּן עִדּוּנִין דִּמְשַׁח רְבוּת קוּדְשָׁא עִלָּאָה, דְּנָגִיד וְאִתְמְשַׁךְ תָּדִיר לְהַהוּא כָּבוֹד עִלָּאָה, כְּתִיב וְנֶפֶשׁ נַעֲנָה תַּשְׂבִּיעַ, מַה כְּתִיב בַּתְרֵיהּ, אָז תִּתְעַנַּג עַל יְיָ'.</p>"],[9520011746,"<p>רִבִּי יוֹסִי וְרִבִּי חִיָּיא הֲוָה אַזְלֵי בְּאוֹרְחָא, וַהֲוָה חַד טַיְּיעָא טָעִין אֲבַתְרַיְיהוּ, אָמַר רִבִּי יוֹסִי לְרַ' חִיָּיא, אִית לָן לְאִתְעַסְּקָא וּלְאִשְׁתַּדְּלָא בְּמִלֵּי דְּאוֹרַיְיתָא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אָזִיל לְקַמָּן, (נ\"א דהא שכינתא אזלא קמן דכתיב (תהילים פ\"ה) צדק לפניו יהלך) וְעַל דָּא עִידָּן הוּא, לְמֶעְבַּד לֵיהּ (נ\"א לה) תִּקּוּנָא בַּהֲדָן בְּהַאי אָרְחָא.</p>\n<p>פָּתַח רַבִּי חִיָּיא וְאָמַר (תהילים קי״ט:קכ״ו) עֵת (בראשית קנ\"ו ע\"ב) לַעֲשׂוֹת לַיְיָ' הֵפֵרוּ תּוֹרָתֶךָ, הַאי קְרָא אִתְּמַר, וְאוּקְמוּהָ חַבְרַיָּיא. אֲבָל עֵת לַעֲשׂוֹת לַיְיָ', בְּכָל זִמְנָא דְּאוֹרַיְיתָא מִתְקַיְּימָא בְּעָלְמָא, וּבְנֵי נָשָׁא מִשְׁתַּדְלָן בָּהּ, כִּבְיָכוֹל, קוּדְשָׁא בְּרִיךְ הוּא חַדֵּי בְּעוֹבְדֵי יְדוֹי, וְחַדֵּי בְּעָלְמִין כֻּלְּהוּ, וּשְׁמַיָא וְאַרְעָא קַיְימֵי בְּקִיוּמַיְיהוּ. וְלָא עוֹד, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא כָּנִישׁ כָּל פָּמַלְיָא דִּילֵיהּ, וְאָמַר לוֹן, חָמוּ עַמָּא קַדִּישָׁא דְּאִית לִי בְּאַרְעָא, דְּאוֹרַיְיתִי מִתְעַטְּרָא בְּגִינֵיהוֹן. חָמוּ עוֹבְדֵי יְדַי, דְּאָתוּן אֲמַרְתּוּן (תהילים ח׳:ה׳) מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ. וְאִינּוּן כַּד חֲמָאן חֶדְוָה דְּמָארֵיהוֹן בְּעַמֵיהּ, מִיָּד פַּתְחֵי וְאַמְרֵי, (שמואל ב ז׳:כ״ג) וּמִי כְעַמְּךָ כְּיִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ.</p>\n<p>וּבְשַׁעֲתָא דְּיִשְׂרָאֵל מִתְבַּטְלֵי מֵאוֹרַיְיתָא, כִּבְיָכוֹ\"ל, תָּשַׁשׁ חֵילֵיהּ, דִּכְתִּיב, (דברים ל״ב:י״ח) צוּר יְלָדְךָ תֶּשִׁי. וּכְדֵין כְּתִיב, (דברי הימים ב י״ח:י״ח) וְכָל צְבָא הַשָּׁמַיִם עוֹמְדִים עָלָיו, וְעַל דָּא עֵת לַעֲשׂוֹת לַיְיָ', אִינּוּן (בני עלמא) צַדִּיקַיָּיא דְּאִשְׁתָּאֲרָן, אִית לוֹן לְחַגְרָא חַרְצִין, וּלְמֶעְבַּד עוֹבָדִין דְּכַשְׁרָאן, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא יִתְתָּקַף בְּהוּ בְּצַדִּיקַיָּיא, וּמַשְׁרְיָין וְאוֹכְלֹסִין דִּילֵיהּ. מַאי טַעְמָא. בְּגִין דְּהֵפֵרוּ תּוֹרָתֶךָ, וְלָא מִשְׁתַּדְּלֵי בָּהּ בְּנִי עָלְמָא, כְּדְקָא יֵאוֹת.</p>\n<p>הַהוּא טַיְּיעָא דְּהֲוָה טָעִין אֲבַתְרַיְיהוּ, אָמַר לוֹן בְּמָטוּ מִנַּיְיכוּ, שְׁאֶלְתָּא חֲדָא בָּעֵינָא לְמִנְדַּע. אָמַר רַבִּי יוֹסִי, וַדַּאי אָרְחָא מִתְתַּקְנָא קָמָּן, שָׁאִיל שְׁאֶלְתָּךְ. אָמַר, הַאי קְרָא, אִי כְּתִיב יֵשׁ לַעֲשׂוֹת, אוֹ נַעֲשֶׂה, הֲוָה אֲמֵינָא הָכִי. מַאי עֵת. וְתוּ, לַעֲשׂוֹת לַיְיָ', לִפְנֵי יְיָ' אִצְטְרִיךְ, מַאי לַעֲשׂוֹת לַיְיָ'. אָמַר רַבִּי יוֹסִי, בְּכַמָּה גַּוְונִין אָרְחָא מִתְתַּקְנָא קָמָּן. חַד, דַּהֲוֵינָן תְּרֵין, וְהַשְּׁתָּא הָא אֲנָן תְּלָתָא, וּשְׁכִינְתָּא אִתְכְּלִילַת בַּהֲדָן. וְחַד דַּחֲשִׁיבְנָא דְּלָא הֲוֵית אֶלָּא כְּאִילָנָא יַבֶּשְׁתָּא, וְאַנְתְּ רַעֲנָנָא כְּזֵיתָא. וְחַד, דְּיֵאוֹת שָׁאַלְתָּ, וְהוֹאִיל וְשָׁרִית מִלָּה, אֵימָא.</p>\n<p>פָּתַח וְאָמַר עֵת לַעֲשׂוֹת לַיְיָ' הֵפֵרוּ תּוֹרָתֶךָ. עֵת לַעֲשׂוֹת לַיְיָ', אִית עֵת. וְאִית עֵת. (קהלת ג׳:ח׳) עֵת לֶאֱהֹב וְעֵת לִשְׂנֹא. עֵת אִיהוּ לְעֵילָּא. דְּהַהוּא עֵת, רָזָא דִּמְהֵימְנוּתָא אִיהוּ. וְדָא אִקְרֵי עֵת רָצוֹן, וְהַאי אִיהוּ דְּאִתְחַיָּיב בַּר נָשׁ לְמִרְחַם לַיְיָ' תָּדִיר, כְּמָה דְאַתְּ אָמֵר (דברים ו׳:ה׳) וְאָהַבְתָּ אֶת יְיָ' אֱלהֶיךָ, וְעַל דָּא, עֵת לֶאֱהֹב, דָּא אִיהוּ עֵת דְּאִתְחַיָּיב בַּר נָשׁ לֶאֱהֹב.</p>\n<p>וְאִית עֵת אָחֳרָא, דְּאִיהוּ רָזָא דֶּאֱלֹהִים אֲחֵרִים, וְאִתְחַיָיב בַּר נָשׁ לְמִשְׂנָא לֵיהּ, וְלָא יִתְמְשַׁךְ לִבֵּיהּ אֲבַתְרִיהּ, וְעַל דָּא עֵת לִשְׂנֹא, וּבְגִין כַּךְ כְּתִיב (ויקרא ט״ז:ב׳) דַּבֵּר אֶל אַהֲרֹן אָחִיךָ וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ.</p>\n<p>(והכא) בְּזִמְנָא דְּיִשְׂרָאֵל מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וּפִקוּדֵי אוֹרַיְיתָא, הַהוּא עֵת רָזָא דִּמְהֵימְנוּתָא קַדִּישָׁא, מִתַּתְקְנָא בְּתִקּוּנָהָא, וּמִתְקַשְּׁטָא בִּשְׁלֵימוּתָא, כְּדְקָא יֵאוֹת. וּבְזִמְנָא דְּיִשְׂרָאֵל מִתְבַּטְלֵי מֵאוֹרַיְיתָא, כִּבְיָכוֹל הַהוּא עֵת, לָאו אִיהוּ בְּתִקּוּנָהָא, וְלָא אִשְׁתְּכַחַת בִּשְׁלִימוּ, וְלָא בִּנְהוֹרָא וּכְדֵין עֵת לַעֲשׂוֹת לַיְיָ'.</p>\n<p>מַאי לַעֲשׂוֹת. כְּמָה דְאַתְּ אָמֵר (בראשית ב׳:ג׳) אֲשֶׁר בָּרָא אֱלהִים לַעֲשׂוֹת. מַאי לַעֲשׂוֹת. דְּאִשְׁתָּאָרוּ גּוּפֵי דְּשֵׁידֵי, דְּאִתְקַדָּשׁ יוֹמָא, וְלָא אִתְעָבִידוּ, וְאִשְׁתָּאָרוּ לַעֲשׂוֹת, רוּחִין בְּלָא גּוּפֵי. אוּף הָכָא עֵת לַעֲשׂוֹת, אִשְׁתְּאַר בְּלָא תִּקּוּנָא, וּבְלָא שְׁלִימוּ. מַאי טַעְמָא. מִשּׁוּם דְּהֵפֵרוּ תּוֹרָתֶךָ, בְּגִין דְּאִתְבָּטְלוּ יִשְׂרָאֵל לְתַתָּא מִפִּתְגָּמֵי אוֹרַיְיתָא. בְּגִין דְּהַהוּא עֵת, הָכִי קַיְּימָא, אוֹ סַלְּקָא, אוֹ נַחְתָּא, בְּגִינֵיהוֹן דְּיִשְׂרָאֵל.</p>\n<p>אָתוּ רִבִּי יוֹסִי וְרַבִּי <Nonei></i>חִיָּיא וּנְשָׁקוּהוּ בְּרֵישֵׁיהּ. אָמַר רִבִּי יוֹסִי, וַדַּאי לֵית אַנְתְּ כְּדַאי, לְטַיְיעָא אֲבַתְרָן. זַכָּאָה אָרְחָא דָּא, דְּזָכֵינָן לְמִשְׁמַע דָּא, זַכָּאָה דָּרָא דְּרַבִּי שִׁמְעוֹן שָׁארֵי בְּגַוֵּיהּ, דְּאֲפִילּוּ בֵּינֵי טוּרַיָא, חָכְמְתָא אִשְׁתְּכַחַת תַּמָּן. נָחְתוּ רַבִּי יוֹסִי וְרַבִּי חִיָּיא, וְאָזְלוּ תְּלָתְהוֹן בְּאָרְחָא.</p>"],[9520011747,"<p>פָּתַח הַהוּא טַיְיעָא וְאָמַר (תהילים ס״ט:י״ד) וַאֲנִי תְפִלָּתִי לְךָ יְיָ' עֵת רָצוֹן אֱלהִים בְּרָב חַסְדֶּךָ עֲנִנִי בֶּאֱמֶת יִשְׁעֶךָ, תָּנֵינָן, אֵימָתַי אִקְרֵי עֵת רָצוֹן. בְּשַׁעֲתָא דְּצִבּוּר קָא מְצַלָאן. שַׁפִּיר אִיהוּ, וְהָכִי אִיהוּ וַדַּאי. דְּהָא כְּדֵין צִבּוּרָא מְסַדְּרֵי וּמְתַקְּנִי תִּקּוּנָא דְּהַאי עֵת, וּכְדֵין אִיהוּ עֵת רָצוֹן, וְאִצְטְרִיךְ לְמִשְׁאַל שְׁאֶלְתָּא, דִּכְתִּיב אֱלהִים בְּרָב חַסְדֶּךָ עֲנֵנִי בֶּאֱמֶת יִשְׁעֶךָ דְּהָא כְּדֵין אִצְטְרִיךְ לְמִשְׁאַל שְׁאֶלְתָּא. וַאֲנִי תְפִלָּתִי לְךָ יְיָ', הָא הָכָא רָזָא דְּיִחוּדָא.</p>\n<p>וַאֲנִי: דָּא דָּוִד מַלְכָּא, (אמור צ\"ה ע\"ב) אֲתָר דְּאִקְרֵי גְּאוּלָה. תְפִלָּתִי: דָּא תְּפִלָּה. וְהָכָא אִיהוּ סְמִיכָא לִגְּאוּלָה, דְּאִיהוּ חַד. כַּד אִיהוּ סָמִיךְ גְּאוּלָה לִתְפִלָּה, כְּדֵין אִיהוּ עֵת (ר\"ה) רָצוֹן. עֵת רָצוֹן: אוּף הָכִי, כְּלָלָא אִיהוּ כַּחֲדָא, עֵת חַד, רָצוֹן חַד, אִתְכְּלִילוּ דָּא בְּדָא, וַהֲווּ חַד. וְדָוִד מַלְכָּא בָּעָא לְיַחֲדָא בְּהַאי קְרָא, יִחוּדָא חֲדָא.</p>\n<p>וְאִי תֵּימָא, אֲמַאי אִתְמָנֵי הַאי קְרָא, בִּצְלוֹתָא דְּמִנְחָה דְּשַׁבָּת. יֵאוֹת אִיהוּ לְמֶהֱוֵי בְּשַׁבָּת בְּהַהוּא צְלוֹתָא דְּמִנְחָה, וְלָא בִּצְלוֹתָא דְּחוֹל, דְּוַדַּאי לָאו צְלוֹתָא דְּמִנְחָה דְּשַׁבָּת כְּחוֹל. בְּגִין דְּהָא בְּחוֹל בְּשַׁעֲתָא דְּמִנְחָה, (פ\"ח ע\"ב) תַּלְיָא דִּינָא בְּעָלְמָא, וְלָאו אִיהוּ עֵת רָצוֹן. אֲבָל בְּשַׁבָּת, דְּכָל רוּגְזָא אִתְעָדֵי, וְכֹלָּא אִתְכְּלִיל כַּחֲדָא, וְאַף עַל גַּב דְּדִינָא אִתְּעַר, אִתְבַּסְמוּתָא אִיהוּ, וְעַל דָּא אִצְטְרִיךְ קְרָא דְּיִחוּדָא, לְיַחֲדָא כָּל דַּרְגִּין, דְּכַד הֲוֵי יִחוּדָא, דִּינָא אִתְחֲבָּר וְאִתְכְּלִיל בְּרַחֲמֵי, וְאִתְבָּסַּם כֹּלָּא, וּכְדֵין עֵת רָצוֹן כְּתִיב. עֵת רָצוֹן, כָּלִיל כֹּלָּא כַּחֲדָא. וְדִינָא אִתְבְּסָם בְּהַהוּא זִמְנָא, וַהֲוֵי חֶדְוָה בְּכֹלָּא.</p>\n<p>מֹשֶׁה אִסְתַּלָּק מֵעָלְמָא, בְּהַהוּא שַׁעֲתָא דִּצְלוֹתָא דְּמִנְחָה דְּשַׁבָּת, בְּשַׁעֲתָא דְּעֵת רָצוֹן אִשְׁתְּכַח. וּבְהַהִיא שַׁעֲתָא רַעֲוָא הֲוָה לְעֵילָּא, וְצַעֲרָא לְתַתָּא, וְעַל דָּא נִנְעָלוּ תַּרְעִין בְּשַׁבָּת, מִשַׁעֲתָא דְּמִנְחָה וּלְעֵילָּא. מַאן תַּרְעִין נִנְעָלוּ. תַּרְעִין דְּבֵי מִדְרָשָׁא, בְּגִין לְאַדְכְּרָא לְמֹשֶׁה רַעְיָא מְהֵימָנָא, דְּאוֹרַיְיתָא אִתְבַּטְלָא בְּגִינֵיהּ.</p>\n<p>בְּהַהוּא זִמְנָא, בֵּי מִדְרָשָׁא דְּמֹשֶׁה אִתְבְּטִיל, כָּל שֶׁכֵּן אַחֲרָנִין. מַאן חָמֵי תַּרְעִין דְּבֵי מִדְרָשָׁא דְּמֹשֶׁה דְּנִנְעָלוּ, דְּלָא נִנְעָלוּ אַחֲרָנִין כֻּלְּהוּ. אוֹרַיְיתָא דְּמֹשֶׁה עֲצִיבָא עָלֵיהּ בְּהַהוּא זִמְנָא, מַאן לָא עָצִיב. בְּגִין כָּךְ כָּל תַּרְעֵי דְּבֵי מִדְרָשֵׁי נִנְעָלוּ, וְאִצְטְרִיכוּ כֹּלָּא לְצַדְקָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּאֹרַח שְׁבָחָא, וְהַיְינוּ (תהילים ל״ו:ז׳) צִדְקָתְךָ כְּהַרְרִי אֵל.</p>\n<p>תְּלָתָא אִינּוּן דְּאִסְתָּלָקוּ מֵעָלְמָא בְּהַאי זִמְנָא, וְכֻלְּהוּ כְּלִילָן בְּמֹשֶׁה. חַד, מֹשֶׁה נְבִיאָה מְהֵימָנָא עִלָּאָה. וְחַד, יוֹסֵף צַדִּיקָא. וְחַד, דָּוִד מַלְכָּא. בְּגִינֵי כַּךְ, תְּלַת צִדּוּקֵי דִּינִי הָכָא, חַד אִיהוּ דְּיוֹסֵף זַכָּאָה, קָדִים לְכָל הָנִי, וְדָא אִיהוּ צִדְקָתְךָ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךָ תְּהוֹם רַבָּה וְגוֹ', דָּא יוֹסֵף, דְּאִיהוּ בִּלְחוֹדוֹי כְּהַרְרֵי אֵל, כְּכֻלְּהוּ טוּרִין עִלָּאִין. וְחַד מֹשֶׁה נְבִיאָה מְהֵימָנָא, וְדָא אִיהוּ דִּכְתִּיב, (תהילים ע״א:י״ט) וְצִדְקָתְךָ אֱלהִים עַד מָרוֹם אֲשֶׁר עָשִׂיתָ גְּדוֹלוֹת, בְּגִין דְּאִיהוּ נָטִיל לְכָל סִטְרִין, יְמִינָא וּשְׂמָאלָא. וְחַד אִיהוּ דָּוִד מַלְכָּא, וְדָא אִיהוּ דִּכְתִּיב, (תהילים קי״ט:קמ״ב) צִדְקָתְךָ צֶדֶק לְעוֹלָם וְתוֹרָתְךָ אֱמֶת, לְעוֹלָם: דָּא דָּוִד מַלְכָּא.</p>\n<p>כְּדֵין אִתְכְּנִישׁ כֹּלָּא בְּהַאי זִמְנָא, תּוֹרָה שֶׁבִּכְתָב, וְתוֹרָה שֶׁבְּעַל פֶּה. וְעַל דָּא בְּהַאי זִמְנָא נִנְעָלוּ תַּרְעֵי דְּאוֹרַיְיתָא, וְנִנְעָלוּ תַּרְעֵי דְּכָל עָלְמָא, בְּהַאי זִמְנָא. בְּשַׁעֲתָּא דְּמִית יוֹסֵף צַדִּיקָא, יָבְשׁוּ מְקוֹרִין וּמַבּוּעִין, וְכֻלְּהוּ שְׁבָטִין נָפְלוּ בְּגָלוּתָא, פָּתְחוּ עִלָּאֵי וְאָמְרוּ, צִדְקָתְךָ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךָ תְּהוֹם רַבָּה וְגוֹ'. בְּשַׁעֲתָא דְּמִית מֹשֶׁה, אִתְחֲשָׁךְ שִׁמְשָׁא בְּטִיהֲרָא, וְאֲנְעָלַת תּוֹרָה שֶׁבִּכְתָב, נְהוֹרָהָא דְּאַסְפָּקָלַרְיָאה דְּנָהֲרָא. בְּשַׁעֲתָא דְּמִית דָּוִד מַלְכָּא, כְּנִישַׁת סִיהֲרָא נְהוֹרָהָא <Nonei></i>וְאוֹרַיְיתָא דִּבְעַל פֶּה כְּנִישַׁת נְהוֹרָהָא. וּמֵהַהוּא זִמְנָא אִתְגְּנִיזוּ נְהוֹרִין דְּאוֹרַיְיתָא, וְאַסְגִּיאוּ מַחֲלוֹקֶת עַל מִשְׁנָה, וְחַכִּימַיָּא בְּמַחְלוֹקֶת, וְכֻלְּהוּ תַּקִיפֵי לִבָּא בְּעִרְבּוּבְיָא. וְעַל דָּא, חֶדְוָה דְּאוֹרַיְיתָא לָאו אִיהוּ בְּהַהוּא זִמְנָא, בְּכָל דָּרִין דְּעָלְמָא.</p>\n<p>וּמָה אִינּוּן חוֹמְרֵי דְּתַעֲנִיוֹת דְּגָזְרוּ רַבָּנָן, כַּד מִית פְּלוֹנִי, גָּזְרוּ תַּעֲנִית. כַּד הֲוָה כַּךְ, גָּזְרוּ כַּךְ. (ס\"א דא דהוה) וְכַד הֲוָה כְּנִישׁוּ יַתִּיר דְּחֶדְוָה דְּתוֹרָה דְּבִכְתָּב וְתוֹרָה דִּבְעַל פֶּה, בְּהַהוּא זִמְנָא, עַל אַחַת כַּמָּה וְכַמָּה דְּאִצְטְרִיךְ לְמִנְעַל תַּרְעֵי דְּאוֹרַיְיתָא בְּהַהוּא זִמְנָא. וּבְּגִין כָּךְ אַמְרֵינָן הָנֵי צִדּוּקֵי דִּינָא, כְּמָה דְּאִתְּמַר. חֲדוּ רַבִּי יוֹסִי וְרַבִּי חִיָּיא, וּנְשָׁקוּהוּ בְּרֵישֵׁיהּ כְּמִלְקַדְּמִין, אָמְרוּ זַכָּאָה חוּלָקָנָא בְּהַאי אָרְחָא.</p>"]]});
